    ), $atts));

    $return = '<form class="sml_subscribe" method="post"><input class="sml_hiddenfield" name="sml_subscribe" type="hidden" value="1">';

    if ($prepend) $return .= '<p class="prepend">'.$prepend.'</p>';

    if ($_POST['sml_subscribe'] && $thankyou) {
