Người bình luận nhiều nhất: không bao gồm admin Tôi đang sử dụng mã sau đây trong tệp function.php của tôi để hiển thị những người bình luận hàng đầu trong chủ đề của tôi:

function top_comment_authors($amount = 5) {
    global $wpdb;
    $results = $wpdb->get_results(
        "SELECT COUNT(comment_author_email) AS comments_count, comment_author_email, comment_author, comment_author_url
         FROM " . $wpdb->comments . "
         WHERE comment_author_email != '' AND comment_type = '' AND comment_approved = 1
         GROUP BY comment_author_email
         ORDER BY comments_count DESC, comment_author ASC
         LIMIT " . $amount
    );
    $output = "<ul>";
    foreach ($results as $result) {
        $output .= "<li>" . get_avatar($result->comment_author_email, 30) . ' <p>' . (($result->comment_author_url) ? "<a href='" . $result->comment_author_url . "'>" : "") . $result->comment_author . (($result->comment_author_url) ? "</a>" : "") . " (" . $result->comments_count . ")</p></li>";
    }
    $output .= "</ul>";
    echo $output;
}

