Và đây là cách tôi cố gắng lưu dữ liệu (chỉ trường year_released cho bây giờ):

// Lưu thông tin album

function wpt_save_album_meta($post_id, $post) {
if ( !wp_verify_nonce( $_POST['albummeta_noncename'], plugin_basename(__FILE__) )) {
return $post->ID;
}

if ( !current_user_can( 'edit_post', $post->ID ))
return $post->ID;

$album_meta['_year_released'] = $_POST['_year_released'];

foreach ($album_meta as $key => $value) {
if( $post->post_type == 'revision' ) return;
$value = implode(',', (array)$value);

if(get_post_meta($post->ID, $key, FALSE)) {
update_post_meta($post->ID, $key, $value);
} else {
add_post_meta($post->ID, $key, $value);
}

if(!$value) delete_post_meta($post->ID, $key);
}
}

add_action('save_post', 'wpt_save_album_meta', 1, 1);

