Cách tránh vòng lặp vô hạn trong callback save_post Tôi đã sử dụng trang này rất nhiều để giải quyết các vấn đề của tôi, nhưng lần này tôi không thành công trong việc tìm ra câu trả lời cho vấn đề của mình. Tôi nhận được một vòng lặp vô hạn khi sử dụng `wp_update_post` bên trong một hàm được gọi trên `save_post`. Tôi biết rằng đây là một vấn đề phổ biến, nhưng tôi không thể tìm ra cách để tránh nó. Tôi muốn lưu lại thứ tự của các bài viết (mà là loại bài viết 'section'). Vì vậy, tôi đã tạo một hộp meta tùy chỉnh chứa một số phần tử có thể sắp xếp được. Trong mỗi phần tử có một thẻ input ẩn với tên='sectionorder[]'. Vì vậy, khi tôi nhấp vào nút 'Cập nhật' chuẩn của WordPress, một mảng chứa tất cả các ID của bài viết (theo thứ tự) được gửi qua POST. Vì vậy, đây là mã mà tôi lấy mảng và muốn lưu lại thứ tự:

// Cập nhật thứ tự sắp xếp phần


$sectionorder = $_POST['sectionorder'];

nếu (isset($sectionorder)) { // Tránh lỗi nếu chưa có phần nào được thêm

foreach( $sectionorder như $no => $sectionID ) {

$post_update = mảng();

$post_update ['ID'] = $sectionID;

$post_update ['menu_order'] = $no;

wp_update_post( $post_update );

}

}

Nhưng vấn đề là nó bắt đầu một vòng lặp vô hạn. Làm thế nào tôi có thể tránh điều đó? Có lẽ tôi có thể làm điều đó theo một cách khác hoàn toàn? Tôi rất cảm kích sự giúp đỡ của bạn!

Thêm 'active' vào các danh mục tùy chỉnh sử dụng walker trong functions.php Tôi đang cố gắng sử dụng mã sau trong functions.php để hiển thị một menu với các danh mục (thực ra là các từ điển tùy chỉnh). Tôi chỉ muốn nó hiển thị hoạt động khi ở trên trang hiện tại. Tôi đang mắc lỗi gì vậy? Tôi cũng thấy rằng dòng $category = get_category($mycatid); không điền vào biến $category.

<?php
class walker_archives extends Walker_Nav_Menu
{
    public function start_el( &$output, $item, $depth, $args )
    {
        $attributes  = '';
        ! empty ( $item->attr_title ) && $item->attr_title !== $item->title && $attributes .= ' title="' . esc_attr( $item->attr_title ) .'"';
        ! empty ( $item->url ) && $attributes .= 'href="' . esc_attr( $item->url ) .'"';
        $attributes  = trim( $attributes );
        $title       = apply_filters( 'the_title', $item->title, $item->ID );
        $item_output = "$args->before<a $attributes>$args->link_before$title</a>" . "$args->link_after$args->after";
        $mycatid = $item->object_id;
        $category = get_category($mycatid);
        $mycatslug = $category->slug;
        $classes = empty( $item->classes ) ? array() : (array) $item->classes;
        $class_names .= in_array("current_page_item",$item->classes) ? ' active' : '';
        $class_names = ' class="staysexy'. esc_attr( $class_names );
        $output .= $indent . ' <li id="nav-menu-item-'. $item->ID . '" class="genre-'. $mycatslug . '">';
        $output .= apply_filters(
            'walker_nav_menu_start_el'
            ,   $item_output
            ,   $item
            ,   $depth
            ,   $args
        );
    }

    public function start_lvl( &$output )
    {
        $output .= '<ul class="sub-menu">';
    }

    public function end_lvl( &$output )
    {
        $output .= '</ul>';
    }

    function end_el( &$output )
    {
        $output .= '</li>';
    }
}
?>

add_rewrite_rule không hoạt động trong Wordpress Multisite Tôi cần phải viết lại các URL trên một mạng/multisite Wordpress, vì vậy tôi đã viết một plugin để làm điều đó cho tôi. Plugin này hoạt động hoàn hảo khi sử dụng trên một trang web đơn của Wordpress mà không sử dụng tính năng multisite, bây giờ khi tôi cố gắng sử dụng nó trên một thiết lập multisite nó chỉ không muốn hoạt động, cũng không ghi vào file htaccess. Mã của tôi ở dưới đây

function rewrite_builtrules() {
global $wp_rewrite;
//Rule 1
$rewrite_rule1 = get_option('rewrite_rule1');
$rewrite_virtual_rule1 = get_option('rewrite_virtual_rule1');
if(!empty($rewrite_rule1) && !empty($rewrite_virtual_rule1))
add_rewrite_rule($rewrite_virtual_rule1,$rewrite_rule1,'top');
//Rule 2
$rewrite_rule2 = get_option('rewrite_rule2');
$rewrite_virtual_rule2 = get_option('rewrite_virtual_rule2');
if(!empty($rewrite_rule2) && !empty($rewrite_virtual_rule2))
add_rewrite_rule($rewrite_virtual_rule2,$rewrite_rule2,'top');
//Rule 3
$rewrite_rule3 = get_option('rewrite_rule3');
$rewrite_virtual_rule3 = get_option('rewrite_virtual_rule3');
if(!empty($rewrite_rule3) && !empty($rewrite_virtual_rule3))
add_rewrite_rule($rewrite_virtual_rule3,$rewrite_rule3,'top');
//
flush_rewrite_rules(true);
$wp_rewrite->flush_rules( true );
}
add_action( 'init', 'rewrite_builtrules' );

