Tạo breadcrumb với wp_nav_menu Tôi đang tìm một phương pháp nhanh chóng và bẩn thỉu để đưa ra điều hướng breadcrumb trên một trang web WP, không yêu cầu cài đặt một plugin và cũng sử dụng menu được tích hợp của WP. Đây là những gì tôi đã nghĩ ra. Tôi tò mò muốn biết liệu có một giải pháp tốt hơn mà tôi đã bỏ lỡ, và / hoặc nếu có bất cứ điều gì rõ ràng là sai khi làm theo cách này. Cho đến nay trong thử nghiệm của tôi nó hoạt động khá tốt.
class BreadcrumbWalker extends Walker_Nav_Menu {
private $i_current_page_id;
private $i_depth;
private $a_output;
function __construct() {
// thiết lập trang hiện tại của chúng tôi để chúng tôi biết khi nào phải thoát ra
$this->i_current_page_id = get_queried_object()->ID;
}
function start_lvl(&$output, $depth=0, $args=array()) {
// tăng độ sâu mỗi lần một ul mới được vào
$this->i_depth++;
}
function end_lvl(&$output, $depth=0, $args=array()) {
// giảm độ sâu khi chúng tôi thoát ra khỏi một ul
$this->i_depth--;
}
function start_el(&$output, $item, $depth=0, $args=array()) {
// nếu giá trị này là zero, chúng tôi đang bắt đầu một nhánh mới
if($item->menu_item_parent == 0) {
// đặt lại mảng đầu ra và bộ đếm độ sâu
$this->a_output = array();
$this->i_depth = 0;
}
// nếu chúng tôi chưa đặt mục đại diện cho độ sâu này, hãy làm như vậy
if(!isset($this->a_output[$this->i_depth])) {
$this->a_output[$this->i_depth] = '<a href="' . get_permalink($item->object_id) . '">' . $item->title . '</a>';
}
}
function end_el(&$output, $item, $depth=0, $args=array()) {
if($this->i_current_page_id == $item->object_id) {
// kiểm tra xem đây có phải là mục cuối cùng của chúng tôi không, nếu vậy hiển thị breadcrumb
if($this->i_depth > 0) {
// nhưng chỉ hiển thị nó nếu chúng tôi thực sự có một đường dẫn breadcrumb
$this->display_breadcrumb();
}
} else {
// nếu không, xóa mục cho độ sâu này vì đây không phải là điều chúng tôi sẽ hiển thị
unset($this->a_output[$this->i_depth]);
}
}
function display_breadcrumb() {
// kết nối mảng của chúng tôi thành một chuỗi
echo implode(' &raquo; ', $this->a_output);
}
}
Về cơ bản tôi đang sử dụng các phương pháp Walker_Nav_Menu để thiết lập một mảng đầu ra sử dụng độ sâu làm khóa của nó, và một khi phương thức end_el được gọi, nếu đó không phải là ID của trang là cuối của breadcrumb, nó xóa mục ở độ sâu đó và tiếp tục lặp qua mảng. Nếu nó _là_ ID chính xác, nó gọi phương thức display_breadcrumb để đầu ra menu. Cảm ơn trước cho bất kỳ đầu vào nào. Tôi cảm thấy có lẽ có một cách tốt hơn để làm điều này, nhưng hiện tại tôi bối rối về điều đó có thể là gì.

Thay đổi meta_query của truy vấn chính dựa trên các biến query tùy chỉnh và sử dụng pre_get_posts Tôi đã đăng ký các quy tắc ghi lại tùy chỉnh và "query_vars" để sử dụng cho việc hiển thị một danh sách các sự kiện dựa trên định dạng ngày ISO. Ví dụ, khi người dùng yêu cầu URL, "http://site.com/by-date/2013-04-04/", biến "query_var" của tôi là phần ngày và tôi muốn hiển thị một danh sách các sự kiện mà "meta_key" của "_event_scheduled_date" bằng giá trị ngày ISO trong "query_var". Mỗi khi tôi thử mã sau để sửa đổi "$query" trong "pre_get_posts", WordPress khởi tạo 404 và không có bài viết nào được truy vấn. Tôi đã có thể sử dụng "pre_get_posts" để thao tác các danh sách phân loại và trang lưu trữ khác nhau, nhưng vẫn chưa thể thực hiện chính xác với biến "query_var" tùy chỉnh mà tôi đã tạo ra.

hàm rewrite_rule_by_date() {
add_rewrite_rule('(by\-date)/([0-9]{4}\-[0-9]{2}\-[0-9]{2})$', 'index.php?pagename=$matches[1]&event_date=$matches[2]', 'top');
}

add_action( 'init', 'rewrite_rule_by_date' );

hàm query_var_by_date() {
add_rewrite_tag( '%event_date%', '([0-9]{4}-[0-9]{2}-[0-9]{2})');
}

add_action( 'init', 'query_var_by_date' );

hàm custom_event_query( $query ) {
nếu ( is_page( 'by-date' ) && get_query_var( 'event_date' ) && is_main_query() ) {
$query->set( 'post_type', 'event' );
$query->set( 'post_status', 'publish' );
$query->set( 'meta_key', '_event_scheduled_date' );
$query->set( 'orderby', 'meta_value' );
$query->set( 'order', 'ASC' );
$query->set( 'post_per_page', -1 );

$meta_query = array(
dãy(
'khóa' => '_event_scheduled_date',
'giá trị' => get_query_var( 'event_date' ),
'type' => 'DATE',
'compare' => '='
)
);

$query->set( 'meta_query', $meta_query );
}

trả về $query;
}

add_filter( 'pre_get_posts', 'custom_event_query' );

