Trả về ID của tác giả có ít nhất một bài viết Tôi tìm thấy một đoạn mã tuyệt vời ở đây mà trả về ID của người dùng theo vai trò. Điều tôi muốn làm là sửa đổi nó để chỉ trả về ID của những người dùng có ít nhất một bài đăng. Tôi đã cố gắng "INNER JOIN" bảng $wpdb->posts và cảm thấy rằng tôi đã làm điều đó chính xác nhưng không chắc chắn. Đây là những gì tôi đã có cho đến nay:

function getUsersByRole( $roles ) {
    global $wpdb;
    if ( ! is_array( $roles ) ) {
        $roles = explode( ",", $roles );
        array_walk( $roles, 'trim' );
    }
    $sql = '
        SELECT  ID, display_name
        FROM ' . $wpdb->users . ' INNER JOIN ' . $wpdb->usermeta . ' ON ' . $wpdb->users . '.ID=' . $wpdb->usermeta . '.user_id
        AND INNER JOIN '. $wpdb->posts .'
        ON ' .$wpdb->users . '.ID=' . $wpdb->posts . '.post_author
        WHERE   ' . $wpdb->usermeta . '.meta_key
        =
        \'' . $wpdb->prefix . 'capabilities\'
        AND
        (
        ';
    $i = 1;
    foreach ( $roles as $role ) {
        $sql .= ' ' . $wpdb->usermeta . '.meta_value    LIKE    \'%"' . $role . '"%\' ';
        if ( $i < count( $roles ) ) $sql .= ' OR ';
        $i++;
    }
    $sql .= ' ) ';
    $sql .= ' ORDER BY display_name ';
    $userIDs = $wpdb->get_col( $sql );
    return $userIDs;
}

Câu truy vấn SQL đầu ra> SELECT ID, display_name FROM wp_users INNER JOIN wp_usermeta ON > wp_users.ID=ba_usermeta.user_id AND INNER JOIN wp_posts ON > wp_users.ID=ba_posts.post_author WHERE wp_usermeta.meta_key = > 'wp_capabilities' AND ( wp_usermeta.meta_value LIKE '%"author"%' OR > wp_usermeta.meta_value LIKE '%"editor"%' ) ORDER BY display_name Tôi chưa bao giờ sử dụng "INNER JOIN" (hoặc "JOIN") vì vậy tôi có thể làm sai. Tôi cũng nghĩ rằng tôi cần phải thực hiện một số đếm hoặc điều gì đó để đảm bảo tôi nhận được kết quả. Bất kỳ sự giúp đỡ nào sẽ rất tuyệt vời **SỬA ĐỔI:** Đây là chức năng đầy đủ hoạt động như PHP cho bất cứ ai tìm thấy điều này sau này

function getUsersByRole( $roles ) {
    global $wpdb;
    if ( ! is_array( $roles ) ) {
        $roles = explode( ",", $roles );
        array_walk( $roles, 'trim' );
    }
    $sql = 'SELECT ID, display_name
        FROM '. $wpdb->users .'
        JOIN '. $wpdb->usermeta.' ON ('.$wpdb->users.'.ID = '.$wpdb->usermeta.'.user_id AND '.$wpdb->usermeta.'.meta_key = \''.$wpdb->prefix.'capabilities\')
        WHERE ID IN (SELECT post_author FROM ' .$wpdb->posts.')
        AND(';
    $i = 1;
    foreach ( $roles as $role ) {
        $sql .= ' ' . $wpdb->usermeta . '.meta_value    LIKE    \'%"' . $role . '"%\' ';
        if ( $i < count( $roles ) ) $sql .= ' OR ';
        $i++;
    }
    $sql .= ' ) ';
    $sql .= ' ORDER BY display_name ';
    $userIDs = $wpdb->get_col( $sql );
    return $userIDs;
}

