Jetpack Infinite scroll xung đột với chủ đề's pre_get_posts tùy chỉnh posts_per_page Tôi có một chức năng hiện tại trên chủ đề của tôi sử dụng `pre_get_posts`, hiện tại ngay ở dưới cùng của tệp functions.php của chủ đề của tôi:

    function mytheme_portfolio_archive_pages( $query ) {
        if ( is_admin() || ! $query->is_main_query() )
            return;

        if ( is_post_type_archive( 'mytheme_portfolio' ) ) {
            // Hiển thị 20 bài viết cho một loại bài đăng tùy chỉnh được gọi là 'mytheme_portfolio'
            $query->set( 'posts_per_page', 20 );
            return;
        }
    }

    add_action( 'pre_get_posts', 'mytheme_portfolio_archive_pages', 1 );

Điều đó có nghĩa là tôi có 20 bài viết trên mỗi trang nếu lưu trữ hiện tại là của loại bài đăng 'mytheme_portfolio', thay vì mặc định 5 cho các trang blog (số 5 được đặt trong "Trang Blog hiển thị tối đa __ bài viết" trong Cài đặt -> Đọc). Chức năng trên hoạt động tốt khi Jetpack Infinite Scroll bị vô hiệu hóa. Vấn đề là tôi muốn sử dụng Jetpack Infinite Scroll với lưu trữ 'mytheme_portfolio'. Và khi nó được kích hoạt, chức năng trên ngừng hoạt động và Infinite Scroll sử dụng số "Trang Blog hiển thị tối đa 5 bài viết" từ Cài đặt -> Đọc khi nó tải các bài viết mới. Infinite Scroll hoạt động tốt nhưng tôi cần hiển thị 20 bài viết trên mỗi trang, không phải 5, nếu tôi đang ở một trang lưu trữ 'mytheme_portfolio'! Mã thiết lập Jetpack của tôi như sau, chỉ để tham khảo:

    function mytheme_render_infinite_scroll() {
        while ( have_posts() ) : the_post();
            if ('mytheme_portfolio' == get_post_type() && !is_search()) :
                get_template_part( 'content', 'archive-portfolio' );
            elseif ( is_search() ) :
                get_template_part('content','search');
            else :
                get_template_part( 'content', get_post_format() );
            endif;
        endwhile;
    }

    function mytheme_jetpack_setup() {
        add_theme_support( 'infinite-scroll', array(
            'container'      => 'content',
            'footer_widgets' => 'footer-widgets',
            'type'           => 'click',
            'render'         => 'mytheme_render_infinite_scroll',
            'wrapper'        => true,
            'posts_per_page' => false
        ) );
    }

    add_action( 'after_setup_theme', 'mytheme_jetpack_setup' );

Cảm ơn rất nhiều cho bất kỳ sự giúp đỡ nào mà ai đó có thể cung cấp! **SỬA ĐỔI:** Tôi đã tìm thấy dòng trong mã plugin Jetpack xung đột, trong `jetpack/modules/infinite-scroll/infinity.php`, dòng 26...

