function wpbeginner_numeric_posts_nav() {
if( is_singular() )
return;
global $wp_query;
/** Ngừng thực thi nếu chỉ có 1 trang */
if( $wp_query->max_num_pages <= 1 )
return;
$paged = get_query_var( 'paged' ) ? absint( get_query_var( 'paged' ) ) : 1;
$max   = intval( $wp_query->max_num_pages );
/** Thêm trang hiện tại vào mảng */
if ( $paged >= 1 )
$links[] = $paged;
/** Thêm các trang xung quanh trang hiện tại vào mảng */
if ( $paged >= 3 ) {
$links[] = $paged - 1;
$links[] = $paged - 2;
}
if ( ( $paged + 2 ) <= $max ) {
$links[] = $paged + 2;
$links[] = $paged + 1;
}
echo '<div class="navigation"><ul>' . "\n";
/** Liên kết bài viết trước */
if ( get_previous_posts_link() )
printf( '<li>%s</li>' . "\n", get_previous_posts_link() );
/** Liên kết đến trang đầu tiên, cộng với dấu chấm nếu cần thiết */
if ( ! in_array( 1, $links ) ) {
$class = 1 == $paged ? ' class="active"' : '';
printf( '<li%s><a href="%s">%s</a></li>' . "\n", $class, esc_url( get_pagenum_link( 1 ) ), '1' );
if ( ! in_array( 2, $links ) )
echo '<li>…</li>';
}
/** Liên kết đến trang hiện tại, cộng với 2 trang ở cả hai bên nếu cần thiết */
sort( $links );
foreach ( (array) $links as $link ) {
$class = $paged == $link ? ' class="active"' : '';
printf( '<li%s><a href="%s">%s</a></li>' . "\n", $class, esc_url( get_pagenum_link( $link ) ), $link );
}
/** Liên kết đến trang cuối cùng, cộng với dấu chấm nếu cần thiết */
if ( ! in_array( $max, $links ) ) {
if ( ! in_array( $max - 1, $links ) )
echo '<li>…</li>' . "\n";
$class = $paged == $max ? ' class="active"' : '';
printf( '<li%s><a href="%s">%s</a></li>' . "\n", $class, esc_url( get_pagenum_link( $max ) ), $max );
}
/** Liên kết bài viết tiếp theo */
if ( get_next_posts_link() )
printf( '<li>%s</li>' . "\n", get_next_posts_link() );
echo '</ul></div>' . "\n";
}

Giúp tôi sắp xếp lại mã widget của mình Tôi là một người mới bắt đầu với WordPress và PHP. Tôi đã tạo một tiện ích nhỏ để nhúng video từ YouTube hoặc các dịch vụ lưu trữ video khác. Mọi thứ hoạt động tốt. Tôi biết mã của tôi khá lộn xộn, vì vậy tôi sẽ rất cảm kích nếu ai đó có thể chỉnh sửa lại mã cho gọn gàng hơn. Đây là mã của tôi:

<?php
/**
* Plugin Name: Tên tiện ích
* Tác giả: Tên tác giả
* URI của tác giả: URL trang web
*/
class Today_video extends WP_Widget {
/**
* Thiết lập tiện ích.
*/
function Today_video() {
/* Cài đặt tiện ích. */
$widget_ops = array(
'classname' => 'tm_widget_today_video',
'description' => __('Hiển thị video hôm nay trên trang web của bạn', 'today_video')
);
/* Cài đặt điều khiển tiện ích. */
$control_ops = array(
'width' => 300,
'height' => 350,
'id_base' => 'today_video'
);
/* Tạo tiện ích. */
$this->WP_Widget( 'today_video' , __( 'Video Hôm nay' , 'today_video' ), $widget_ops );
}
/**
* Hàm phía front-end.
*/
function widget( $args, $instance ) {
extract( $args );
/* Các biến từ cài đặt tiện ích. */
if(isset($instance))
{
if( isset( $instance[ 'title' ] ) ) {
$title = apply_filters( 'widget_title', $instance[ 'title' ] );
}
if( isset( $instance[ 'template' ] ) ) {
$template = htmlspecialchars_decode( $instance[ 'template' ] );
}
}
/* Trước tiện ích (được xác định bởi theme). */
if( isset( $before_widget ) ) {
echo $before_widget;
}
/* Hiển thị tiêu đề tiện ích nếu có (trước và sau được xác định bởi theme). */
if( isset( $title ) ) {
echo $before_title . $title . $after_title;
}
/* Hiển thị video của tiện ích */
if( isset( $template ) ) {
echo '<div class="tm_today_video"> '.$template.' </div>';
}
/* Sau tiện ích (được xác định bởi theme). */
echo $after_widget;
}
/**
* Cài đặt phía back-end của tiện ích.
*/
function update( $new_instance, $old_instance ) {
$instance = $old_instance;
/* Loại bỏ thẻ cho tiêu đề và tên để loại bỏ HTML (quan trọng cho các trường văn bản). */
$instance['title'] =
strip_tags( $new_instance['title'] );
// Sử dụng htmlspecialchars để lưu mã HTML trong cơ sở dữ liệu, ở phía front-end chúng ta sử dụng htmlspecialchars_decode
$instance['template'] =
htmlspecialchars($new_instance['template']);
return $instance;
}
/**
* Hiển thị các cài đặt điều khiển tiện ích trên bảng điều khiển tiện ích.
*
* Mẫu tùy chọn back-end của tiện ích.
*/
function form( $instance ) {
$defaults = array(
'title' => __(  'Video Hôm nay', 'today_video'),
'template' => __('<iframe width="200" height="112" src="http://www.youtube.com/embed/Xrt1V_XhvSk?showinfo=0" frameborder="0" allowfullscreen></iframe>', 'today_video'),
);
$instance = wp_parse_args( (array) $instance, $defaults );
?>
<p>
<label for="<?php echo $this->get_field_id( 'title' ); ?>"><?php _e('Tiêu đề:', 'hybrid'); ?></label>
<input id="<?php echo $this->get_field_id( 'title' ); ?>" name="<?php echo $this->get_field_name( 'title' ); ?>" value="<?php echo $instance['title']; ?>" style="width:96%;" />
</p>
<p>
<label for="<?php echo $this->get_field_id( 'template' ); ?>"><?php _e('Mã nhúng:', 'hybrid'); ?></label>
<textarea id="<?php echo $this->get_field_id( 'template' ); ?>" name="<?php echo $this->get_field_name( 'template' ); ?>"  style="width:100%;height:100px;"><?php echo $instance['template']; ?></textarea>
</p>
<?php
}
}
// Thêm hàm vào widgets_init để tải today_video
add_action( 'widgets_init', create_function( '', 'register_widget( "Today_video" );' ) );
?>
