Làm thế nào để tùy chỉnh slug tự động với chức năng ghi đè Tôi đang dùng một đoạn mã nhỏ mà tôi đã đưa vào trong tập tin chức năng của mình để tự động lấy bất kỳ thông tin nào được nhập vào tiêu đề bài viết mới và tạo ra một slug với những từ dừng cụ thể bị xóa bỏ (mã được đưa ra bên dưới). Vấn đề là đôi khi sau khi slug này được tạo ra tự động tôi muốn nhấp vào slug (dưới tiêu đề) và sửa đổi nó trực tiếp. Câu hỏi của tôi dành cho cộng đồng là ... tôi cần thay đổi gì trong mã bên dưới để khi tôi nhấp vào slug (dưới tiêu đề) và sửa đổi nó mọi thứ tôi nhập vào đó sẽ được sử dụng mà không bị hàm bên dưới ngăn trở điều đó xảy ra. Đây là mã:
// TỰ ĐỘNG LÀM SẠCH SLUG SEO CỦA trang/bài viết TỪ từ NGẮN
// NGUỒN: http://www.vretoolbar.com/news/seo-slugs-wordpress-plugin
add_filter('name_save_pre', 'seo_slugs', 0);
function seo_slugs($slug) {
// Chúng ta không muốn thay đổi slug hiện có
nếu ($slug) trả về $slug;
tổ chức toàn cầu $wpdb;
$seo_slug = strtolower(stripslashes($_POST['post_title']));
$seo_slug = preg_replace('/&.+?;/', '', $seo_slug); // diệt thực thể HTML
// diệt bất cứ điều gì không phải là chữ cái, số, khoảng trắng hoặc dấu nháy đơn
$seo_slug = preg_replace ("/[^a-zA-Z0-9 \']/", "", $seo_slug);
// Chuyển nó thành một mảng và loại bỏ các từ phổ biến bằng cách so sánh với mảng c.w.
$seo_slug_array = array_diff (split(" ", $seo_slug), seo_slugs_stop_words());
// Chuyển chuỗi được làm sạch thành một chuỗi
$seo_slug = join("-", $seo_slug_array);
trả về $seo_slug;
