Xóa bài viết tự động dựa trên truy vấn Tôi đang cố gắng tự động xóa một số bài đăng (của loại bài đăng tùy chỉnh) dựa trên so sánh giữa thời gian hiện tại và một số giờ trước đây, ví dụ 24 giờ. Loại bài đăng tùy chỉnh là "đặt lịch hẹn", và nếu một cuộc hẹn được đặt trong vòng 24 giờ và có giá trị meta 'available' trong khóa meta 'app_status', tôi muốn xóa nó. Mã sau đây là mã tôi đang thử, nhưng nó không hoạt động. Những bài viết mà tôi đã thiết lập với thời gian bắt đầu của ứng dụng ít hơn 24 giờ từ bây giờ không bị xóa. Tôi cũng đã thử các hook khác nhau để gắn mã vào mà không thành công.

function delete_unclaimed_apps () {
    $avail = array(
        'post_type' => 'appointment',
        'meta_key' => 'app_status',
        'meta_value' => 'available',
    );

    $availapps = get_posts($avail);

    $now = (time()-(7*60*60));
    $cutoff = (get_field('minimum_reserve_notice', 'options') * 60 * 60);

    foreach ($availapps as $post) {
        setup_postdata( $post );
        $appid = get_the_ID();

        if (get_post_meta($appid, 'app_date_start', true)) {
            if (get_post_meta($appid, 'app_date_start', true) < ($now + $cutoff)) {
                wp_delete_post($appid, false);
            }
        }

        wp_reset_postdata();
    }
}

add_action('wp_enqueue_scripts', 'delete_unclaimed_apps');

