Và trong trang functions.php, tôi đang sử dụng mã sau để chuyển hướng người dùng đến trang chủ sau khi họ đăng nhập:

hàm my_login_redirect ( $redirect_to, $request, $user ) {
// có người dùng để kiểm tra không?
nếu ( isset ( $user->roles ) && is_array ( $user->roles ) ) {
// kiểm tra quản trị viên
nếu ( in_array ( "administrator", $user->roles ) ) {
// chuyển hướng họ đến địa điểm mặc định
trả về $redirect_to;
} khác {
trả về home_url ();
}
} khác {
trả về $redirect_to;
}
}
add_filter ( "login_redirect", "my_login_redirect", 10, 3 );

