Cố gắng áp dụng áp dụng bộ lọc cho nội dung loại bài viết tùy chỉnh - không hoạt động Đây là một yêu cầu khá lạ. Tôi có một plugin thêm một kiểu bài viết tùy chỉnh - sau đó plugin có một số cài đặt cho phép người dùng chọn từ bất kỳ bài viết nào họ tạo ra (trong kiểu bài viết tùy chỉnh đó) để thêm vào nội dung của bài viết khác. Mã sau đây là mã thực hiện chức năng này:

<?php
global $wpdb;
$options = get_option('wp_optin_studio');
$post_form = $options['post_form_select'];
$post_options = get_post_meta($post_form, 'wp_optin_form_settings', true);
$optin_post = get_post($post_form);
$optin_content = $optin_post->post_content;
$optin_content = apply_filters('the_content', $optin_content);
$optin_content = str_replace(']]>', ']]&gt;', $optin_content);

/* Thêm bài viết tùy chỉnh vào bài viết */
function wp_optin_studio_add_post_forms($content) {
    global $options;
    global $post_options;
    global $post_form;
    global $optin_content;
    $my_custom_text = $post_options['optin_studio_headline']; // văn bản-html để thay thế
    $my_custom_text .= $optin_content;
    if(!is_single()) {
        return $content;
    }
    if(is_single()) {
        $content .= $my_custom_text;
    }
    remove_filter( current_filter(), __FUNCTION__ );
    return $content;
}

/* Kiểm tra xem người dùng có muốn thêm bài viết tùy chỉnh vào trang/bài viết hay không */
if ($post_form) {
    add_filter('the_content', 'wp_optin_studio_add_post_forms');
}
?>

