function my_meta_save($post_id, $post) {
// xác minh rằng nó đến từ màn hình của chúng ta và với quyền ủy quyền thích hợp,
// bởi vì save_post có thể được kích hoạt vào những thời điểm khác
if ( !wp_verify_nonce( $_POST['eventmeta_noncename'], plugin_basename(__FILE__) )) {
return $post->ID;
}
// Người dùng có được phép chỉnh sửa bài viết hoặc trang không?
if ( !current_user_can( 'edit_post', $post->ID ))
return $post->ID;
// Được rồi, chúng tôi đã xác thực: chúng tôi cần tìm và lưu dữ liệu
// Chúng tôi sẽ cho nó vào một mảng để dễ dàng lặp qua.
$events_meta['_designation'] = $_POST['_designation'];
// Thêm giá trị của $events_meta như các trường tùy chỉnh
foreach ($events_meta as $key => $value) { // Lặp qua mảng $events_meta!
if( $post->post_type == 'revision' ) return; // Không lưu dữ liệu tùy chỉnh hai lần
$value = implode(',', (array)$value); // Nếu $value là một mảng, hãy biến nó thành CSV (không có khả năng)
if(get_post_meta($post->ID, $key, FALSE)) { // Nếu trường tùy chỉnh đã có giá trị
update_post_meta($post->ID, $key, $value);
} else { // Nếu trường tùy chỉnh không có giá trị
add_post_meta($post->ID, $key, $value);
}
if(!$value) delete_post_meta($post->ID, $key); // Xóa nếu trống
}
}
add_action('save_post','my_meta_save');
}
}

