Tìm kiếm tùy chỉnh dùng $_SESSION và pre_get_posts Tôi đã hack cả ngày vào một hệ thống tìm kiếm/lọc tùy chỉnh loại bài đăng. Cho đến nay tôi đã có:

function kdev_property_query($query) {
    if(isset($_POST['rooms_n'])) $_SESSION['rooms_n'] = $_POST['rooms_n'];
    if(isset($_POST['univer'])) $_SESSION['univer'] = $_POST['univer'];
    nếu (isset($_POST['area_t'])) $_SESSION['area_t'] = $_POST['area_t'];

    $query_post_type = $query->query_vars["post_type"];

    nếu (! is_post_type_archive('properties') hoặc $query_post_type == 'nav_menu_item') trả về;

    // Hiển thị tất cả các tài sản có sẵn
    $query->set('posts_per_page','-1');

    $meta_query = array();

    $tax_query = array();

    toàn cầu $query_string;

    nếu (isset($_SESSION['rooms_n'])) $room_query = $_SESSION['rooms_n'];

    nếu (isset($_SESSION['univer'])) $uni_query = $_SESSION['univer'];

    nếu (isset($_SESSION['area_t'])) $area_query = $_SESSION['area_t'];

    nếu (isset($room_query)) {
        $meta_query[] = array(
            'khóa' => '_rooms',
            'giá trị' => $room_query
        );
    }

    nếu (isset($uni_query)) {
        $tax_query[] = array(
            'thuật ngữ' => 'đại học',
            'cột' => 'slug',
            'các điều khoản' => $uni_query
        );
    }

    nếu (isset($area_query)) {
        $tax_query[] = array(
            'thuật ngữ' => 'khu vực',
            'cột' => 'slug',
            'các điều khoản' => $area_query
        );
    }

    nếu (! trống ($meta_query))
        $query->set('meta_query', $meta_query);

    nếu (! trống ($tax_query))
        $query->set('tax_query', $tax_query);
}

add_action('pre_get_posts', 'kdev_property_query', 1);

