    nếu (isset($_SESSION['area_t'])) $area = $_SESSION['area_t'];
    khác nếu (is_tax('khu vực')) $area = get_query_var('term');
    nếu (isset($area)) $area = strtolower($area);?>
    <nhãn cho="area_t">Khu vực:</label>
    <chọn tên="area_t">
    <tùy chọn giá trị="NULL">Bất kỳ</option>
    <?php
    $area_terms = get_categories('taxonomy=area');

    nếu (isset($area)) {
        foreach ($area_terms as $term) {
            $option = '<option value="'.$term->slug.'"';
            nếu ($area == $term->slug) {
                $option.= ' selected="selected"';
            }
            $option .= '>'.$term->name;
            $option .= '</option>';
            echo $option;
        }
    } khác {
        foreach ($area_terms as $term) {
            $option = '<option value="'.$term->slug.'"';
            $option .= '>'.$term->name;
            $option .= '</option>';
            echo $option;
        }
    }
    ?>
    </select>
    </p>

    <p>
    <?php
    nếu (isset($_SESSION['rooms_n'])) $rooms = $_SESSION['rooms_n'];
    ?>
    <nhãn cho="rooms_n">Phòng ngủ:</label>
    <chọn tên="rooms_n">
    <tùy chọn giá trị="NULL">Bất kỳ</option>
    <?php
    $room_array = array(3,4,5,6,7);
    foreach($room_array as $no) {
        $output = '<option ';
        nếu (isset($rooms) và $rooms == $no) $output .= 'selected="selected" ';
        $output .= 'value="'.$no.'">'.$no.'</option>';
        echo $output;
    }
    ?>
    </select>
    </p>

    <p>
    <input class="<?php nếu (is_archive()) echo 'new-search '; ?>button" type="submit" name="search_props" value="<?php nếu (is_archive() hoặc is_post_type_archive('properties')) echo 'New '; ?>Tìm kiếm"></p>

    </form>
    </div>
    <?php
}

Nếu tôi tìm kiếm tất cả ba giá trị cùng một lúc (đại học, khu vực và phòng ngủ), trang hiển thị kết quả chính xác. Tuy nhiên, nếu bất kỳ hoặc tất cả các trường tùy chọn được để trống, sau đó không có bài đăng nào được trả về. $GLOBALS['wp_query']->request là tất cả các tùy chọn được chọn trả về:

    SELECT
    wp_posts.*
    TỪ wp_posts
    NỐI KẾT wp_term_relationships ON (wp_posts.ID = wp_term_relationships.object_id)
    NỐI KẾT wp_term_relationships AS tt1 ON (wp_posts.ID = tt1.object_id)
    NỐI KẾT wp_postmeta ON (wp_posts.ID = wp_postmeta.post_id)
    NƯỚC 1=1
    VÀ (wp_term_relationships.term_taxonomy_id IN (5) VÀ tt1.term_taxonomy_id IN (18,15))
    VÀ wp_posts.post_type = 'properties'
    VÀ (wp_posts.post_status = 'publish' HOẶC wp_posts.post_status = 'private')
    VÀ ( (wp_postmeta.meta_key = '_rooms' VÀ CAST (wp_postmeta.meta_value AS CHAR) = '4') )
    NHÓM BỞI wp_posts.ID
    ĐƯỢC XẾP HẠNG wp_posts.post_date DESC

... và nếu chỉ có đại học và các tùy chọn phòng ngủ được chọn:

    SELECT
    wp_posts.*
    TỪ wp_posts
    NỐI KẾT wp_postmeta ON (wp_posts.ID = wp_postmeta.post_id)
    NƯỚC 1=1
    VÀ 0 = 1
    VÀ wp_posts.post_type = 'properties'
    VÀ (wp_posts.post_status = 'publish' HOẶC wp_posts.post_status = 'private')
    VÀ ( (wp_postmeta.meta_key = '_rooms' VÀ CAST (wp_postmeta.meta_value AS CHAR) = '4') )
    NHÓM BỞI wp_posts.ID
    ĐƯỢC XẾP HẠNG wp_posts.post_date DESC

