Hạn chế quyền truy cập trong Bảng điều khiển quản trị viên Tôi muốn hạn chế quyền truy cập vào một số trang plugin / trang WP bình thường. Tôi đã tìm ra cách để ẩn những trang này khỏi menu nhưng hiện tại chưa thể hạn chế chúng. Ví dụ, tôi có một người chỉnh sửa và tôi không muốn họ có quyền truy cập vào "Media" và "Tools" - tôi có thể ẩn những trang này bằng đoạn mã sau:

function editor_menu() {
    global $menu;
    if(!current_user_can('administrator')) {
        $restricted = array(__('Media'),__('Tools'));
        end($menu);
        while (prev($menu)) {
            $value = explode(' ',$menu[key($menu)][0]);
            if(in_array($value[0] != NULL?$value[0]:"" , $restricted)) {unset($menu[key($menu)]);}
        }
    }
}
add_action('admin_menu', 'editor_menu', 999);

