API nhịp tim oEmbed Theo mặc định chạy nội dung thông qua bộ lọc `the_content` tự động kiểm tra nội dung oEmbed. Tuy nhiên khi trả về dữ liệu thông qua `heartbeat_received` bộ lọc cho oEmbed không có vẻ hoạt động. Ví dụ -

function test_heartbeat_received( $response, $data ) {
    if( $data['test_heartbeat'] == 'test' ) {
        $content = "https://twitter.com/WordPress/status/456502643738030080";
        // Không hoạt động
        global $wp_embed;
        $content = $wp_embed->autoembed( $content );
        $response['test_heartbeat'] = $content;
        // Cũng không hoạt động
        $response['test_heartbeat'] = apply_filters( 'the_content', $content );
    }
    return $response;
}
add_filter( 'heartbeat_received', 'test_heartbeat_received', 10, 2 );
add_filter( 'heartbeat_nopriv_received', 'test_heartbeat_received', 10, 2 );

Thực hiện chính xác cùng một điều mà không sử dụng Heartbeat có vẻ hoạt động. Bộ lọc nội dung đang được áp dụng vì định dạng tồn tại, chỉ là không có oEmbed. Các bạn có gợi ý nào không? Cảm ơn!

Nhận giá trị meta và người dùng liên quan Tôi đang làm việc trên một trang web mà người dùng có thể xuất bản bài viết với các trường tùy chỉnh liên quan đến chúng. Tôi muốn hiển thị các giá trị meta từ tất cả các bài viết, và bao gồm người dùng đã tạo bài viết mà giá trị meta xuất phát từ đó. Cho đến nay tôi đã có thể hiển thị tất cả các giá trị meta từ tất cả các bài viết. Mã của tôi:

function get_meta_values( $key = '', $type = 'workout', $status = 'publish' ) {
    global $wpdb;

    if ( empty( $key ) )
        return;

    $r = $wpdb->get_col(
        $wpdb->prepare( "
            SELECT pm.meta_value FROM {$wpdb->postmeta} pm
            LEFT JOIN {$wpdb->posts} p ON p.ID = pm.post_id
            WHERE pm.meta_key = '%s'
            AND p.post_status = '%s'
            AND p.post_type = '%s'",
            $key,
            $status,
            $type
        )
    );

    return $r;
}

$workout_leader= get_meta_values( '1_rep', 'workout' );

foreach ( $workout_leader as $value ) {
    echo $value;
}

