function modify_post_query($query)
{
if ($query->get('post_type') == 'my_post_type' && !is_admin())
{
if (isset($_COOKIE["my_key"]) && $_COOKIE["my_key"] == "val1")
{
$query->set('meta_key', 'my_meta_key');
$query->set('meta_value', 'meta_value_1');
}
else
{
$query->set('meta_key', 'my_meta_key');
$query->set('meta_value', 'meta_value_2');
}
}
}
