function map_categories_link( $post_link, $id = 0 ){
$post = get_post($id);
if ( is_object( $post ) ){
$terms = wp_get_object_terms( $post->ID, 'map_categories' );
if( $terms ){
return str_replace( '%map_categories%' , $terms[0]->slug , $post_link );
}
}
return $post_link;
}

add_filter( 'post_type_link', 'map_categories_link', 1, 3 );

