// Hàm save_video_meta được gọi bên dưới với hành động "save_post" và lưu các ID vào bài viết

function save_video_meta($post_id, $post) {

// Xác minh rằng nó đến từ màn hình của chúng ta và với quyền ủy quyền thích hợp,
// bởi vì save_post có thể được kích hoạt vào những thời điểm khác

if ( !wp_verify_nonce( $_POST['video_noncename'], plugin_basename(__FILE__) )) {
return $post->ID;
}

// Người dùng có được phép chỉnh sửa bài viết hoặc trang không?

if ( !current_user_can( 'edit_post', $post->ID )){
return $post->ID;
}

$video_meta['_youtubeID'] = $_POST['_youtubeID'];
$video_meta['_vimeoID'] = $_POST['_vimeoID'];

foreach ($video_meta as $key => $value) { // Duyệt qua mảng $video_meta
if( $post->post_type == 'revision' ) return; // Không lưu dữ liệu tùy chỉnh hai lần

$value = implode(',', (array)$value); // Nếu $value là một mảng, hãy chuyển đổi nó thành CSV

if($value) {
update_post_meta($post_id, $key, $value);
} else
delete_post_meta($post_id, $key); // Xóa nếu trống
}
}

// Kết thúc hàm save_video_meta

// Lưu các trường tùy chỉnh video

add_action( 'save_post', 'my_save_postdata' );

function my_save_postdata($post_id){
$video_meta['_youtubeID'] = $_POST['_youtubeID'];
$video_meta['_vimeoID'] = $_POST['_vimeoID'];

foreach ($video_meta as $key => $value) { // Duyệt qua mảng $video_meta
if( $_POST['post_type'] == 'revision' ) return; // Không lưu dữ liệu tùy chỉnh hai lần

$value = implode(',', (array)$value); // Nếu $value là một mảng, hãy chuyển đổi nó thành CSV

if(get_post_meta($post_id, $key, FALSE)) { // Nếu trường tùy chỉnh đã có giá trị
update_post_meta($post_id, $key, $value);
} else { // Nếu trường tùy chỉnh chưa có giá trị
add_post_meta($post_id, $key, $value);
}

if(!$value) delete_post_meta($post_id, $key); // Xóa nếu trống
}
}

