Cách nào để upload hình ảnh và đính kèm vào Woocommerce product gallery? Tôi có đoạn mã sau đây, nó nhận một hình ảnh, tải lên máy chủ của tôi và đặt nó làm hình ảnh nổi bật. Làm thế nào tôi có thể thay đổi nó để thêm hình ảnh vào thư viện sản phẩm trong WooCommerce? Có lẽ như tạo và đính kèm siêu dữ liệu?

function postmeta_img_update($postid, $img) {
    global $post;
    require_once(ABSPATH . 'wp-includes/pluggable.php');

    // Nếu trường siêu dữ liệu tùy chỉnh cho hình ảnh/nhán nhỏ không tồn tại
    if (!get_post_meta($postid, "skipimage", true)) : // nếu siêu dữ liệu tồn tại thì bỏ qua
        // Lấy phần mở rộng tệp
        $ext = substr(strrchr($img, '.'), 1);

        // Thư mục tải lên của WordPress để sao chép (phải được CHMOD thành 777)
        $uploads = wp_upload_dir();
        $copydir = $uploads['path'] . "/";

        // Mã để sao chép hình ảnh vào thư mục tải lên của WordPress (máy chủ phải hỗ trợ file_get_content/fopen/fputs)
        $data = file_get_contents($img);
        $filetitle = strtolower(str_replace(array(' ', '-', '.', '(', ')', '!', '@', '#', '$', '%', '^', '&', '*', '_', '=', '+'), "-", get_the_title()));
        $file = fopen($copydir . "$filetitle-$postid.$ext", "w+");
        fputs($file, $data);
        fclose($file);

        // Chèn hình ảnh vào thư viện đa phương tiện của WordPress
        $filepath = $uploads['path'] . "/$filetitle-" . $post->ID . "$ext";
        $wp_filetype = wp_check_filetype(basename($filepath), null);
        $attachment = array(
            'post_mime_type' => $wp_filetype['type'],
            'post_title' => get_the_title(),
            'post_content' => 'Image for ' . get_the_title(),
            'post_status' => 'inherit'
        );
        wp_insert_attachment($attachment, $filepath, $postid);

        // Lấy ID Phụ thuộc để chèn vào bài viết
        global $wpdb;
        $attachment_id = $wpdb->get_var("SELECT ID FROM $wpdb->posts WHERE post_parent = '$postid' AND post_status = 'inherit' AND post_type='attachment' ORDER BY post_date DESC LIMIT 1");

        // Đính kèm hình ảnh làm hình thu nhỏ nổi bật trong bài viết
        update_post_meta($postid, "_thumbnail_id", $attachment_id);
    endif;
}

Khó khăn khi tạo chức năng tự động làm sạch khi tải lên video Tôi đang cố gắng tạo ra một công cụ tùy chỉnh chủ đề trong Wordpress cho phép người dùng tải lên một video MP4 và WEBM, và để làm điều đó tôi cần tạo một tùy chọn khử trùng để xác minh loại file. Tôi gặp một số khó khăn và vẫn có thể tải lên mọi loại tệp... Đây là những gì tôi đang làm:

