Tuy nhiên, tôi không biết cách viết hàm! Tôi có thể viết một vòng lặp thông thường và lọc kết quả, giống như tôi sẽ làm ở phía phía trước, nhưng tất cả những gì tôi cần làm là hiển thị cùng một thông tin như trang quản trị bình thường, nhưng hiển thị các sự kiện đã trôi qua. Đây là cách tôi lọc màn hình chỉnh sửa bài viết tùy chỉnh để chỉ hiển thị các sự kiện trong tương lai:

function concerts_pre_get_posts($query) {
    if (is_admin()) {
        if (isset($query->query_vars['post_type'])) {
            if ($query->query_vars['post_type'] == 'concerts') {
                $query->set('meta_key', 'date_value');
                $query->set('orderby', 'meta_value');
                $query->set('order', 'ASC');
                $query->set('meta_compare', '>=');
                $query->set('meta_value', time());
            }
        }
    }
}

add_filter('pre_get_posts' , 'concerts_pre_get_posts');

