Tôi dùng add_rewrite_rule ở đâu? Tôi cần phải thêm một RewriteRule vào trang web của mình. Tôi đã thử trong .htaccess mà không có kết quả, nó không được phân tích, vì vậy tôi đang gần như từ bỏ nó. Tôi đã tìm thấy tài liệu về add_rewrite_rule, nhưng không biết tôi nên sử dụng nó ở đâu. Tôi không viết một plugin. Tôi cần thêm một quy tắc đơn giản. Tôi đã đi đến tệp functions.php nằm trong thư mục chủ đề hiện tại. Đây là cái tôi sử dụng à? Tôi đã chèn đoạn sau:
add_action('init', 'add_news_rule3');
function add_news_rule3() {
add_rewrite_rule('^/content/([^/]*)/([^/]*)\.htm$', '/content/$matches[1] [NC,R=301,L]', 'top');
}
Tôi cũng đã thử, dựa trên một bài đăng tôi đã thấy ở nơi khác:
add_action('generate_rewrite_rules', 'add_news_rule');
function add_news_rule($wp_rewrite) {
$new_rules = array('^/content/([^/]*)/([^/]*)\.htm$' => '/content/$matches[1] [NC,R=301,L]');
$wp_rewrite->rules = $new_rules + $wp_rewrite->rules;
}
add_filter('rewrite_rules_array', 'add_news_rule2');
function add_news_rule2($rules) {
$new_rules = array('^/content/([^/]*)/([^/]*)\.htm$' => '/content/$matches[1] [NC,R=301,L]');
return $new_rules + $rules;
}

Xem bài viết x trong y thuộc danh mục Tôi hiện đang sử dụng lớp này trong các bài viết đơn lẻ để nhận được số bài viết tổng cộng và đánh số cho bài viết của tôi (Bài viết 89 của 90, v.v...)

class MY_Post_Numbers {
private $count = 0;
private $posts = array();

public function display_count() {
$this->init(); // ngăn chặn những truy vấn không cần thiết
$id = get_the_ID();
echo sprintf( '<div class="post-counter">Số bài viết<span class="num">%s</span><span class="slash">/</span><span class="total">%s</span></div>', $this->posts[$id], $this->count );
}

private function init() {
if ( $this->count )
return;
global $wpdb;

$posts = $wpdb->get_col( "SELECT ID FROM $wpdb->posts WHERE post_status = 'publish' AND post_type = 'post' ORDER BY post_date " ); // có thể thêm hoặc thay đổi thứ tự nếu muốn
$this->count = count($posts);
foreach ( $posts as $key => $value ) {
$this->posts[$value] = $key + 1;
}
unset($posts);
}
}

$GLOBALS['my_post_numbers'] = new MY_Post_Numbers;

function my_post_number() {
$GLOBALS['my_post_numbers']->display_count();
}

