Tắt chế độ đăng xuất / đăng nhập tự động của WordPress 3.6 Tôi quản lý một trang web WordPress lưu trữ trên WPEngine đã được nâng cấp lên phiên bản 3.6 gần đây. Việc nâng cấp này giới thiệu "Đăng nhập trực tuyến sau khi hết thời gian", và đó là vấn đề ở đây. Trang web được sử dụng để quản lý đăng ký, phân công phòng và các chức năng tương tự cho một khu nghỉ dưỡng. Điều này có nghĩa là WordPress thường được mở, nhưng không được sử dụng tích cực, trong nhiều giờ liền. Trước phiên bản 3.6 mọi thứ đều ổn, nhưng bây giờ khách hàng phàn nàn về cửa sổ đăng nhập mới bật lên "thường xuyên" (mỗi 2-3 phút hoặc mỗi 20 phút, tùy thuộc vào ai được hỏi). Câu hỏi của tôi ngắn gọn như thế này: Làm thế nào để vô hiệu hóa hoặc kéo dài phiên làm việc chịu trách nhiệm cho cửa sổ bật lên mới này? Tôi đã thử sử dụng bộ lọc `auth_cookie_expiration`, nhưng điều này chỉ có vẻ ảnh hưởng đến việc đăng xuất giữa các lần tải trang và không có tác động gì đến cửa sổ bật lên đăng nhập trực tuyến. Mã đầy đủ của những gì tôi đã thử:

function myplugin_cookie_expiration( $expiration, $user_id, $remember ) {
// Nếu hộp "Ghi nhớ tôi" được đánh dấu, giữ phiên làm việc trong 14 ngày. Ngoài ra
// chỉ giữ phiên làm việc trong 2 giờ
return $remember ? 1209600 : 7200;
}
add_filter( 'auth_cookie_expiration', 'myplugin_cookie_expiration', 99, 3 );

Có vẻ như đã có câu hỏi tương tự như vậy đã được đăng trước đây, nhưng không có phản hồi... Cảm ơn trước vì bất kỳ thông tin nào bạn có thể cung cấp!

kiểm tra nếu thanh bên đã đăng ký có hoạt động và có nội dung widget Tôi muốn kiểm tra xem một thanh bên đã đăng ký có nội dung widget hay không, nhưng không thể tìm thấy một hàm của WP cho trường hợp này - is_active_widget kiểm tra xem nó có nội dung hay không, nhưng không kiểm tra sự tồn tại hay không.

function ql_widget( $widget, $widget_name, $element = 'sider' ){
if ( $widget ) { // tên widget được truyền đi ##
// kiểm tra xem widget có đang hoạt động hay không - trả về html & nội dung widget nếu đúng ##
if ( is_active_sidebar( $widget ) ) {
echo '
<div class="'.$element.'">';
dynamic_sidebar( $widget );
echo '</div>';
} else {
// phát sinh lỗi nếu widget được yêu cầu không tồn tại hoặc trống ##
if ( ql_user_is_administator() ) { // người dùng là quản trị viên ##
if ( dynamic_sidebar( $widget ) ) { // trống ##
$message = 'empty';
} else { // ID hoặc tên widget sai ##
$message = 'error';
}
?>
<div class="error"><strong>Widget <?php echo $message; ?>:</strong>
<?php echo $widget_name ? $widget_name : $widget ; ?></div>
<?php
}
}
}
}
}
