Giúp đỡ với chức năng Bài viết liên quan Tôi đang cố gắng viết một hàm sẽ hiển thị các bài viết liên quan theo thuật ngữ của một phân loại. Tuy nhiên, tôi gặp khó khăn khi cố gắng truy vấn nhiều thuật ngữ. Cách tôi đang thực hiện bây giờ là sử dụng thuật ngữ đầu tiên để hiển thị các bài viết liên quan. Bạn có ý tưởng nào về cách kiểm tra xem nó có phải là nhiều thuật ngữ không?

function related_posts($related_type, $related_tax) {
global $wpdb, $post;
// Lấy thuật ngữ liên quan
$terms = array();
foreach(wp_get_object_terms($post->ID, $related_tax) as $term){
$terms[] = $term->slug;
};
// Lấy thuật ngữ đầu tiên từ mảng
$related_term = array_shift(array_values($terms));
// Truy vấn các bài viết liên quan
$related_posts = $wpdb->get_results(
"
SELECT *
FROM $wpdb->posts
LEFT JOIN $wpdb->term_relationships ON($wpdb->posts.ID = $wpdb->term_relationships.object_id)
LEFT JOIN $wpdb->term_taxonomy ON($wpdb->term_relationships.term_taxonomy_id = $wpdb->term_taxonomy.term_taxonomy_id)
LEFT JOIN $wpdb->terms ON($wpdb->term_taxonomy.term_id = $wpdb->terms.term_id)
WHERE $wpdb->posts.post_type = '$related_type'
AND $wpdb->posts.post_status = 'publish'
AND $wpdb->term_taxonomy.taxonomy = '$related_tax'
AND $wpdb->terms.slug = '$related_term'
AND $wpdb->posts.ID <> $post->ID
ORDER BY $wpdb->posts.post_date DESC
"
);
if($related_posts) {
echo '<ul>';
foreach ($related_posts as $post):setup_postdata($post);
echo '<li><a href="'.get_permalink().'">'.get_the_title().'</a></li>';
endforeach;
echo '</ul>';
} else {
echo 'Không tìm thấy bài viết liên quan';
}
}
Tôi muốn có một thứ gì đó như: nếu thuật ngữ này OR thuật ngữ này OR thuật ngữ này thì hiển thị tất cả các bài viết liên quan. Tôi đã từng sử dụng $wpdb->terms.slug IN ('$terms') nhưng điều này chỉ hiển thị các bài viết liên quan với sự khớp chính xác.

