// cũng cần phải thêm vào
function fileupload_process() {
$uploadfiles = $_FILES['uploadfiles'];
if (is_array($uploadfiles)) {
foreach ($uploadfiles['name'] as $key => $value) {
// chỉ tìm kiếm các tập tin đã tải lên
if ($uploadfiles['error'][$key] == 0) {
$filetmp = $uploadfiles['tmp_name'][$key];
// xóa tên tập tin và trích xuất phần mở rộng
$filename = $uploadfiles['name'][$key];
// lấy thông tin về tập tin
// @fixme: wp kiểm tra phần mở rộng tập tin....
$filetype = wp_check_filetype( basename( $filename ), null );
$filetitle = preg_replace('/\.[^.]+$/', '', basename( $filename ) );
$filename = $filetitle . '.' . $filetype['ext'];
$upload_dir = wp_upload_dir();

/**
* Kiểm tra xem tên tập tin có tồn tại trong thư mục hay không và đổi tên tập tin nếu cần thiết
*/
$i = 0;
while ( file_exists( $upload_dir['path'] .'/' . $filename ) ) {
$filename = $filetitle . '_' . $i . '.' . $filetype['ext'];
$i++;
}
$filedest = $upload_dir['path'] . '/' . $filename;

/**
* Kiểm tra quyền ghi
*/
if ( !is_writeable( $upload_dir['path'] ) ) {
$this->msg_e('Không thể ghi vào thư mục %s. Thư mục này có thể ghi bởi máy chủ?');
return;
}

/**
* Lưu tập tin tạm thời vào thư mục tải lên
*/
if ( !@move_uploaded_file($filetmp, $filedest) ){
$this->msg_e("Lỗi, tập tin $filetmp không thể di chuyển đến : $filedest ");
continue;
}
$attachment = array(
'post_mime_type' => $filetype['type'],
'post_title' => $filetitle,
'post_content' => '',
'post_status' => 'inherit'
);
$attach_id = wp_insert_attachment( $attachment, $filedest );
require_once( ABSPATH . "wp-admin" . '/includes/image.php' );
$attach_data = wp_generate_attachment_metadata( $attach_id, $filedest );
wp_update_attachment_metadata( $attach_id,  $attach_data );
}
}
}
}
}
