Hiển thị bài viết mới nhất mà không có 301 redirect Trang web WordPress của tôi hiện đang chuyển hướng đến bài viết mới nhất bằng cách thêm chức năng sau vào file `function.php`:

add_action( 'template_redirect', 'redirect' );

function redirect() {
    $args = array(
        'numberposts' => 1,
        'post_type' => 'seller',
        'post_status' => 'publish'
    );

    $last = wp_get_recent_posts($args);
    $last_id = $last['0']['ID'];

    if ( is_home() && ! is_paged() && ! is_archive() && ! is_tag() && !isset($_GET['ptype']) ) :
        wp_redirect( get_permalink($last_id) , 301 );
        exit;
    endif;
}

