get_the_content("more...") trả về toàn bộ nội dung Tôi đang tạo mã ngắn [latest_post] và muốn hiển thị ngày bài viết, tiêu đề và nội dung tóm tắt. (nội dung có "more" phân cách). Đây là mã:

function shortcode_latest_post() {
    global $post, $more;
    $tmp_post = $post;
    $tmp_more = $more;
    $posts = get_posts(array('numberposts' => 1, 'post_status' => 'publish'));
    $output = "";
    foreach($posts as $post) {
        setup_postdata($post);
        $more = 0;
        $output .= '<div class="latest_post">';
        $output .= '<span class="date">'. get_the_date() . '</span>';
        $output .= '<h3><a href="'. get_permalink() .'">'. get_the_title() .'</a></h3>';
        $output .= get_the_content("Đọc tiếp...");
        $output .= "</div>";
    }
    $post = $tmp_post;
    $more = $tmp_more;
    return $output;
}
add_shortcode("latest_post", "shortcode_latest_post");

