get_term_link không hiển thị Tôi đã tạo một widget hiển thị danh sách sản phẩm theo danh mục trong WooCommerce. Tôi không thể khiến tiêu đề widget liên kết đến trang danh mục sản phẩm. Tiêu đề của danh mục hiển thị tốt nhưng tôi không thể khiến liên kết hoạt động với get_term_link. Dưới đây là mã:

public function widget( $args, $instance ) {
    $title = apply_filters( 'widget_title', $instance['title'] );
    $product_cat = apply_filters( 'widget_title', $instance['product_cat'] );
    $post_numb = apply_filters( 'widget_title', $instance['post_numb'] );
    $args1 = array(
        'post_status' => 'publish',
        'post_type' => 'product',
        'tax_query' => array(
            'taxonomy' => 'product_cat',
            'field' => 'id',
            'terms' => $product_cat
        ),
        'posts_per_page' => $post_numb
    );
    echo $args['before_widget'];
    if ( ! empty( $title ) )
        echo $args['before_title'] . '<a href="' . get_term_link($product_cat, 'product_cat') . '" >' . $title . '</a>' . $args['after_title'];
    wp_reset_query();
    $the_query = new WP_Query( $args1 );
    if ( $the_query->have_posts() ) {
        echo "<ul>";
        while ( $the_query->have_posts() ) {
            $the_query->the_post();
            echo '<li><a href="' . get_permalink() . '" >' . get_the_title() . '</a></li>';
        }
        echo "</ul>";
        //wp_reset_query();
    }
    echo $args['after_widget'];
}

