Lọc get_adjacent_post() cho bài viết riêng tư, cách chỉnh sửa JOIN/WHERE? Tôi có một plugin mu lọc truy vấn WP để rằng trong vòng lặp chỉ mục, một khách truy cập chỉ nhìn thấy các bài đăng mà họ có thể đọc. Nó làm điều này bằng cách cung cấp cho tác giả bài đăng khả năng gán một phân loại thành viên đa cấp cho mỗi bài đăng. Ở mức thấp nhất (công khai), không có phân loại thành viên nào được đính kèm với bài đăng. Đây là bộ lọc truy vấn trong plugin mu:

nếu (! class_exists ('Site_Members_Taxonomy')) {
lớp Site_Members_Taxonomy
// định nghĩa ('LANG', 'some_textdomain'); xóa LANG, đang ném lỗi
công khai $ post_types = mảng ('post', 'page', 'gallery');
công khai $ tax = 'thành viên';
công khai $ tax_label; // THAY ĐỔI: biến này ba công khai
chức năng __construct()
{
$this->tax_label = __('Membership');
// plugin xác định phân loại và thành viên meta và sau đó:
thêm_hành động ('pre_get_posts', mảng (& $this, 'filter_query'));
/**
* Sửa đổi truy vấn dựa trên phân loại thành viên
*/
hàm filter_query ($ query) {
// thoát ngay lập tức nếu trong quản trị
nếu (is_admin()) trả về;
$ tax_query = '';
$ terms = $this->get_terms_to_exclude(); // xem hàm bên dưới
nếu ($ terms)
$ tax_query = mảng (
mảng (
'taxonomy' => $this->tax,
' trường' => 'slug',
'terms' => $terms,
'nhà điều hành' => 'NOT IN'
)
);
// nếu sau tất cả chúng tôi có một truy vấn thuế để thực hiện, hãy làm điều đó!
nếu ($ tax_query)
set_query_var ('tax_query', $ tax_query);
}
} // kết thúc lớp
$ Site_Members_Taxonomy toàn cầu;
$ Site_Members_Taxonomy = new Site_Members_Taxonomy();
}
// cuối cùng, bên ngoài định nghĩa lớp, có một hàm `members_can_view` được sử dụng làm điều kiện để ẩn/hiện các thẻ mẫu khác nhau v.v.
cho đến nay, rất tốt. Bộ lọc này hoạt động tuyệt vời. Vấn đề là, trong chế độ xem bài đăng duy nhất, `next_post_link()` và `previous_post_link()` không nhận được bộ lọc, vì vậy khách truy cập có thể điều hướng đến các bài đăng mà họ **không** thể đọc. Tôi muốn lọc các liên kết đến các bài đăng này để chỉ hiển thị liên kết đến bài đăng tiếp theo mà họ thực sự có thể đọc. Về cơ bản, tôi muốn sử dụng bộ lọc truy vấn trên get_adjacent_post(). Trong WP core trac cho link-template.php ( cũng như trong bài đăng Kaiser liên kết đến bên dưới) Tôi tìm thấy `next_post_link()`, `get_next_post()` và `get_adjacent_post()` chạy truy vấn bài đăng liền kề qua các bộ lọc sau:

* `get_{$adjacent}_post_join`
* `get_{$adjacent}_post_where`
* `get_{$adjacent}_post_sort`

**SỬA ĐỔI BỘ LỌC GIAO HỢP / ĐÂU**

Tôi đã thử việc sửa đổi sau đây của G.M. về GIAO HỢP / ĐÂU được đề xuất trong câu trả lời của anh ấy. Như anh ấy nói, nó rất dựa trên hàm wp-core, với tr và tt được đặt tên khác nhau và các điều khoản bị loại trừ được truyền trực tiếp vào hàm. Hàm này hiện đang hoạt động trên trang web và không gây ra lỗi, tuy nhiên nó cũng không lọc đúng truy vấn bài đăng liền kề.

**Câu hỏi hiện tại:** Khi chuyển đổi $excluded_terms từ slug thành ID trong hàm _filter_adjacent_ bên dưới, tôi có đang xây dựng đúng mảng không? Làm thế nào tôi có thể ghi nhật ký các điều khoản bị loại trừ và tìm hiểu những gì đang xảy ra?

// Bộ lọc cho get_adjacent_posts() để chúng không hiển thị trong điều hướng bài đăng duy nhất
// Các bộ lọc này được thêm vào trong hàm __construct{} được lưu ý ở trên
// THAY ĐỔI: & $this thành $this
thêm_hành động ('get_previous_post_where', mảng ($this, 'filter_adjacent'));
thêm_hành động ('get_next_post_where', mảng ($this, 'filter_adjacent'));
thêm_hành động ('get_previous_post_join', mảng ($this, 'filter_adjacent'));
thêm_hành động ('get_next_post_join', mảng ($this, 'filter_adjacent'));
/**
* Những hàm này được thêm vào trong lớp plugin mu:
*
* Đầu tiên, sửa đổi các điều khoản bị loại trừ dựa trên phân loại thành viên
*
* Lưu ý: Các điều khoản bị loại trừ có thể là một mảng
*/
hàm get_terms_to_exclude() {
// nếu là quản trị viên thực hoặc "level1" chúng tôi sẽ không thay đổi truy vấn thuế
nếu (current_user_can ('manage_options') || current_user_can ('view_level1_posts'))
trả về sai;
// mặc định/công khai sẽ loại trừ tất cả các bài đăng cấp cao hơn
// nói cách khác, tất cả các bài đăng có phân loại thành viên
$ terms = mảng ('level1', 'level2', 'level3');
// nếu là người đọc level3 chúng tôi sẽ loại trừ các bài đăng level1 và level2
nếu (current_user_can ('view_level3_posts'))
$ terms = mảng ('level1', 'level2');
// nếu ở cấp độ level2 chúng tôi sẽ loại trừ các bài đăng cấp level1
nếu (current_user_can ('view_level2_posts'))
$ terms = mảng ('level1');
trả về $terms;
}
/**
* Tiếp theo, sử dụng các điều khoản này để lọc get_adjacent_post JOIN / WHERE
*/
hàm filter_adjacent ($ clause) {
nếu (substr_count (current_filter(), '_post_join')) { // lọc giao hợp
nếu (empty ($ clause)) $ clause = '';
toàn cầu $wpdb;
$ clause .=
"INNER JOIN {$wpdb->term_relationships} AS trmship ON p.ID = trmship.object_id
INNER JOIN {$wpdb->term_taxonomy} ttmship
ON trmship.term_taxonomy_id = ttmship.term_taxonomy_id";
trả về $clause;
} nếu (substr_count (current_filter(), '_post_where')) { // lọc nơi
$ excluded_term_slugs = get_terms_to_exclude();
nếu (! $excluded_term_slugs) trả về $clause; // không có gì để lọc nếu không có điều khoản
$ excluded_terms = mảng (); // chúng tôi cần id thuật ngữ, hãy chuyển đổi slug trong các id thuật ngữ
foreach ($excluded_term_slugs as $slug) {
$ t = get_term_by ('slug', $ slug, 'thành viên');
nếu (! $t hoặc is_wp_error ($ t)) tiếp tục;
$ excluded_terms [] = $ t;
}
// có điều gì đó sai trong get_level_term_to_exclude()?
nếu (empty ($excluded_terms)) trả về $where;
$ posts_in_ex_terms_sql =
"VÀ ttmship.taxonomy = 'thành viên'
VÀ ttmship.term_id KHÔNG IN (" . implode ($excluded_terms, ',') . ')';
// trả về mệnh đề lọc
trả về $clause. $posts_in_ex_terms_sql;
}
}

Mã kịch bản bên ngoài sử dụng WP - Hooks / Actions không hoạt động? Tôi đã nghiên cứu kỹ vấn đề này, nhưng vẫn chưa tìm ra giải pháp. **Để nói đơn giản, tôi có một đoạn mã tải lên bên ngoài để tải WordPress. Tuy nhiên, tôi không thể sử dụng bất kỳ hành động/lọc nào mà tôi đã đặt vào nó. Tại sao vậy?** Tôi đã thử nhiều phương pháp khác nhau để tải WordPress trong đoạn mã. Đoạn mã này trả về 404 khi trình tải lên (javascript) gọi nó:

```php
define( 'WP_USE_THEMES', false );
require_once '../../wp-blog-header.php');
```

Vậy là một giải pháp thay thế mà tôi tìm thấy, dường như hoạt động tốt:

```php
require_once '../../wp-config.php');
$wp->init();
$wp->parse_request();
$wp->query_posts();
$wp->register_globals();
```

Ví dụ trên hoạt động tốt, ngoại trừ tôi không thể tìm ra cách nào để kết nối với nó. Ngay cả khi tôi đặt toàn bộ bộ xử lý tải lên vào một hàm và kết nối với các vị trí khác nhau như ...

```php
add_action('plugins_loaded', 'the_upload_processing_function');
//hoặc
add_action('wp_loaded', 'the_upload_processing_function');
//và vân vân...
```

Kết quả là không có phản hồi. Đoạn mã sẽ chạy nếu tôi để nó bên ngoài hàm, chỉ chạy dưới mã khởi động WordPress, **nhưng các móc / hành động không hoạt động**. Kết quả mà tôi không thể đạt được:

* Plugin gọi đoạn mã tải lên qua javascript, upload.php (hoạt động)...
* Plugin có thể tải trước đoạn mã tải lên, và tùy thuộc vào biến $_POST, nó sẽ thay đổi đường dẫn thư mục đích bằng cách sử dụng bộ lọc: Đây là bộ lọc...

```php
$targetDir = apply_filters('ss_upload_destination', $targetDir);
```

* Do đó, $targetDir nên được thay đổi, nhưng các móc dường như không hiển thị cho plugin. Không có cách nào để bắt lấy nó. Tôi đã cố gắng mô tả vấn đề mà không khiến vấn đề trở nên quá dài. Tôi rất cảm kích bất kỳ thông tin nào có thể được chia sẻ.

**Để tham khảo, đây là toàn bộ đoạn mã tải lên:**

```php
<?php
require_once '../../wp-config.php');
$wp->init();
$wp->parse_request();
$wp->query_posts();
$wp->register_globals();
//define( 'WP_USE_THEMES', false );
//require_once '../../wp-blog-header.php');
if(!is_user_logged_in())
   die();
// Đảm bảo tệp không được lưu trữ bộ nhớ đệm (như xảy ra ví dụ trên các thiết bị iOS)
header("Expires: Mon, 26 Jul 1997 05:00:00 GMT");
header("Last-Modified: " . gmdate("D, d M Y H:i:s") . " GMT");
header("Cache-Control: no-store, no-cache, must-revalidate");
header("Cache-Control: post-check=0, pre-check=0", false);
header("Pragma: no-cache");
/*
// Hỗ trợ CORS
header("Access-Control-Allow-Origin: *");
// các tiêu đề CORS khác nếu có...
if ($_SERVER['REQUEST_METHOD'] == 'OPTIONS') {
   exit; // kết thúc yêu cầu CORS trước bay ở đây
}
*/
// 5 phút thời gian thực thi
//@set_time_limit(5 * 60);
// Bình luận điều này để giả thời gian tải lên
// usleep(5000);
// Cài đặt
$targetDir = ss_upload_dir . ss_blog_path . '/';
if(!is_numeric($_REQUEST['upload_destination']))
   die;
$blog_id = $_REQUEST['upload_destination'];
switch_to_blog($blog_id);
$path = ss_get_blog_path($blog_id);
$targetDir = ss_upload_dir . $path . '/';
$targetDir = apply_filters('ss_upload_destination', $targetDir);
//$targetDir = 'uploads';
$cleanupTargetDir = false; // Xóa các tệp cũ
$maxFileAge = 5 * 3600; // Tuổi tệp tạm thời tính theo giây
// Nhận tên tệp
if (isset($_REQUEST["name"])) {
   $fileName = $_REQUEST["name"];
} elseif (!empty($_FILES)) {
   $fileName = $_FILES["file"]["name"];
} else {
   $fileName = uniqid("file_");
}
$filePath = $targetDir . $fileName;
// Phân đoạn có thể được bật
$chunk = isset($_REQUEST["chunk"]) ? intval($_REQUEST["chunk"]) : 0;
$chunks = isset($_REQUEST["chunks"]) ? intval($_REQUEST["chunks"]) : 0;
// Xóa các tệp tạm thời cũ
if ($cleanupTargetDir) {
   if (!is_dir($targetDir) || !$dir = opendir($targetDir)) {
      die('{"jsonrpc" : "2.0", "error" : {"code": 100, "message": "Không thể mở thư mục tạm thời."}, "id" : "id"}');
   }
   while (($file = readdir($dir)) !== false) {
      $tmpfilePath = $targetDir . $file;
      // Nếu tệp tạm thời là tệp hiện tại thì tiếp tục sang phần tiếp theo
      if ($tmpfilePath == "{$filePath}.part") {
         continue;
      }
      // Xóa tệp tạm thời nếu nó cũ hơn tuổi tối đa và không phải là tệp hiện tại
      if (preg_match('/\.part$/', $file) && (filemtime($tmpfilePath) < time() - $maxFileAge)) {
         @unlink($tmpfilePath);
      }
   }
   closedir($dir);
}
// Mở tệp tạm thời
if (!$out = @fopen("{$filePath}.part", $chunks ? "ab" : "wb")) {
   die('{"jsonrpc" : "2.0", "error" : {"code": 102, "message": "Không thể mở luồng đầu ra."}, "id" : "id"}');
}
if (!empty($_FILES)) {
   if ($_FILES["file"]["error"] || !is_uploaded_file($_FILES["file"]["tmp_name"])) {
      die('{"jsonrpc" : "2.0", "error" : {"code": 103, "message": "Không thể di chuyển tệp đã tải lên."}, "id" : "id"}');
   }
   // Đọc luồng đầu vào nhị phân và thêm nó vào tệp tạm thời
   if (!$in = @fopen($_FILES["file"]["tmp_name"], "rb")) {
      die('{"jsonrpc" : "2.0", "error" : {"code": 101, "message": "Không thể mở luồng đầu vào."}, "id" : "id"}');
   }
} else {
   if (!$in = @fopen("php://input", "rb")) {
      die('{"jsonrpc" : "2.0", "error" : {"code": 101, "message": "Không thể mở luồng đầu vào."}, "id" : "id"}');
   }
}
while ($buff = fread($in, 4096)) {
   fwrite($out, $buff);
}
@fclose($out);
@fclose($in);
// Kiểm tra xem tệp đã được tải lên hay chưa
if (!$chunks || $chunk == $chunks - 1) {
   // Bỏ đi hậu tố .part tạm thời
   rename("{$filePath}.part", $filePath);
   do_action('ss_file_upload_complete', $filePath);
}
do_action('ss_after_upload');
// Trả về phản hồi JSON-RPC thành công
die('{"jsonrpc" : "2.0", "result" : null, "id" : "id"}');
```

Overide enqueue trong các hàm không thể cắm được thông qua chủ đề con Tôi đang cố gắng ghi đè một hàm không thể cắm bằng thông tin trên trang này nhưng dường như không có tác dụng. Có ai phát hiện ra lỗi gì không? Mã của tôi là
