Kiểm tra phiên bản PHP trước khi kích hoạt chủ đề Tôi có một chủ đề yêu cầu phiên bản php 5.3+. Nếu không, lỗi nghiêm trọng xảy ra cùng với nó. Vì vậy điều tôi cần làm khi người dùng cố gắng kích hoạt chủ đề này là kiểm tra phiên bản php trước khi đi vào mã chủ đề và sau đó, nếu phiên bản php quá cũ, hiển thị một số thông báo và **không** kích hoạt chủ đề của tôi, nhưng ở lại với chủ đề đã được kích hoạt trước đó. Liệu điều đó có thể không? Tôi có mã này để kiểm tra phiên bản:

define("THEME_REQUIRED_PHP_VERSION", '5.3.0');
define("THEME_IGNORE_PHP_VERSION", 0);

//kiểm tra nếu phiên bản php tốt
if ( !THEME_IGNORE_PHP_VERSION && version_compare(phpversion(), THEME_REQUIRED_PHP_VERSION, '<') ) {
//phiên bản php không đủ cao
wp_die("<h2>Bạn cần cập nhật phiên bản php.</h2>Phiên bản PHP quá cũ để chạy Circle Theme. Phiên bản thực tế là <strong>" . phpversion() . "</strong>, yêu cầu là <strong>" . CIRCLE_REQUIRED_PHP_VERSION . "</strong>.", "Theme");
}

Tuy nhiên điều này không thể vì chủ đề vẫn được kích hoạt và người dùng không thể làm gì cả.

Lọc tất cả các bài viết và bài viết được ghim thông qua meta_query Tôi có một bộ lọc mà lọc các bài viết từ vòng lặp chính dựa trên vai trò của người dùng (điều khiển bên ngoài) dữ liệu siêu là nhập khi thêm một bài đăng / trang. Đây là bộ lọc - nó hoạt động để lọc các bài viết từ các vòng lặp trang chủ và các trang tìm kiếm nhưng bài đăng **dính** bị bỏ qua và sẽ hiển thị bất kể vai trò của người dùng. Những thứ này có không được bao gồm trong main_query?
add_filter('pre_get_posts', 'hide_private_posts');

function hide_private_posts($query) {
$loggedInArray = array(
'key' => 'smartPrivate',
'value' => 'smartPrivate_loggedIn',
'compare' => '!='
);
$mentorArray = array(
'key' => 'smartPrivate',
'value' => 'smartPrivate_loggedInMentors',
'compare' => '!='
);
// Nếu người dùng không đăng nhập, ẩn tất cả các bài đăng / trang riêng tư
nếu (! is_user_logged_in()) {
nếu ($query->is_main_query() || $query->is_feed()) {
$query->set('meta_query', array(
$loggedInArray,
$mentorArray
));
}
// Nếu người dùng đã đăng nhập nhưng là học viên, hiển thị các bài đăng / trang đã đăng nhập
khác nếu (is_user_sso_role(array('learner'))) {
nếu ($query->is_main_query() || $query->is_feed()) {
$query->set('meta_query', array(
$mentorArray
));
}
}
trả về $query;
}

