$url = get_permalink ( $page->ID ) . 'wp-admin/post.php?post=' . $page->ID . '&action=edit'; // url chỉnh sửa bài viết
$wp_admin_bar->add_menu ( array ( // hiển thị mục menu cấp cao nhất 'chỉnh sửa trang'
'title' => $title,
