Metabox tùy chỉnh đơn giản không lưu lại dữ liệu Tôi không chắc chắn tại sao nhưng tôi đã thử nghiệm với nhiều giải pháp khác nhau nhưng không có giải pháp nào hoạt động được. Tôi đã thay thế 'update_post_meta' bằng 'add_post_meta' và thậm chí chia nó thành 3 điều kiện để kiểm tra xem nó có đang thêm, cập nhật hay xóa không nhưng vẫn không hiệu quả gì cả. Vấn đề là nó không lưu lại dữ liệu và hiển thị khi cập nhật. Tôi biết rằng '_desc' đã được thiết lập vì dữ liệu được hiển thị khi tôi sử dụng hàm 'die()' (ngay trước khi cập nhật). Các bạn có thể cho tôi biết cách để tìm ra lý do tại sao nó không được cập nhật?

/** Thêm hộp meta */
function add_custom_meta_box() {
    global $meta_box;
    add_meta_box(
        'short-desc', // $id
        'Short Description', // $title
        'show_custom_meta_box', // $callback
        'post', // $page
        'side', // $context
        'high'); // $priority
}
add_action('add_meta_boxes', 'add_custom_meta_box');

/** Hàm callback */
function show_custom_meta_box() {
    global $post;
    // Sử dụng nonce để xác minh
    echo '<input type="hidden" name="shortdesc_meta_box_nonce" value="'.wp_create_nonce(basename(__FILE__)).'" />';
    // Lấy giá trị của trường này nếu nó tồn tại trong bài viết
    $meta = get_post_custom($post->ID);
    // Bắt đầu bảng trường
    echo '<table class="form-table"><tr><td>';
    echo '<strong>Nhập mô tả ngắn:</strong>
    <input type="text" name="_desc" id="short-desc" value="'.$meta['_desc'].'" size="30" />';
    echo '</td></tr></table>'; // kết thúc bảng
}

/** Lưu dữ liệu */
function save_custom_meta($post) {
    // Xác minh nonce
    if (!wp_verify_nonce($_POST['shortdesc_meta_box_nonce'], basename(__FILE__)))
        return $post->ID;
    // Kiểm tra autosave
    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE)
        return $post->ID;
    // Kiểm tra quyền
    if (!current_user_can('edit_post', $post->ID))
        return $post->ID;
    //echo $_POST['_desc'];
    //die();
    if(isset($_POST['_desc']))
        update_post_meta($post->ID, '_desc', strip_tags($_POST['_desc']));
