function SearchFilter($query) {
nếu ( is_admin() ||! $query->is_main_query() )
trở về;
nếu ( $query->is_search ) {
// thiết lập mảng rỗng
$beds_query = array();
$baths_query = array();
$price_query = array();
// thiết lập truy vấn cho giường
nếu (! trống ( $query->query['beds'] ) ) {
$beds_query = array(
'khóa' => 'giường',
'giá trị' => sanitize_text_field($query->query['beds']),
'so sánh' => '> =',
);
}
// thiết lập truy vấn cho phòng tắm
nếu (! trống ( $query->query['baths'] ) ) {
$baths_query = array(
'khóa' => 'phòng tắm',
'giá trị' => sanitize_text_field($query->query['baths']),
'so sánh' => '> =',
);
}
nếu (! trống ( $query->query['min-price'] ) ||! trống ( $query->query['max-price'] ) ) {
$min_price = ( trống ( $query->query['min-price'] ) ) ? 0 : $query->query['min-price'];
$max_price = ( trống ( $query->query['max-price'] ) ) ? 999999999 : $query->query['max-price'];
$price_query = array(
'khóa' => 'giá',
'giá trị' => mảng ( sanitize_text_field($min_price), sanitize_text_field($max_price) ),
// 'loại' => 'số học',
'so sánh' => 'giữa'
);
}
$meta_query = array(
'relationship' => 'VÀ',
$beds_query,
$baths_query,
$price_query
);
$query->set( 'meta_query', $meta_query );
$query->set( 'posts_per_page', 1 );
} // kết thúc is_search và tài sản lưu trữ
trở về $query;
}
