Lấy hình ảnh nổi bật với trực tiếp $wpdb trong plugin Tôi đang sử dụng một phiên bản tùy chỉnh của plugin Last Viewed Posts để thu thập các bản phát hành gần đây trên trang web của tôi. Mã tôi đang sử dụng thu thập một hình ảnh đính kèm nhưng nó không phải lúc nào cũng là hình ảnh nổi bật trên trang - kết quả không ổn định. Đây là mã:

function zg_recently_viewed() {
// Output
echo '<ul style="list-style:none; padding-left:0px;font-size:11px;" class="viewed_posts">';
if (isset($_COOKIE["WP-LastViewedPosts"])) {
//echo "Cookie was set.<br/>"; // Để gỡ lỗi - bỏ chú thích để xem nếu cookie được thiết lập
//echo $_COOKIE["WP-LastViewedPosts"]; // Để gỡ lỗi (nội dung cookie)
$zg_post_IDs = unserialize(preg_replace('!s:(\d+):"(.*?)";!e', "'s:'.strlen('$2').':\"$2\";'", stripslashes($_COOKIE["WP-LastViewedPosts"]))); // Đọc mảng được mã hóa từ cookie và giải mã nó
//echo $_COOKIE["WP-LastViewedPosts"];
foreach ($zg_post_IDs as $value) { // Thực hiện đầu ra miễn là có bài viết
global $wpdb;
$zg_get_title = $wpdb->get_results("SELECT post_title FROM $wpdb->posts WHERE ID = '$value+0' AND ID IN ( SELECT object_id FROM $wpdb->term_relationships WHERE term_taxonomy_id = '5' ) LIMIT 1");
$thumb = $wpdb->get_var("SELECT ID FROM $wpdb->posts where post_parent = '$value' and post_type = 'attachment'");
/* $thumb = $wpdb->get_var( "SELECT meta_value FROM {$wpdb->postmeta} where post_parent = '$value' AND meta_key = '_thumbnail_id'" ); */
