function restrict_manage_posts() {

// Chỉ hiển thị các bộ lọc phân loại này trên danh sách loại bài viết tùy chỉnh mong muốn

global $typenow;

if ($typenow == 'blocks') {

// Tạo một mảng các slug phân loại mà bạn muốn lọc - nếu bạn muốn lấy tất cả các phân loại, có thể sử dụng get_taxonomies() để xây dựng danh sách

$filters = array('location', 'section');

foreach ($filters as $tax_slug) {

// Lấy đối tượng phân loại

$tax_obj = get_taxonomy($tax_slug);

$tax_name = $tax_obj->labels->name;

// Lấy mảng các thuật ngữ cho mỗi phân loại

$terms = get_terms($tax_slug);

// Xuất ra html cho bộ lọc thả xuống phân loại

echo "<select name='$tax_slug' id='$tax_slug' class='postform'>";

echo "<option value=''>Show All $tax_name</option>";

foreach ($terms as $term) {

// Xuất ra mỗi dòng tùy chọn, so sánh với $_GET cuối cùng để hiển thị tùy chọn hiện tại được chọn

echo '<option value='. $term->slug, $_GET[$tax_slug] == $term->slug ? ' selected="selected"' : '','>' . $term->name .' (' . $term->count .')</option>';

}

echo "</select>";

}

}

}

