public function jobs_by_codes( $show_counts = 1, $hierarchical = 1, $show_uncategorized = 1, $orderby = '' ) {
    global $typenow, $wp_query,$wpdb;

    if ( $typenow != 'job_listing')
        return;

    $r = array();
    $r['pad_counts'] = 1;
    $r['hierarchical'] = $hierarchical;
    $r['hide_empty'] = 1;
    $r['show_count'] = $show_counts;
    $r['selected'] = ( isset( $wp_query->query['job_code'] ) ) ? $wp_query->query['job_code'] : '';
    $r['menu_order'] = false;

    if ( $orderby == 'order' )
        $r['menu_order'] = 'asc';
    elseif ( $orderby )
        $r['orderby'] = $orderby;

    $terms = get_terms( 'job_code', $r );

    if ( ! $terms )
        return;

    $output = "<input type='text' name='job_code' id='input_job_code' value='' placeholder='Jobk Code'/>";
    echo $output;
}

