Thêm hành động để tạo bài viết mới sau khi wp_insert_post đã bắn? Tôi nghĩ nó đang tạo một vòng lặp vô hạn Tôi cần lấy meta của một bài viết và tạo một bài viết tùy chỉnh. Tôi đang sử dụng đoạn mã sau đây nhưng nghĩ rằng nó đang tạo ra một vòng lặp vô tận. Khi wp_insert_post được kích hoạt, hàm create_cptpost được thực thi, nhận ID bài viết được tạo ra và tôi cần tạo một bài viết mới trong loại bài viết tùy chỉnh và cập nhật meta của bài viết đó. Có cách nào khác để thực hiện điều này không? Mục tiêu cơ bản của tôi là sao chép nội dung của bài viết bình thường đầu tiên vào một bài viết mới trong loại bài viết tùy chỉnh.

function create_mycpt( $post_id ) {
  $post = get_post($post_id, ARRAY_A);
  if ( wp_is_post_revision( $post_id ) )
    return;
  $ac1 = get_field('ac_1',$post_id);
  $my_post = array(
    'post_title' => 'Tiêu đề',
    'post_type' => 'mycpt'
  );
  $pid = wp_insert_post( $my_post );
  update_post_meta($pid, 'ac_1', $ac1);
}
add_action( 'wp_insert_post', 'create_mycpt' );

