Tôi không phải là người giỏi trong việc gọi ajax, vì vậy xin hãy tha thứ cho tôi nếu đây là điều gì đó rõ ràng. Nhưng tôi thực sự tuyệt vọng gần đây với điều này và xin vui lòng - giúp đỡ.

Thêm nội dung tùy chỉnh vào trang không tồn tại Tôi đang cố gắng thêm nội dung vào trang 404. Ví dụ tôi muốn định nghĩa nội dung bài viết cho mysite.com/existing-page/imaginary-page thay vì hiển thị trang 404. Tôi đã thử nhiều cách khác nhau nhưng không hiệu quả, vì vậy tôi rất mong nhận được sự giúp đỡ của bạn. Cấu trúc thực tế của tôi là: mysite.com/personal-development/class. Mysite.com/personal-development tồn tại nhưng mysite.com/personal-development/class không tồn tại. Mysite.com/personal-development/class sẽ hiển thị nội dung thay đổi từ mysite.com/personal-development nếu dường như add_rewrite_rule sẽ hoạt động nếu trang lớp thực sự tồn tại.

add_action( 'init', 'dynamic_classes_class_type_rewrite' );

function dynamic_classes_class_type_rewrite()
{
    global $wp_rewrite;
    add_rewrite_tag( '%personal-development%', '([^&]+)' );
    add_rewrite_rule(
        '^personal-development/([^/]*)/?',
        'index.php?page_id=17318&class_type=$matches[1]',
        'top'
    );
}

Mã này bắt được trang và hủy bỏ trang 404. Nó sau đó hiển thị nội dung trang chủ nhưng không sử dụng các bảng phong cách mẫu hoặc cho phép tôi thay đổi nội dung. Ví dụ bên dưới là nỗ lực của tôi để nhận được nội dung phù hợp và hiển thị nó. Tôi cũng đã thử hiển thị một mẫu khác. Tôi có thể hiển thị mẫu, nhưng vẫn không thể hiển thị nội dung nào cả.

add_filter('template_redirect', 'dynamic_classes_class_type_redirect' );

function dynamic_classes_class_type_redirect()
{
    //for best seo I am setting up a redirect for pages.
    global $wp, $wpdb, $wp_query;
    if(!$post_title=get_post($post)->post_title)//looks like we hit a 404
    {
        $url=explode('/',dynamic_classes_page_url());//see if its one of our dynamically created pages.
        if(count($url)>4)//we need to make sure this long enough
        {
            $db_prefix= $wpdb->prefix;
            $sql='SELECT ID
                  FROM '.$db_prefix.'posts
                  WHERE post_name=\''.implode('',array_slice($url,-2,1)).'\' /*get the second to last*/
                  LIMIT 1';
            $rs_class = $wpdb->get_results($sql);
            if($rs_class)
            {
                status_header( 200 );
                $wp_query->is_404=false;
                wp_reset_query();
                setup_postdata(get_post($rs_class[0]->ID));
            }
        }
    }
}

add_action và 'the_post' sẽ cho phép tôi thay đổi nội dung theo nhu cầu, nhưng không phải đối với các trang 404 - ngay cả khi tôi hủy bỏ trang 404 như trong ví dụ trên.

add_action( 'the_post', 'my_the_post_action' );

function my_the_post_action( $post_object )
{
    $post_object->post_content='Programmer test.';
}

