*/
protected static $theme_options = array();
/**
* Options Page title
* @var string
*/
protected $title = '';
/**
* Constructor
* @since 0.1.0
*/
public function __construct() {
// Đặt tiêu đề cho chúng ta
$this->title = __( 'Madame Noire Options', 'myprefix' );
}
/**
* Khởi tạo các hook của chúng ta
* @since 0.1.0
*/
public function hooks() {
add_action( 'admin_init', array( $this, 'mninit' ) );
add_action( 'admin_menu', array( $this, 'add_page' ) );
}
/**
* Đăng ký cài đặt của chúng ta với WP
* @since  0.1.0
*/
public function mninit() {
register_setting( self::$key, self::$key );
}
/**
* Thêm trang menu options
* @since 0.1.0
*/
public function add_page() {
$this->options_page = add_menu_page( $this->title, $this->title, 'manage_options', self::$key, array( $this, 'admin_page_display' ) );
add_action( 'admin_head-' . $this->options_page, array( $this, 'admin_head' ) );
}
/**
* CSS, v.v...
