* @since  0.1.0
*/
public function admin_page_display() {
?>
<div class="wrap">
<h2><?php echo esc_html( get_admin_page_title() ); ?></h2>
<?php cmb_metabox_form( $this->option_fields(), self::$key ); ?>
</div>
<?php
}
/**
* Định nghĩa cấu hình metabox và trường tùy chỉnh cho tùy chọn chủ đề
* @since  0.1.0
* @return array
*/
public static function option_fields() {
// Chỉ cần khởi tạo mảng một lần mỗi lần trang được tải
if ( ! empty( self::$theme_options ) )
return self::$theme_options;
self::$theme_options = array(
'id' => 'theme_options',
'show_on' => array(
'key' => 'options-page',
'value' => array( self::$key, ),
),
'show_names' => true,
'fields' => array(
array(
'name' => __( 'Test Text', 'cmb' ),
'desc' => __( 'field description (optional)', 'cmb' ),
'id' => $prefix . 'test_text',
