),
)
);
return self::$theme_options;
}
/**
* Làm cho biến $key được bảo vệ thành công khai.
* @since  0.1.0
* @return string  Option key
*/
public static function key() {
return self::$key;
}
}
// Bắt đầu sử dụng nó
