function register_post_type( $post_type, $args = array() ) {
    global $wp_post_types, $wp_rewrite, $wp;

    if ( !is_array($wp_post_types) )
        $wp_post_types = array();

    // Các tham số có dấu gạch dưới là dành cho mục đích sử dụng nội bộ.

    $defaults = array(
        'labels' => array(), 'description' => '', 'publicly_queryable' => null, 'exclude_from_search' => null,
        'capability_type' => 'post', 'capabilities' => array(), 'map_meta_cap' => null,
        '_builtin' => false, '_edit_link' => 'post.php?post=%d', 'hierarchical' => false,
        'public' => false, 'rewrite' => true, 'has_archive' => false, 'query_var' => true,
        'supports' => array(), 'register_meta_box_cb' => null,
        'taxonomies' => array(), 'show_ui' => null, 'menu_position' => null, 'menu_icon' => null,
        'can_export' => true,
        'show_in_nav_menus' => null, 'show_in_menu' => null, 'show_in_admin_bar' => null,
        'delete_with_user' => null,
    );

    $args = wp_parse_args($args, $defaults);
    $args = (object) $args;

    $post_type = sanitize_key($post_type);

    $args->name = $post_type;

    if ( strlen( $post_type ) > 20 )
        return new WP_Error( 'post_type_too_long', __( 'Post types cannot exceed 20 characters in length' ) );

    // Nếu không được thiết lập, mặc định sẽ sử dụng thiết lập cho public.

    if ( null === $args->publicly_queryable )
        $args->publicly_queryable = $args->public;

    // Nếu không được thiết lập, mặc định sẽ sử dụng thiết lập cho public.

    if ( null === $args->show_ui )
        $args->show_ui = $args->public;

    // Nếu không được thiết lập, mặc định sẽ sử dụng thiết lập cho show_ui.

    if ( null === $args->show_in_menu || ! $args->show_ui )
        $args->show_in_menu = $args->show_ui;

    // Nếu không được thiết lập, mặc định sẽ sử dụng thiết lập cho việc hiển thị toàn bộ giao diện người dùng.

    if ( null === $args->show_in_admin_bar )
        $args->show_in_admin_bar = true === $args->show_ui;

    // Xác định xem loại bài viết này có được hiển thị trong nav-menus.php hay không. Mặc định là thiết lập cho public.

    if ( null === $args->show_in_nav_menus )
        $args->show_in_nav_menus = $args->public;

    // Nếu không được thiết lập, mặc định là true nếu không phải là public, hoặc false nếu là public.

    if ( null === $args->exclude_from_search )
        $args->exclude_from_search = !$args->public;

    // Tương thích ngược với cách xử lý kỳ lạ trong phiên bản 3.0. #14122

    if ( empty( $args->capabilities ) && null === $args->map_meta_cap && in_array( $args->capability_type, array( 'post', 'page' ) ) )
        $args->map_meta_cap = true;

    if ( null === $args->map_meta_cap )
        $args->map_meta_cap = false;

    $args->cap = get_post_type_capabilities( $args );

    unset($args->capabilities);

    if ( is_array( $args->capability_type ) )
        $args->capability_type = $args->capability_type[0];

    if ( ! empty($args->supports) ) {
        add_post_type_support($post_type, $args->supports);
        unset($args->supports);
    } elseif ( false !== $args->supports ) {
        // Thêm các tính năng mặc định

        add_post_type_support($post_type, array('title', 'editor'));
    }

    if ( false !== $args->query_var && !empty($wp) ) {
        if ( true === $args->query_var )
            $args->query_var = $post_type;
        else
            $args->query_var = sanitize_title_with_dashes($args->query_var);

        $wp->add_query_var($args->query_var);
    }

    if ( false !== $args->rewrite && ( is_admin() || '' != get_option('permalink_structure') ) ) {
        if ( ! is_array( $args->rewrite ) )
            $args->rewrite = array();

        if ( empty( $args->rewrite['slug'] ) )
            $args->rewrite['slug'] = $post_type;

        if ( ! isset( $args->rewrite['with_front'] ) )
            $args->rewrite['with_front'] = true;

        if ( ! isset( $args->rewrite['pages'] ) )
            $args->rewrite['pages'] = true;

        if ( ! isset( $args->rewrite['feeds'] ) || ! $args->has_archive )
            $args->rewrite['feeds'] = (bool) $args->has_archive;

        if ( ! isset( $args->rewrite['ep_mask'] ) ) {
            if ( isset( $args->permalink_epmask ) )
                $args->rewrite['ep_mask'] = $args->permalink_epmask;
            else
                $args->rewrite['ep_mask'] = EP_PERMALINK;
        }

        if ( $args->hierarchical )
