        add_permastruct( $post_type, "{$args->rewrite['slug']}/%$post_type%", $args->rewrite );
    }

    if ( $args->register_meta_box_cb )
        add_action('add_meta_boxes_' . $post_type, $args->register_meta_box_cb, 10, 1);

    $args->labels = get_post_type_labels( $args );

