function basetheme_nodetitle($before_title="",$after_title="",$link = true) {
    /*
     * basetheme_nodetitle() chỉ có thể được gọi bên trong vòng lặp
     * $before_title là thẻ ban đầu để bao quanh tiêu đề của bạn, thường là <h2> hoặc tương tự.
     * $after_title là thẻ sau tiêu đề, thường là </h2> hoặc tương tự. Chỉ hoạt động nếu $before_title KHÔNG rỗng
     * $link là liệu tiêu đề có nên được liên kết hay không. Mặc định là true
     */
    if(empty($before_title)){$before_title = '<h1 class="title" id="post-' . the_ID() . '">';$after_title = "</h1>";}
    if($link == false){$beforelink = '';$afterlink = '';}else{$beforelink = '<a rel="bookmark" href="' . the_permalink() . '">';$afterlink = '</a>';}
    echo $before_title . $beforelink . the_title() . $afterlink . $after_title;
}

