function myquery_custom_post_rewrite( $rewrite_rules ) {
    $myqueryslug = 'customposttype';
    $month_archive = array(
        $myqueryslug . '/([0-9]{4})/?$' => 'index.php?year=' . $wp_rewrite->preg_index(1) . '&post_type=' . $myqueryslug . '&paged=' . $wp_rewrite->preg_index(3)
    );
    $rewrite_rules = $month_archive + $rewrite_rules;
    return $rewrite_rules;
