Làm thế nào để lấy được category/tag trong URL cho các liên kết Pagination? Tôi có một chức năng phân trang tùy chỉnh trong functions.php. Nếu tôi ở URL: http://mysite.com/tag/dogs, liên kết tiếp theo hiện tại chỉ chứa /page/2. Làm thế nào để tôi có thể làm cho nó trông giống như /tag/dogs/page/2? Đây là chức năng tôi đang sử dụng: (ban đầu được đăng ở đây)

function pagination( $query, $baseURL = '' ) {
    if ( ! $baseURL )
        $baseURL = get_bloginfo( 'url' );

    $page = $query->query_vars["paged"];
    if ( !$page )
        $page = 1;

    $qs = $_SERVER["QUERY_STRING"] ? "?".$_SERVER["QUERY_STRING"] : "";

    // Chỉ cần thiết nếu có nhiều bài viết hơn số bài viết trên mỗi trang
    if ( $query->found_posts > $query->query_vars["posts_per_page"] ) {
        echo '<ul class="paging">';

        // Liên kết trước đó?
        if ( $page > 1 ) {
            echo '<li class="previous"><a href="'.$baseURL.'page/'.($page-1).'/'.$qs.'">« previous</a></li>';
        }

        // Vòng lặp qua các trang
        for ( $i=1; $i <= $query->max_num_pages; $i++ ) {
            // Trang hiện tại hay trang liên kết?
            if ( $i == $page ) {
                echo '<li class="active">'.$i.'</li>';
            } else {
                echo '<li><a href="'.$baseURL.'page/'.$i.'/'.$qs.'">'.$i.'</a></li>';
            }
        }

        // Liên kết tiếp theo?
        if ( $page < $query->max_num_pages ) {
            echo '<li><a href="'.$baseURL.'page/'.($page+1).'/'.$qs.'">next »</a></li>';
        }

        echo '</ul>';
    }
}

