Chuyển đổi ngày tháng tùy chỉnh post_date => future - bỏ lỡ lịch trình lỗi Tôi đang viết một bộ lập lịch sự kiện tùy chỉnh cho trang web của tôi cho phép mọi người dễ dàng vào và thiết lập bài viết để đăng trong tương lai. Lý do tôi ghi đè chức năng WordPress bình thường là vì tôi muốn làm cho nó thật đơn giản để chọn ngày, vì bài giảng chỉ nên được đăng vào Chủ nhật. Vì vậy, tôi có một lịch thả xuống tùy chỉnh chỉ cho phép bạn chọn các ngày Chủ nhật trong một tháng. Tuy nhiên, vấn đề của tôi là tất cả các bài viết của tôi đều hiển thị lỗi "Missed Schedule" trong bảng điều khiển quản trị viên. Tôi có thể khắc phục điều này bằng cách sử dụng "post_status" => "future" để liệt kê bài viết trên trang, nhưng điều này khá "hacky". Tại sao mã này lại cho tôi lỗi "Missed Schedule"?

function cfc_reset_sermondate( $data ) {
    if($data['post_type'] == 'sermon_post') {
        if($_POST['cfc_sermon_date']) {
            $date = $_POST['cfc_sermon_date'];
            // $date = DateTime::createFromFormat('D - M j, Y', $date);
            // $date = $date->format('Y-m-d');
            $date = createFromFormat($date);
            $postDate = strtotime($date);
            $data['post_date'] = $date;
            $todaysDate = strtotime( date( 'Y-m-d' ) );
            if ( $postDate > $todaysDate ) {
                $data['post_status'] = 'future';
            }
        }
    }
    return $data;
}

add_filter( 'wp_insert_post_data', 'cfc_reset_sermondate', '99', 1);

Đây là hàm createFromFormat:

function createFromFormat($date_ugly) {
    $schedule = 'Sunday - Sep 15, 2000';
    // %Y, %m và %d tương ứng với Y m và d của hàm date()
    // %I tương ứng với H, %M tương ứng với i và %p tương ứng với a
    $ugly = strptime($date_ugly, '%A - %b %e, %Y');
    $ymd = sprintf(
        // Đây là một chuỗi định dạng nhận tổng cộng sáu tham số thập phân
        // sau đó điền vào các chữ số 0 cho đến khi chúng có 4 hoặc 2 chữ số
        '%04d-%02d-%02d',
        $ugly['tm_year'] + 1900, // Sẽ được "111", vì vậy chúng tôi cần thêm 1900.
        $ugly['tm_mon'] + 1,      // Sẽ là tháng trừ đi 1, vì vậy chúng tôi thêm 1.
        $ugly['tm_mday'],
        $ugly['tm_hour'],
        $ugly['tm_min'],
        $ugly['tm_sec']
    );
    $new_schedule = new DateTime($ymd);
    return $new_schedule->format('Y-m-d');
}

