                </td>
            </tr><?php
        }

        function handle_request_options() {
            // Xác minh các tùy chọn và lưu trữ chúng để có thể sử dụng trong các bản nhập tự động
            if ( empty( $_POST['category'] ) || !ctype_digit( $_POST['category'] ) )
                $this->error( __( "Hãy đảm bảo bạn chọn một danh mục hợp lệ để nhập các bài đăng của bạn vào." ) );

            if ( empty( $_POST['author'] ) || !ctype_digit( $_POST['author'] ) )
                $this->error( __( "Bạn phải chọn một tác giả để gán cho tất cả các bài đăng." ) );

            if ( isset( $_POST['auto_import'] ) )
                $_POST['auto_import'] = true;
            else
                $_POST['auto_import'] = false;

            if ( isset( $_POST['include_rts'] ) )
                $_POST['include_rts'] = true;
            else
                $_POST['include_rts'] = false;

            if ( isset( $_POST['include_replies'] ) )
                $_POST['include_replies'] = true;
            else
                $_POST['include_replies'] = false;

            // Nếu có lỗi, hiển thị chúng, nếu không lưu trữ các tùy chọn và bắt đầu nhập
            if ( count( $this->errors ) ) {
                $this->step = 'greet';
            } else {
                $this->set_option( array(
                    'category' => (int) $_POST['category'],
                    'tags' => explode( ',', $_POST['tags'] ),
                    'author' => (int) $_POST['author'],
                    'include_replies' => (bool) $_POST['include_replies'],
                    'include_rts' => (bool) $_POST['include_rts'],
                    'auto_import' => (bool) $_POST['auto_import'],
                    'user_id' => $this->service->get_token()->get_meta( 'user_id' ),
                ) );
                $this->step = 'import';
            }
        }

        function build_request_url() {
            // URL yêu cầu cơ bản
            $url = "http://api.twitter.com/1/statuses/user_timeline.json?";
            $params = array(
                'user_id' => $this->get_option( 'user_id' ),
                'trim_user' => 'true',
                'count' => 75, // Nhiều hơn điều này và Twitter dường như trở nên không ổn định
                'include_entities' => 'true',
            );

            if ( false == $this->get_option( 'include_replies' ) )
                $params['exclude_replies'] = 'true';

            if ( true == $this->get_option( 'include_rts' ) )
                $params['include_rts'] = 'true';

            $url = $url . http_build_query( $params );

            if ( $this->auto_import ) {
                // Tìm bài đăng Tweet mới nhất của chúng tôi, và nhận được những bài đăng kể từ đó
                $latest = get_posts( array(
                    'numberposts' => 1,
                    'orderby' => 'date',
                    'order' => 'DESC',
                    'meta_key' => 'keyring_service', // Trong trường hợp có các bài phụ khác
                    'meta_value' => 'twitter',
                    'tax_query' => array( array(
                        'taxonomy' => 'post_format',
                        'field' => 'slug',
                        'terms' => array( 'post-format-standard' ), // Các bài đăng Twitter được lưu trữ dưới dạng bài phụ
                        'operator' => 'IN',
                    ) ),
                ) );

                // Nếu chúng tôi đã nhập một số, hãy bắt đầu từ bài đăng mới nhất
                if ( $latest ) {
                    $max = get_post_meta( $latest[0]->ID, 'twitter_id', true );
                    $url = add_query_arg( 'since_id', $max, $url );
                }
            } else {
                // Xử lý các bù trang (chỉ dành cho các yêu cầu không tự động nhập)
                $url = add_query_arg( 'page', $this->get_option( 'page', 0 ), $url );
            }

            return $url;
        }

