function avt_homepage_save_meta_box_data($post_id) {
    // Kiểm tra xem nonce của chúng tôi có được thiết lập hay không.
    if (!isset($_POST['avt_homepage_meta_box_nonce'])) {
        return;
    }

    // Xác minh rằng nonce là hợp lệ.
    if (!wp_verify_nonce($_POST['avt_homepage_meta_box_nonce'], 'avt_homepage_meta_box')) {
        return;
    }

    // Nếu đây là một bản tự động lưu, biểu mẫu của chúng tôi chưa được gửi, vì vậy chúng tôi không muốn làm gì cả.
    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
        return;
    }

    // Kiểm tra quyền của người dùng.
    if (isset($_POST['post_type']) && 'page' == $_POST['post_type']) {
        if (!current_user_can('edit_page', $post_id)) {
            return;
        }
    } else {
        if (!current_user_can('edit_post', $post_id)) {
            return;
        }
    }

    /* OK, bây giờ an toàn cho chúng tôi để lưu dữ liệu. */

    // Đảm bảo rằng nó được thiết lập.
    if (!isset($_POST['home_slider_display'])) {
        return;
    }

    // Làm sạch đầu vào của người dùng.
    $my_data = sanitize_text_field($_POST['home_slider_display']);

    // Cập nhật trường siêu dữ liệu trong cơ sở dữ liệu.
    update_post_meta($post_id, 'home_slider_display', $my_data);
}

add_action('save_post', 'avt_homepage_save_meta_box_data');

