// Tạo CEU nếu số tiền thanh toán được nhập thủ công

function generate_ceu( $post_id ) {

    // kiểm tra nonce

    if (!isset($_POST['invoice_meta_box_nonce']) || !wp_verify_nonce($_POST['invoice_meta_box_nonce'], 'invoice_meta_box')) {

        return $post_id;

    }

    // kiểm tra quyền năng

    if ('invoice' == $_POST['post_type']) {

        if (!current_user_can('edit_post', $post_id)) {

            return $post_id;

        }

    } elseif (!current_user_can('edit_page', $post_id)) {

        return $post_id;

    }

    // thoát khỏi autosave

    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {

        return $post_id;

    }

    // Kiểm tra xem số tiền thanh toán đã tồn tại hay chưa để chúng tôi không tạo ra một CEU khác

    if (!get_post_meta($post->ID, 'invoice_payment_amount', true)) {

        if (isset($_POST['invoice_payment_amount'])) {

            $title = 'CEU'.date('YmdHs');

            // Tạo bài đăng

            $new_post = array(

                'post_title'    =>  $title,

                'post_date_gmt' => strtotime('+5 minutes'), // Thiết lập thời gian xuất bản bài đăng là 5 phút từ bây giờ để tránh vòng lặp

                'post_status'   =>  'future',

                // Chọn: publish, preview, future, draft, v.v.

                'post_type' =>  'ceu',

                //'post',page' hoặc sử dụng loại bài đăng tùy chỉnh nếu bạn muốn

            );

            $pid = wp_insert_post($new_post);

        } // kết thúc kiểm tra cho mục nhập bài đăng

    } // kết thúc kiểm tra cho dữ liệu siêu dữ liệu

    } // kết thúc hàm

    add_action( 'save_post', 'generate_ceu');

