Không thể thao tác quy tắc ghi lại mà không gọi flush_rewrite_rules() mỗi lần. Tôi đang cố gắng tạo một trang web danh mục nhỏ với nhiều ngôn ngữ. Chỉ có vài trang (chủ blog không cần phải có nhiều ngôn ngữ), chủ yếu là các trang được tạo ra bởi plugin do tôi tự làm. (Sử dụng template_redirect, tôi không thể tìm ra cách nào sạch sẽ hơn?) Sử dụng bài viết trên SO về quy tắc ghi lại, tôi đang cố gắng thêm /%lang%/ vào URL của tôi. Mọi thứ hoạt động tốt khi tôi gọi flush_rewrite_rules() trong init, nhưng ngay khi tôi xóa nó $wp_rewrite->rules hoàn toàn trống. Tôi có bộ lọc sau trong init:

// Đăng ký các URL nhiều ngôn ngữ
add_rewrite_tag('%lang%', '(nl|en)');

// Bộ lọc cho việc ghi lại URL
add_filter('root_rewrite_rules', array(&$this, 'root_rewrite_rules'));
add_filter('page_rewrite_rules', array(&$this, 'page_rewrite_rules'));
add_filter('rewrite_rules_array', array(&$this, 'final_rules_correction'), PHP_INT_MAX, 1);

add_filter('page_link', array(&$this, 'rewrite_lang_in_permalink'), 11, 3);
add_filter('request', array(&$this, 'default_language'), 9);

Tất cả các phương thức này thực hiện cùng một điều như trong bài viết SO. Tôi biết việc thực hiện flush_rewrite_rules() mỗi lần là thói quen xấu, vì vậy tôi muốn tránh điều đó. Ngoài ra, có thể ghi lại các URL tùy chỉnh trong menu trỏ đến trang web không? (một số loại cách str_replace(base_url, base_url/%lang%/)?)

**SỬA ĐỔI: Thêm các phương thức chỉ để đề phòng**

public function root_rewrite_rules($rules)
{
    global $wp_rewrite;

    $struct = ltrim($wp_rewrite->get_date_permastruct(), '/');
    $struct = preg_replace('#^%lang%/?#', '', $struct);

    $root_structure = '/%lang%/'.$struct;

    return $wp_rewrite->generate_rewrite_rules($root_structure, EP_DATE) + $rules;
}

public function page_rewrite_rules($rules)
{
    global $wp_rewrite;

    if (empty($wp_rewrite->permalink_structure))
    {
        $wp_rewrite->page_structure = '';
        $page_structure = false;
    }
    else
    {
        $struct = ltrim($wp_rewrite->root.'%pagename%', '/');
        $struct = preg_replace('#^%lang%/?#', '', $struct);

        $wp_rewrite->page_structure = '/%lang%/'.$struct;
        $page_structure = $wp_rewrite->page_structure;
    }

    return $wp_rewrite->generate_rewrite_rules($page_structure, EP_PAGES, true, true, false, false) + $rules;
}

public function final_rules_correction($rules)
{
    global $wp_rewrite;

    $new_rules = array();
    $find = "nl|en";
    $find_find = '#(?<!\()('.preg_quote($find, '#').')#';
    $preg_node = str_replace('%%%', '(\d+)', preg_quote($wp_rewrite->preg_index('%%%'), '#'));

    foreach ($rules as $k => $v)
    {
        if (preg_match($find_find, $k))
        {
            $nk = preg_replace($find_find, '('.$find.')', $k);
            $parts = explode('?', $v);
            $index = array_shift($parts);
            $pv = implode('?', $parts);
            $pv = preg_replace_callback('#'.$preg_node.'#', function ($matches) use ($wp_rewrite) {
                return $wp_rewrite->preg_index($matches[1]+1);
            }, $pv);

            $nv = $index.'?lang='.$wp_rewrite->preg_index(1).(!empty($pv) ? '&'.$pv : '');

            $new_rules[$nk] = $nv;
        }
        else
        {
            $new_rules[$k] = $v;
        }
    }

    return $new_rules;
}

public function rewrite_lang_in_permalink($permalink, $post = 0, $leavename = false)
{
    return str_replace('%lang%', DatabaseHelper::get_active_language(), $permalink);
}

public function default_language($vars)
{
    if (array_diff(array_keys($vars), array('preview', 'page', 'paged', 'cpage')))
        $vars['lang'] = !empty($vars['lang']) ? $vars['lang'] : DatabaseHelper::Dutch;

    return $vars;
}

