add_filter( 'map_meta_cap', 'taylors_map_meta_cap', 10, 4 );
function taylors_map_meta_cap( $caps, $cap, $user_id, $args ) {
/* Nếu chỉnh sửa, xóa hoặc đọc một trang, lấy bài viết và đối tượng loại bài viết. */
if ( 'edit_pages' == $cap || 'delete_pages' == $cap || 'read_pages' == $cap ) {
$post = get_post( $args[0] );
$post_access = get_post_meta($post->ID, 'allow_access', true); //một mảng chứa các người dùng được phép truy cập bài viết này.
$post_type = get_post_type_object( $post->post_type );
/* Đặt một mảng rỗng cho các khả năng. */
$caps = array();
}
/* Nếu chỉnh sửa một trang, gán khả năng cần thiết. */
if ( 'edit_pages' == $cap && $post->post_type == 'page' && in_array(get_current_user_id(), $post_access) ) {
if ( $user_id == $post->post_author )
$caps[] = $post_type->cap->edit_life_stages_children_pages;
else
$caps[] = $post_type->cap->edit_others_life_stages_children_pages;
}
/* Nếu xóa một trang, gán khả năng cần thiết. */
elseif ( 'delete_pages' == $cap && $post->post_type == 'page' && in_array(get_current_user_id(), $post_access) ) {
if ( $user_id == $post->post_author )
$caps[] = $post_type->cap->delete_life_stages_children_pages;
else
$caps[] = $post_type->cap->delete_others_life_stages_children_pages;
}
/* Nếu đọc một trang riêng tư, gán khả năng cần thiết. */
elseif ( 'read' == $cap && $post->post_type == 'page' && in_array(get_current_user_id(), $post_access) ) {
if ( 'private' != $post->post_status )
$caps[] = 'read';
elseif ( $user_id == $post->post_author )
$caps[] = 'read';
else
$caps[] = $post_type->cap->read_private_life_stages_children_pages;
}
/* Trả về các khả năng cần thiết của người dùng. */
return $caps;
}

Làm thế nào để thiết lập một đường dẫn tùy chỉnh, cho thư mục tải lên hình ảnh ajax trong quản trị viên? Tôi đang mã hóa plugin Wordpress đầu tiên của tôi để xử lý một số dữ liệu cho một loại bài viết tùy chỉnh (giống như cửa hàng). Nó cũng có trình tải lên hình ảnh trong một metabox, nơi bạn chỉ cần kéo vào hình ảnh của bạn và nó sẽ tự động xử lý tải lên, tên tệp và tích hợp thư viện đa phương tiện mà không làm mới trang. (AJAX) Để làm điều này tôi sử dụng JavaScript cho kéo và thả và gửi AJAX để gửi hình ảnh đến một chức năng wp ở phía sau. Tôi sử dụng `media_handle_upload()` mà wordpress cung cấp. Nó tạo ra các hình thu nhỏ và thực hiện quá trình tải lên bằng cách sử dụng `wp_handle_upload()` nó cũng thực hiện phần cơ sở dữ liệu cho tôi mà là khá thoải mái.

Mã cho phần này:

// // WP AJAX: UPLOAD FILES //
add_action('wp_ajax_save_attachments', function ($post) {
    $file = $_FILES['file'];
    if(!empty($file) && $file['size'] > 0) {
        if(isset($_POST['apt_post_id'])) {
            $post_id = $_POST['apt_post_id'];
            // lấy loại tệp và kiểm tra xem có được phép tải lên hay không
            $filetype = wp_check_filetype(basename($file['name']));
            $allowed_filetypes = array(
                'image/jpeg',
                'image/png',
                'image/gif',
            );
            if(in_array($filetype['type'], $allowed_filetypes)) {
                // Thiết lập mảng tùy chọn để thêm tệp này dưới dạng tệp đính kèm
                $post_data = array(
                    "post_title" => 'Testimage',
                    "post_content" => "",
                    "post_status" => "inherit",
                );
                $overrides = array( 'test_form' => false );
                if( $attachment_id = media_handle_upload('file', $post_id, $post_data, $overrides) ) {
                    $attachments = get_attached_media('image', $post_id);
                    $attachment = get_object_vars($attachments[$attachment_id]);
                    $data = array(
                        'ID' => $attachment['ID'],
                        'thumbnail' => wp_get_attachment_thumb_url($attachment['ID']),
                        'name' => $attachment['post_title'],
                    );
                    echo json_encode(array(
                        'success' => true,
                        'message' => 'Hình ảnh đã được tải lên thành công!',
                        'attachment' => $data,
                    ));
                    die;
                }
            } else {
                // xử lý lỗi
            }
        } else {
            // xử lý lỗi
        }
    } else {
        // xử lý lỗi
    }
});

Bây giờ tôi muốn tải hình ảnh lên một thư mục cụ thể như `/wp-root/wp-content/uploads/apartments/` để làm điều này tôi phát hiện ra rằng một người có thể đặt bộ lọc: `add_filter( 'upload_dir', array($this, 'wpUploadDir') );`mà tôi đã thử và kiểm tra với tải lên "bình thường" (không phải AJAX) và nó hoạt động tốt. Nhưng làm điều tương tự với tải lên AJAX không có tác dụng gì cả. Nó luôn tải hình ảnh vào thư mục `../2014/07/`. Có cách nào để thay đổi điều này không? Tôi đã thử đặt cuộc gọi bộ lọc trong 'admin_init' hoặc 'init' hoặc thậm chí trước đó, nhưng không có gì có vẻ hoạt động. Tôi không thể tìm thấy bất cứ điều gì trên Google có thể giải quyết câu hỏi của tôi, vì vậy tôi ở đây. Cảm ơn bạn vì bất kỳ gợi ý và giải pháp nào!

SỬA ĐỔI: Cách tôi tích hợp cuộc gọi bộ lọc:

Ở trạng thái này lớp của tôi khá hỗn loạn, nhưng hoạt động tốt cho đến nay... (sẽ làm sạch sau). Tôi cố gắng chỉ hiển thị mã cần thiết vì nó sẽ dài hơn 1000 dòng mã nếu tôi đăng tất cả. Như tôi đã đề cập trước đó, tôi đã thử 3 cuộc gọi bộ lọc. Ở đây bạn có thể thấy tất cả chúng được đánh dấu bằng các bình luận.

new Zap('zap_apartments');
class Zap
{
    // một số riêng tư...

    /**
     * Lưu trữ thư mục tải lên cho loại bài viết này
     */
    private $_upload_dir = '/apartments';

    public function __construct($post_type_id)
    {
        // đặt post_type_id theo đối số
        $this->post_type_id = $post_type_id;

        // đặt post_type là một đối tượng mới từ Fixture
        $this->post_type = new wpObjectsData($this->post_type_id);

        // MỘT THỨ THỨC THỨC ĐỂ Thêm GỌI BỘ LỌC:
        // add_filter( 'upload_dir', array($this, 'wpUploadDir') );

        // chạy khi kích hoạt plugin
        $this->wpPluginActivation();

        // chạy khởi tạo wp toàn cầu
        $this->wpInit();

        // chạy khởi tạo wp quản trị
        $this->wpAdminInit();
    }

    public function wpInit($post)
    {
        add_action('init', function($post) {
            // đăng ký loại bài viết cho wordpress
            $this->post_type->registerPostType();

            // đăng ký các danh mục cho wordpress
            $this->post_type->registerAllTaxonomies();

            // MỘT THỨ THỨC THỨC KHÁC ĐỂ Thêm GỌI BỘ LỌC:
            // add_filter( 'upload_dir', array($this, 'wpUploadDir') );
        });
    }

    public function wpAdminInit()
    {
        add_action('admin_init', function() {
            // MỘT THỨ THỨC THỨC KHÁC ĐỂ Thêm GỌI BỘ LỌC:
            // add_filter( 'upload_dir', array($this, 'wpUploadDir') );

            // đăng ký các tập lệnh wp
            add_action( 'admin_enqueue_scripts', array($this, 'wpRegisterScripts') );

            // gọi các metaboxes
            $this->metaboxes();
        });
    }

    /**
     * Thiết lập thư mục tải lên wp mới cho loại bài viết tùy chỉnh
     *
     * @param  []  (yêu cầu) mảng với cấu trúc _FILE
