add_filter('request', 'myfeed_request');

Sau đó, tôi gặp phải WPBeginner's Adding Additional Text to Post Titles in RSS và quyết định sửa đổi mã sau:

function wpbeginner_titlerss($content) {
  global $wp_query;
  $postid = $wp_query->post->ID;
  $gpost = get_post_meta($postid, 'guest_post', true);
  $spost = get_post_meta($postid, 'sponsored_post', true);

  if($gpost !== '') {
    $content = 'Guest Post: '.$content;
  }
  elseif ($spost !== ''){
    $content = 'Sponsored Post: '.$content;
  }
  else {
    $content = $content;
  }
  return $content;
}
add_filter('the_title_rss', 'wpbeginner_titlerss');

thành mã này để phù hợp với việc hiển thị các loại bài viết tùy chỉnh của tôi trong RSS:

function wpbeginner_titlerss($content) {
  global $wp_query;
  $post_type = $wp_query->post_type;

  if( get_post_type() == 'essays' ) {
