  }
  elseif ( get_post_type() == 'gallery' ){
    $content = 'Gallery: '.$content;
  }
  elseif ( get_post_type() == 'games' ){
    $content = 'Game: '.$content;
  }
  else {
    $content = $content;
  }
  return $content;
}
add_filter('the_title_rss', 'wpbeginner_titlerss');

Mã cuối cùng này không hiển thị các loại bài viết tùy chỉnh của tôi theo cách tôi muốn, bất kỳ ý tưởng/trợ giúp nào sẽ được đánh giá cao!

trang chủ vấn đề với kết quả tìm kiếm từ khóa Tôi đang sử dụng paginate_links nhưng nó lại tạo ra URL theo thứ tự sai khi trên trang kết quả tìm kiếm với một từ khóa. Do cấu trúc của trang web, tôi sử dụng GET để tìm kiếm với một loại bài viết tùy chỉnh được truyền qua URL. Thay vì http://localhost/site/page/2/?s=s&post_type=product nó lại tạo ra http://localhost/site/?s=s&post_type=product/page/2 Nếu tôi sử dụng previous_post_link và next_post_link mặc định thì mọi việc hoạt động tốt. Đây là hàm phân trang của tôi. Hãy cho tôi biết nếu bạn có thể tìm ra cách sắp xếp lại để nó tạo ra URL đúng.

function dl_pagination( $args = array() ) {
global $wp_query;
$total_pages = $wp_query->max_num_pages;
if ($total_pages > 1){
$current_page = max(1, get_query_var('paged'));
echo '<nav class="profile_box">';
echo paginate_links(array(
'base' => get_pagenum_link(1) . '%_%',
'format' => '/page/%#%',
'current' => $current_page,
'total' => $total_pages,
'prev_text' => '<i class="fa fa-chevron-left"></i>',
'next_text' => '<i class="fa fa-chevron-right"></i>',
'type' => 'list'
));
echo '</nav">';
}
}

