function get_post_ids_in_taxonomies($taxonomies, &$terms=array()) {
    $post_ids = array();
    $query = gen_query_get_posts_in_taxonomies($taxonomies, $terms);
    // var_dump($query);
    // Thực hiện truy vấn
    $queryObject = new WP_Query($query); //*****8 MEGABYTES BỊ RÒ Rỉ Ở ĐÂY*****
    // Đối với tất cả các bài viết được tìm thấy...
    if($queryObject->have_posts()) {
        while($queryObject->have_posts()) {
            $queryObject->the_post();
            // Lấy $post_id bằng cách bắt đầu đầu ra của the_ID()
            ob_start();
            the_ID();
            $post_id = (int) ob_get_contents();
            ob_end_clean();
            // echo $post_id."\n";
            $post_ids[] = $post_id;
        }
    }
    unset($queryObject);
    return $post_ids;
}

gen_query_get_posts_in_taxonomies() là:

function gen_query_get_posts_in_taxonomies($taxonomies, &$terms=array()) {
    // Các tham số truy vấn chung
    $query = array(
        'posts_per_page'    => -1,  //Lấy tất cả các bài viết (không có trang)
        'tax_query'             => array('relation' => 'OR'),
    );
    // Thêm các taxonomies và terms cụ thể vào $query['tax_query']
    foreach($taxonomies as $tax) {
        // Lấy các terms trong taxonomies nếu chúng chưa tồn tại
        if(!array_key_exists($tax, $terms)) {
            $terms[$tax] = array();
            $terms_tmp = get_terms($tax);
            foreach($terms_tmp as $tt)
                $terms[$tax][] = $tt->term_taxonomy_id;
        }
        $query['tax_query'][] = array(
            'taxonomy' => $tax,
            'terms' => $terms[$tax],
            'field' => 'term_taxonomy_id',
        );
    }
    return $query;
}

Tạo menu động mới bao gồm các liên kết BP Có lẽ tôi đã bỏ lỡ điều gì đó cơ bản, nhưng tôi đang cố gắng bao gồm các mục menu động khác nhau được tích hợp với BuddyPress và các tiện ích bổ sung khác vào menu thả xuống chính của tôi. Ví dụ, chủ đề Twenty Mười Một WP có một header cao với menu thả xuống bên dưới header. Menu này có thể thao tác thông qua tùy chọn Hiển thị -> Menu trong wp-admin. BuddyPress thêm các mục menu riêng của nó vào thanh quản trị ở đầu trang nhưng không bao gồm các liên kết này trong menu thả xuống bên dưới header. Tôi muốn loại bỏ thanh quản trị hoàn toàn và di chuyển tất cả các liên kết động đến menu thả xuống. Tôi đã tạo một menu tùy chỉnh trong tệp `functions.php`:

```php
function register_my_menus() {
  register_nav_menus(
    array(
      'header-menu' => __( 'Nav Menu' )
    )
  );
}
add_action( 'init', 'register_my_menus' );
```

Và menu này được tải trong `header.php` với:

```php
<?php wp_nav_menu( array( 'theme_location' => 'header-menu' ) ); ?>
```

Tôi có thể thêm các liên kết riêng lẻ vào menu này bằng cách sử dụng hàm `wp_nav_menu_items`, nhưng dường như không thể sao chép cấu trúc menu động được tạo bởi chức năng `bp_nav` dựa trên người dùng. Ai có ý tưởng về cách tôi có thể di chuyển chức năng này? Hoặc có lẽ tôi đang nhìn vào cấu trúc menu không đúng?

