Custom walker nav - Thêm số thứ tự như lớp Tôi đang làm quen với bộ điều khiển tại thời điểm này, nhưng tôi cần một số hỗ trợ để đạt được hiệu ứng mong muốn. Bộ điều khiển của tôi trông giống như:

class ik_walker extends Walker_Nav_Menu {
    // Bắt đầu của phần menu con
    function start_lvl(&$output, $depth) {
        $output .= '<nav class="site-navigation" role="navigation">
                        <ul>';
    }
    // Kết thúc của phần menu con
    function end_lvl(&$output, $depth) {
        $output .= '
                        </ul>
                        <button id="menu" class="menu-button" type="button" role="button" aria-label="Menu Toggle">
                            <span class="icon-menu"></span>
                        </button>
                    </div>';
    }
    // Thêm mô tả vào đầu ra của mục menu
    function start_el(&$output, $item, $depth, $args) {
        global $wp_query;
        $indent = ( $depth ) ? str_repeat( "\t", $depth ) : '';
        $class_names = $value = '';
        $classes = empty( $item->classes ) ? array() : (array) $item->classes;
        $class_names = join( ' ', apply_filters( 'nav_menu_css_class', array_filter( $classes ), $item ) );
        $class_names = ' class="' . esc_attr( $class_names ) . '"';
        $output .= $indent . '<li id="menu-item-'. $item->ID . '"' . $value . $class_names .'>';
        $attributes  = ! empty( $item->attr_title ) ? ' title="'  . esc_attr( $item->attr_title ) .'"' : '';
        $attributes .= ! empty( $item->target )  ? ' target="' . esc_attr( $item->target     ) .'"' : '';
        $attributes .= ! empty( $item->xfn )        ? ' rel="'  . esc_attr( $item->xfn      ) .'"' : '';
        $attributes .= ! empty( $item->url )        ? ' href="'   . esc_attr( $item->url        ) .'"' : '';
        $item_output = $args->before;
        $item_output .= '<a'. $attributes .'>';
        $item_output .= $args->link_before . apply_filters( 'the_title', $item->title, $item->ID ) . $args->link_after;
        if(strlen($item->description)>2){ $item_output .= '<br /><span class="sub">' . $item->description . '</span>'; }
        $item_output .= '</a>';
        $item_output .= $args->after;
        $output .= apply_filters( 'walker_nav_menu_start_el', $item_output, $item, $depth, $args );
    }
}

Điều tôi cần là cho mỗi thẻ "a" trong thẻ "li" của menu điều hướng, nó phải có lớp riêng bắt đầu bằng chữ "c" sau đó là một số - bắt đầu từ 1.

