<script type="text/javascript">
jQuery(
function() {
//lấy tất cả thẻ anchor với thuộc tính rel là shareit
$('a[rel=shareit], #shareit-box').click(function(e) {
e.preventDefault();
//lấy chiều cao và vị trí top rồi tính giá trị left cho hộp chia sẻ
var height = $(this).height();
var top = $(this).offset().top;
//lấy giá trị left và tìm giá trị giữa
