    extract(shortcode_atts(array(
        'type' => 'simple',
        'parent_id' => '',
        'category' => '',
        'count' => '10',
        'link' => ''
    ), $attr));

    $data['events'] = $ec->getMultipleEvents($cal_type, $count, $parent_id, $category);
    $data['link'] = $link;
    $data['type'] = $type;

    $ec->displayCalendarList($data);
}

