echo $before_widget;
/* Hiển thị tiêu đề tiện ích nếu có đầu vào (trước và sau được xác định bởi các chủ đề). */
if ( $title )
echo $before_title . $title . $after_title;
/* Hiển thị tên từ cài đặt tiện ích nếu có đầu vào. */
if ( $name )
printf( '<p>' . __('Xin chào. Tôi là %1$s.', 'example') . '</p>', $name );
if ( $number )
printf( '<p>' . __('Xin chào. Số điện thoại của tôi là %1$s.', 'example') . '</p>', $number );
if ( $message )
printf( '<p>' . __('Xin chào. Tin nhắn của tôi là %1$s.', 'example') . '</p>', $message );
/* Sau tiện ích (được xác định bởi các chủ đề). */
echo $after_widget;
}
