Lỗi "Trying to get property of non-object" với Custom Walker cho wp_nav_menu Tôi đang cố gắng thêm một vài thứ liên quan đến ARIA vào hàm wp_nav_menu. Tôi sử dụng lớp walker tùy chỉnh cho mục đích này:

class Walker_Nav_Menu_With_Aria extends Walker_Nav_Menu { function start_lvl( &$output, $depth = 0, $args = array() ) { $indent = str_repeat("\t", $depth); $output .= "\n$indent<ul class=\"sub-menu\" role=\"group\">\n"; } function end_lvl( &$output, $depth = 0, $args = array() ) { $indent = str_repeat("\t", $depth); $output .= "$indent</ul>\n"; } function start_el( &$output, $item, $depth = 0, $args = array(), $id = 0 ) { $indent = ( $depth ) ? str_repeat( "\t", $depth ) : ''; $class_names = $value = ''; $classes = empty( $item->classes ) ? array() : (array) $item->classes; $classes[] = 'menu-item-' . $item->ID; $class_names = join( ' ', apply_filters( 'nav_menu_css_class', array_filter( $classes ), $item, $args ) ); $class_names = $class_names ? ' class="' . esc_attr( $class_names ) . '"' : ''; $id = apply_filters( 'nav_menu_item_id', 'menu-item-'. $item->ID, $item, $args ); $id = $id ? ' id="' . esc_attr( $id ) . '"' : ''; // Thêm thuộc tính cho thẻ <li> $li_attributes  = ' role="treeitem"'; $li_attributes .= ' aria-expanded="false"'; $output .= $indent . '<li' . $id . $value . $class_names . $li_attributes .'>'; $attributes  = ! empty( $item->attr_title ) ? ' title="'  . esc_attr( $item->attr_title ) .'"' : ''; $attributes .= ! empty( $item->target )     ? ' target="' . esc_attr( $item->target     ) .'"' : ''; $attributes .= ! empty( $item->xfn )        ? ' rel="'    . esc_attr( $item->xfn        ) .'"' : ''; $attributes .= ! empty( $item->url )        ? ' href="'   . esc_attr( $item->url        ) .'"' : ''; // Thêm thuộc tính cho thẻ <a> $attributes .= $depth == 0 ? ' tabindex="0"' : ' tabindex="-1"'; $item_output = $args->before; $item_output .= '<a'. $attributes .'>'; $item_output .= $args->link_before . apply_filters( 'the_title', $item->title, $item->ID ) . $args->link_after; $item_output .= '</a>'; $item_output .= $args->after; $output .= apply_filters( 'walker_nav_menu_start_el', $item_output, $item, $depth, $args ); } function end_el( &$output, $item, $depth = 0, $args = array() ) { $output .= "</li>\n"; } }

Tôi chỉ sao chép và dán lớp Walker_Nav_Menu ban đầu và thêm một vài thứ, nhưng tôi nhận được lỗi vì biến $args được xử lý như một đối tượng thực ra lại là một mảng. Điều kỳ lạ là lỗi này vẫn xuất hiện ngay cả khi tôi truyền vào lớp walker ban đầu như sau:

wp_nav_menu( array( 'theme_location' => 'main-nav', 'walker'         => new Walker_Nav_Menu, ) );

Đây là các thông báo lỗi mà tôi nhận được:

NOTICE: TRYING TO GET PROPERTY OF NON-OBJECT IN /USERS/RUDOLF/SITES/LOCALHOST/WP/WP- INCLUDES/NAV-MENU-TEMPLATE.PHP ON LINE 88 NOTICE: TRYING TO GET PROPERTY OF NON-OBJECT IN /USERS/RUDOLF/SITES/LOCALHOST/WP/WP- INCLUDES/NAV-MENU-TEMPLATE.PHP ON LINE 90 NOTICE: TRYING TO GET PROPERTY OF NON-OBJECT IN /USERS/RUDOLF/SITES/LOCALHOST/WP/WP- INCLUDES/NAV-MENU-TEMPLATE.PHP ON LINE 90 NOTICE: TRYING TO GET PROPERTY OF NON-OBJECT IN /USERS/RUDOLF/SITES/LOCALHOST/WP/WP- INCLUDES/NAV-MENU-TEMPLATE.PHP ON LINE 92

