Tải lên hình ảnh không kèm theo từ giao diện phía trước Tôi đang sử dụng hàm dưới đây để cho phép người dùng tải lên các tập tin từ giao diện phía trước. Nó hoạt động tốt ngoại trừ tôi muốn tập tin không được đính kèm vào bất kỳ bài viết nào. Hiện tại, tập tin tự động đính kèm vào trang tôi đang sử dụng để tải lên (mysite.com/publish). Tôi muốn nó không đính kèm thay vì vậy. Tôi nên thay đổi điều gì dưới đây để thực hiện được điều đó? Đây là các hàm:

// Tải lên hình ảnh từ giao diện phía trước
function insert_attachment($file_handler,$post_id,$setthumb='false') {
// kiểm tra để đảm bảo đó là một quá trình tải lên thành công
if ($_FILES[$file_handler]['error'] !== UPLOAD_ERR_OK) __return_false();
require_once(ABSPATH . "wp-admin" . '/includes/image.php');
require_once(ABSPATH . "wp-admin" . '/includes/file.php');
require_once(ABSPATH . "wp-admin" . '/includes/media.php');
$attach_id = media_handle_upload( $file_handler, $post_id );
nếu ($setthumb) update_post_meta($post_id,'_thumbnail_id',$attach_id);
trả về $attach_id;
}

