Thêm mã vào thanh quản trị Tôi đang cố gắng thêm mã QR vào thanh và tôi có thể làm điều này nhưng đây là lần đầu tiên tôi tạo một plugin WordPress và tôi gặp khó khăn. Nó hiển thị cho mọi người ngay cả khi họ không phải là quản trị viên hoặc thậm chí không đăng nhập. Bất kỳ ý tưởng hoặc hướng dẫn nào sẽ rất biết ơn.

function selfURL() {
    $s = empty($_SERVER["HTTPS"]) ? ''
        : ($_SERVER["HTTPS"] == "on") ? "s"
        : "";
    $protocol = strleft(strtolower($_SERVER["SERVER_PROTOCOL"]), "/").$s;
    $port = ($_SERVER["SERVER_PORT"] == "80") ? ""
        : (":".$_SERVER["SERVER_PORT"]);
    return $protocol."://".$_SERVER['SERVER_NAME'].$port.$_SERVER['REQUEST_URI'];
}

function strleft($s1, $s2) {
    return substr($s1, 0, strpos($s1, $s2));
}

$urlToEncode=(selfURL());
generateQRwithGoogle($urlToEncode);

function generateQRwithGoogle($url,$widthHeight ='30',$EC_level='L',$margin='0') {
    $url = urlencode($url);
    echo '<img src="http://chart.apis.google.com/chart?chs='.$widthHeight.
        'x'.$widthHeight.'&cht=qr&chld='.$EC_level.'|'.$margin.
        '&chl='.$url.'" alt="QR code" widthHeight="'.$widthHeight.
        '" widthHeight="'.$widthHeight.' "/>';
}

