URL và trang nội dung được tạo ra một cách năng động Tôi cần một số lời khuyên. Tôi có một phần trên trang chủ của tôi động kéo vào một danh sách các điều khoản từ một bảng tùy chỉnh trong WP db. Tôi đã tạo một URL tùy chỉnh duy nhất cho mỗi điều khoản này dựa trên mã thử nghiệm:

<a href="<?php bloginfo('url'); ?>/test-directory/test-code/<?php echo $record->test_code; ?>"

Điều này hoạt động tốt. Bước tiếp theo của tôi là khi nhấp vào các URL này sẽ tải nội dung động đi kèm vào một mẫu. Tôi đã thử mã dưới đây để tạo quy tắc ghi đè để trỏ đến một mẫu nhưng nó không hoạt động. Nó không tải mẫu mà mẫu blog mặc định. Tôi đang sử dụng một chủ đề con nhưng điều này nên hoạt động:

function my_add_query_vars( $qvars ) {
    $qvars[] = 'test-directory';
    $qvars[] = 'test-code';
    return $qvars;
}
add_action('query_vars', 'my_add_query_vars');

function my_add_rewrite_rules( $wp_rewrite ) {
    $newrules = array();
    $new_rules['^test-directory/(.*)/(.*)'] = 'index.php?test-directory=$matches[1]test-code=$matches[2]';
    $wp_rewrite->rules = $new_rules + $wp_rewrite->rules;
}
add_action('generate_rewrite_rules', 'my_add_rewrite_rules');

function my_template_redirect() {
    if( get_query_var('test-code') ) {
        include_once(locate_template('template-faq-fullwidth.php', true));
        exit();
    }
}
add_action('template_redirect','template_redirect');

