// Sử dụng mẫu hai cột làm kết quả tìm kiếm.
add_action('template_include', 'new_search_tmpl');
function new_search_tmpl( $template ) {
  if ( is_search() ) {
    $t = locate_template('page-two-column.php', false);
    if ( ! empty($t) ) $template = $t;
  }
  return $template;
}
