        $post_link = str_replace( '% tin tức_danh mục%', array_pop( $glossary_letter )->slug, $post_link );
    }
    return $post_link;

Tags phá vỡ chức năng trích xuất Câu hỏi nhanh. Tôi có một hàm hiển thị nội dung của kiểu bài viết (nếu không có nội dung, thì hiển thị đoạn trích dẫn). Nó trông như thế này:

function era_excerpt($post, $length = 11, $ext = ' ...') {
    if(is_int($post)) {
        $post = get_post($post);
    } elseif(!is_object($post)) {
        return false;
    }

    if(has_excerpt($post->ID)) {
        $the_excerpt = $post->post_excerpt;
    } else {
        $the_excerpt = $post->post_content;
    }

    $the_excerpt = strip_shortcodes(strip_tags(stripslashes($the_excerpt), '<a><em><strong>'));
    $the_excerpt = preg_split('/\b/', $the_excerpt, $length * 2+1);
    $excerpt_waste = array_pop($the_excerpt);
    $the_excerpt = implode($the_excerpt);
    $the_excerpt .= $ext;
    $post = $post->ID;

    return apply_filters('the_content', $the_excerpt);
}

Tôi nhận ra rằng hàm này có một vấn đề lớn: người dùng bắt đầu một kiểu bài viết với thẻ HTML đặc biệt, chẳng hạn như <em>, <a> và/hoặc <strong>, đã phá vỡ toàn bộ bố cục. Giả sử điều này là do tham số "allowed tags" của hàm strip_shortcodes gây ra, tôi đã thay đổi hàm thành:

function era_excerpt_new($post, $length = 11, $ext = ' ...') {
