công khai phương pháp tải
/ *** /
# tải RSS bằng URL
công khai chức năng tải ($ url = sai, $ unblock = đúng) {
nếu ($ url) {
nếu ($ unblock) {
$ this-> loadParser (file_get_contents ($ url,
sai,
$ this-> randomContext ()));
} khác {
$ this-> loadParser (file_get_contents ($ url));
}
}
}

# tải dữ liệu RSS thô
công khai chức năng loadRSS ($ rawxml = sai) {
nếu ($ rawxml) {
$ this-> loadParser ($ rawxml);
}
}
/ *****************************
công khai phương pháp tải
@ param $ includeAttributes boolean
trả về mảng; *** /
# trả về mảng rss đầy đủ
công khai chức năng getRSS ($ includeAttributes = sai) {
nếu ($ includeAttributes) {
trả về $ this-> tài liệu;
}
trả về $ this-> valueReturner ();
}

# trả về dữ liệu kênh
công khai chức năng getChannel ($ includeAttributes = sai) {
nếu ($ includeAttributes) {
trả về $ this-> kênh;
}
trả về $ this-> valueReturner ($ this-> kênh);
}

# trả về mục rss
công khai chức năng getItems ($ includeAttributes = sai) {
nếu ($ includeAttributes) {
trả về $ this-> mục;
}
trả về $ this-> valueReturner ($ this-> mục);
}

