gọi wp_insert_user trong lớp tùy chỉnh không hoạt động Tôi đang tạo một lớp tùy chỉnh để quản lý người dùng trong WordPress và Chamilo nhưng đó không phải là điểm chính. Lớp trông giống như thế này:

class Platform {
    private $security_key = '..';
    private $secret_key;
    private $firstname;
    private $lastname;
    private $status;
    private $email;
    private $login;
    private $password;
    private $encrypt_method = "md5";
    private $original_user_id_name = "uid";
    private $original_user_id_value;

    public function __construct() {
        $arguments = func_get_args();
        if(!empty($arguments)) {
            foreach($arguments[0] as $key => $property) {
                if(property_exists($this, $key)) {
                    $this->{$key} = $property;
                }
            }
        }
    }

    /*
     * Thực hiện xác thực từ Chamilo cần IP client + auth_code.
     * Từ những dữ liệu này tạo ra API_KEY được sử dụng trong quá trình giao tiếp với nền tảng.
     * Các hàm kiểm tra IP và auth_code hợp lệ của nền tảng và tạo ra API_KEY
     */
    public function check_client_ip() {
        $ip = trim($_SERVER['REMOTE_ADDR']);
        if (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
            list($ip1,$ip2) = split(',',$_SERVER['HTTP_X_FORWARDED_FOR']);
            $ip = trim($ip1);
        }
        return $ip;
    }

    public function generate_secret_key() {
        $ip_address = $this->check_client_ip();
        $secret_key = sha1($ip_address.$this->security_key);
        return $secret_key;
    }

    /*
     * Thêm người dùng vào Chamilo
     */
    public function add_user_to_chamilo() {
        $params = array(
            'firstname' => $this->firstname,
            'lastname' => $this->lastname,
            'status' => '5', // 5 STUDENT - 1 TEACHER - luôn đặt thành học sinh - chúng tôi sẽ tạo tài khoản quản trị thủ công
            'email' => $this->email,
            'loginname' => $this->login,
            'password' => $this->password, // mã hóa bằng sha1
            'encrypt_method' => 'md5',
            'language' => 'Polish',
            'official_code' => '',
            'phone' => '',
            'expiration_date' => '0000-00-00',
            'original_user_id_name' => 'uid', // trường người dùng bổ sung sẽ được tạo tự động trong hồ sơ người dùng xem: main/admin/user_fields.php
            'original_user_id_value' => $this->wp_user_id, // ID người dùng bên thứ ba
            'secret_key' => $this->generate_secret_key(),
        );

        echo "<pre>";
        print_r($params);
        echo "</pre>";

        //$client = new SoapClient('http://....pl/registration.soap.php?wsdl');
        //$response = $client->WSCreateUserPasswordCrypted($params);
    }

    /*
     * Thêm người dùng vào WordPress
     */
    public function add_user_to_wordpress() {
        $params = array(
            'ID' => '',
            'first_name' => $this->firstname,
            'last_name' => $this->lastname,
            'user_email' => $this->email,
            'user_login' => $this->login,
            'user_pass' => $this->password,
            'role' => 'subscriber'
        );

        echo "<pre>";
        print_r($params);
        echo "</pre>";

        wp_insert_user($params);
    }
}

