Nhận được url của hình ảnh trong một gallery? Tôi cần lấy các URL của hình ảnh trong một gallery, câu lệnh SQL phù hợp cho việc này dựa trên ID bài viết là gì? Tôi hiện đang có một câu lệnh như sau mà tôi tìm thấy trên Google, nhưng không biết làm thế nào để truy cập biến toàn cầu của WP từ bên ngoài Wordpress - tôi cần làm gì?

function getGallery($id) {
global $wpdb;
//Câu lệnh SQL để lấy tất cả các tập tin đính kèm có kiểu MIME là image/jpeg từ bài viết được cho
$querystr = "
SELECT ID, post_name, guid, meta_value
FROM $wpdb->posts wposts
INNER JOIN $wpdb->postmeta meta ON meta.post_id = wposts.ID AND meta.meta_key = '_wp_attachment_metadata'
WHERE wposts.post_type = 'attachment'
AND wposts.post_parent = '".$id."'
AND wposts.post_mime_type = 'image/jpeg'
";
//Lấy kết quả từ câu lệnh truy vấn
$pictures = $wpdb->get_results($querystr, ARRAY_A);
//Trả về kết quả
return $pictures;
}

add_rewrite_endpoint() và Custom Post Type Archive Tôi có một loại bài viết tùy chỉnh. Hãy gọi nó là "sách". Tôi đang thêm một điểm kết nối lại mới được gọi là "trang". Tôi muốn URL "/books/pages/2/" hoạt động nhưng tôi không thấy bất kỳ quy tắc kết nối lại nào được tạo ra bởi WordPress cho điều này. Tôi có thể thêm thủ công các quy tắc kết nối lại cho ví dụ cụ thể này, nhưng tôi đang tìm kiếm một cách để làm cho điều này hoạt động tự động. Làm thế nào tôi có thể làm cho điều này hoạt động tự động cho bất kỳ bản lưu trữ loại bài viết tùy chỉnh nào? Tôi đoán tôi sẽ cần thêm một hàm vào plugin của mình để tìm tất cả các loại bài viết tùy chỉnh được đăng ký cho trang web hiện tại và sau đó lặp lại danh sách đó để thêm các quy tắc kết nối lại tùy chỉnh. Có ý tưởng nào tốt hơn không? **Cập nhật** Đây là những gì tôi đã làm:

function my_plugin_rewrite_rules( $wp_rewrite ) {
    $pages_regex = '?([\d\-]+|all)';

    $args = array(
        'has_archive' => true
    );

    $post_types = get_post_types( $args );

    $new_rewrites = array();

    foreach( $post_types as $post_type ) {
        $key = $post_type . '/pages/' . $pages_regex . '/?$';
        $val = 'post_type=' . $post_type . '&pages=' . $wp_rewrite->preg_index(1);

        $new_rewrites[ $key ] = $val;
    }

    $wp_rewrite->rules = $new_rewrites + $wp_rewrite->rules;
}

add_action('generate_rewrite_rules', 'my_plugin_rewrite_rules');

