Làm thế nào để tạo bảng dữ liệu, thêm, cập nhật và xóa dữ liệu bằng wpdb thông qua plugin? Tôi chỉ mới bắt đầu tạo các plugin với cơ sở dữ liệu. Tôi biết cách tạo một cơ sở dữ liệu tùy chỉnh khi kích hoạt plugin. Tôi chỉ muốn biết rằng chúng ta có thể tạo bảng ở giao diện phía trước như thêm tên trường, kiểu trường. Và tôi cũng đã thử tạo các giá trị hàng, nhưng dường như các giá trị không được chèn vào bảng. Đây là mã của tôi để thêm giá trị vào các bảng:

function test_get_log_table_columns() {
    return array(
        'log_id' => '%d',
        'user_id' => '%d',
        'activity' => '%s'
    );
}

function insert_data_into_table() {
    global $wpdb;

    $logid = $_POST['logid'];
    $userid = $_POST['userid'];

    // Thiết lập giá trị mặc định
    $data = wp_parse_args($data, array(
        'user_id' => get_current_user_id(),
        'date' => current_time('timestamp')
    ));

    // Kiểm tra tính hợp lệ của ngày
    if (!is_float($data['date']) || $data['date'] <= 0) {
        return 0;
    }

    // Chuyển đổi ngày hoạt động từ thời gian địa phương sang định dạng GMT của MySQL
    $data['activity_date'] = date_i18n('Y-m-d H:i:s', $data['date'], true);

    // Khởi tạo mảng định dạng cột
    $column_formats = test_get_log_table_columns();

    // Đổi chữ hoa thành chữ thường cho các trường
    $data = array_change_key_case($data);

    // Danh sách trắng các cột
    $data = array_intersect_key($data, $column_formats);

    // Sắp xếp lại $column_formats để khớp với thứ tự của các cột được cung cấp trong $data
    $data_keys = array_keys($data);
    $column_formats = array_merge(array_flip($data_keys), $column_formats);

    $wpdb->insert($wpdb->wptuts_activity_log, $data, $column_formats);

    return $wpdb->insert_id;
}

function retrieve_val_data() {
    global $wpdb;
}

