class Walker_Nav_Menu_Dropdown extends Walker_Nav_Menu {
  function start_lvl(&$output, $depth) {
    $indent = str_repeat("\t", $depth); // không hiển thị thẻ mở của các mục con (<ul>)
  }

  function end_lvl(&$output, $depth) {
    $indent = str_repeat("\t", $depth); // không hiển thị thẻ đóng của các mục con
  }

  function start_el(&$output, $item, $depth, $args) {
    // thêm khoảng cách vào tiêu đề dựa trên độ sâu
    $item->title = str_repeat("&nbsp;", $depth * 4).$item->title;

    parent::start_el(&$output, $item, $depth, $args);

    // không có ý nghĩa khi định nghĩa lại phương thức này, chúng ta chỉ thay thế thẻ li bằng thẻ option
    $output = str_replace('<li', '<option', $output);
  }

  function end_el(&$output, $item, $depth) {
    $output .= "</option>\n"; // thay thế thẻ đóng </li> bằng thẻ option
  }
}

