Lấy giá trị từ bảng dữ liệu dựa trên giá trị trường Tôi đang sử dụng một plugin có tên là formidable tương tự như Gravity Forms về mặt mục đích. Tôi có hai trường quan tâm. Trường đầu tiên tải tất cả các giá trị trong cột 'Town' của bảng 'wp_locations' của tôi bằng mã sau:

function frm_populate_posts_town($values, $field){
    if($field->id == 800){ //thay đổi 125 thành ID của trường để điền
        global $wpdb;
        $towns =$wpdb->get_results("SELECT Town FROM wp_locations");
        $values['options'] = array();
        foreach ($towns as $town) {
            $values['options'][$town->Town] = $town->Town;
        }
    }
    return $values;
}

