wp_logout không hoạt động Tôi đang cố gắng xóa một số cookie được thiết lập để kiểm soát đăng nhập liên tục khi người dùng cụ thể muốn đăng xuất khỏi một trang web. Tôi nghĩ rằng nó sẽ đơn giản như:

function remove_user_cookie() {
unset($_COOKIE['woai']);
unset($_COOKIE['woak']);
}
add_action('wp_logout', 'remove_user_cookie');

Tôi cũng đã thử:

function remove_user_cookie() {
if( $_GET['action'] == 'logout' ) :
unset($_COOKIE['woai']);
unset($_COOKIE['woak']);
endif;
}
add_action('wp_logout', 'remove_user_cookie');

Tuy nhiên, các cookie của người dùng vẫn còn đó, vì vậy họ vẫn được đăng nhập lại tự động. Tôi không chắc liệu hành động wp_logout có hoạt động hay không, hay là nó xung đột với mã của tôi đăng nhập người dùng tự động. Hiện tại, tôi có điều này trong header.php:

<?php if( !is_user_logged_in() ) :
// kiểm tra xem người dùng có cookie hay không
if ( isset($_COOKIE['woai']) && isset($_COOKIE['woak']) ) :
$args = array(
'meta_key' => 'login_key',
'meta_value' => $_COOKIE['woak'],
'meta_compare' => '=',
'fields' => 'ID',
'include' => $_COOKIE['woai']
);
$user_query = new WP_User_Query($args);
if( $user_query->results[0] != '' || $user_query->results[0] != NULL ) :
// lấy ID và tên đăng nhập của người dùng
$user_id = $user_query->results[0];
$user_login = get_user_by( 'id', $user_id );
// đăng nhập người dùng
wp_set_current_user( $user_id, $user_login->user_login );
wp_set_auth_cookie( $user_id );
do_action( 'wp_login', $user_login->user_login );
endif;
endif; // kết thúc nếu cookie
endif; ?>

Và khi người dùng đã đăng nhập, họ nhận được một khóa mới được đặt với điều này:

function set_user_cookie($user_login) {
// nếu họ có cookie, xóa chúng
if ( isset($_COOKIE['woai']) && isset($_COOKIE['woak']) ) :
unset($_COOKIE['woai']);
unset($_COOKIE['woak']);
endif;
$user_id = get_user_by( 'login', $user_login );
// tạo khóa mới cho người dùng
$salt = wp_generate_password(20); // chuỗi "ngẫu nhiên" 20 ký tự
$key = sha1($salt . $email . uniqid(time(), true));
// đặt cookie mới
setcookie("woai", $user_id->ID, time()+31536000); /* hết hạn trong 1 năm */
setcookie("woak", $key, time()+31536000); /* hết hạn trong 1 năm */
// cập nhật cơ sở dữ liệu
update_field('field_53c3de9cd031e', $key, 'user_'.$user_id->ID.'');
}
add_action('wp_login', 'set_user_cookie', 10, 1);

