$VIP = get_post_meta($pid, 'vip', false);

/*
Thực hiện một số thao tác ở đây
*/

update_post_meta($pid, 'vip', $NEW_VIP);

Mã này nằm **trong một hàm** được gọi khi đăng bài: `add_action('publish_post', 'function_name');`. Nhưng nó không được cập nhật! Tôi đã kiểm tra xem hàm có chạy không và giá trị mà `$NEW_VIP` chứa gì không. Vì vậy, tôi đã thêm một dòng trước hàm `update_post_meta()` để đảm bảo với bản thân mình:

print_r($NEW_VIP); die();

Kết quả được như mong đợi và `$NEW_VIP` có giá trị đúng (là một mảng) nhưng `update_post_meta` không lưu nó và giá trị hộp meta sẽ luôn không thay đổi. Ai có thể giúp tôi xin vui lòng giúp đỡ.

**Cập nhật #1** Hàm đầy đủ:

function dl_url($pid)
{
    global $wpdb;
    $VIP = array_filter(get_post_meta($pid, 'vip', false));
    //$urls = array();
    //print_r($VIP); die();
    if(!wp_is_post_revision($pid) && $VIP[0])
    {
        foreach ($VIP[0] as $mid => $link)
        {
            if(preg_match("/^((https?:\/\/)|(www\.))([a-z0-9-].?)+(:[0-9]+)?(\/.*)?$/i", $link))
            {
                $rand = rand(1000,99999999);
                $hash = strrev(md5($link.$rand));
                $file = pathinfo($link);
                $filename = $file['basename'];
                $size = get_size($link);
                $price = get_post_meta($pid, 'price', true);
                if(!$price)
                    $price = 0;
                if($row = $wpdb->get_row("SELECT * FROM wp_dlurl WHERE pid = '{$pid}' AND hash = '{$hash}'",ARRAY_A)) // kiểm tra xem có tồn tại trong db không
                {
                    // nếu tồn tại thì cập nhật url
                    $arr = array('price' => $price);
                    $format = array(0 => '%d');
                    $home = str_replace(array("/",":"),array("\/","\:"),get_bloginfo('url'));
                    if(!preg_match("/".$home."\/\?download\=\w{32}/", $link))
                    {
                        $arr += array('url' => $link, 'filename' => $filename, 'size' => $size, 'hash' => $hash);
                        $format += array(1 => '%s', 2 => '%s', 3 => '%d', 4 => '%s');
                        $urls[] = get_bloginfo('url')."/?download=".$hash;
                        //update_post_meta($pid, 'vip', get_bloginfo('url')."/?download=".$hash);
                    }
                    $wpdb->update(REV_DL, $arr, array('pid' => $pid, 'hash' => $row['hash']), $format, array('%d','%s'));
                }
                else
                {
                    // nếu không tồn tại thì chèn vào
                    $wpdb->insert(REV_DL, array('pid' => $pid, 'price' => $price, 'url' => $link, 'filename' => $filename, 'size' => $size, 'hash' => $hash), array('%d','%d','%s','%s','%d','%s'));
                    $urls[] =  get_bloginfo('url')."/?download=".$hash;
                    //print_r($urls);
                    //die();
                }
            }
        }
        if(isset($urls))
        {
            //print_r($urls);
            //die();
            $VIP = $urls;
        }
        //print_r($VIP); die();
        update_post_meta($pid, 'vip', $VIP);
        //print_r(get_post_meta($pid, "vip", true));
        //die();
    }
}

add_action('publish_post', 'dl_url', 99);

