function check_user() {
    $user = wp_get_current_user();
    if (! $user->ID || in_array('subscriber', $user->roles)) {
        // người dùng chưa đăng nhập hoặc là người đăng ký
        return false;
    }
    return true;
}

function restrict_by_category( $template ) {
    if (! is_main_query()) return $template; // chỉ ảnh hưởng đến truy vấn chính.
    $allow = true;
    $private_categories = array('reserved', 'personal'); // các mục mà người đăng ký không thể xem
    if (is_single()) {
        $cats = wp_get_object_terms(get_queried_object()->ID, 'category', array('fields' => 'slugs')); // lấy các mục liên quan đến bài viết được yêu cầu
        if (array_intersect($private_categories, $cats)) {
            // bài viết có mục được bảo lưu, hãy kiểm tra người dùng
            $allow = check_user();
        }
    } elseif (is_tax('category', $private_categories)) {
        // lưu trữ của một trong các mục riêng tư được yêu cầu, hãy kiểm tra người dùng
        $allow = check_user();
    }
    // nếu được phép bao gồm mẫu được yêu cầu, nếu không bao gồm mẫu 'không được phép'
    return $allow ? $template : get_template_directory() . '/not-allowed.php';
}

