/* Hàm trợ giúp để lưu thông tin thêm */

function save_user_fields($user_id) {
    if ( !current_user_can( 'edit_user', $user_id ) )
        return false;

    //Lưu giá trị của các trường hộp kiểm vào cơ sở dữ liệu
    $save_meta = get_user_fields($current_user, false);

    //Đi qua tất cả các khóa học và lưu chúng
    foreach($save_meta as $current_meta) {
        $course = $current_meta['course'];
        $is_reserve = $current_meta['is_reserve'];
        $update = 0;

        if (isset($_POST[$course])) {
            $chkbox = $_POST[$course];
            if ($chkbox == 'on') {
                $update = 1;
            }
        }

        //Lưu giá trị từ biểu mẫu vào cơ sở dữ liệu
        update_usermeta($user_id, $course, $update);

        //Lưu khóa học vào cơ sở dữ liệu với định dạng course_{id của khóa học}
        update_usermeta($user_id, $course . '_reserve', $is_reserve); //Lưu trạng thái dự phòng của người dùng (1 = dự phòng, 0 = không dự phòng) cho khóa học này
    }
}

