function if_user_can_save($post_id, $nonce) {
    // Kiểm tra xem bài viết có phải là bản tự động lưu không
    $is_autosave = wp_is_post_autosave($post_id);

    // Kiểm tra xem nó có phải là bản sửa đổi không
    $is_revision = wp_is_post_revision($post_id);

    // Kiểm tra xem mã xác thực có hợp lệ không
    $is_valid_nonce = isset($_POST[$nonce]) && wp_verify_nonce($_POST[$nonce], basename(__FILE__));

    return !$is_autosave && !$is_revision && $is_valid_nonce;
}

function display_content($content) {
    $test = get_post_meta(get_the_ID(), 'options-select', true);
    $content .= $test;
    print_r($test);
    return $content;
}

