Thêm dữ liệu biểu tượng vào liên kết menu tùy chỉnh WordPress Tôi cần thêm vào 'data-icon=""` vào hộp nhập Custom Menu của Wordpress. Điều này cho phép tôi sử dụng phông chữ biểu tượng và gõ mã cho một biểu tượng cụ thể và trong CSS sử dụng các yếu tố giả để khớp với nó và hiển thị biểu tượng. Tôi đã tìm thấy rất nhiều hướng dẫn cho thấy cách mở rộng lớp 'Walker_Nav_Menu' để tôi có thể thêm thuộc tính, nhưng không có hướng dẫn nào mở rộng điều này để thêm một hộp nhập mới trên màn hình Custom Menu của Wordpress (http://cl.ly/Sn0C) và sau đó có giá trị của hộp nhập này hiển thị trong HTML. Tôi đã sử dụng mã này để thêm một hộp nhập 'data-icon' trên màn hình quản trị Custom Menu (http://cl.ly/SmqM), nhưng tôi không giỏi PHP đến mức có thể kết nối nó với lớp mở rộng 'Walker_Nav_Menu' để hiển thị giá trị 'data-icon' trong HTML. Có ai có thể giúp tôi không? Cảm ơn! Tôi muốn nếu điều này có thể được thực hiện trong functions.php và/hoặc mà không cần sử dụng plugin. Ngoài ra, đây là mã lớp mở rộng 'Walker_Nav_Menu' của tôi:

class data_type_walker extends Walker_Nav_Menu {
    function start_el(&$output, $item, $depth, $args) {
        global $wp_query;
        $indent = ( $depth ) ? str_repeat( "\t", $depth ) : '';
        $class_names = $value = '';
        $classes = empty( $item->classes ) ? array() : (array) $item->classes;
        $class_names = join( ' ', apply_filters( 'nav_menu_css_class', array_filter( $classes ), $item ) );
        $class_names = ' class="'. esc_attr( $class_names ) . '"';
        $output .= $indent . '<li id="menu-item-'. $item->ID . '"' . $value . $class_names .'>';
        $attributes  = ! empty( $item->attr_title ) ? ' title="'     . esc_attr( $item->attr_title       ) .'"' : '';
        $attributes .= ! empty( $item->target )     ? ' target="'    . esc_attr( $item->target           ) .'"' : '';
        $attributes .= ! empty( $item->xfn )        ? ' rel="'       . esc_attr( $item->xfn              ) .'"' : '';
        $attributes .= ! empty( $item->url )        ? ' href="'      . esc_attr( $item->url              ) .'"' : '';
        $attributes .= ! empty( $item->data_icon )  ? ' data-icon="' . esc_attr( $item->data_icon        ) .'"' : '';
        $prepend = '';
        $append = '';
        if($depth != 0) {
            $description = $append = $prepend = "";
        }
        $item_output = $args->before;
        $item_output .= '<a'. $attributes .' aria-hidden="true">';
        $item_output .= $args->link_before .$prepend.apply_filters( 'the_title', $item->title, $item->ID ).$append;
        $item_output .= $description.$args->link_after;
        $item_output .= '</a>';
        $item_output .= $args->after;
        $output .= apply_filters( 'walker_nav_menu_start_el', $item_output, $item, $depth, $args );
    }
}

