Và đây là hàm lưu của tôi để lưu dữ liệu vào một mảng.

add_action('save_post', 'repeatable_meta_box_save', 10, 2);

function repeatable_meta_box_save($post_id) {
    if ( ! isset( $_POST['repeatable_meta_box_nonce'] ) ||
        !wp_verify_nonce( $_POST['repeatable_meta_box_nonce'], 'repeatable_meta_box_nonce' ) )
        return;

    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE)
        return;

    if (!current_user_can('edit_post', $post_id))
        return;

    $old = get_post_meta($post_id, 'repeatable_fields', true);
    $new = array();

    $playbackFormats = $_POST['playback_format'];

    $count = count( $names ) - 1;

    for ( $i = 0; $i < $count; $i++ ) {
        // hiện tại chỉ lưu trữ giá trị nút phát sóng cuối cùng
        $new[$i]['playback_format'] = $playbackFormats[$i];

        // lưu mô tả phim

        // và bất cứ cách nào bạn muốn làm sạch dữ liệu
        if ( !empty( $new ) && $new != $old ) {
            update_post_meta( $post_id, 'repeatable_fields', $new );
        } elseif ( empty($new) ) {
            delete_post_meta( $post_id, 'repeatable_fields', $old );
        }
    }
}

Vấn đề tôi đang gặp phải là, giả sử tôi có ba hàng. Nếu tôi đặt hàng đầu tiên là DVD, hàng thứ hai là Bluray và hàng thứ ba là 3D, chỉ có giá trị cuối cùng được lưu lại là 3D. Tất cả các giá trị khác được lưu là 'null'. Cách tôi thiết lập mọi thứ trông giống như mọi thứ nên được lưu đúng cách. Đây là phiên bản rút gọn. Tôi có các trường đầu vào đang lưu trữ chính xác, nhưng nút phát sóng đã trở thành một vấn đề lớn. Nó trông giống như hàm lưu của tôi nên lưu trữ mỗi 'playback_format'] vào vị trí thích hợp trong mảng. Nhưng chỉ có một được lưu. Tôi đã có thể lưu cùng một giá trị cho tất cả ba hàng, nhưng không thể nhận được một giá trị duy nhất cho mỗi hàng và không chắc tại sao.

