phương thức XMLRPC tùy chỉnh cộng với xác thực người dùng và đơn hàng của WooCommerce Tôi đang làm việc với một phương pháp XML-RPC tùy chỉnh để thu thập một số thông tin cho một plugin tôi đang xây dựng. Khi kích hoạt, người dùng phải xác thực bản thân bằng cách nhập tên người dùng/mật khẩu được cung cấp cho họ khi mua plugin trên trang web WP của tôi. Plugin này sử dụng mã sau:

if ( isset( $_POST['username'] ) && isset( $_POST['password'] ) ) {

    /* kiểm tra trên máy chủ từ xa */
    require_once( ABSPATH . WPINC . '/class-IXR.php' );
    $this->client = new IXR_Client( trailingslashit( CUSTOMLOGIN_UPDATE_API ) . 'xmlrpc.php' ); //*/

    $url = ( ( is_multisite() ) ? network_site_url() : site_url() );
    $client_request_args = array(
        'username' => $_POST['username'],
        'password' => $_POST['password'],
        'plugin' => CUSTOMLOGINPRO_BASENAME,
        'url' => $url
    );

    if ( !$this->client->query( 'thefrosty.is_user_authorized', $client_request_args ) ) {
        add_action( 'admin_notices', array( $this, 'error_notice' ) );
        return false;
    }

    $this->settings = get_option( CUSTOMLOGINPRO . '_settings', array() );
    $this->settings['api-key'] = $this->client->getResponse();
    update_option( CUSTOMLOGINPRO . '_settings', $this->settings );
    header( 'Location: ' . admin_url( 'options-general.php?page=' . CUSTOMLOGINPRO ) );
    die();
}

Mã này gửi yêu cầu và trông giống như nó hoạt động, nhận được lỗi 200 khi chạy trên máy chủ cục bộ, nhưng khi thử nghiệm với một plugin khác gửi cùng mã lỗi, nhưng lại gửi phản hồi từ máy chủ (không có gì đáng lo ngại ở đây). Vấn đề tôi gặp phải là ở mã phía sau. Tôi đã tạo một lớp trong plugin cốt lõi trên cài đặt WP của tôi. Tôi giả định đây là nơi nó cần được đặt. Tôi thiếu một số mã xử lý lỗi và phản hồi thông báo lỗi, không biết làm thế nào để thực hiện chúng. Tôi chỉ cần một chút hướng dẫn... Như bạn thấy, tôi cũng đang kiểm tra người dùng so với một đơn hàng WooCommerce (mã từ WC, nên tốt) nhưng sau đó cố gắng cập nhật meta của đơn hàng có thể cần phải sửa chữa để lưu URL của người dùng.

class frosty_core {
    function __construct() {
        add_filter( 'xmlrpc_methods', array( $this, 'xmlrpc_methods' ) );
    }

    /**
     * Tạo phương thức XML-RPC tùy chỉnh của chúng tôi.
     * @ref http://kovshenin.com/2010/04/custom-xml-rpc-methods-in-wordpress-2151/
     */
    function xmlrpc_methods( $methods ) {
        $methods['thefrosty.is_user_authorized'] = array( $this, 'thefrosty_plugin_callback' );
        return $methods;
    }

    /**
     * Phương thức XML-prc
     */
    function thefrosty_plugin_callback( $args ) {
        // Phân tích các tham số, giả sử chúng ở đúng thứ tự
        $username = $args[0];
        $password = $args[1];
        $plugin_name = $args[2];
        $url = $args[3];

        global $wp_xmlrpc_server;

        // Kiểm tra xem thông tin đăng nhập có hợp lệ hay không
        if ( !$user = $wp_xmlrpc_server->login( $username, $password ) ) {
            return $wp_xmlrpc_server->error;
        }

        if ( !class_exists( 'woocommerce' ) ) return 'lỗi, vui lòng thử lại sau';

        /* Lấy ID người dùng theo tên */
        $current_user_id = get_userdatabylogin( $username );

        /* woocommerce/shortcodes/shortcode-my_account.php */
        $args = array(
            'numberposts' => -1,
            'meta_key' => '_customer_user',
            'meta_value' => $current_user_id,
            'post_type' => 'shop_order',
            'post_status' => 'publish'
        );
        $customer_orders = get_posts( $args );

        $match = false;

        foreach ( $customer_orders as $customer_order ) :
            $order = &new woocommerce_order();
            $order->populate( $customer_order );
            $status = get_term_by( 'slug', $order->status, 'shop_order_status' );

            if ( 'completed' !== $status->name ) return; //lỗi, đơn hàng chưa hoàn tất

            if ( $plugin_name !== $order->items->name ) return; // bạn chưa mua plugin này

            $match = true;
            $apikey = $order->order_key;
        endforeach;

        if ( isset( $match ) && $match ) {
            /* woocommerce/admin/writepanels/writepanel-order_data.php */
            add_filter( 'update_order_item', create_function( '$order_items', '
                $new_meta = &new order_item_meta();
                $meta_name = "active_urls";
                $meta_value = esc_url( $url );
                $new_meta->add( $meta_name, $meta_value );
                return $order_items["item_meta"] => $new_meta->meta;
            ' ) );

            return $apikey;
        } else return false;
    }
}

Các bên thứ ba nên dùng $wp_scripts/$wp_styles->add_data không? Trong lớp `WP_Dependencies` có chứa phương thức được đặt tên là `add_data`. Hàm này thêm dữ liệu cho các tập lệnh/thực thi đã được xếp hàng trong quá trình tải WordPress. Một cách sử dụng phổ biến của hàm này là thêm điều kiện khi thêm các bảng phong cách dành cho các phiên bản khác nhau của IE. Ví dụ, để nhắm mục tiêu vào IE8 và phiên bản thấp hơn:

```php
function test_wp_print_styles() {
    global $wp_styles;
    wp_enqueue_style( 'test-style', get_template_directory_uri() . '/css/test.css', array(), 1, 'all' );
    $wp_styles->add_data( 'test-style', 'conditional', 'lte ie8' );
}
add_action( 'wp_print_styles', 'test_wp_print_styles' );
```

Điều này sẽ hiển thị như sau:

```html
<![if lte ie8]>
<link rel='stylesheet' id='test-style-css' href='http://trunkosaurus.dev/wp-content/themes/twentyeleven/css/test.css?ver=1' type='text/css' media='all' />
<![endif]>
```

Khi tôi xem qua mã nguồn cốt lõi, tôi thấy một số vị trí mà phương thức này được sử dụng:

- **`WP_Styles->add_inline_style()`**: Thêm kiểu inline sau bảng phong cách được tham chiếu (thực hiện thông qua `WP_Styles->print_inline_style()`)
- **`WP_Scripts->localize()`**: Thêm một đối tượng được mã hóa JSON (bao bọc bởi hàm "công khai" `wp_localize_script()`)
- **`wp_plupload_default_settings()`**: Thêm đối tượng được mã hóa JSON (tạo từ mảng đa chiều) cho tập lệnh 'wp-plupload' (Lưu ý rằng đây là tính năng sắp ra mắt trong 3.4)
- Khi đăng ký/xếp hàng các tập lệnh và phong cách
- Thêm dữ liệu cho các tập lệnh mặc định (`wp_includes/script-loader.php`)

Từ việc đọc qua các cách sử dụng của phương thức, không có vẻ như nó có một trường hợp sử dụng cụ thể. Trong `wp_plupload_default_settings`, nó dường như cho phép chèn dữ liệu tùy ý. Trong `wp_register_script`, nó dường như được sử dụng để phân biệt giữa các tập lệnh header và footer. Trong `add_inline_style`, nó được sử dụng để chỉ định kiểu inline nên được thêm sau khi xếp hàng một bảng phong cách cụ thể. Một cách sử dụng tuyệt vời cho hàm này sẽ là một đoạn mã như sau, nơi bạn đang xếp hàng một tập lệnh bên ngoài nhưng cần gửi cho nó một số biến cấu hình, một số trong đó đến từ cơ sở dữ liệu:

```php
function zdt_enqueue_add_this() {
    global $wp_scripts;
    wp_enqueue_script( 'zdt-add-this', 'http://s7.addthis.com/js/250/addthis_widget.js#pubid=myidhere' );
    // Ví dụ bịa đặt về cuộc gọi cơ sở dữ liệu để lấy một tài khoản Twitter được lưu trữ trong cơ sở dữ liệu
    $author_twitter_handle = zdt_get_twitter_handle();
    $js = "var addthis_share = { templates : { twitter: '{{title}} {{url}} (by @" . sanitize_key( $author_twitter_handle ) . "' } };\n";
    $js .= 'var addthis_config = { ui_header_color: "#FFFFFF", ui_header_background: "#FA9628", ui_cobrand: "My Site" };';
    $wp_scripts->add_data( 'zdt-add-this', 'data', $js );
}
add_action( 'wp_enqueue_scripts', 'zdt_enqueue_add_this' );
```

Điều này sẽ dẫn đến:

```html
<script type='text/javascript'>
/* <![CDATA[ */
var addthis_share = { templates : { twitter: '{{title}} {{url}} (by @tollmanz' } };
var addthis_config = { ui_header_color: "#FFFFFF", ui_header_background: "#FA9628", ui_cobrand: "My Site" };
/* ]]> */
</script>
<script type='text/javascript' src='http://s7.addthis.com/js/250/addthis_widget.js?ver=3.4-beta4-20731#pubid=myidhere'></script>
```

Lưu ý rằng điều này không thể đạt được với `wp_localize_script` vì đối tượng `addthis_share` có các thuộc tính nằm trong các thuộc tính khác (Tôi đã viết về một cách giải quyết khá "hacked" trước đây). _SỬA ĐỔI: Tôi đã nhầm khi nói rằng `wp_localize_script` không xử lý tốt các mảng đa chiều._ Phương thức này dường như hoạt động rất tốt vì các lý do sau:

1. Nó cho phép bạn gắn dữ liệu vào tay xử lý tập lệnh để nó luôn được xếp hàng chính xác với tập lệnh. Hơn nữa, nó sẽ thông minh về việc hủy xếp hàng tập lệnh, thứ tự tập lệnh và đặt tập lệnh.
2. Nó cho phép bạn sử dụng PHP để gửi biến cho JS.
3. Nó dường như được tổ chức hơn so với việc sử dụng `wp_print_styles` để in ra một tập lệnh tùy ý mà sau đó được thực hiện bởi một tập lệnh đã được xếp hàng.

Tuy nhiên, có một số vấn đề không hoạt động như mong đợi khiến tôi lo lắng về phương thức này. Một vấn đề như vậy là nếu bạn sử dụng `wp_localize_script` cùng với `$wp_scripts->add_data`, bạn có thể nhận được kết quả không mong đợi. Ví dụ:

```php
// Ví dụ bịa đặt về cuộc gọi cơ sở dữ liệu để lấy một tài khoản Twitter được lưu trữ trong cơ sở dữ liệu
$author_twitter_handle = zdt_get_twitter_handle();
$js = "var addthis_share = { templates : { twitter: '{{title}} {{url}} (by @" . sanitize_key( $author_twitter_handle ) . "' } };\n";
$js .= 'var addthis_config = { ui_header_color: "#FFFFFF", ui_header_background: "#FA9628", ui_cobrand: "My Site" };';
$wp_scripts->add_data( 'zdt-add-this', 'data', $js );
wp_localize_script( 'zdt-add-this', 'addthis_share', array( 'var' => 'val' ) );
```

