Đã thất bại khi thay đổi kích thước hình ảnh Mình đã thêm hỗ trợ chủ đề cho post_thumbnails với ba kích thước mới, mình muốn thay đổi kích thước tất cả hình ảnh cũ được tải lên trước đó. Mình đã viết đoạn mã sau:

function resizeImages() {
    require ( ABSPATH . 'wp-admin/includes/image.php' );
    global $wpdb;
    $images = $wpdb->get_results( "SELECT ID FROM $wpdb->posts WHERE post_type = 'attachment' AND post_mime_type LIKE 'image/%' ORDER BY ID DESC");
    foreach ($images as $image) {
        $fullsizepath = get_attached_file( $image->ID );
        $metadata = wp_generate_attachment_metadata( $image->ID, $fullsizepath );
        // Nếu nó không thành công, điều đó có nghĩa là không có gì thay đổi (giá trị cũ == giá trị mới)
        if (wp_update_attachment_metadata( $image->ID, $metadata )) {
            echo $fullsizepath . " resized" . "<br/>";
        }
    }
}

