Lượt xem tăng gấp đôi Tôi đang gặp một vấn đề nhỏ khi hiển thị số lượt xem bài viết trên blog của tôi, đó là mỗi lần truy cập bài viết thì số lượt xem lại tăng gấp đôi. Tôi không biết tại sao điều này lại xảy ra vì tôi không thêm bất kỳ mã nào vào file `single.php`. Dưới đây là các quy tắc và mã được sử dụng để truyền hàm theo dõi vào `wp_head`:

```php
function cosonix_set_post_views($postID) {
    $count_key = 'count_post_views';
    $count = get_post_meta($postID, $count_key, true);

    if ($count == '') {
        $count = 0;
        delete_post_meta($postID, $count_key);
        add_post_meta($postID, $count_key, '0');
    } else {
        $count = $count + 1;
        update_post_meta($postID, $count_key, $count);
    }
}

// Để đảm bảo tính chính xác của số lượt xem, hãy loại bỏ việc dự trữ trước nội dung
remove_action('wp_head', 'adjacent_posts_rel_link_wp_head', 10, 0);

// Thêm hàm theo dõi vào wp_head
function track_post_views() {
    if (is_single() && !is_page()) {
        global $post;
        cosonix_set_post_views($post->ID);
    } else {
        return;
    }
}

add_action('wp_head', 'track_post_views');

function cosonix_get_post_views($postID) {
    $count_key = 'count_post_views';
    $count = get_post_meta($postID, $count_key, true);

    if ($count == '') {
        delete_post_meta($postID, $count_key);
        add_post_meta($postID, $count_key, '0');
        return "0";
    }

    return $count;
}
```

