Làm thế nào để tôi chuyển một đối số cho bộ đếm của riêng tôi? Tôi đã thiết lập một bộ đi bộ tùy chỉnh, và nó hoạt động như mong muốn khi tôi mã hóa cứng biến của tôi. Điều mà tôi muốn là có thể gọi bộ đi bộ của mình và truyền cho nó một biến được sử dụng trong bộ đi bộ. Ví dụ: 'walker' => new Plus_walker( $refine => 'review'), Bộ đi bộ mà tôi đã điều chỉnh để đầu ra http://URL/review để tìm bài viết trong danh mục đánh giá cho mục menu này. Nhưng tôi muốn có thể sử dụng cùng một bộ đi bộ cho 'previews', 'interviews' và nhiều hơn nữa. Cho đến nay những nỗ lực của tôi tại việc đưa vào các biến chỉ phá hỏng toàn bộ mọi thứ, 'Parse error: syntax error, unexpected T_DOUBLE_ARROW'. Tôi biết rằng tôi có thể chỉ viết lại mã và tạo vài bộ đi bộ khác nhau (Review_walker, Preview_walker, v.v.), nhưng điều này chỉ dường như sai (và tôi hình dung rằng điều này có thể là một điều quan trọng cần biết...) Mã bộ đi bộ của tôi ở đây: 
class plus_walker extends Walker_Nav_Menu {
  var $refine;
  function __construct($refine) {
    $this->refine = $refine;
  }

  function start_el(&$output, $item, $depth, $args) {
    global $wp_query;
    $indent = ( $depth ) ? str_repeat( "\t", $depth ) : '';
    $class_names = $value = '';
    $classes = empty( $item->classes ) ? array() : (array) $item->classes;
    $class_names = join( ' ', apply_filters( 'nav_menu_css_class', array_filter( $classes ), $item ) );
    $class_names = ' class="'. esc_attr( $class_names ) . '"';
    $output .= $indent . '<li id="menu-item-'. $item->ID . '"' . $value . $class_names .'>';
    $attributes  = ! empty( $item->attr_title ) ? ' title="'  . esc_attr( $item->attr_title ) .'"' : '';
    $attributes .= ! empty( $item->target )     ? ' target="' . esc_attr( $item->target     ) .'"' : '';
    $attributes .= ! empty( $item->xfn )        ? ' rel="'    . esc_attr( $item->xfn        ) .'"' : '';
    $attributes .= ! empty( $item->url )       ? ' href="'   . esc_attr( $item->url     )  . '' : ''; //Đây là nơi tôi muốn cho đối số sống.
    $modded_url = substr($attributes,0,-1) . '+' . $refine . '"';
    $item_output = $args->before;
    $item_output .= '<a'. $modded_url .'>';
    $item_output .= $args->link_before .$prepend.apply_filters( 'the_title', $item->title, $item->ID ).$append;
    $item_output .= $description.$args->link_after;
    $item_output .= '</a>';
    $item_output .= $args->after;
    $output .= apply_filters( 'walker_nav_menu_start_el', $item_output, $item, $depth, $args );
  }
}
