Và đây là mã điền vào các trường thả xuống:

//Mã này điền vào trường thả xuống cho các chương trình đại học để sử dụng mã này, thêm các chương trình vào lớp CSS của trường thả xuống để được điền vào.

add_filter('gform_pre_render', '<CAMPUSNAME>_populate_ugradprograms');

function <CAMPUSNAME>_populate_ugradprograms($form){
    foreach($form['fields'] as &$field){
        if($field['type'] != 'select' || strpos($field['cssClass'], 'programs') === false)
            continue;
        // bạn có thể thêm các tham số bổ sung ở đây để thay đổi các bài viết được lấy
        // thêm thông tin: http://codex.wordpress.org/Template_Tags/get_posts

        $posts = get_posts('post_type=program_of_study&post_parent=0&orderby=title&order=asc&numberposts=-1&post_status=publish');

        // cập nhật 'Chọn một bài viết' thành bất cứ điều gì bạn muốn tùy chọn hướng dẫn để trở thành

        $choices = array(array('text' => 'Chọn một chương trình', 'value' => ' '));

        foreach($posts as $post){
            $choices[] = array('text' => $post->post_title, 'value' => $post->ID);
        }

        $field['cssClass'] = 'programs';
        $field['choices'] = $choices;
    }

    return $form;
}

