function myplugin_delete_image_items( $postid ) {
    $args = array(
        'post_type'     => 'myplugin_image_item',
        'cache_results' => false, // Vô hiệu hóa lưu trữ, được sử dụng cho các truy vấn một lần
        'no_found_rows' => true,    // Chúng tôi không cần phân trang, vì vậy hãy vô hiệu hóa nó
        'fields'        => 'ids',   // Chỉ trả về ID bài viết
        'meta_query'    => array(
            array(
                'key'     => 'myplugin_image_id',
                'value'   => $postid,
                'compare' => 'LIKE'
            )
        )
    );

    $image_item_ids = get_posts( $args );

    foreach( $image_item_ids as $image_item_id ) {
        $purge = wp_delete_post( $image_item_id, true ); // Xóa mục hình ảnh, bỏ qua thùng rác
    }

    wp_reset_postdata();
}

