Phân trang không hoạt động (nội dung trùng lặp) Mỗi trang của tôi hiển thị cùng một nội dung. Trang 1 được truy vấn để hiển thị 2 bài đăng, và nó hiển thị chính xác. Trang hai hiển thị chính xác cùng 2 bài đăng như trang 1. Đây là mã của tôi: (functions.php) (Đây là mã đã được làm sẵn mà tôi tìm thấy trên mạng).

function wp_corenavi() {
    global $wp_query, $wp_rewrite;
    $pages = '';
    $max = $wp_query->max_num_pages;
    if (!$current = get_query_var('paged')) $current = 1;
    $a['base'] = str_replace(999999999, '%#%', get_pagenum_link(999999999));
    $a['total'] = $max;
    $a['current'] = $current;
    $total = 1; //1 - hiển thị văn bản "Trang N của N", 0 - không hiển thị
    $a['mid_size'] = 5; //số liên kết hiển thị ở bên trái và phải của trang hiện tại
    $a['end_size'] = 1; //số liên kết hiển thị ở đầu và cuối
    $a['prev_text'] = '&laquo; Prev'; //văn bản của liên kết "Trang trước"
    $a['next_text'] = 'Next &raquo;'; //văn bản của liên kết "Trang tiếp theo"
    if ($max > 1) echo '<div class="navigation">';
    if ($total == 1 && $max > 1) $pages = '<span class="pages">Page ' . $current . ' of ' . $max . '</span>'."\r\n";
    echo $pages . paginate_links($a);
    if ($max > 1) echo '</div>';
}

