    $nonce = $_POST['damad_inner_custom_box_nonce'];
    if ( ! wp_verify_nonce( $nonce, 'damad_inner_custom_box' ) )
        return $post_id;
    if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE )
        return $post_id;
    if ( 'page' == $_POST['post_type'] ) {
        if ( ! current_user_can( 'edit_page', $post_id ) )
            return $post_id;
    } else {
        if ( ! current_user_can( 'edit_post', $post_id ) )
            return $post_id;
    }
    $featureddata = $_POST['post-featured'];
    update_post_meta( $post_id, '_post_featured', $featureddata );
}
add_action( 'save_post', 'damad_save_postdata' );

Truy vấn bài viết thông qua URL của WordPress Tôi muốn tìm hiểu thêm về cách truy vấn các loại bài viết và trường tùy chỉnh của chúng trong WordPress. Tôi có hai câu hỏi... Tôi đã làm theo hướng dẫn này về Advanced Custom Fields và đang cố gắng hiểu những gì đang xảy ra ở đây. Đây được đặt trong tệp chức năng chủ đề của tôi.

add_action('pre_get_posts', 'my_pre_get_posts');

function my_pre_get_posts( $query ) {
    if( is_admin() ) {
        return;
    }

    if( isset($_GET['type']) ) {
        $type = explode(',', $_GET['type']);

        $meta_query[] = array(
            'key'       => 'type',
            'value'     => $type,
            'compare'   => 'IN',
        );
    }

    $query->set('meta_query', $meta_query);

    return; // luôn trả về
}

Bây giờ tôi hiểu rằng điều này cho phép URL thay đổi truy vấn dựa trên trường tùy chỉnh (trong trường hợp này là "type") và các giá trị được gán cho bài viết. Nhưng nó hoạt động chính xác như thế nào? Câu hỏi thứ hai của tôi là, khi tôi truyền truy vấn này trong URL của tôi như sau:

http://example.com/cars?type=coupe,hatchback

nó trả về tất cả các chiếc xe Coupe và Hatchback - điều đó thật tuyệt! Điều này dường như hoạt động vì trường tùy chỉnh của tôi ("type") chỉ chấp nhận một giá trị. Một chiếc xe phải là Coupe hoặc Hatchback - nó không thể là cả hai. Mặt khác, một số trường tùy chỉnh của tôi (lấy "for" làm ví dụ) có thể chứa nhiều hơn một giá trị. Trường tùy chỉnh "for" của tôi thực sự có thể chứa đến năm giá trị ("him", "her", "families" v.v.). Vì một lý do nào đó, mã trên không hoạt động tốt khi được gán cho trường tùy chỉnh (như "for") có thể có nhiều giá trị. Điều này hoàn toàn không hoạt động:

http://example.com/cars?for=him,her

Bạn có ý tưởng tại sao lại như vậy và tôi phải làm gì để khiến nó hoạt động? Cảm ơn trước.

