// Lưu dữ liệu hộp Meta

function whiteout_save_idea_meta($post_id, $post) {
    // Xác minh điều này đến từ màn hình của chúng tôi và với quyền ủy quyền thích hợp,

    // vì save_post có thể được kích hoạt vào những thời điểm khác

    if ( !wp_verify_nonce( $_POST['ideameta_noncename'], plugin_basename(__FILE__) )) {
        return $post->ID;
    }

    // Người dùng có được phép chỉnh sửa bài viết hoặc trang không?

    if ( !current_user_can( 'edit_post', $post->ID ))
        return $post->ID;

    // Được rồi, chúng tôi đã xác thực: chúng tôi cần tìm và lưu dữ liệu

    // Chúng tôi sẽ cho nó vào một mảng để dễ dàng lặp qua.

    $station_meta['_ideas_quicknote'] = $_POST['_ideas_quicknote'];

    // Thêm các giá trị của $station_meta làm trường tùy chỉnh

    foreach ($station_meta as $key => $value) { // Duyệt qua mảng $station_meta!

        if( $post->post_type == 'revision' ) return; // Đừng lưu dữ liệu tùy chỉnh hai lần

        $value = implode(',', (array)$value); // Nếu $value là một mảng, hãy biến nó thành CSV (hiếm khi)

        if(get_post_meta($post->ID, $key, FALSE)) { // Nếu trường tùy chỉnh đã có giá trị

            update_post_meta($post->ID, $key, $value);

        } else { // Nếu trường tùy chỉnh không có giá trị

            add_post_meta($post->ID, $key, $value);

        }

        if(!$value) delete_post_meta($post->ID, $key); // Xóa nếu trống

    }
}

add_action('save_post', 'whiteout_save_idea_meta', 1, 2); // lưu các trường tùy chỉnh

