$news_tmp[strtotime($d)]['author'] = 'Yahoo!';
$news_tmp[strtotime($d)]['title'] = $pipe['title'];
$c++;
if ($c == $news_limit) {break;}
}
// Sắp xếp theo chỉ số (ngày)
ksort($news_tmp);
// Cắt mảng xuống số bài viết được yêu cầu
$news = array_slice(array_reverse($news_tmp), 0, $news_limit);
// Hiển thị
foreach ($news as $n) {
echo "
<div class=\"newspost\">
<h2><a href=\"".htmlentities($n['permalink'])."\" title=\"Permalink to ".$n['title']."\" target=\"_blank\">".$n['title']."</a></h2>
<div class=\"thumbnailmt\">
the_post_thumbnail();
</div>
";
if( $n['author'] != 'Yahoo!' ) {
echo "
<span class=\"author\">Viết bởi: ".$n['author']." vào ngày " . $n['month'] . " " . $n['date'] . "</span>
";
}
else{
echo "
<span class=\"author\">Được tạo bởi Yahoo! Pipes. Viết vào ngày " . $n['month'] . " " . $n['date'] . "</span>
";
}
echo "
<div class=\"main-divider\"></div>
" . $n['excerpt'] . "
</div>
<!-- END NEWS ITEM -->
";
}
switch_to_blog(19);
