Làm thế nào để hiển thị thông tin chủ trang web trên mặt tiền (front end) của một trang đa trang web? Dùng plugin "user meta shortcode" Tôi đã tìm kiếm ở khắp mọi nơi để sửa chữa và không may mắn. Tôi đang sử dụng plugin "User Meta Shortcodes" để hiển thị thông tin người dùng. Plugin hoạt động tốt, vấn đề là nó không hiển thị thông tin meta từ chủ trang/blog, nó chỉ hiển thị thông tin meta của người quản trị siêu. Tôi giả định rằng hàm "get" được sử dụng trong plugin chỉ dành cho cài đặt đơn chứ không phải cài đặt đa trang. HỌC GIÚP! Ngoài ra, thông tin _user_meta chỉ hiển thị khi ai đó đã đăng nhập nhưng tôi muốn nó hiển thị công khai trên mỗi trang trong mạng của tôi dựa trên chủ trang/blog. Tôi rất mới với PHP, vì vậy bất kỳ sự hỗ trợ nào cũng sẽ được đánh giá cao. Cảm ơn! Dưới đây là mã cho plugin:

function userInfoSc ( $attributes, $content=null ) {
extract(shortcode_atts(array(
"field" => null,
"if" => null,
"nospan"=>false,
"size"=>32,
$default=>""
), $attributes));
//use {{empty}} instead of nothing inside the shortcode
if('{{empty}}'==$content) $content="";
global $user_info, $user_ID;
get_currentuserinfo();
$user_info = get_userdata($user_ID);
//if we have a test, we print the content in case the test is true. otherwise we print the field value concatenated with the content of the shortcode
if (isset($if) && $field != "avatar") {
if ( $if == $user_info->$field ) return do_shortcode($content);
}
else {
if ( is_user_logged_in() ) {
if( $field != "avatar" ) {
if ($nospan)
return $user_info->$field . do_shortcode($content);
else
return "<span class=\"userinfo\">" . $user_info->$field . do_shortcode($content) . "</span>";
}
else {
return get_avatar( $user_info->id, $size, $default, $user_info->first_name . " " . $user_info->last_name );
}
}
}
//return empty string in case we arrive here
return "";
}
add_shortcode('userinfo','userInfoSc');

