hàm greatest() trả về thuộc tính không xác định Tôi đang sử dụng hàm GREATEST() của MySQL để so sánh hai trường trong bảng và hiển thị giá trị số nguyên cao nhất trong vòng lặp. Hai trường này bao gồm điểm bầu cử cho bài viết: UP hoặc DOWN.

function vote_results($post_id) {
    global $wpdb;
    $table = $wpdb->prefix . "post_votes";
    $results = $wpdb->get_row("SELECT GREATEST(up, down) FROM $table WHERE voted_post_id = $post_id");
    echo $results->up; //hiển thị nếu có giá trị cao nhất
