    function get_random_gallery_images(){
        global $wpdb,$post;
        $ids = "";
        $counter = 0;
        $number_of_posts = 4;
        $args = array(
            'post_type' => 'attachment',
            'numberposts' => 4,
            'post_status' => null,
            'orderby' => 'rand',
            'post_parent' => $post->ID
        );
        $attachments = get_posts($args);
