làm một cuốn từ điển với wordpress Tôi biết rằng có các plugin từ điển trong kho lưu trữ wordpress. Các plugin này thường tìm kiếm các thuật ngữ từ điển trong nội dung bài viết và thêm một liên kết vào đó. Nhưng tôi chưa tìm thấy một plugin nào có thể tìm kiếm và thay thế các thuật ngữ trong các loại bài viết tùy chỉnh. Vì vậy, tôi đang cố gắng tạo plugin từ điển của riêng mình. Nếu bạn biết về một plugin nào làm được điều này, hãy cho tôi biết. Mã của tôi tìm kiếm tiêu đề bài viết trong các loại bài viết tùy chỉnh trong nội dung bài viết và thay thế nó bằng một liên kết. Vấn đề là nó thực hiện việc thay thế trong tất cả văn bản, bao gồm cả thuộc tính tiêu đề của một liên kết, và tôi không muốn thay thế nó bằng một liên kết trong những trường hợp này. Tôi có thể làm gì để nó không thay thế khi là văn bản thuộc tính liên kết? Đây là mã của tôi:

function reemplazar($cadena){
//lấy các bài viết loại từ điển
$args = array(
'showposts'   => -1,
'category_name' => 'glosario',
'post_type' => 'glosario',
);
$posts_array = get_posts( $args );

//Tạo một mảng với tiêu đề bài viết trong khóa và liên kết bài viết trong một giá trị
$reemplaza = array();
foreach ($posts_array as $posts) {
$reemplaza[get_the_title($posts->ID)] = '<a href="' . get_permalink($posts->ID) . '" title="' . $posts->post_content .'">' . get_the_title($posts->ID) . '</a>';
}

//tạo một mảng với các khóa mảng và thêm một regex để tìm kiếm các thuật ngữ trước dấu chấm, dấu phẩy hoặc khoảng trắng
$patterns = array_keys($reemplaza);
$pattern_final = array();
foreach ($patterns as $pattern) {
$pattern_final[] = '/(?<=\s|^)' . $pattern . '(?=\s|\.|\,|$)/i';
}

//thay thế trong nội dung bài viết các từ là thuật ngữ từ điển bằng một liên kết đến từ điển
$cadena = preg_replace($pattern_final, $reemplaza, $cadena, 1);
return $cadena;
}

//gọi hàm reemplazar khi hiển thị nội dung bài viết
add_filter('the_content', 'reemplazar');

