class Walker_Category_BS extends Walker_Category {
  function start_el( &$output, $category, $depth = 0, $args = array() ) {
    extract($args);
    $cat_name = esc_attr( $category->name );
    $cat_name = apply_filters( 'list_cats', $cat_name, $category );
    $link = '<a href="' . esc_url( get_term_link($category) ) . '" ';
    if ( $use_desc_for_title == 0 || empty($category->description) )
      $link .= 'title="' . esc_attr( sprintf(__( 'Xem tất cả bài viết thuộc danh mục %s' ), $cat_name) ) . '"';
    else
      $link .= 'title="' . esc_attr( strip_tags( apply_filters( 'category_description', $category->description, $category ) ) ) . '"';
    $link .= '>';
    $link .= $cat_name . '</a>';

    if ( !empty($feed_image) || !empty($feed) ) {
      $link .= ' ';
      if ( empty($feed_image) )
        $link .= '(';
      $link .= '<a href="' . esc_url( get_term_feed_link( $category->term_id, $category->taxonomy, $feed_type ) ) . '"';
      if ( empty($feed) ) {
        $alt = ' alt="' . sprintf(__( 'Feed cho tất cả bài viết thuộc danh mục %s' ), $cat_name ) . '"';
      } else {
        $title = ' title="' . $feed . '"';
        $alt = ' alt="' . $feed . '"';
        $name = $feed;
        $link .= $title;
      }
      $link .= '>';
      if ( empty($feed_image) )
        $link .= $name;
      else
        $link .= "<img src='$feed_image'$alt$title" . ' />';
      $link .= '</a>';
      if ( empty($feed_image) )
        $link .= ')';
    }

    if ( !empty($show_count) )
      $link .= ' (' . intval($category->count) . ')';

    if ( 'list' == $args['style'] ) {
      $output .= "\t<li";
      $class = 'list-group-item cat-item cat-item-' . $category->term_id;
      if ( !empty($current_category) ) {
        $_current_category = get_term( $current_category, $category->taxonomy );
        if ( $category->term_id == $current_category )
          $class .=  ' current-cat';
        elseif ( $category->term_id == $_current_category->parent )
          $class .=  ' current-cat-parent';
      }
      $output .=  ' class="' . $class . '"';
      $output .= ">$link\n";
    } else {
      $output .= "\t$link<br />\n";
    }
  }
}
/* end start_el */
}
/* end Walker_Category_BS */

