Menu danh mục loại bỏ các danh mục trống Tôi đang cố gắng tạo một menu có thể được quản lý từ trình chỉnh sửa menu, nhưng được lọc trước khi hiển thị. Cụ thể hơn, menu chứa các danh mục sản phẩm Woocommerce, được sắp xếp theo thứ bậc, và tôi muốn loại trừ các danh mục trống khỏi việc hiển thị. Điều này sẽ cho phép quản trị viên thiết lập thứ bậc một lần và menu phản ánh các sản phẩm hiện có trong kho hàng một cách động. Sau khi theo dõi bình luận của ENTHUSIAST về một bài đăng tương tự, tôi có mã sau đây nhưng không nhận được kết quả đúng. Tất cả các mục đều được hiển thị

function exclude_empty_cat_menu_items( $items, $menu, $args ) {
// Lấy danh sách các danh mục sản phẩm loại trừ các danh mục trống
$non_empty_categories = get_categories(array('taxonomy' => 'product_cat'));

// Duyệt qua các mục menu
foreach ( $items as $key => $item ) {
$is_empty = true;

// kiểm tra mục hiện tại có nằm trong mảng các danh mục không trống hay không
foreach ( $non_empty_categories as $key => $cat )
if ($item->title == $cat->name)
$is_empty = false;

// nếu nó là trống, xóa nó khỏi mảng
if ($is_empty) unset($items[$key]);
}

return $items;
}

add_filter( 'wp_get_nav_menu_items', 'exclude_empty_cat_menu_items', null, 3 );

Làm sao để hình ảnh hiển thị trong RSS Reader Tôi đang cố gắng để hiển thị hình ảnh giới thiệu của bài viết trong RSS Reader. Khi tôi xem vào mã XML gốc của RSS thì thấy hình ảnh đã được chèn thành công vào phần <description> và cũng dưới phần <post-thumbnail> (tôi tìm ra hàm này tại một chủ đề trên diễn đàn). Tuy nhiên, hình ảnh không hiển thị cùng với đoạn trích dẫn trong Google Reader, ví dụ. Tôi sử dụng các hàm và bộ lọc sau:

function insertThumbnailRSS($content) {
    global $post;
    if(has_post_thumbnail($post->ID)){
        $content = ''.get_the_post_thumbnail($post->ID, 'thumbnail', array('alt' => get_the_title(), 'title' => get_the_title(), 'style' => 'float:left;')).''.$content;
    }
    return $content;
}
add_filter('the_excerpt_rss', 'insertThumbnailRSS');
add_filter('the_content_feed', 'insertThumbnailRSS');

add_action('rss2_item', function(){
    global $post;
    $output = '';
    $thumbnail_ID = get_post_thumbnail_id( $post->ID );
    $thumbnail = wp_get_attachment_image_src($thumbnail_ID, 'thumbnail');
    $output .= '<post-thumbnail>';
    $output .= '<url>'. $thumbnail[0] .'</url>';
    $output .= '<width>'. $thumbnail[1] .'</width>';
    $output .= '<height>'. $thumbnail[2] .'</height>';
    $output .= '</post-thumbnail>';
    echo $output;
});

Thêm các loại file với plugin Tôi đã thử một vài plugin để thêm các loại MIME bao gồm cả plugin PJW Mime Config. Và việc thêm nó vào một file `functions.php` của theme cũng hoạt động tốt, quá, cho một trang không phải là WPMS. Nhưng tôi cần những thứ này được phép trên toàn mạng. Vì vậy tôi đã viết plugin của riêng mình để thực hiện điều này. Sau khi xem thông tin từ codex cũng như nhiều bài blog và câu hỏi WPSE này. Đây là những gì tôi đã tìm ra:

