     */
    public function register_plugin_styles() {
        wp_register_style( 'lc-form-widget', plugins_url( 'LeadCapture_Form_Widget/css/form.css' ) );
        wp_enqueue_style( 'lc-form-widget' );
    }

Tùy chỉnh câu lệnh tìm kiếm wordpress Phương thức parse_query của lớp WP_Query cho phép thực hiện truy vấn tùy chỉnh trên bảng tùy chỉnh không? Tôi hỏi như vậy vì Codex viết rằng "Để tùy chỉnh truy vấn, hãy thêm các tham số bổ sung vào (dãy) $search_query. Thực thi $search_query thông qua đối tượng $wp_query mới".

<?php
global $query_string;
$query_args = explode("&", $query_string);
$search_query = array();
foreach($query_args as $key => $string) {
$query_split = explode("=", $string);
$search_query[$query_split[0]] = urldecode($query_split[1]);
} // foreach
$search = new WP_Query($search_query);
?>

Vậy tôi nghĩ sẽ thực hiện điều gì đó như thế này: $search_query = parse_query('SELECT * FROM custom_talble'); Nếu điều này áp dụng ở đây Từ Codex: parse_query( $query ) Lấy một chuỗi truy vấn xác định yêu cầu, phân tích và điền đầy tất cả các thuộc tính ngoại trừ $posts, $post_count, $post và $current_post.

