WP_Query có trang không trả về 404, ngay cả khi bài viết không tồn tại Tôi đang xây dựng một chủ đề cho khách hàng, và một trong những yêu cầu của họ là cuộn không giới hạn trên trang "Biểu đồ". Họ muốn điều này được phân trang, và cuộn không giới hạn để tải trang tiếp theo bên dưới trang đầu tiên, hiển thị 40 bài đăng phổ biến nhất trên trang web. Để thực hiện điều này, tôi đã sử dụng một truy vấn WP_Query mới, đang chạy trong một mẫu trang tùy chỉnh. Cuộn không giới hạn hoạt động bằng cách lấy trang tiếp theo, và kết thúc khi nó gặp phải lỗi 404. Vấn đề là các trang bổ sung tiếp tục được tải, ngay cả khi không có bài đăng nào để hiển thị. Script không bao giờ gặp lỗi 404 nên nó tiếp tục tải. Đây là truy vấn của tôi:

<?php
$temp = $wp_query;
$wp_query= null;
$wp_query = new WP_Query();
$wp_query->query('posts_per_page=8&meta_key=_count-views_all&orderby=meta_value_num&order=DESC'.'&paged='.$paged);
$count = 1; while ($wp_query->have_posts()) : $wp_query->the_post();
?>
<div class="count"><?php echo $count; ?></div>
// vòng lặp ở đây
<?php $count++; endwhile; ?>
<?php content_nav( 'nav-below' ); ?>
<?php else : ?>
<?php get_template_part( 'no-results' ); ?>
<?php endif; ?>
<?php $wp_query = null; $wp_query = $temp;?>

Cùng một truy vấn hoạt động chính xác mà không có vấn đề gì trên trang chủ và các trang lưu trữ. Nó chỉ xảy ra khi nó ở trong một mẫu trang. Tôi đã bị bối rối bởi điều này trong ngày hôm qua, và tôi không chắc tại sao nó lại xảy ra. Bất kỳ ý tưởng nào sẽ rất được đánh giá cao :)

Lưu trữ cho Custom Post Types (không phải trang) Tôi muốn mở rộng tiện ích mặc định lưu trữ để nó không chỉ hiển thị danh sách {tháng: năm} của bài viết mặc định mà còn bao gồm cả loại bài viết tùy chỉnh mới của tôi. Từ ví dụ này, tôi đã có thể nhận được các mục {tháng: năm} mới xuất hiện trong danh sách lưu trữ nhưng không nhấp vào bất cứ điều gì. Sau đó ví dụ này cho thấy cách bao gồm các mục từ các loại bài viết tùy chỉnh trong vòng lặp và cho phép chúng nhấp vào và trả về kết quả thực tế. Tuy nhiên, vấn đề cuối cùng của tôi là khi nhấp vào mục {tháng: năm} trong danh sách nó cũng trả về kết quả từ các mục nhập trang. Tôi cần biết cách lọc các trang khỏi kết quả của tôi để chỉ có loại bài viết. Mã tôi có trong functions.php là:
/**
* Thêm các loại bài viết tùy chỉnh vào lưu trữ.
*/
add_filter( 'getarchives_where' , 'ucc_getarchives_where_filter' , 10 , 2 );
hàm ucc_getarchives_where_filter( $where , $r ) {
$args = array(
'public' => true ,
'_builtin' => false
);
$output = 'names';
$operator = 'and';
$post_types = get_post_types( $args , $output , $operator );
$post_types = array_merge( $post_types , array( 'post' ) );
$post_types = "'" . implode( "' , '" , $post_types ) . "'";
trả về str_replace( "post_type = 'post'" , "post_type IN ( $post_types )" , $where );
}
/**
* Thêm các loại bài viết tùy chỉnh vào kết quả vòng lặp.
*/
add_filter( 'request' , 'ucc_request_filter' );
hàm ucc_request_filter( $query ) {
// Xem trước không thích có post_type được đặt; nguồn cấp dữ liệu là sở thích cá nhân của tôi.
nếu ( trống( $query['preview'] ) && trống( $query['feed'] ) ) {
$my_post_type = $query['post_type'];
nếu ( trống( $my_post_type ) ) {
$query['post_type'] = 'bất kỳ';
}
}
trả về truy vấn;
}

