Hiển thị các thanh bên trên một trang Tôi cần tạo một danh sách các thanh bên trên một trang cụ thể. Tôi biết cách liệt kê tất cả các thanh bên đã được đăng ký, và tất cả các thanh bên đã được đăng ký có các widget hoạt động, nhưng tôi không biết cách lọc chúng để hiển thị các thanh bên được hiển thị trên một trang cụ thể bằng PHP. Để cố gắng giải quyết vấn đề này, tôi đã thay thế $wp_registered_sidebars bằng một lớp thực hiện ArrayAccess, giúp tôi đạt được 90% mục tiêu vì nó bắt các cuộc gọi và lưu trữ các thanh bên được yêu cầu, tuy nhiên các thanh bên này không bao giờ hiển thị do lỗi kiểm tra is_array hoặc các lỗi khác. Tôi cũng có thể bắt dynamic_sidebar_params và kiểm tra trường id trong phần tử mảng đầu tiên, nhưng điều này chỉ cho tôi biết các thanh bên động nào được gọi với các widget hoạt động, nó không cho tôi biết khi nào một thanh bên trống được thử nghiệm. Đây là lớp bắt của tôi:

class sidebar_counter implements \ArrayAccess {
private $container;
private $offsets = array();

function __construct( $container ) {
$this->container = $container;
}

public function addOffset( $offset ) {
if ( !in_array( $offset, $this->offsets ) ) {
$this->offsets[] = $offset;
}
}

public function getOffsets() {
return $this->offsets;
}

public function offsetExists( $offset ) {
$this->addOffset( $offset );
return isset($this->container[$offset]);
}

public function offsetGet( $offset ) {
$this->addOffset( $offset );
return isset($this->container[$offset]) ? $this->container[$offset] : null;
}

public function offsetSet( $offset, $value ) {
if ( is_null( $offset ) ) {
$this->container[] = $value;
} else {
$this->container[$offset] = $value;
$this->addOffset( $offset );
}
}

public function offsetUnset( $offset ) {
if ( ( $key = array_search( $offset, $this->offsets ) ) !== false ) {
unset( $this->offsets[$key] );
}
return isset($this->container[$offset]) ? $this->container[$offset] : null;
}
}

Cách sử dụng dự định:

// sớm nhất có thể:
global $wp_registered_sidebars;
$this->counter = new sidebar_counter( $wp_registered_sidebars );
$wp_registered_sidebars = $this->counter;

sau đó sau phần chân trang:

$sidebar_ids = $counter->getOffsets();

