);

$temp = $wp_query;
$wp_query = null;
$wp_query = new WP_Query($args);

Bây giờ tôi có thể chèn số lượng bài viết tùy chỉnh trong bảng điều khiển quản trị và vòng lặp hoạt động như mong muốn của tôi (tôi nhập "Blog pages show at most" và giá trị là 3) và bây giờ vòng lặp hiển thị ba bài viết như mong muốn của tôi.

