function wpt_save_events_meta($post_id, $post) {
    // Xác minh dữ liệu đến từ màn hình của chúng tôi và với quyền xác thực thích hợp,
    // vì save_post có thể được kích hoạt vào thời điểm khác
    if ( !wp_verify_nonce( $_POST['eventmeta_noncename'], plugin_basename(__FILE__) )) {
        return $post->ID;
    }

    // Người dùng có được phép chỉnh sửa bài viết hoặc trang không?
    if ( !current_user_can( 'edit_post', $post->ID ))
        return $post->ID;

    // Chúng ta đã xác thực: chúng ta cần tìm và lưu dữ liệu
    // Chúng ta sẽ cho nó vào một mảng để dễ dàng lặp qua.
    $events_meta['_location'] = $_POST['_location'];

    // Thêm giá trị của $events_meta dưới dạng trường tùy chỉnh
    foreach ($events_meta as $key => $value) { // Đi qua mảng $events_meta!
        if( $post->post_type == 'revision' ) return; // Không lưu dữ liệu tùy chỉnh hai lần
        $value = implode(',', (array)$value); // Nếu $value là một mảng, hãy chuyển nó thành CSV (không có khả năng)
        if(get_post_meta($post->ID, $key, FALSE)) { // Nếu trường tùy chỉnh đã có giá trị
            update_post_meta($post->ID, $key, $value);
        } else { // Nếu trường tùy chỉnh không có giá trị
            add_post_meta($post->ID, $key, $value);
        }
        if(!$value) delete_post_meta($post->ID, $key); // Xóa nếu trống
    }
}
