Cách phân tích mà không thay đổi chữ hoa và chữ thường trong wordpress the_content? Tôi đã tạo một chức năng phân tích tùy chỉnh cho plugin của tôi và nó hoạt động tốt. Tôi chỉ có một chút vấn đề! Đây là chức năng của tôi:

public function ys_glossary_parse( $text )
{
// Lấy tất cả các mục trong cơ sở dữ liệu
$terms = $this->get_all_termes();

// Lấy ID của trang từ điển
$glossary_page_id = get_option('ys_glossary_PageID');

if(!$glossary_page_id OR $glossary_page_id == 0)
{
return $this->admin_message('Bạn chưa có trang từ điển. Đi vào trang tùy chọn!');
}

// Lấy liên kết vĩnh viễn của trang
$permalink = get_permalink($glossary_page_id);

$text_to_link = apply_filters('ys_glossary_text', $terms);

$preg_flags = 'si';

$text = ' ' . $text . ' ';

if ( ! empty( $text_to_link ) ) {
foreach ( $text_to_link as $old_text ) {
// TODO: sửa đổi điều này để sử dụng chữ hoa/thường của từng từ mà không thay đổi chúng
$new_text = '<a href="' . esc_url( $permalink ) . '#' . $old_text . '" title="Liên kết đến định nghĩa" target="_blank">' . $old_text . '</a>';
$new_text = apply_filters('ys_glossary_text_linked_text', $new_text, $old_text, $permalink);
$text = preg_replace("|(?!<.*?)\b$old_text\b(?![^<>]*?)|$preg_flags", $new_text, $text);
}

// Xóa liên kết trong liên kết
$text = preg_replace("#(<a [^>]+>)(.*)<a [^>]+>([^<]*)</a>([^>]*)</a>#iU", "$1$2$3$4</a>" , $text );
}

return trim( $text );
}

