Nhiều tham số trong một URL viết lại loại bài đăng tùy chỉnh Tôi có một loại bài viết tùy chỉnh được gọi là "venues" hiện tại chúng hiển thị qua định dạng URL:

http://mywebsite.com/venue/{venue-name}

Tôi muốn có định dạng:

http://mywebsite.com/venue/{venue-suburb}/{venue-name}

Nhưng vùng ngoại ô không thực sự có bất kỳ mối liên hệ nào để lấy loại bài viết tùy chỉnh "venue". Tên luôn là duy nhất. Điều cần thiết phải xảy ra là vào thời điểm ghi lại, nó sẽ lấy {venue-suburb} dựa trên {venue-name} hoặc ID và ghi lại URL với thông tin đó trong đó. Đây có phải là điều gì đó có thể thực hiện được và nếu đúng vậy thì tôi có thể bắt đầu như thế nào?

**Cập nhật:** Đây là mã mà tôi đã có thể đưa ra sau một số nghiên cứu. Kết quả:

http://mywebsite.com/my-venues/{venue-suburb}/{venue-name}/{post_id}

add_action('init', 'myposttype_rewrite');

function myposttype_rewrite() {
    global $wp_rewrite;
    $queryarg = 'post_type=venue&p=';
    $wp_rewrite->add_rewrite_tag('%cpt_id%', '([^/]+)', $queryarg);
    $wp_rewrite->add_rewrite_tag('%suburb%', '([^/]+)', $queryarg);
    $wp_rewrite->add_rewrite_tag('%title%', '([^/]+)', $queryarg);
    $wp_rewrite->add_permastruct('venue', '/my-venues/%suburb%/%title%/%cpt_id%', false);
}

add_filter('post_type_link', 'venue_permalink', 1, 3);

function venue_permalink($post_link, $id = 0, $leavename) {
    global $wp_rewrite;
    global $wpdb;

    $post = &get_post($id);

    if ( is_wp_error( $post ) )
        return $post;

    $newlink = $wp_rewrite->get_extra_permastruct('venue');

    $sql = "
        SELECT meta_value
        FROM " . $wpdb->postmeta . "
        WHERE post_id = " . $post->ID . " AND meta_key = 'address'";

    $address = $wpdb->get_var( $sql );
    $address = unserialize( $address );

    $suburb = str_replace(" ", "-", strtolower($address['suburb']));
    $title = str_replace(" ", "-", strtolower(get_the_title( $post->ID )));

    $newlink = str_replace("%suburb%", $suburb, $newlink);
    $newlink = str_replace("%title%", $title, $newlink);
    $newlink = str_replace("%cpt_id%", $post->ID, $newlink);

    $newlink = home_url(user_trailingslashit($newlink));

    return $newlink;
}

