<?php

function add_post_type($name, $args = array()) {
    add_action('init', function() use($name, $args) {
        $upper = ucwords($name);
        $name = strtolower(str_replace(' ','_',$name));
        $args = array_merge(
            array(
                'public'=> true,
                'label' => "All $upper" . 's',
                'labels' => array('add_new_item' => "Add New $upper"),
                'support' => array('title', 'editor', 'author', 'thumbnail', 'excerpt', 'comments', 'custom-fields'),
                'taxonomies' => array('post_tag','category')
            ),
            $args
        );
        register_post_type('$name', $args);
    });
}

// Bây giờ chúng ta tạo và đăng ký một danh mục

function add_taxonomy($name, $post_type, $args = array()) {
    $name = strtolower($name);
    add_action('init', function() use($name, $post_type, $args) {
        $args = array_merge(
            array(
                'label' => ucwords($name),
            ),
            $args
        );
        register_taxonomy($name, $post_type, $args);
    });
}

