function my_custom_post_status(){
    if(current_user_can('update_core')) $p = true;
    else $p = false;

    register_post_status('archive', array(
        'label' => _x('Archive', 'post'),
        'public' => $p,
        'exclude_from_search' => true,
        'show_in_admin_all_list' => true,
        'show_in_admin_status_list' => true,
        'label_count' => _n_noop('Archive <span class="count">(%s)</span>', 'Archive <span class="count">(%s)</span>')
    ));
}

add_action('init', 'my_custom_post_status');

Thực tế điều này hoạt động tốt, nhưng tôi đã làm hỏng cơ sở dữ liệu hay chỉ đơn giản là loại đăng ký này chỉ là biến tải trang? (Tôi muốn nói đến "đăng ký", đó chỉ là hướng dẫn cách xử lý "đã lưu trữ" và "để lưu trữ" trong cơ sở dữ liệu hay không?) Đừng hỏi tại sao tôi làm điều này (!), chỉ cần tôi có thể làm điều đó - hoặc tôi đang làm lộn xộn mọi thứ... Cảm ơn tất cả các bạn đóng góp trên diễn đàn này!

Tại sao register_setting() không tạo ra một thiết lập? Tôi đang bối rối. Tôi đã nghiên cứu vấn đề này một cách điên cuồng, nhưng tôi không thể tìm ra lý do tại sao `register_setting()` không hoạt động cho tôi. Tôi mới bắt đầu phát triển plugin WP (rõ ràng rồi), vì vậy có lẽ đó chỉ là một điều ngớ ngẩn mà tôi bỏ lỡ. Hãy cùng xem xét nhé. Tôi chạy đoạn mã sau trong hàm tạo đối tượng:

add_action( 'admin_init', array( $this, 'register_settings_and_fields') );

Sau đó tôi có đoạn mã sau đây thực hiện những gì tôi cần:

/**
* Đăng ký cài đặt và trường cho trang cài đặt plugin.
*
* @since 1.0.0
*/
public function register_settings_and_fields() {
    register_setting('my_plugin_settings', 'my_plugin_settings');
    add_settings_section(
        'my_plugin_main_section', // ID được sử dụng để xác định phần này và đăng ký các tùy chọn
        'Cài đặt chính', // Tiêu đề được hiển thị trên trang quản trị
        array($this, 'my_plugin_main_settings_callback'), // Hàm callback được sử dụng để hiển thị mô tả của phần
        $this->plugin_slug // Trang để thêm phần tùy chọn này
    );

    // Bắt đầu định nghĩa các trường
    add_settings_field('my_plugin_data_1', 'Data 1', array( $this, 'my_plugin_data_1_setting' ), $this->plugin_slug, 'my_plugin_main_section');
}

// ... và tất nhiên là những dòng mã khác.

Tất nhiên, tôi có nhiều mã hơn để thực hiện các tác vụ như định nghĩa các hàm callback, v.v. Mọi thứ dường như hoạt động hoàn hảo, và phần cài đặt/trường được hiển thị đúng cách. Nhưng khi tôi truy cập vào `/wp-admin/options.php`, my_plugin_settings _chưa được tạo_. Tôi đang bối rối. Các bạn có ý tưởng gì không? Hãy cho tôi biết nếu bạn muốn xem thêm mã.

Trang menu phụ xóa cài đặt từ mảng tùy chọn khi lưu Tôi đang viết một chủ đề và thêm vào menu với nhiều trang con. Nó hoạt động tốt, ngoại trừ việc tôi đang cố gắng sử dụng chỉ một mảng để lưu tất cả các thiết lập vào cơ sở dữ liệu và điều này đang gây ra một số vấn đề. Vấn đề là khi mỗi trang con được lưu, nó chỉ lưu các giá trị từ trang đó vào mảng và xóa tất cả các giá trị khác từ các trang khác đã được lưu trước đó nên mảng cuối cùng chỉ chứa các giá trị từ một trang tại một thời điểm. Đây là các hàm mà tôi tạo các trang và đăng ký thiết lập:

add_action('admin_menu', 'theme_add_admin');
add_action('admin_init', 'register_theme_settings');

function theme_add_admin() {
add_menu_page( 'Theme Settings', 'Theme Settings', 'update_themes', 'themesettings', 'settings_messages_page');
add_submenu_page( 'themesettings', 'messages', 'Titles and Messages', 'update_themes', 'themesettings');
add_submenu_page( 'themesettings', 'layout', 'Layout', 'update_themes', 'settings_layout', 'settings_layout_page');
add_settings_messages();
