publish_post hook không hoạt động cho bài viết đã lên lịch Tôi gặp một chút vấn đề với wp-to-twitter khi xuất bản một tweet liên kết đến bài viết được đặt là "đang chờ" mà tôi đã gửi email đến trang web wordpress.org của mình. Email bao gồm một phần chân trang, trong đó có số điện thoại di động của tôi. Tôi quyết định tạo plugin riêng cho mình.

add_action('publish_post', 'tcr_tweet');

/* hàm */

function tcr_tweet($postID)
{
if ( $_POST['post_status'] == 'publish' ) && ( $_POST['original_post_status'] != 'publish' ) ) {
/* lấy bài viết đang được xuất bản */
$post = get_post($postID);
$post_title = $post->post_title;

/* lấy tác giả của bài viết */
$author_id=$post->post_author;

/* tác giả cần có một twitterid trong dữ liệu meta của họ */
$author = get_the_author_meta('twitterid',$author_id );

/* lấy permalink và rút ngắn nó */
$url = get_permalink($postID);
$short_url = getBitlyUrl($url);

// kiểm tra để đảm bảo rằng tweet nằm trong giới hạn 140 ký tự
// nếu không, rút ngắn và thêm dấu chấm lửng và dành chỗ cho liên kết.

if (strlen($post_title) + strlen($short_url) > 100) {
$total_len = strlen($post_title) + strlen($short_url);
$over_flow_count = $total_len - 100;
$post_title = substr($post_title,0,strlen($post_title) - $over_flow_count - 3);
$post_title .= '...';
}

// thêm vào liên kết bit.ly đã được rút ngắn

$message = "New: ".$post_title." - ".$short_url." by @".$author." #hashtag";

if ( $post->post_status != 'publish' ) return;

// gọi hàm tweet để tweet ra thông điệp
goTweet($message);
}
}

Plugin của tôi khá đơn giản, nó gọi ra hàm bit.ly của tôi và sau đó gọi đến một hàm khác để tweet, các hàm này được sử dụng ở nơi khác và hoạt động hoàn hảo. Vấn đề của tôi là nếu tôi lên lịch đăng bài, không có gì được tweet, nếu tôi nhấp vào nút "Xuất bản" trên một bài viết mới, tôi nhận được một màn hình trắng, nhưng tweet được gửi đi. Làm thế nào để tôi có thể nhắm mục tiêu đúng vào các bài viết đã lên lịch? Tôi đã kiểm tra dữ liệu $_POST và nó có vẻ ổn. Mã dường như khá đơn giản, vì vậy tôi đang bỏ lỡ điều gì đó ...

Chỉnh sửa: Tôi có một số nhầm lẫn về cách WordPress hoạt động với các bài viết đã lên lịch post_status='future' khi thời gian đến và bài viết cần được đưa lên trực tiếp, chắc chắn nó trở thành post_status='publish' vì nó không còn là bài viết 'future' nữa. Vì vậy, hàm của tôi nên được kích hoạt khi

add_action('publish_post', 'tcr_tweet');
add_action('publish_future_post', 'tcr_tweet');
add_action('future_to_publish', 'tcr_tweet');

các hành động này được kích hoạt. Tôi cần kiểm tra xem ngày đã qua thay thế, nếu trạng thái bài viết vẫn là 'future' chưa?

cột tùy chỉnh sắp xếp trong thư viện phương tiện Tôi đang cố gắng tạo một cột tùy chỉnh có thể sắp xếp trong thư viện phương tiện truyền thông. Tôi đã tìm thấy rất nhiều ví dụ cho bài viết, và người dùng nhưng không thể làm cho chúng hoạt động trên trang thư viện phương tiện truyền thông.

function wpse_hook_isv_columns() {
    add_action('manage_media_custom_column', 'isv_custom_media_column_content',10,2);
    add_filter('manage_media_columns', 'isv_custom_media_column_headings');
    add_filter('manage_media_imwidth_sortable_columns', 'imwidth_column_register_sortable' );
}
add_action( 'admin_init', 'wpse_hook_isv_columns' );

function isv_custom_media_column_headings($defaults) {
    $defaults['isv_width'] = __( 'Width', 'imwidth' );
    $defaults['isv_height']    = 'Height';
    return $defaults;
}

function isv_custom_media_column_content($column_name,$id) {
    $meta = wp_get_attachment_metadata($id);
    switch ($column_name) {
        case 'isv_width':
            $imWidth = get_post_meta($id, "_im_width", true);
            if(  $imWidth ) :
                echo $imWidth .' ('.$meta['width'].')';
            else : // Thêm giá trị meta nếu không tồn tại
                update_post_meta($id, '_im_width', $meta['width']);
                echo $meta['width'].' (cập nhật)';
            endif;
            break;
        case 'isv_height':
            $desc = get_the_content();
            echo $meta['height'] ? $meta['height'] : $none;
            break;
    }
}

// Đăng ký cột là có thể sắp xếp?
function imwidth_column_register_sortable( $columns ) {
    $custom = array(
        // id cột meta => giá trị sử dụng trong truy vấn
        'imwidth'    => 'Width',
    );
    return wp_parse_args($custom, $columns);
}

// Ví dụ này tôi tìm thấy hoạt động!
function registerdate($columns) {
    $columns['registerdate'] = __('Registered', 'registerdate');
    return $columns;
}
add_filter('manage_users_columns', 'registerdate');

function registerdate_columns( $value, $column_name, $user_id ) {
    if ( 'registerdate' != $column_name )
        return $value;
    $user = get_userdata( $user_id );
    $registerdate = $user->user_registered;
    return $registerdate;
}
add_action('manage_users_custom_column',  'registerdate_columns', 10, 3);

function registerdate_column_sortable($columns) {
    $custom = array(
        // id cột meta => giá trị sử dụng trong truy vấn
        'registerdate'    => 'registered',
    );
    return wp_parse_args($custom, $columns);
}
add_filter( 'manage_users_sortable_columns', 'registerdate_column_sortable' );

Làm thế nào tôi có thể làm cho isv_width có thể sắp xếp? Mọi sự giúp đỡ đều được đánh giá cao!

sắp xếp bài viết theo getPostViews trong functions.php Tôi có hàm sau đây trong functions.php cho phép sắp xếp theo thứ tự bảng chữ cái hoặc theo thời gian gần đây nhất. Tôi muốn thay đổi thứ tự bảng chữ cái thành sắp xếp theo lượt xem nhiều nhất. Đây là mã của tôi cho trình sắp xếp, đó là một menu thả xuống chọn:

function sorter($wp_query) {
if(mysql_real_escape_string($_REQUEST["sorting"]) == "date"){
usort($wp_query->posts, 'cmp_date');
}else if(mysql_real_escape_string($_REQUEST["sorting"]) == "title"){
usort($wp_query->posts, 'cmp_alpha');
}
}

Và đây là mã cho trình sắp xếp:

