    foreach ($comments as $comment) {
        $output .= '<li><strong>'. $comment->comment_author . ' nói</strong> : "' . strip_tags($comment->com_excerpt). '..."</li>';
    }

    $output .= '</ul>';

    echo $output;
}//end function

