Làm thế nào để tải thư viện kịch bản trong quản trị viên từ plugin trong wrapper không xung đột? Tôi cần thực hiện một meta box cho một số trường tùy chỉnh trong CPT của tôi (`xyz`), và để sắp xếp các trường, tôi cần thực hiện các tab. Và tôi được dạy để tải jQuery / JavaScripts sử dụng `wp_enqueue_script()`, vì vậy từ plugin của tôi, tôi đã thêm vào đoạn mã sau (với ý kiến của Chip Bennett trong đầu, tôi loại bỏ `wp_register_script()` và chỉ sử dụng `wp_enqueue_script()` và _tránh_ hủy đăng ký các script mặc định):

```php
function my_scripts() {
    wp_enqueue_script( 'jquery-lib-scripts', plugins_url( '/js/jquery-1.10.2.min.js', __FILE__ ) );
    wp_enqueue_script( 'jquery-ui-for-tabs', plugins_url( '/js/jquery-ui.js', __FILE__ ) );
    //wp_enqueue_script( 'plugin-scripts', plugins_url( '/js/plugin-scripts.js', __FILE__ ) );
    wp_enqueue_style( 'plugin-style', plugins_url( 'plugin-style.css', __FILE__ ) );
}
add_action('admin_enqueue_scripts', 'my_scripts');
```
Vì vậy các tập tin được tải toàn cục trên bảng điều khiển quản trị. Mọi thứ đều ổn, mặc dù tôi biết rõ về các tập lệnh quản trị WP mặc định `jquery`, `jquery-ui-core`, và `jquery-ui-tabs`. Nhưng không hiểu sao các tập lệnh của tôi không xung đột, và hoạt động với các tab trong trang `post-new.php` (Thêm mới) của CPT `xyz` của tôi; nhưng lại phá vỡ các tab trong trang `post.php` (màn hình chỉnh sửa của CPT `xyz`). Tôi đang làm việc trên môi trường phát triển localhost sử dụng WAMP, và sử dụng WP 3.9.1, trong khi tôi đã thử vô hiệu hóa tất cả các plugin khác và chuyển sang chủ đề mặc định T14. Chỉ mới phát hiện ra rằng, với mã của tôi các tab hoạt động trên mọi trang, nhưng nếu tôi kích hoạt bất kỳ plugin nào khác, ngay cả Akismet, nó cũng **XUNG ĐỐT**. Tôi đã tìm hiểu về các wrapper noConflict, nhưng giả định rằng chúng chỉ dành cho các tập lệnh tùy chỉnh, nhưng **làm thế nào tôi có thể xếp hàng các tập lệnh thư viện cho plugin của tôi trong một wrapper noConflict**?

Làm thế nào để thêm một điều kiện lọc dựa trên các thẻ điều kiện liên quan đến trang Tôi đang phát triển một plugin WordPress và không thể thêm các bộ lọc điều kiện dựa trên thẻ điều kiện. Đây là mã của tôi:
add_Action('init', 'determine_location');
function determine_location() {
$d = get_option('display_locations'); // đây là một trường hộp kiểm trong cài đặt plugin với 7 tùy chọn
nếu (isset($d)) {
nếu ($d[0] == 'home') {
nếu (is_home()) {
add_filter('the_excerpt', 'insert_buttons_to_post_top');
add_filter('the_content', 'insert_buttons_to_post_top');
}
} nếu khác ($d == 'post' || $d == 'post') {
nếu (is_single()) {
add_filter('the_content', 'insert_buttons_to_post_top');
}
} nếu khác ($d[0] == 'page' || $d == 'page' || $d == 'page') {
nếu (is_page()) {
add_filter('the_content', 'insert_buttons_to_post_top');
}
} nếu khác ($d[0] == 'category' || $d[1] == 'category' || $d[2] == 'category' || $d[3] == 'category') {
nếu (is_category()) {
add_filter('the_excerpt', 'insert_buttons_to_post_top');
add_filter('the_content', 'insert_buttons_to_post_top');
}
} nếu khác ($d[0] == 'tag' || $d[1] == 'tag' || $d[2] == 'tag' || $d[3] == 'tag' || $d[4] == 'tag') {
nếu (is_tag()) {
add_filter('the_excerpt', 'insert_buttons_to_post_top');
add_filter('the_content', 'insert_buttons_to_post_top');
}
} nếu khác ($d[0] == 'archive' || $d[1] == 'archive' || $d[2] == 'archive' || $d[3] == 'archive' || $d[4] == 'archive' || $d[5] == 'archive') {
nếu (is_archive()) {
add_filter('the_excerpt', 'insert_buttons_to_post_top');
add_filter('the_content', 'insert_buttons_to_post_top');
}
}
}
}
chức năng insert_buttons_to_post_top() {
trả về "<div>Output</div>"
}
Hiện tại mã này không hiển thị đầu ra. Có vấn đề gì ở đây?

W3 Total Cache - Chuyển đổi Apache rewrite sang Nginx Tôi đang cố gắng chuyển đổi các quy tắc chuyển hướng (rewrite) sau của Apache sang Nginx:

<IfModule mod_rewrite.c>
    RewriteEngine On
    RewriteBase /
    RewriteCond %{REQUEST_METHOD} !=POST
    RewriteCond %{QUERY_STRING} =""
    RewriteCond %{REQUEST_URI} \/$
    RewriteCond %{HTTP_COOKIE} !(comment_author|wp\-postpass|w3tc_logged_out|wordpress_logged_in|wptouch_switch_toggle) [NC]
    RewriteCond "%{DOCUMENT_ROOT}/wp-content/cache/page_enhanced/%{HTTP_HOST}/%{REQUEST_URI}/_index.html" -f
    RewriteRule .* "/wp-content/cache/page_enhanced/%{HTTP_HOST}/%{REQUEST_URI}/_index.html" [L]
</IfModule>

Sau đây là những gì tôi đã thực hiện:

# Đặt một biến để khắc phục sự thiếu hụt của điều kiện lồng nhau
set $cache_uri $request_uri;

# Yêu cầu POST và URL có chuỗi truy vấn nên luôn được gửi đến PHP
if ($request_method = POST) {
    set $cache_uri 'no cache';
}

if ($query_string != "") {
    set $cache_uri 'no cache';
}

# Không lưu trữ các URI chứa các phân đoạn sau
if ($request_uri ~* "(\/wp-admin\/|\/xmlrpc.php|\/wp-(app|cron|login|register|mail)\.php|wp-.*\.php|index\.php|wp\-comments\-popup\.php|wp\-links\-opml\.php|wp\-locations\.php)") {
    set $cache_uri "no cache";
}

# Không sử dụng bộ nhớ đệm cho người dùng đã đăng nhập hoặc người dùng đã bình luận gần đây
if ($http_cookie ~* "comment_author|wp\-postpass|w3tc_logged_out|wordpress_logged_in|wptouch_switch_toggle") {
    set $cache_uri 'no cache';
}

# Nếu tập tin bộ nhớ đệm không tồn tại, gửi nó đến Apache để xử lý
location / {
    try_files /wp-content/cache/page_enhanced/example.com/$cache_uri/_index.html @backend;
}

# Gửi các yêu cầu PHP đến Apache
location ~* \.php$ {
    include /usr/local/etc/nginx/proxypass.conf;
    proxy_pass http://127.0.0.1:80;
}

# Gửi các yêu cầu PHP đến Apache
location @backend {
    include /usr/local/etc/nginx/proxypass.conf;
    proxy_pass http://127.0.0.1:80;
}

Điều tôi thắc mắc là liệu tôi có bỏ lỡ điều gì hay đã làm sai điều gì không?

Làm cho plugin của tôi sẵn sàng dịch thuật. Poedit không hoạt động Tôi đang xây dựng một plugin mà cho đến nay mọi việc diễn ra tốt đẹp. Tôi muốn bắt đầu làm cho nó sẵn sàng để bản địa hóa. Tôi không biết điều gì đang sai, nhưng nó khiến tôi bối rối khi tôi cố gắng tải nó vào Poedit. Vậy nên chúng ta hãy thực hiện từng bước một theo nhiều hướng dẫn khác nhau cho tôi. Vì vậy trong myplugin.php tôi tải nội dung sau đây để nói với WP rằng các tệp ngôn ngữ của tôi nằm ở đâu (sau khi thực sự tạo thư mục).

function ap_action_init() {
    // Bản địa hóa
    load_plugin_textdomain( 'myplugin', false, dirname( plugin_basename( __FILE__ ) ) . '/languages/' );
}

add_action('init', 'ap_action_init');

Sau đó tôi điều chỉnh tất cả các chuỗi cần dịch trong tệp của tôi (nằm trong thư mục admin).

<h2><?php _e('MyPlugin Settings', 'myplugin'); ?></h2>
<?php _e('Element Width', 'myplugin'); ?>
<?php _e('This defines the default width of your Elements', 'myplugin'); ?>

Cho đến nay mọi thứ đều ổn, tôi nghĩ vậy. Nhưng sau đó tôi mở Poedit. Tôi bảo Poedit lưu tệp "myplugin-nl_NL.po" trong thư mục "languages" trong plugin của tôi. Tôi đặt đường dẫn cơ sở là "../" Và tôi đặt đường dẫn của mình là "./admin" hoặc "admin" (nếu tôi cho nó "/admin", hoặc bất cứ điều gì khác, nó cho tôi lỗi rằng thư mục không tồn tại. Vì vậy tôi đoán nó tìm thấy các thư mục của tôi). Tôi bảo Poedit tìm kiếm các từ khóa "__()" và "_e()". Và sau đó tôi nhấn OK! Mỗi lần (dù tôi có thử những gì đi nữa) nó không hiển thị bất kỳ chuỗi nào để dịch, trong khi đó nếu tôi nhập một tệp .po thông thường nó sẽ hiển thị rất nhiều chuỗi.

