function mytheme_save_data($post_id) {
    global $meta_box, $food_box;
    global $wpdb;

    //die( var_dump( $_POST, $_GET, $_REQUEST ) );

    // KHÔNG may mắn $foodbox không bao gồm trường 'n11'

    foreach ($food_box['fields'] as $field) {
        $old = get_post_meta($post_id, $field['id'], true);
        $new = $_POST[$field['id']];

        if ($new && $new != $old) {
            update_post_meta($post_id, $field['id'], $new);
        } elseif ('' == $new && $old) {
            delete_post_meta($post_id, $field['id'], $old);
        }
    }

    $new = $_POST['n11']; // giải pháp tạm thời và không phù hợp: $_POST có trường này
    update_post_meta($post_id, 'n11', $new);
}

