    if( $_GET['lang']=='es_US' ){
        $_SESSION['WPLANG'] = 'es_US';
    } elseif( $_GET['lang']=='en_US' ){
        $_SESSION['WPLANG'] = 'en_US';
    } else {
        //Đặt lại thành giá trị mặc định nếu nó không phải là es_US hoặc en_US.
        $_SESSION['WPLANG'] = '';
    }
    //Khi $_SESSION['WPLANG'] đã được thiết lập, xác định giá trị của nó cho WPLANG.
    define ('WPLANG', $_SESSION['WPLANG']);
    //... nếu $_GET không được thiết lập, hãy kiểm tra xem $_SESSION['WPLANG'] đã được thiết lập trước đó hay chưa...
} elseif( isset($_SESSION['WPLANG']) ){
    //Nếu nó là es_US hoặc en_US, hãy xác định WPLANG theo cách đó.
    if( $_SESSION['WPLANG']=='es_US' || $_SESSION['WPLANG']=='en_US' ){
