    } else {
        //Đặt lại thành giá trị mặc định nếu nó không phải là es_US hoặc en_US.
        define ('WPLANG', '');
    }
    //... và cuối cùng chỉ đặt WPLANG thành một chuỗi trống (giá trị mặc định).
