function wptuts_options_validate( $input ) {
    $default_options = wptuts_get_default_options();
    $valid_input = $default_options;
    $wptuts_options = get_option('theme_wptuts_options');
    $submit = ! empty($input['submit']) ? true : false;
    $reset = ! empty($input['reset']) ? true : false;
    $delete_logo = ! empty($input['delete_logo']) ? true : false;
    $delete_fav = ! empty($input['delete_fav']) ? true : false;

    foreach ( $wptuts_options as $key => $value ) {
        if ( $submit ) {
            if ( $wptuts_options[$key] != $input[$key] && $wptuts_options[$key] != '' ) {
                delete_image( $wptuts_options[$key] );
                $valid_input[$key] = $input[$key];
            }
        } elseif ( $reset ) {
            delete_image( $wptuts_options[$key] );
            $valid_input[$key] = $default_options[$key];
        } elseif ( $delete_logo ) {
            delete_image( $wptuts_options[$key] );
            $valid_input[$key] = '';
        }

        if ( $submit ) {
            if ( $wptuts_options[$key] != $input[$key] && $wptuts_options[$key] != '' ) {
                delete_image( $wptuts_options[$key] );
                $valid_input[$key] = $input[$key];
            }
        } elseif ( $reset ) {
            delete_image( $wptuts_options[$key] );
            $valid_input[$key] = $default_options[$key];
        } elseif ( $delete_fav ) {
            delete_image( $wptuts_options[$key] );
            $valid_input[$key] = '';
        }
    }

    return $valid_input;
}

function delete_image( $image_url ) {
    global $wpdb;

    // Chúng ta cần lấy ID meta của hình ảnh
    $query = "SELECT ID FROM wp_posts where guid = '" . esc_url($image_url) . "' AND post_type = 'attachment'";
    $results = $wpdb -> get_results($query);

    // Và xóa chúng (nếu có nhiều hơn một tệp đính kèm trong Thư viện)
    foreach ( $results as $row ) {
        wp_delete_attachment( $row -> ID );
    }
}

