function getSliderImages() {
    global $wpdb, $theme_shortname;
    $query = "SELECT * FROM $wpdb->options AS o1 WHERE o1.option_name LIKE '%$theme_shortname_header_image%'";
    $imgs = $wpdb->get_results($query);

