Sửa đổi tập tin mẫu tùy chỉnh nhưng is_home() trả về true, và không có 404 Tôi muốn tạo một số trang tùy chỉnh cho chủ đề của tôi không xuất hiện trong danh sách Trang trong wp-admin. Tôi có lớp sau đây bắt URL:

class jtvRewrite {
var $path = '';

function __construct($path) {
$this->path = $path;
register_activation_hook( __file__, array($this, 'activate') );
// Viết quy tắc -> Thêm biến số truy vấn -> Tính lại các quy tắc viết lại
add_filter('rewrite_rules_array', array($this, 'create_rewrite_rules'));
add_filter('query_vars',array($this, 'add_query_vars'));
add_filter('admin_init', array($this, 'flush_rewrite_rules'));
add_action('template_redirect', array($this, 'template_redirect_intercept') );
}

function activate() {
global $wp_rewrite;
$this->flush_rewrite_rules();
}

function create_rewrite_rules($rules) {
global $wp_rewrite;
$newRule = array($this->path . '/(.+)' => 'index.php?' . $this->path . '='.$wp_rewrite->preg_index(1));
$newRules = $newRule + $rules;
return $newRules;
}

function add_query_vars($qvars) {
$qvars[] = $this->path;
return $qvars;
}

function flush_rewrite_rules() {
global $wp_rewrite;
$wp_rewrite->flush_rules();
}

function template_redirect_intercept() {
global $wp_query;
if ($wp_query->get($this->path)) {
$this->output($wp_query->get($this->path));
exit;
}
}

function output( $output ) {
global $wp_query;
if (file_exists( TEMPLATEPATH . '/' . $this->path . '/' . $output . '.php' )) {
include( TEMPLATEPATH . '/' . $this->path . '/' . $output . '.php' );
exit;
} else {
return $wp_query->is_404();
}
}
}

$member = new jtvRewrite('member');

Tuy nhiên, nếu tôi chạy 'is_home()' trên trang này nó trả về true. Điều đó có ý nghĩa vì đằng sau việc viết lại là "/index.php?member=profile". Có điều gì đó tôi có thể ném vào đó để không phải là trang chủ? Lý do là tôi có một số hàm khác thêm thứ gì đó vào trang chủ trên "is_home()". Thứ hai, tôi đã có "return $wp_query->is_404();" ở đó nếu tệp chủ đề không có sẵn (tức là trang không tồn tại), nhưng trên một URL không tồn tại chỉ trả về một trang trống (WP_DEBUG true không trả về gì cả). Ai biết cách gửi 404 chính xác?

_Chỉnh sửa với giải pháp:_ Otto đề nghị thêm "$wp_query->is_home = false" vào "template_redirect_intercept()" - điều đó hoạt động rất tốt. Và sau đó tôi đã thực hiện hàm "output" kiểm tra xem có hàm nào tồn tại hay không dựa trên đường dẫn đã được yêu cầu ban đầu. Nếu hàm đó tồn tại (xem bên dưới), nó gọi hàm đó. Hàm đó cung cấp chuyển hướng. Nếu không, 404 được thiết lập. Bằng cách này tôi có thể sử dụng lớp "class jtvRewrite" bao nhiêu tùy thích cho mỗi tệp mẫu mới tôi thêm.

function template_redirect_intercept() {
global $wp_query;
if ($wp_query->get($this->path)) {
$wp_query->is_home = false; // đặt tham số is_home thành false
nếu (! $this->output($wp_query->get($this->path)))
$wp_query->set_404();
}
}

function output( $output ) {
global $wp_query;
$function = 'jtv_rewrite_action_' . $this->path . '_' . $output;
nếu (function_exists($function)) {
$function();
exit;
} khác {
trả về sai;
}
}

Sau đó tôi có thể sử dụng hàm sau để chuyển đến tệp mẫu chính xác:

