add_filter('post_type_link', 'properties_permalink_rewrite', 1, 3);

function properties_permalink_rewrite( $post_link, $id = 0, $leavename = FALSE ) {
if ( strpos('%property_type%', $post_link) === 'FALSE' ) {
return $post_link;
}

$post = get_post($id);
if ( !is_object($post) || $post->post_type != 'property' ) {
return $post_link;
}

$terms = wp_get_object_terms($post->ID, 'property_type');
if ( !$terms ) {
return str_replace('%property_type%/', '', $post_link);
}

return str_replace('%property_type%', $terms[0]->slug, $post_link);
}

// Fix permalinks
//---------------------------

flush_rewrite_rules();
}

