Cách buộc một hàm chạy sau cùng khi lưu bài viết? Tôi không biết cách để buộc hàm này chạy như là hàm cuối cùng sau khi tất cả các hoạt động lưu khác từ WP đã được thực hiện. Đây là mã của tôi trong plugin:

add_action( 'save_post', 'do_custom_save' );

function do_custom_save( $post_id ) {

   // Không tự lưu

   if( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) return;

   // đảm bảo người dùng hiện tại có thể chỉnh sửa bài viết

   if( ! current_user_can( 'edit_post' ) ) return;

   // đảm bảo loại bài viết

   if ( ! get_post_type($post_id) == 'post' ) return;

   $latitude  = $_POST['rw_company_latitude'];

   $longitude = $_POST['rw_company_longitude'];

   $zoom      = '6';

   $lat_lon_zoom = $latitude . ', ' . $longitude . ', ' . $zoom ;

   update_post_meta($post_id, 'company_map', $lat_lon_zoom );

}

** Làm thế nào để buộc mã này được thực thi và lưu biến trộn như là việc cuối cùng? Sau khi tất cả các hoạt động lưu và cập nhật khác đã được thực hiện.** Bởi vì ngay bây giờ nó được cập nhật tốt, nhưng sau đó lại được ghi đè bởi giá trị từ trường bản đồ gốc $_POST['company_map']. Tôi cần phải nói với WP theo một cách nào đó rằng hàm này nên chạy như là hàm cuối cùng khi thực hiện lưu/cập nhật bài viết. Làm thế nào để làm điều đó?

Thiết lập tiêu đề bài viết từ hai trường meta Trong một loại bài đăng tùy chỉnh tôi đã vô hiệu hóa tiêu đề bài viết, tuy nhiên trong danh sách bài viết và trong slug nó chỉ hiển thị tiêu đề là "auto-draft". Tôi muốn tự động lấy hai phần của bài viết meta và làm chúng thành tiêu đề và slug. Tôi nghĩ rằng điều đó sẽ hoạt động, nhưng tôi không thể thực hiện được:

function set_event_title( $data , $postarr ) {
if($data['post_type'] == 'events') {
$event_date = get_post_meta($post_id,'event_datetime',true);
$event_venue = get_post_meta($post_id, 'venue_name' , true);
$event_title = $event_venue . ' - ' . $event_date;
$post_slug = sanitize_title_with_dashes ($event_title,'','save');
$post_slugsan = sanitize_title($post_slug);
$data['post_title'] = $post_title;
$data['post_name'] = $post_slugsan;
}
return $data;
}
add_filter( 'wp_insert_post_data' , 'set_event_title' , '99', 2 );

Chèn thẻ wordpress bên dưới bài viết thông qua functions.php Tôi đang trong quá trình xây dựng chủ đề Wordpress của tôi từ đầu và kiến thức PHP của tôi bị hạn chế. Điều tôi đang cố gắng làm là chèn thẻ dưới mỗi bài viết. Tôi có thể làm điều này bằng cách chèn mã vào tệp single.php của tôi nhưng tôi muốn thực hiện điều này thông qua tệp functions.php. Tôi đã chèn hộp tác giả dưới mỗi bài viết thông qua tệp functions.php. Tôi đã nhận được mã cho việc đó ở đâu đó trực tuyến và tôi muốn làm điều tương tự với các thẻ. Đây là mã hộp tác giả trong tệp functions.php của tôi.

function get_author_bio($content='') {
    global $post;
    $post_author_name=get_the_author_meta("display_name");
    $post_author_description=get_the_author_meta("description");
    $html="<div class='author-box'>\n";
    $html.="<h5 class='author'>Về tác giả</h5>\n";
    $html.="<div class='author-entry'>\n";
    $html.="<img width='100' height='100' class='avatar' src='http://www.gravatar.com/avatar.php?gravatar_id=".md5(get_the_author_email()). "&default=".urlencode
    ($GLOBALS['defaultgravatar'])."&size=80&r=PG' alt='PG'/>\n";
    $html.="<h6 class='author-name'>".$post_author_name."</h6>\n";
    $html.= "<p>".$post_author_description."</p>\n";
    $html.="</div>\n";
    $html.="</div>\n";
    $content .= $html;
    return $content;
}
add_filter('the_content', 'get_author_bio');

