<?php
if ( ! function_exists( 'wp_new_user_notification' ) ) {
    function wp_new_user_notification( $user_id, $plaintext_pass = '' ) {
        $user = new WP_User( $user_id );
        $user_login = stripslashes( $user->user_login );
        $user_email = stripslashes( $user->user_email );
        $user_first = stripslashes( $user->user_firstname );
        $user_last = stripslashes( $user->user_lastname );
        $user_full = $user_first . ' ' . $user_last;
        $user_role = $user->roles[0];
        $client_report_id = get_the_author_meta( 'am_client_report_id', $user_id );
        $am_company_logo = get_the_author_meta( 'am_company_logo', $client_report_id );

        if ( $user_first == '' ) {
            $user_name = $user_login;
        } else {
            $user_name = $user_full;
        }

        $email_subject = "Chào mừng đến với SITE NAME " . $user_name . "!";

        ob_start();

        if ( $user_role == 'client' ) {
            include ABSPATH . 'wp-content/plugins/email_system/welcome/client.php';
        } else {
            include ABSPATH . 'wp-content/plugins/email_system/welcome/user.php';
        }

        $message = ob_get_contents();

        ob_end_clean();

        wp_mail( $user_email, $email_subject, $message );
    }
}
