/* Lưu siêu dữ liệu bài viết trên móc 'save_post'. */
add_action( 'save_post', 'smashing_flautist_access_save_meta', 10, 2 );

/* Lưu siêu dữ liệu hộp meta. */
function smashing_flautist_access_save_meta( $post_id, $post ) {

/* Đảm bảo tất cả các tham chiếu $wpdb trong hàm này đều trỏ đến biến này */
global $wpdb;

/* Xác minh mã nonce trước khi tiếp tục. */
if ( !isset( $_POST['smashing_flautist_access_nonce'] ) || !wp_verify_nonce( $_POST['smashing_flautist_access_nonce'], basename( __FILE__ ) ) )
return $post_id;

/* Lấy đối tượng loại bài viết. */
$post_type = get_post_type_object( $post->post_type );

/* Kiểm tra xem người dùng hiện tại có quyền chỉnh sửa bài viết hay không. */
if ( !current_user_can( $post_type->cap->edit_post, $post_id ) )
return $post_id;

/* Lấy dữ liệu được gửi và làm sạch nó để sử dụng làm lớp HTML. */
$new_meta_value = ( isset( $_POST['smashing-flautist-access'] ) ? sanitize_html_class( $_POST['smashing-flautist-access'] ) : '' );

/* Lấy khóa siêu dữ liệu. */
$meta_key = 'smashing_flautist_access';

/* Lấy giá trị siêu dữ liệu của khóa trường tùy chỉnh. */
$meta_value = get_post_meta( $post_id, $meta_key, true );

/* Nếu một giá trị siêu dữ liệu mới được thêm vào và không có giá trị cũ, hãy thêm nó. */
if ( $new_meta_value && '' == $meta_value )
{
add_post_meta( $post_id, $meta_key, $new_meta_value, true );
$wpdb->query($wpdb->prepare("UPDATE $wpdb->posts SET post_status = 'private' WHERE ID = ".$post_id." AND post_type ='post'"));
}

/* Nếu giá trị siêu dữ liệu mới không khớp với giá trị cũ, hãy cập nhật nó. */
elseif ( $new_meta_value && $new_meta_value != $meta_value )
{
update_post_meta( $post_id, $meta_key, $new_meta_value );
$wpdb->query($wpdb->prepare("UPDATE $wpdb->posts SET post_status = 'private' WHERE ID = ".$post_id." AND post_type ='post'"));
}

/* Nếu không có giá trị siêu dữ liệu mới nhưng có giá trị cũ, hãy xóa nó. */
elseif ( '' == $new_meta_value && $meta_value )
{
delete_post_meta( $post_id, $meta_key, $meta_value );
$wpdb->query($wpdb->prepare("UPDATE $wpdb->posts SET post_status = 'public' WHERE ID = ".$post_id." AND post_type ='post'"));
}
}

