        $wp_rewrite->page_structure = $wp_rewrite->page_structure . '.html';
}
Đối với các loại bài viết tùy chỉnh? Có một mẩu mã tương tự như trên cho phép tôi thay đổi hoặc thêm `.html` vào URL của loại bài viết tùy chỉnh không?

Nếu câu lệnh cho trang quản trị Làm thế nào để tôi viết điều kiện `if` để hiển thị mã cụ thể chỉ khi tôi vào trang này:
/wordpress/wp-admin/post-new.php? post_type = slideshow
Đây là những gì tôi đang cố gắng để nhận được ;) Cảm ơn Krzysiek!
hàm plu_admin_enqueue ($ hook) {
$ màn hình = get_current_screen ();
nếu ('post.php' == $ hook && $ screen-> post_type == 'slideshow') {
wp_enqueue_script ('plupload-all');
wp_register_script ('cplupload', get_template_directory_uri () . '/js/cplupload.js', mảng ('jquery'));
