$args=array(
'tag__in' => $tag_ids,
'post__not_in' => array($post->ID),
'showposts'=>4, // Số bài viết liên quan sẽ được hiển thị.
'caller_get_posts'=>1
);
$my_query = new wp_query($args);
if( $my_query->have_posts() ) {
while ($my_query->have_posts()) {
$my_query->the_post();
?>
<div class="relatedPosts"><a href="<?php the_permalink() ?>" rel="bookmark"><?php the_post_thumbnail(array(120,80)); ?></a>
<div class="relatedPosts_title"><a href="<?php the_permalink() ?>" rel="bookmark" title="Liên kết vĩnh viễn đến <?php the_title_attribute(); ?>"><?php the_title(); ?></a></div></div>
<?php
}
echo '';
}
}
$post = $backup;
wp_reset_query();
?>
</div>
<!-- bài viết 5-8 -->
<div>
......
</div>
</div>
</div>
