// Thêm các meta boxes vào các loại bài viết
function plib_add_box() {
    global $meta_box;

    foreach($meta_box as $post_type => $value) {
        add_meta_box($value['id'], $value['title'], 'plib_format_box', $post_type, $value['context'], $value['priority']);
    }
}

// Định dạng
function plib_format_box() {
    global $meta_box, $post;

    // Xác minh
    echo '<input type="hidden" name="plib_meta_box_nonce" value="', wp_create_nonce(basename(__FILE__)), '" />';
    echo '<table class="form-table">';

    foreach ($meta_box[$post->post_type]['fields'] as $field) {
        // Lấy dữ liệu meta hiện tại của bài viết
        $meta = get_post_meta($post->ID, $field['id'], true);

        echo '<tr>'.
            '<th style="width:20%"><label for="'. $field['id'] .'">'. $field['name']. '</label></th>'.
            '<td>';

        switch ($field['type']) {
            case 'text':
                echo '<input type="text" name="'. $field['id']. '" id="'. $field['id'] .'" value="'. ($meta ? $meta : $field['default']) . '" size="30" style="width:97%" />'. '<br />'. $field['desc'];
                break;

            case 'textarea':
                echo '<textarea name="'. $field['id']. '" id="'. $field['id']. '" cols="60" rows="4" style="width:97%">'. ($meta ? $meta : $field['default']) . '</textarea>'. '<br />'. $field['desc'];
                break;

            case 'select':
                echo '<select name="'. $field['id'] . '" id="'. $field['id'] . '">';
                foreach ($field['options'] as $option) {
                    echo '<option '. ( $meta == $option ? ' selected="selected"' : '' ) . '>'. $option . '</option>';
                }
                echo '</select>';
                break;

            case 'radio':
                foreach ($field['options'] as $option) {
                    echo '<input type="radio" name="' . $field['id'] . '" value="' . $option['value'] . '"' . ( $meta == $option['value'] ? ' checked="checked"' : '' ) . ' />' . $option['name'];
                }
                break;

            case 'checkbox':
                echo '<input type="checkbox" name="' . $field['id'] . '" id="' . $field['id'] . '"' . ( $meta ? ' checked="checked"' : '' ) . ' />';
                break;
        }

        echo    '<td>'.'</tr>';
    }

    echo '</table>';
}

// Lưu dữ liệu từ meta box
function plib_save_data($post_id) {
    global $meta_box, $post;

    // Xác minh
    if (!wp_verify_nonce($_POST['plib_meta_box_nonce'], basename(__FILE__))) {
        return $post_id;
    }

    // Kiểm tra > tự động lưu
    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
        return $post_id;
    }

    // Kiểm tra > quyền truy cập
    if ('page' == $_POST['post_type']) {
        if (!current_user_can('edit_page', $post_id)) {
            return $post_id;
        }
    } elseif (!current_user_can('edit_post', $post_id)) {
        return $post_id;
    }

    foreach ($meta_box[$post->post_type]['fields'] as $field) {
        $old = get_post_meta($post_id, $field['id'], true);
        $new = $_POST[$field['id']];

        if ($new && $new != $old) {
            update_post_meta($post_id, $field['id'], $new);
        } elseif ('' == $new && $old) {
            delete_post_meta($post_id, $field['id'], $old);
        }
    }
}

add_action('save_post', 'plib_save_data');

Custom Post Type .current-menu-item không áp dụng trên Custom Post Type Archive Page Tôi đang làm việc với các loại bài viết tùy chỉnh và tôi gặp khó khăn khi menu điều hướng không nhận được `.current-menu-item` trên mục `trang lưu trữ bài viết tùy chỉnh` của tôi. Thật ra, khi tôi ở trên trang đó hoặc bất kỳ bài viết tùy chỉnh nào, thay vì mục menu lưu trữ CPT nhận được lớp hiện tại, mục menu trỏ đến các bài viết lại nhận được `.current-menu-item` (trong trường hợp này là trang blog). Sau vài tiếng đồng hồ tìm kiếm trên Google, thử nghiệm và hack mã, tôi tìm thấy một bài viết trên WordPress và đây là bản sao chép chỉnh sửa của cách khắc phục:

// Kể từ WP 3.1.1, việc thêm các lớp cho kiểu CSS vào các phần tử cha của các loại bài viết tùy chỉnh chưa được thực hiện.

// Chúng ta muốn thêm các lớp chính xác vào phần tử cha của loại bài viết tùy chỉnh trong wp-nav-menu để tạo kiểu CSS và nhấn mạnh, vì vậy chúng tôi sẽ chỉnh sửa từng mục một...

// ID của mỗi liên kết là cần thiết cho từng mục bạn muốn chỉnh sửa

// Đặt đoạn mã này vào tệp functions.php của WordPress

function remove_parent_classes($class) {
  // kiểm tra các lớp trang hiện tại, trả về false nếu chúng tồn tại.
  return ($class == 'current_page_item' || $class == 'current_page_parent' || $class == 'current_page_ancestor' || $class == 'current-menu-item') ? FALSE : TRUE;
}

function add_class_to_wp_nav_menu($classes) {
  switch (get_post_type()) {
    case 'artist':
      // chúng ta đang xem một loại bài viết tùy chỉnh, vì vậy xóa các lớp 'current_page_xxx' và 'current-menu-item' khỏi tất cả các mục menu.
      $classes = array_filter($classes, "remove_parent_classes");

      // thêm lớp trang hiện tại vào một mục menu cụ thể (thay thế ###).
      if (in_array('menu-item-171', $classes)) {
        $classes[] = 'current_page_parent';
      }
      break;
  }
  return $classes;
}

add_filter('nav_menu_css_class', 'add_class_to_wp_nav_menu');

Giải pháp này hoạt động khi chúng ta sử dụng ID mục menu, nhưng tôi thấy nó rất lộn xộn và không thể sử dụng nó cho việc phát triển plugin... Có ý tưởng nào khác để chọn mục menu tương ứng với trang lưu trữ của các bài viết tùy chỉnh khi chúng ta đang ở trên trang lưu trữ hoặc trên một trong các bài viết tùy chỉnh theo cách đơn giản hơn không? Nói cách khác, một mẫu lưu trữ không nên chọn mục menu của chính nó theo mặc định phải không? Tôi chưa bao giờ nghĩ rằng việc nhấn mạnh một phần tử trong menu điều hướng của WordPress có thể là vấn đề với các loại bài viết tùy chỉnh, tôi cảm thấy hơi thất vọng. Dù sao đây là những đoạn mã tôi sử dụng để quản lý các bài viết tùy chỉnh (nghệ sĩ):

