Bây giờ tôi muốn biết cách thêm các hành động tùy chỉnh vào các liên kết mà tôi đã tạo. Có cách nào để gửi các biến đến một trang không? Để xử lý cơ sở dữ liệu của các liên kết này và cập nhật lại 'WP_List_Table' sau khi thực hiện hành động.

### Cập nhật 1

Dưới đây là mã đầy đủ cho lớp 'WP_List_Table':

<?php
// Lớp của chúng tôi mở rộng lớp WP_List_Table, vì vậy chúng tôi cần đảm bảo rằng nó tồn tại
if( ! class_exists( 'WP_List_Table' ) ) {
    require_once( ABSPATH . 'wp-admin/includes/class-wp-list-table.php' );
}

class Link_List_Table extends WP_List_Table {

    /**
     * Hàm khởi tạo, chúng tôi ghi đè lên hàm cha để truyền các tham số của riêng mình
     * Chúng tôi thường tập trung vào ba tham số: nhãn đơn và đa số, cũng như liệu lớp có hỗ trợ AJAX hay không.
     */
    function __construct() {
        parent::__construct( array(
            'singular'=> 'wp_list_text_link', // Nhãn đơn
            'plural' => 'wp_list_test_links', // Nhãn đa số, cũng sẽ là một trong các lớp bảng CSS
            'ajax'  => true // Chúng tôi sẽ không hỗ trợ AJAX cho bảng này
        ) );
    }

    /**
     * Định nghĩa các cột sẽ được sử dụng trong bảng
     * @return array $columns, mảng các cột để sử dụng với bảng
     */
    function get_columns() {
        return $columns= array(
            'col_person_name' => 'Name',
            'col_business_name' => 'Business Name',
            'col_person_email' => 'Email',
            'col_pserson_phone' => 'Contact Number',
            'col_request_status' => 'Status',
            'col_is_deleted' => 'Deleted'
        );
    }

    /**
     * Chuẩn bị bảng với các tham số khác nhau, phân trang, cột và các phần tử bảng
     */
    function prepare_items() {
        global $wpdb, $_wp_column_headers;
        $screen = get_current_screen();

        /* -- Chuẩn bị truy vấn của bạn -- */
        $query = "SELECT * FROM approval_requests";

        /* -- Tham số sắp xếp -- */
        // Các tham số sẽ được sử dụng để sắp xếp kết quả
        $orderby = !empty($_GET["orderby"]) ? mysql_real_escape_string($_GET["orderby"]) : 'ASC';
        $order = !empty($_GET["order"]) ? mysql_real_escape_string($_GET["order"]) : '';
        if(!empty($orderby) && !empty($order)){ $query.=' ORDER BY '.$orderby.' '.$order; }

        /* -- Tham số phân trang -- */
        // Số lượng phần tử trong bảng của bạn?
        $totalitems = $wpdb->query($query); // trả về tổng số hàng bị ảnh hưởng

        // Hiển thị bao nhiêu trên mỗi trang?
        $perpage = 20;

        // Trang này là trang nào?
        $paged = !empty($_GET["paged"]) ? mysql_real_escape_string($_GET["paged"]) : '';

        // Số trang
        if(empty($paged) || !is_numeric($paged) || $paged<=0 ){ $paged=1; }

        // Tổng số trang chúng ta có?
        $totalpages = ceil($totalitems/$perpage);

        // Điều chỉnh truy vấn để tính đến phân trang
        if(!empty($paged) && !empty($perpage)){
            $offset=($paged-1)*$perpage;
            $query.=' LIMIT '.(int)$offset.','.(int)$perpage;
        }

        /* -- Đăng ký phân trang -- */
        $this->set_pagination_args( array(
            "total_items" => $totalitems,
            "total_pages" => $totalpages,
            "per_page" => $perpage,
        ) );

        // Các liên kết phân trang được xây dựng tự động theo các tham số này

        /* -- Đăng ký các cột -- */
        $columns = $this->get_columns();
        $hidden = array();
        $sortable = array();
        $this->_column_headers = array($columns, $hidden, $sortable);

        /* -- Lấy các mục -- */
        $this->items = $wpdb->get_results($query);
    }

    /**
     * Hiển thị các hàng bản ghi trong bảng
     * @return chuỗi, echo dấu hiệu của các hàng
     */
    function display_rows() {
        // Lấy các bản ghi được đăng ký trong phương thức prepare_items
        $records = $this->items;

        list( $columns, $hidden ) = $this->get_column_info();

        // Vòng lặp qua từng bản ghi
        if(!empty($records)){foreach($records as $rec){

            // Mở dòng
            echo '<tr id="record_'.$rec->sr_no.'">';

            foreach ( $columns as $column_name => $column_display_name ) {

                // Thuộc tính kiểu cho từng cột
                $class = "class='$column_name column-$column_name'";
                $style = "";
                if ( in_array( $column_name, $hidden ) ) $style = ' style="display:none;"';
                $attributes = $class . $style;

                // Liên kết chỉnh sửa
                // Hiển thị ô
                switch ( $column_name ) {
                    case "col_person_name":
                        echo '<td '.$attributes.'>'.stripslashes($rec->person_name);
                        $actions = $this->get_bulk_actions();
                        echo $this->row_actions( $actions );
                        echo '</td>';
                        break;
                    case "col_business_name": echo '<td '.$attributes.'>'.stripslashes($rec->business_name).'</td>'; break;
                    case "col_person_email": echo '<td '.$attributes.'>'.$rec->person_email.'</td>'; break;
                    case "col_pserson_phone": echo '<td '.$attributes.'>'.$rec->pserson_phone.'</td>'; break;
                    case "col_request_status": echo '<td '.$attributes.'>'.$rec->request_status.'</td>'; break;
                    case "col_is_deleted": echo '<td '.$attributes.'>'.$rec->is_deleted.'</td>'; break;
                }

            }

            // Đóng dòng
            echo'</tr>';
        }}
    }

    function get_bulk_actions() {
        $actions = array();
        $actions['approv'] = '<a href="#">'.__( 'Approve' ).'</a>';
        $actions['reject'] = '<a href="#">'.__( 'Reject' ).'</a>';
        $actions['delete'] = '<a href="#">'.__( 'Delete' ).'</a>';
        $actions['view'] = '<a href="#">'.__( 'View' ).'</a>';
        return $actions;
    }

    function show_table(){
        $wp_list_table = new Link_List_Table();
        $wp_list_table->prepare_items();

        // Bảng các phần tử
        $wp_list_table->display();
    }

}
