Loại bài viết tùy chỉnh với pre_get_posts Tôi đang tạo một bài đăng tùy chỉnh cho lịch sự kiện. Bài đăng tùy chỉnh của tôi có 2 trường siêu dữ liệu tùy chỉnh được gọi là "event_star_date" & "event_end_date". Tôi muốn sử dụng `pre_get_posts` để loại trừ các sự kiện mà "event_end_date" của chúng nhỏ hơn ngày hôm nay hoặc "event_end_date" trống và "event_start_date" nhỏ hơn ngày hôm nay. Tôi đã xem một số mã nhưng cuối cùng không hoạt động cho tôi. Cảm ơn @cybnet Tôi đã gần như có được mã tôi cần, nhưng vẫn chưa hoạt động. Điều tôi cần có thể giống như thế này:

function bbwp_calendar_visible_events( $query ) {
    if ( !is_admin() && $query->is_main_query() ){
        if ( is_post_type_archive( $postType ) ) {
            $meta_query = array(
                'relation' => 'OR',
                array(
                    'relation' => 'AND',
                    array(
                        'key'   => 'event_start_date',
                        'value' => current_time( 'timestamp' ),
                        'type' => 'CHAR',
                        'compare' => '>=',
                    ),
                    array(
                        'key'   => 'event_end_date',
                        'value' => '',
                        'type' => 'CHAR',
                        'compare' => '=',
                    ),
                ),
                array(
                    'key'   => 'event_end_date',
                    'value' => current_time( 'timestamp' ),
                    'type' => 'CHAR',
                    'compare' => '>=',
                ),
            );
            $query->set( 'meta_query', $meta_query );
        }
    }
}

add_action( 'pre_get_posts', 'bbwp_calendar_visible_events' );

