Làm thế nào để lọc một meta key với các giá trị meta? Tôi có một loại bài viết tùy chỉnh mà tôi muốn lọc trên một giá trị meta. Tôi đã có thể sắp xếp các giá trị meta từ một khóa meta với mã sau:

// Đăng ký cột
hàm status_column_register ( $columns ) {
$columns['status'] = __( 'status', 'b_score' );
trả về $columns;
}
add_filter ( 'manage_edit-b_score_columns', 'status_column_register' );

// Hiển thị nội dung cột
hàm status_column_display ( $column_name, $post_id ) {
nếu ( 'status' != $column_name )
trở về;
$status = get_post_meta($post_id, 'status', true);
nếu ( !$status )
$status = '<em>' . __( 'undefined', 'b_score' ) . '</em>';
echo $status;
}
add_action ( 'manage_posts_custom_column', 'status_column_display', 10, 2 );

// Đăng ký cột như có thể sắp xếp
hàm status_column_register_sortable ( $columns ) {
$columns['status'] = 'status';
trả về $columns;
}
add_filter ( 'manage_edit-b_score_sortable_columns',
'status_column_register_sortable' );

// Sắp xếp cột
hàm status_column_orderby ( $vars ) {
nếu ( isset ( $vars['orderby'] ) && 'status' == $vars['orderby'] ) {
$vars = array_merge ( $vars, mảng (
'meta_key' => 'status',
'orderby' => 'meta_value'
) );
}
trả về $vars;
}
add_filter ( 'request', 'status_column_orderby' );

