// Ghi lại URL bài giảng
function sermon_rewrite() {
    $cpt = 'sermon';
    $tax = 'series';
    add_rewrite_rule(
        '^'.$cpt.'/([^/]+)/([^/]+)/([^/]+)/?',
        'index.php?post_type='.$cpt.'&'.$tax.'=$matches[1]&'.$tax.'=$matches[2]&'.$cpt.'=$matches[3]',
        'top'
    );
    add_rewrite_rule(
        'sermon/([^/]+)/page/?([0-9]{1,})/?$',
        'index.php?post_type='.$cpt.'&'.$tax.'=$matches[1]&paged=$matches[2]',
        'top'
    );
}
add_action('init','sermon_rewrite');
