Cách xử lý các biểu mẫu từ tiện ích thanh bên - Xử lý biến $_POST sử dụng get_field_name() Cảm ơn WordPress gọi nội dung của họ là "bài viết", nó làm cho việc tìm kiếm thông tin về cách xử lý biểu mẫu gửi bằng giao thức POST trở nên khó khăn. Câu hỏi của tôi rất đơn giản, câu trả lời sẽ đơn giản đối với một nhà phát triển WordPress giàu kinh nghiệm. Sử dụng một plugin WordPress có một biểu mẫu trong phương thức widget của lớp, tôi đặt tên cho các biến bằng hàm get_field_name của WordPress. Tôi không thể tìm thấy hàm tương ứng để xác định biến $_POST nào để xử lý. Tôi có thể tạo ra một giải pháp tạm thời, nhưng tôi muốn sử dụng khung WordPress dành riêng cho điều này. Tôi cần duy trì cấu trúc biến lớp để nhiều instance của widget này không có sự chồng chéo biến. Tôi có thể đơn giản chỉ định tên và sử dụng widget_id từ các đối số, nhưng điều đó không có vẻ như là cách _đúng đắn_ để tuân thủ theo khung. **Để làm rõ thêm, widget cung cấp một biểu mẫu cho phía người dùng, không phải phía quản trị viên.** Ví dụ:
class someWidget extends WP_Widget {
public function someWidget() {
$this->WP_Widget('somewidget', __('Some Widget'));
}

public function form($instance) {
}

public function update( $new_instance, $old_instance ) {
$instance = $old_instance;
return $instance;
}

public function widget($args, $instance) {
$before_title = $before_widget = $after_widget = $after_title = '';
extract($args, EXTR_IF_EXISTS);
echo $before_widget.$before_title.$instance['WidgetTitle'].$after_title;

$somewidget_variable = $_POST['????']; // < -- Hàm nào lấy được biến này?
if ($somewidget_variable) {
// những điều tuyệt vời
}
?>
<form method="POST">
<input id="<?php echo $this->get_field_id('somewidget_variable'); ?>" name="<?php echo $this->get_field_name('somewidget_variable'); ?>" type="text" value="<?php echo $somewidget_variable; ?>" />
<input type="submit" />
</form>
<?php
echo $after_widget;
}
}

$query->query_var['post_type'] không được thiết lập cho trang. Dựa trên phản hồi của @kaiser về khả năng lọc theo loại bài viết trên trang tìm kiếm, tôi muốn có thể tự động thêm tất cả các loại bài viết công khai có sẵn. Vì vậy, sau một số giúp đỡ từ @kaiser, tôi đã đưa ra:

function sw_custom_post_type_includes($query) {
    $args = array(
        'public' => true
    );
    $output = 'names'; // names hoặc objects, lưu ý rằng names là mặc định
    $operator = 'and'; // 'and' hoặc 'or'
    $post_types = get_post_types( $args, $output, $operator );

    if ( !is_search() && !in_array( get_post_type(), $post_types ) )
        return;

    $query->set( 'post_type', $post_types );
    return $query;
}
add_filter('pre_get_posts', 'sw_custom_post_type_includes');

Ban đầu nó hoạt động tốt, nhưng tôi gặp phải một vấn đề -> mọi thứ được lọc theo loại bài viết chính xác ngoại trừ khi tôi cố gắng sử dụng &post_type=page. Tôi thực sự nhận được lỗi chỉ mục không được định nghĩa cho `post_type`. Tôi không thể tìm ra lý do tại sao điều này không hoạt động. Vì vậy, tôi quyết định sử dụng `print_r($query->query_vars)` để xem mọi thứ có được kéo vào đúng cách không. Thật không may - đối với tất cả các loại bài viết ngoại trừ trang, biến đó được đặt. Tôi đã tham khảo ý kiến ​​với một nhà phát triển khác về vấn đề này và họ đã xác nhận nó. Đây là giải pháp tôi đã sử dụng để khắc phục sự cố này:

function sw_custom_post_type_includes($query) {
    if(isset($_GET['post_type']) && ((!isset($query->query_vars['post_type'])) || (isset($query->query_vars['post_type']) && $query->query_vars['post_type'] != 'nav_menu_item'))) {
        $query->set('post_type', urldecode($_GET['post_type']));
    }
}
add_action('pre_get_posts', 'sw_custom_post_type_includes');

