Làm sao để chọn từ một bảng WP mỗi 10s trong một lớp (OOP)? Tôi đang cố gắng chọn các bản ghi mỗi 10 giây từ các cột _message_ và _messagetwo_ trong bảng WordPress `wp_userlogin`, nhưng mã không được thực thi. Tôi gọi `wp_schedule_event` khi plugin của tôi được kích hoạt và tôi xóa tất cả các lịch trình khi plugin bị vô hiệu hóa. Tôi cũng đang sử dụng một hook kích hoạt/vô hiệu hóa cho bảng của tôi, nhưng tôi nghĩ rằng nó nên thực thi khối else `echo "wrong columns are empty";` khi các cột trống. Tôi gọi một đối tượng mới của lớp sau lớp người dùng. Tôi đã thử sử dụng chèn thay vì chọn nhưng hàm `refreshDatabase` không được thực thi.

// lớp nằm trong tệp chính

class user {

public function __construct() {

add_filter( 'cron_schedules', array( $this, 'setTimeForSchedule_event' ) );

// ở đây tôi gọi hàm refreshDatabase của tôi

add_action( 'my_schedule_action', array( $this, 'refreshDatabase' ) );

// đăng ký hook thành công

register_activation_hook( __FILE__, array( $this, 'getRefresh' ) );

register_deactivation_hook( __FILE__, array( $this, 'deactivation_schedules' ) );

}

}

public function getRefresh() {

nếu ( !wp_next_scheduled( 'my_schedule_action' ) ) {

wp_schedule_event( time(), 'tensec', 'my_schedule_action');

} khác {

echo "sai";

}

$sched = wp_get_schedule( 'my_schedule_action' );

nếu ( !$sched ) {

echo "sai wp_get_schedule";

}

}

hàm deactivation_schedules() {

wp_clear_scheduled_hook( 'my_schedule_action' );

}

hàm refreshDatabase() {

global $wpdb;

$user_info = get_userdata( 1 );

$this->user_email = $user_info->user_email;

$getmessage = $wpdb->get_results(

"CHỌN tin nhắn, messagetwo TỪ wp_userlogin NƯỚC người_email='$this->user_email'"

);

nếu ( $getmessage ) {

foreach ( $getmessage as $mess ) {

echo $mess->message;

echo $mess->messagetwo;

}

} khác {

// khi các cột trống -> câu này được viết trên trang tùy chọn

echo "sai các cột trống";

}

}

công khai hàm setTimeForSchedule_event( $schedules ) {

$schedules[ 'tensec' ] = mảng (

'khoảng thời gian' => 10,

'display' => __( 'Mỗi TenSec' )

);

trả về $schedules;

}

}

