add_action( 'add_meta_boxes', 'prfx_custom_meta' );

/**
* Xuất nội dung của meta box
*/
function prfx_meta_callback( $post ) {
    wp_nonce_field( basename( __FILE__ ), 'prfx_nonce' );
    $prfx_stored_meta = get_post_meta( $post->ID );
    ?>
    <p>
