function cd_meta_box_save( $post_id )
{
    // Ngừng nếu chúng ta đang tự động lưu
    if( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) return;

    // nếu nonce của chúng tôi không tồn tại, hoặc chúng tôi không thể xác minh nó, hãy dừng lại
    if( !isset( $_POST['meta_box_nonce'] ) || !wp_verify_nonce( $_POST['meta_box_nonce'], 'my_meta_box_nonce' ) ) return;

    // nếu người dùng hiện tại không thể chỉnh sửa bài viết này, hãy dừng lại
    if( !current_user_can( 'edit_post' ) ) return;

    // bây giờ chúng ta thực sự có thể lưu dữ liệu
    $allowed = array(
        'a' => array( // chỉ cho phép thẻ a
            'href' => array() // và những neo đó chỉ có thể có thuộc tính href
        )
    );

    // Có lẽ là một ý tưởng tốt để đảm bảo dữ liệu của bạn được thiết lập
    if( isset( $_POST['my_meta_box_text'] ) )
        update_post_meta( $post_id, 'my_meta_box_text', wp_kses( $_POST['my_meta_box_text'], $allowed ) );

}

