add_filter('add_attachment','generate_responsive_sizes');

function generate_responsive_sizes( $attachment_id ) {

    $image_post_data = get_post( $attachment_id );

    // dừng nếu loại bài viết không phải là đính kèm và loại MIME không phải là jpeg/jpg/gif
    if ( $image_post_data->post_type != 'attachment' || $image_post_data->post_mime_type != ( 'image/jpeg' || 'image/png' || 'image/gif' ) )

        return false;

    // dừng nếu chủ đề không phải là thuần túy - chỉ PURE nhận được hình ảnh đáp ứng, thêm các chủ đề mới với hình ảnh đáp ứng ở đây

    if ( ! isset( $_POST['post_data'] ) ) {

        return false;

    } else {

        if ( $_POST['post_data']['theme'] != 'pure' )

            return false;

    }

    $upload_dir = wp_upload_dir();

    $file = substr( strrchr( $image_post_data->guid, '/' ), 1 );

    $filepath = $upload_dir['path'] . '/' . $file;

    $file_arr = preg_split( '/\./', $file );

    $filename = $file_arr[0];

    $file_ext = $file_arr[1];

    $sizes = array(

        '1024' => array(

            'width' => 1024,

            'height' => 768,

            'crop' => true,

        ),

        '1680' => array(

            'width' => 1680,

            'height' => 1050,

            'crop' => true,

        ),

        '2560' => array(

            'width' => 2560,

            'height' => 1440,

            'crop' => true,

        ),

    );

    $new_sizes_generated = [];

    // trước tiên tạo các hình ảnh

    if ( ! is_wp_error( $image_post_data ) ) {

        foreach ($sizes as $key => $value) {

            $image = wp_get_image_editor( $filepath );

            $new_img_filepath = $upload_dir['path'] . '/' . $filename . '-' . $value['width'] . 'x' . $value['height'] . '.' . $file_ext;

            $dimensions = $image->get_size();

            // nếu kích thước hình ảnh mới không lớn hơn hình ảnh gốc, chúng tôi sẽ tiếp tục và không lưu một phiên bản mới của hình ảnh này

            if ( $dimensions['width'] < $value['width'] && $dimensions['height'] < $value['height'] ) {

                continue;

            }

            $image->resize( $value['width'], $value['height'], $value['crop'] );

            $image->save( $new_img_filepath );

        }

    }

    // bây giờ đính kèm chúng, chúng tôi làm điều này riêng biệt để tránh vòng lặp vô hạn của các tệp được thêm vào,

    // do đó kích hoạt toàn bộ hàm từ đầu, vì nó được gắn vào

    // `add_attachment`.

    if ( ! is_wp_error( $image_post_data ) ) {

        foreach ($sizes as $key => $value) {

            $new_img_filepath = $upload_dir['path'] . '/' . $filename . '-' . $value['width'] . 'x' . $value['height'] . '.' . $file_ext;

            // Kiểm tra sự tồn tại của một bản đính kèm với cùng một GUID để tránh

            // vòng lặp vô hạn như được ghi chú ở đầu vòng lặp foreach trên

            global $wpdb;

            $prefix = $wpdb->prefix;

            $attachment = $wpdb->get_col($wpdb->prepare("SELECT ID FROM " . $prefix . "posts" . " WHERE guid='%s';", $new_img_filepath ));

            if ( ! empty( $attachment ) ) {

                error_log(print_r('đã có bản đính kèm cho ' . $new_img_filepath, true ));

                return false;

            } else {

                error_log(print_r('không có bản đính kèm nào cho ' . $new_img_filepath, true ));

                $wp_filetype = wp_check_filetype(basename($new_img_filepath), null );

                $attachment = array(

                    'guid' => $new_img_filepath,

                    'post_mime_type' => $wp_filetype['type'],

                    'post_title' => preg_replace('/\.[^.]+$/', '', basename($new_img_filepath)),

                    'post_content' => '',

                    'post_status' => 'inherit'

                );

                wp_insert_attachment( $attachment, $new_img_filepath, 37 );

            }

        }

    }

}

