function show_home_meta_box() {
    global $home_meta_fields, $post;

    // Sử dụng nonce để xác minh

    echo '<input type="hidden" name="home_meta_box_nonce" value="'.wp_create_nonce(basename(__FILE__)).'" />';

    // Bắt đầu bảng trường và lặp qua từng trường

    echo '<table class="form-table">';

    foreach ($home_meta_fields as $field) {

        // Lấy giá trị của trường này nếu nó tồn tại cho trang này

        $meta = get_post_meta($post->ID, $field['id'], true);

        // Bắt đầu một hàng bảng với

        echo '<tr>
                <th><label for="'.$field['id'].'">'.$field['label'].'</label></th>
                <td>';

        switch($field['type']) {

            // các trường hợp sẽ được thêm vào đây

            // văn bản

            case 'text':
                echo '<input type="text" name="'.$field['id'].'" id="'.$field['id'].'" value="'.$meta.'" size="30" />
                        <br /><span class="description">'.$field['desc'].'</span>';
                break;

            // vùng văn bản

            case 'textarea':
                echo '<textarea name="'.$field['id'].'" id="'.$field['id'].'" cols="60" rows="4">'.$meta.'</textarea>
                        <br /><span class="description">'.$field['desc'].'</span>';
                break;

            case 'image':
                $image = get_template_directory_uri().'library/images/img-preview-blank.png';
                echo '<span class="custom_default_image" style="display:none">'.$image.'</span>';
                if ($meta) { $image = wp_get_attachment_image_src($meta, 'medium'); $image = $image[0]; }
                echo    '<input name="'.$field['id'].'" type="hidden" class="custom_upload_image" value="'.$meta.'" />
                        <img src="'.$image.'" class="custom_preview_image" style="max-width:300px" alt="" /><br />
                        <input class="custom_upload_image_button button" type="button" value="Chọn Hình ảnh" />
                        <small> <a href="#" class="custom_clear_image_button">Xóa Hình ảnh</a></small>
                        <br clear="all" /><span class="description">'.$field['desc'].'';
                break;

        } // kết thúc chuyển đổi

        echo '</td></tr>';

    } // kết thúc vòng lặp foreach

    echo '</table>'; // kết thúc bảng

}

// Lưu dữ liệu

function save_home_meta($post_id) {

    global $home_meta_fields;

    // Xác minh nonce

    if (!wp_verify_nonce($_POST['home_meta_box_nonce'], basename(__FILE__)))
        return $post_id;

    // Kiểm tra tự động lưu

    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE)
        return $post_id;

    // Kiểm tra quyền truy cập

    if ('page' == $_POST['post_type']) {
        if (!current_user_can('edit_page', $post_id))
            return $post_id;
    } elseif (!current_user_can('edit_post', $post_id)) {
        return $post_id;
    }

    // Lặp qua các trường và lưu dữ liệu

    foreach ($home_meta_fields as $field) {
        $old = get_post_meta($post_id, $field['id'], true);
        $new = $_POST[$field['id']];
        if ($new && $new != $old) {
            update_post_meta($post_id, $field['id'], $new);
        } elseif ('' == $new && $old) {
            delete_post_meta($post_id, $field['id'], $old);
        }
    } // kết thúc vòng lặp foreach

}

add_action('save_post', 'save_home_meta');

