function register_menus() {

    register_nav_menus(

        array(

            'global-nav' => 'Global Navigation',

            'footer-nav' => 'Footer Links',

            'sitemap' => 'Site Map',

            'share-ideas' => 'Share Ideas'

        )

    );

}

add_action( 'init', 'register_menus' );

Sau đó, trong một trang thử nghiệm, tôi có những thứ sau:

