add_filter( 'sanitize_title', 'wpse52690_limit_length', 1, 3 );

function wpse52690_limit_length( $title, $raw_title, $context ) {
    //  bộ lọc
    if( $context != 'save' )
        return $title;

    //  biến
    $desired_length = 100; //số ký tự
    $desired_words = 50; //số từ
    $prohibited = array(
        'the'
        ,'in'
        ,'my'
        ,'etc'
        //đặt bất kỳ từ nào khác bạn không muốn trong slug trong mảng này
    );

    //  thực hiện công việc thực tế

    // loại bỏ các từ không mong muốn
    $_title = explode( ' ', $title );
    //nếu bạn muốn nhiều hơn một chuyển sang preg_split()
    $_title = array_diff( $_title, $prohibited );

    // đếm chữ cái và kết hợp lại
    $new_title = '';
    for( $i=0, $count=count($_title); $i<$count; $i++ ) {
        //kiểm tra số từ
        if( $i > $desired_words )
            break;

        //kiểm tra số chữ cái
        if( mb_strlen( $new_title.' '.$_title[$i] ) > $desired_length )
            break;

        if( $i != 0 )
            $new_title .= ' ';

        $new_title .= $_title[$i];
    }

    return $new_title;
}

