Nav Walker tùy chỉnh - Hiển thị số lượng con Tôi có một menu walker tùy chỉnh (xem mã dưới đây). Tôi muốn menu điều hướng của tôi giống như thế này

------------------------------------------
Trang chủ | liên kết 1 | liên kết 2 | liên kết 3 (5)
------------------------------------------

Trong đó "5" là số lượng con của liên kết 3. Ai có thể giúp tôi thực hiện điều này? Đây là mã nav walker tùy chỉnh hiện tại của tôi.

<?php
/**
* Walker sạch cho wp_nav_menu()
*
* Walker_Nav_Menu (WordPress mặc định) ví dụ về đầu ra:
* <li id="menu-item-8" class="menu-item menu-item-type-post_type menu-item-object-page menu-item-8"><a href="/">Trang chủ</a></li>
* <li id="menu-item-9" class="menu-item menu-item-type-post_type menu-item-object-page menu-item-9"><a href="/sample-page/">Trang mẫu</a></l
*
* Roots_Nav_Walker ví dụ về đầu ra:
* <li class="menu-home"><a href="/">Trang chủ</a></li>
* <li class="menu-sample-page"><a href="/sample-page/">Trang mẫu</a></li>
*/
class Roots_Nav_Walker extends Walker_Nav_Menu {
function check_current($classes) {
return preg_match('/(current[-_])|active|dropdown/', $classes);
}

function start_lvl(&$output, $depth = 0, $args = array()) {
$output .= "\n<ul class=\"dropdown-menu\">\n";
}

function start_el(&$output, $item, $depth = 0, $args = array(), $id = 0) {
$item_html = '';
parent::start_el($item_html, $item, $depth, $args);

if ($item->is_dropdown && ($depth === 0)) {
$item_html = str_replace('<a', '<a class="dropdown-toggle" data-toggle="dropdown" data-target="#"', $item_html);
$item_html = str_replace('</a>', ' <b class="caret"></b></a>', $item_html);
}

elseif (stristr($item_html, 'li class="divider')) {
$item_html = preg_replace('/<a[^>]*>.*?<\/a>/iU', '', $item_html);
}

elseif (stristr($item_html, 'li class="nav-header')) {
$item_html = preg_replace('/<a[^>]*>(.*)<\/a>/iU', '$1', $item_html);
}

$output .= $item_html;
}

function display_element($element, &$children_elements, $max_depth, $depth = 0, $args, &$output) {
$element->is_dropdown = !empty($children_elements[$element->ID]);

if ($element->is_dropdown) {
if ($depth === 0) {
$element->classes[] = 'dropdown';
} elseif ($depth === 1) {
$element->classes[] = 'dropdown-submenu';
}
}

parent::display_element($element, $children_elements, $max_depth, $depth, $args, $output);
}
}

/**
* Xóa id="" trên các mục menu nav
* Trả về 'menu-slug' cho các lớp menu nav
*/
function roots_nav_menu_css_class($classes, $item) {
$slug = sanitize_title($item->title);
$classes = preg_replace('/(current(-menu-|[-_]page[-_])(item|parent|ancestor))/', 'active', $classes);
$classes = preg_replace('/^((menu|page)[-_\w+]+)+/', '', $classes);

$classes[] = 'menu-' . $slug;
$classes = array_unique($classes);

return array_filter($classes, 'is_element_empty');
}

add_filter('nav_menu_css_class', 'roots_nav_menu_css_class', 10, 2);
add_filter('nav_menu_item_id', '__return_null');

/**
* Làm sạch wp_nav_menu_args
*
* Xóa container
* Sử dụng Roots_Nav_Walker() theo mặc định
*/
function roots_nav_menu_args($args = '') {
$roots_nav_menu_args['container'] = false;

if (!$args['items_wrap']) {
$roots_nav_menu_args['items_wrap'] = '<ul class="%2$s">%3$s</ul>';
}

if (current_theme_supports('bootstrap-top-navbar')) {
$roots_nav_menu_args['depth'] = 3;
}

if (!$args['walker']) {
$roots_nav_menu_args['walker'] = new Roots_Nav_Walker();
}

return array_merge($args, $roots_nav_menu_args);
}

add_filter('wp_nav_menu_args', 'roots_nav_menu_args');

