Bạn có gợi ý nào về cách giải quyết vấn đề của tôi không?

wp_ajax_[service] trả về 0 Tôi đang thiết lập một vài dịch vụ Ajax. Tất cả chúng đều yêu cầu đăng nhập, vì vậy tôi đã thêm các hook vào "wp_ajax_[$service]". Vấn đề là khi tôi gọi các dịch vụ này, tôi chỉ nhận được phản hồi "0". Tôi cũng không thấy gì trong nhật ký lỗi PHP. Tôi thắc mắc những điều sau đây:

1. Có cách nào để thêm hook vào tất cả các yêu cầu Ajax và ghi lại thông tin gỡ lỗi vào tập tin nhật ký để tôi có thể tìm hiểu thêm về những gì đang xảy ra không?

2. Có ai gặp vấn đề này trước đây không? Có mẹo nào để giải quyết loại vấn đề này không?

CẬP NHẬT: Dưới đây là mã để cung cấp thêm bối cảnh. Đầu tiên là mã JavaScript:

ServiceCall ('get-action-template', {'action': action}, function(response) { // hàm callback });

và hàm ServiceCall là:

function ServiceCall (service, parameters, callback) { console.log ('getTemplate was called: (' + service +', ' + parameters + ')'); // khởi tạo đối tượng yêu cầu var requestObj = {}; requestObj.response = 'ajax-response'; requestObj.type = 'POST'; requestObj.url = my_config['ajax-service-list'][service]['url']; requestObj.data = $.extend (requestObj.data, { 'service': service, 'request_parameters': JSON.stringify(parameters), 'ajax_nonce': my_config['ajax-service-list'][service]['nonce'] }); requestObj.global = false; requestObj.timeout = 30000; requestObj.success = function (r) { alert ("Success: " + JSON.stringify (r)); callback (r); } requestObj.error = function (r) { console.log ("FAILURE WITH AJAX Call (" + JSON.stringify (r) + ")"); } $.ajax (requestObj); }

Điều này tạo ra thông điệp sau (lấy từ bảng điều khiển mạng trong trình gỡ lỗi trình duyệt):

Cuối cùng, đây là mã cho hàm xử lý (không bao giờ được gọi):

public static function ajax_handler () { error_log ("AJAX HANDLE"); $service = $_POST['action']; $request_parameters = json_decode ($_POST['request_parameters']); if (LG_Utility::key_from_hash (self::$services_list, $service, false)) { $object = new self::$services_list[$service]['class'] ($service); $object->handle ($service, $request_parameters); } else { if (class_exists ('AppLogger')) AppLogger::error ("Trying to handle a service ({$service}) which is not registered!"); } }

Tuy nhiên, tôi đã xác minh rằng nó được kết nối chính xác với sự kiện wp_ajax_get-action-template. Bằng chứng rút gọn là sử dụng plugin "debug objects" phổ biến, tôi có thể xác minh rằng nó đã được thiết lập. Đây là toàn bộ lớp PHP quản lý các giao dịch Ajax (một số phương thức/biến bị xóa để ngắn gọn):

class LG_AjaxServiceManager { private static $services_list = array ( 'get-action-template' => array ('class' => 'LG_GetActionTemplate', 'login_required' => true), 'some-other-service' => array ('class' => 'LG_FooBar', 'login_required' => false) ); public static function add_listeners () { foreach (self::$services_list as $id => $service) { add_action ('wp_ajax_' . $id, 'LG_AjaxServiceManager::ajax_handler'); if (class_exists ('AppLogger')) AppLogger::log ("Registering $id as an Ajax service"); } } public static function ajax_localize () { // Thêm hook cho bản địa hóa script; điều này quan trọng để các script JS có nonce và thông tin URL foreach (self::$services_list as $id => $service) { $service_url = wp_nonce_url (admin_url ('admin-ajax.php?action="' . $id . '"'), self::AJAX_APP_NONCE_KEY . '_' . $id); preg_match ('/.*action=%22(.*)%22&_wpnonce=(.*)/', $service_url, $service_parts); self::$ajax_js_array [$service_parts[1]] = array ('nonce' => $service_parts[2], 'url' => esc_url ($service_url)); } $localize = array ('SiteURL' => get_bloginfo ('url'), 'AjaxURL' => admin_url ('admin-ajax.php'), 'ajax-service-list' => self::$ajax_js_array); wp_enqueue_script ('jquery'); wp_enqueue_script (self::JS_FILE_HANDLE, plugins_url ('/js/lg-ajax-client.js', dirname(__FILE__)), 'jquery'); wp_localize_script (self::JS_FILE_HANDLE, self::JS_NAMESPACE, $localize); } public static function ajax_handler () { error_log ("AJAX HANDLE"); $service = $_POST['action']; $request_parameters = json_decode ($_POST['request_parameters']); if (LG_Utility::key_from_hash (self::$services_list, $service, false)) { $object = new self::$services_list[$service]['class'] ($service); $object->handle ($service, $request_parameters); } else { if (class_exists ('AppLogger')) AppLogger::error ("Trying to handle a service ({$service}) which is not registered!"); } } }

Sao chép giá trị meta tùy chỉnh từ bài viết hiện tại sang bài viết bản sao Tôi đang cố gắng chỉnh sửa một plugin WP hiện có là BU Versions để chấp nhận các giá trị trường meta tùy chỉnh khác nhau từ các mục tôi đã thiết lập bằng cách sử dụng plugin Advanced Custom Fields (ACF). BU Versions sẽ sao chép tiêu đề, đoạn trích, nội dung và một số tính năng cụ thể của trang từ một trang sang trang khác, nhưng tôi không thể khiến nó sao chép các giá trị meta tùy chỉnh. Ví dụ, khi tôi print_r($new_version), tôi nhận được kết quả này trong mảng, vì vậy tôi biết nó đang thêm các trường meta tùy chỉnh và giá trị hiện tại trên trang đang được thử nghiệm trùng lặp bài viết.

Và đây là phần mã mà tôi nghĩ plugin tạo một bài đăng mới dựa trên các giá trị bài đăng hiện có

/**
* Tạo một phiên bản thay thế mới.
*
* @param mixed $post
* @param mixed $alt_post_type
* @access public
* @return int|WP_Error
*/
function create( $post_id, $alt_post_type, $meta_keys = null ) {
$this->get_version( $post_id );
if ( $this->has_version() ) {
return new WP_Error( 'alternate_already_exists', __( 'An alternate version already exists for this post.', BUV_TEXTDOMAIN ) );
}
$this->original = get_post( $post_id );
if ( ! isset( $this->original ) ) {
return new WP_Error( 'alternate_no_original', sprintf( __( 'The post ID: %s could not be found.', BUV_TEXTDOMAIN ), $post_id ) );
}
$new_version['post_type'] = $alt_post_type;
$new_version['post_parent'] = $this->original->ID;
$new_version['ID'] = null;
$new_version['post_status'] = 'draft';
$new_version['post_content'] = $this->original->post_content;
$new_version['post_name'] = $this->original->post_name;
$new_version['post_title'] = $this->original->post_title;
$new_version['post_excerpt'] = $this->original->post_excerpt;
$new_version['_subheading'] = $this->original->_subheading;
// Vòng lặp qua Post Custom Meta và thêm vào mảng
$custom_field_keys = get_post_custom_keys($new_version['post_parent']);
foreach ( $custom_field_keys as $key => $value ) {
$new_version[$value] = $this->original->$value;
}
//
$result = wp_insert_post($new_version);
if ( ! is_wp_error( $result ) ) {
$this->post = get_post( $result );
$this->copy_original_meta( $new_version );
update_post_meta( $this->original->ID, self::tracking_meta_key, $this->post->ID );
}
return $result;
}
/* Do việc khử trùng và序列 hóa, có thể tốt hơn là sử dụng SQL, nhưng hiện tại chúng tôi đang sử dụng API
**/
private function copy_original_meta( $new_version ) {
foreach ( $new_version as $key ) {
$values = get_post_meta( $this->original->ID, $key );
foreach ( $values as $v ) {
update_post_meta( $this->post->ID, $key, $v );
}
}
update_post_meta( $this->post->ID, '_bu_version_copied_keys', $meta_keys);
}
/**
