Làm thế nào để liên kết “đọc thêm” trên đoạn trích của WP Recipies Tôi đã tìm thấy mã trên trang WP Recipies để buộc trích dẫn trên trang chủ:

function my_excerpts($content = false) {
     // Nếu đây là trang chủ, một kho lưu trữ, hoặc kết quả tìm kiếm
     if(is_front_page() || is_archive() || is_search()) :
         global $post;
         $content = $post->post_excerpt;

         // Nếu có trích dẫn được đặt trong hộp Trích dẫn Tùy chọn
         if($content) :
             $content = apply_filters('the_excerpt', $content);

         // Nếu không có trích dẫn nào được đặt
         else :
             $content = $post->post_content;
             $excerpt_length = 55;
             $words = explode(' ', $content, $excerpt_length + 1);

             if(count($words) > $excerpt_length) :
                 array_pop($words);
                 array_push($words, '...');
                 $content = implode(' ', $words);
             endif;
             $content = '<p>' . $content . '</p>';
         endif;
     endif;

     // Đảm bảo trả về nội dung
     return $content;
}

add_filter('the_content', 'my_excerpts');

