Giới hạn số lượng các tiện ích không hoạt động Tôi đang cố gắng giới hạn số lượng widget từ thanh bên "wp_inactive_widgets" xuống tối đa 10, vì trang quản lý widget hoạt động rất chậm. 

add_filter('pre_update_option_sidebars_widgets', 'cleanup_inactive_widgets', 10, 2); 

function cleanup_inactive_widgets($new, $old) { 
    if (!empty($new['wp_inactive_widgets']) && count($new['wp_inactive_widgets']) > 10) { 
        $new['wp_inactive_widgets'] = array_slice($new['wp_inactive_widgets'], -10, 10); 
    } 

    return $new; 
} 

Cách này hoạt động tốt, nhưng vấn đề là các tùy chọn widget vẫn còn trong cơ sở dữ liệu, bất kể widget có tồn tại trong thanh bên hay không. Ai biết cách xóa cả các tùy chọn của widget không? 

* * * 

Tôi đã tìm ra giải pháp: 

Nếu như có trường hợp nào đó mà nó xóa cả các widget từ các thanh bên khác, tôi không chắc điều gì đang gây ra vấn đề này... 

if (!empty($new['wp_inactive_widgets']) && count($new['wp_inactive_widgets']) > 10) { 

    // Tìm ra các widget cần xóa 

    $removed_widgets = array_slice($new['wp_inactive_widgets'], 0, -10); 

    // Xóa các tùy chọn của widget 

    foreach ($removed_widgets as $widget_id) { 
        if (isset($GLOBALS['wp_registered_widgets'][$widget_id])) { 
            $instance = $GLOBALS['wp_registered_widgets'][$widget_id]['callback'][0]->number; 
            $option_name = $GLOBALS['wp_registered_widgets'][$widget_id]['callback'][0]->option_name; 
            $options = get_option($option_name); 

            // Lấy các tùy chọn của tất cả các instance 

            unset($options[$instance]); 

            // Xóa tùy chọn của instance này 

            update_option($option_name, $options); 
        } 
    } 

    // Giữ lại chỉ 10 bản ghi cuối cùng từ khu vực widget không hoạt động 

    $new['wp_inactive_widgets'] = array_slice($new['wp_inactive_widgets'], -10, 10); 
} 

return $new;

