function wpse_59770_ajax_pre_submit_validation()
{
    // Kiểm tra bảo mật đơn giản
    check_ajax_referer( 'pre_publish_validation', 'security' );

    // Trang cha đã được thiết lập, không cần thực hiện thêm hành động gì nữa
    if( '1' == $_POST['form_data'] )
    {
        echo 'true';
        die();
    }

    $args = array( 'post_type' => 'page', 'post_parent'=> 0, 'numberposts' => -1 );
    $parents_total = get_posts( $args );

    // Tổng số trang cha nhỏ hơn 9, không cần thực hiện thêm hành động nào nữa
    if( count($parents_total) < 9 )
    {
        echo 'true';
        die();
    }

    // Không cho phép thêm trang cha nữa
    else
    {
        $error = "Không cho phép thêm trang cha nữa";
        echo $error;
        die();
    }
}

Các tùy chọn plugin không được lưu hoặc tạo ra. Tôi đang gặp nhiều khó khăn với trang cấu hình này. Tôi đã làm theo tài liệu (không nhiều) và tìm kiếm một chút giúp đỡ. Vấn đề của tôi rất đơn giản, các tùy chọn cấu hình không được tạo hoặc lưu lại. Bất kỳ sự giúp đỡ nào cũng sẽ được đánh giá cao! Đây là thiết lập chung:

