Sử dụng trường tùy chỉnh làm tiêu đề bài viết tùy chỉnh Tôi đã thiết lập một loại bài viết tùy chỉnh với một loạt các trường tùy chỉnh sử dụng lớp WPAlchemy. Tôi đang cố gắng lấy giá trị của một trong các trường tùy chỉnh và sử dụng nó làm tiêu đề bài viết. Tuy nhiên, cho đến nay, tôi vẫn chưa thành công. Tôi đã tìm kiếm và thử nghiệm hai đoạn mã sau:

function custom_post_type_title( $post_id ) {
    global $wpdb;
    if ( get_post_type( $post_id ) == 'listing' ) {
        $title = get_post_meta( $post_id, 'listing_name', true );
        $where = array( 'ID' => $post_id );
        $wpdb->update( $wpdb->posts, array( 'post_title' => $title ), $where );
    }
}
add_action('init', 'listing_save_post');
function listing_save_post( $post_id ) {
    if ( ! defined( 'DOING_AUTOSAVE' ) && ! DOING_AUTOSAVE ) return;
    add_action('save_post', 'custom_post_type_title', 100);
    add_action('publish_post', 'custom_post_type_title', 100);
}

