Trong cả hai trường hợp, kết quả là như sau:

1. Khi lưu bài viết mới, nó tải lại trang, cho biết đã hoạt động và tất cả các trường tùy chỉnh đều trống. (Nếu không có mã nào được chạy, bài viết tùy chỉnh hoạt động tốt và các trường được lưu trữ).

2. Khi xem chỉ mục loại bài viết tùy chỉnh, các bài viết không hiển thị. Có ý tưởng nào không? **CẬP NHẬT** Để làm rõ, tôi đang sử dụng bài viết tùy chỉnh _không_ hỗ trợ tiêu đề. Tuy nhiên, tôi vẫn đang cố gắng điền vào trường tiêu đề bằng giá trị trong trường tùy chỉnh.

Dừng tải thêm bài viết nếu không còn bài viết nào nữa AJAX Tôi đang sử dụng đoạn mã JavaScript sau đây để tải thêm trang trong #work_items (xem trực tiếp tại http://mtthwbsh.com):

jQuery(document).ready(function($){
    $('.older a').live('click', function(e) {
        e.preventDefault();
        $('.navigation').prepend("<div class=\"loader\">&nbsp;</div>");
        var link = jQuery(this).attr('href');
        var $content = '#work_items';
        var $nav_wrap = '.navigation';
        var $anchor = '.navigation .older a';
        var $next_href = $($anchor).attr('href'); // Lấy URL cho bộ bài viết tiếp theo
        $.get(link+'', function(data){
            var $timestamp = new Date().getTime();
            var $new_content = $($content, data).wrapInner('').html(); // Lấy nội dung
            $('.navigation .loader').remove();
            $next_href = $($anchor, data).attr('href'); // Lấy href mới
            $($nav_wrap).before($new_content); // Thêm nội dung mới
            $('#rtz-' + $timestamp).hide().fadeIn('slow'); // Hiệu ứng khi tải
            $('.older a').attr('href', $next_href); // Thay đổi URL tiếp theo
            $('#work_items .navigation:last').remove(); // Xóa phần điều hướng ban đầu
        });
    });
});

