wp_nonce_field có dễ bị tấn công nếu bạn biết tên hành động không? Nếu biết tên action thì wp_nonce_field có dễ bị tấn công không? Tôi đang thêm vào một trường ẩn với tên = tên của action trong form để plugin của tôi có thể nhận biết nó. Tôi muốn biết nếu việc hiển thị tên action có gây ra vấn đề bảo mật không? chỉnh sửa: Tôi đang tự động hóa quy trình gửi form; vì vậy nếu việc hiển thị tên action là một vấn đề, tôi có thể mã hóa nó. ví dụ. Tôi gọi `MyFormPlugin::generateAction( 'submitQuestion' );` trong form của tôi để tạo nonce và trường "form_action" ẩn của tôi.

class MyFormPlugin {

public static function generateAction( $action, $referer = true ) {
$nonce_field = wp_nonce_field( self::secured_action( $action ), "mfp_nonce", $referer, FALSE );
return $nonce_field . '<input type="hidden" name="form_action" value="' . $action . '" />';
}

public static function secured_action( $action ) {
return md5( $action . 'randomsalt');
}

public function verify_nonce( $action ) {
$nonce = $_POST[ 'mfp_nonce' ];
return wp_verify_nonce( $nonce, self::secured_action( $action ) );
}
}

