Custom Post type menu được đánh dấu trong archive/post Tôi tạo một menu điều hướng tùy chỉnh cho loại bài đăng tùy chỉnh của tôi bằng các liên kết tùy chỉnh (liên kết đến trang lưu trữ). Hãy nói rằng tôi có một loại bài đăng tùy chỉnh tên là "sản phẩm", và khi tôi nhấp vào menu, nó sẽ đi đến trang lưu trữ của 'sản phẩm', và 'sản phẩm' sẽ được đánh dấu đậm. Điều đó khá dễ dàng vì WP sẽ tự động thêm lớp 'current-menu-item' vào menu khi ở trang lưu trữ 'sản phẩm'. Nhưng có một vấn đề, trong trang lưu trữ, lớp 'current-menu-item' dường như chỉ được thêm vào trang đầu tiên của trang lưu trữ. Khi tôi đi đến trang 2 thì lớp 'current-menu-item' không được thêm vào và menu không được đánh dấu đậm. Ngoài ra, tôi cũng muốn menu được đánh dấu đậm khi xem bài viết dưới dạng 'sản phẩm'. Vì vậy tôi đã thử thêm mã này vào hàm:

function add_active_classes($classes = array(), $menu_item = false) {
    global $wp_query;
    if(in_array('current-menu-item', $menu_item->classes)) {
        $classes[] = 'current-menu-item';
    }
    if ($menu_item->post_type == 'product' && is_post_type_archive('product')) {
        $classes[] = 'current-menu-item';
    }
    if ($menu_item->post_type == 'product' && is_singular('product')) {
        $classes[] = 'current-menu-item';
    }
    return $classes;
}
add_filter('nav_menu_css_class', 'add_active_classes', 10, 2);

