function remove_medialibrary_tab($tabs) {
    if (!current_user_can('administrator') || !current_user_can('editor') || !current_user_can('contibutor') || !current_user_can('author')) {
        unset($tabs['library']);
        return $tabs;
    } else {
        return $tabs;
    }
}

add_filter('media_upload_tabs', 'remove_medialibrary_tab');

