function random_quote() {
// tệp trích dẫn
$array = file("/path to txt file");
// tạo số ngẫu nhiên giữa 0 và tổng số lượng $array trừ 1
// chúng tôi trừ 1 từ tổng số trích dẫn vì chỉ số mảng bắt đầu từ 0 thay vì 1 theo mặc định
