hàm dot_irt_top_posts ( $atts, $content = null ) {
// lấy biến của chúng tôi từ $atts
extract(shortcode_atts(array(
'before' => '<li>',
'after' => '</li>',
'sumber' => '10',
'type_bài viết' => 'post',
'năm' => '',
'monthnum' => '',
'show_count' => '1',
), $atts));

toàn cầu $wpdb;

$request = "SELECT * FROM $wpdb->posts, $wpdb->postmeta";
$request .= "WHERE $wpdb->posts.ID = $wpdb->postmeta.post_id";

nếu ($năm! = '') {
$request .= "VÀ năm=$năm";
}

nếu ($năm! = '' && $monthnum! = '') {
$request .= "VÀ &monthnum='$monthnum'";
} nếu ($monthnum! = '') {
$request .= "VÀ monthnum='$monthnum'";
}

$request .= "VÀ post_status='publish' VÀ type_bài viết='$type_bài viết' VÀ meta_key='_recommended'";
$request .= "SẾP XẾP theo $wpdb->postmeta.meta_value+0 DESC HẠN CHỨC $số";
$bài viết = $wpdb->get_results($request);

$return = '';

foreach ($bài viết như $item) {
$post_title = stripslashes($item->post_title);
$permalink = get_permalink($item->ID);
$post_count = $item->meta_value;
$return .= $before.'<a href="' . $permalink . '" title="' . $post_title.'" rel="nofollow">' . $post_title . '</a> ';

nếu ( $show_count == '1') {
