Phản hồi mã không nhất quán sử dụng HTTP API Tôi đang sử dụng WordPress http api để nhận mã phản hồi từ youtube api để kiểm tra tính hợp lệ của một video. Tôi làm điều này trong một hàm từ functions.php của tôi xử lý biểu mẫu bài viết nơi tôi thu thập URL của video YouTube. Vấn đề là tôi nhận được phản hồi không nhất quán khi các video hợp lệ thỉnh thoảng trả về 403. Bây giờ tôi cũng kiểm tra tính hợp lệ trên front end bằng cách sử dụng jquery .ajax() với cùng một yêu cầu youtube api và điều đó hoạt động chính xác 100% thời gian. Vì vậy, một video sẽ xác thực bằng youtube api và jquery và sau đó thỉnh thoảng trả về 403 bằng phương pháp php. Vì vậy vấn đề ở đây là gì? Đây là hàm xử lý biểu mẫu của tôi. Bạn sẽ thấy tôi in ra $video_id mỗi lần để đảm bảo nó chính xác và nó là.

function video_process_form( $query ) {
    global $error_output;

    if ( $query->is_page( 'submit-video' ) && isset( $_POST['title'] )) {
        $output = null;

        if ( ! function_exists( 'wp_handle_upload' )) {
            require_once(ABSPATH . "wp-admin" . '/includes/image.php');
            require_once(ABSPATH . "wp-admin" . '/includes/file.php');
            require_once(ABSPATH . "wp-admin" . '/includes/media.php');
        }

        $file = $_FILES;

        // Thực hiện một số xác thực biểu mẫu nhỏ để đảm bảo có nội dung

        if ($_POST['title'] != null && $_POST['title'] != 'Tiêu đề video') {
            $title =  $_POST['title'];
        } else {
            $error_output .= 'Vui lòng nhập tiêu đề video<br/>';
        }

        if ($_POST['description'] != null && $_POST['description'] != 'Mô tả video') {
            $description = $_POST['description'];
        }

        if ($_POST['video_url'] != null && $_POST['video_url'] != 'URL YouTube') {
            $vid_url = $_POST['video_url'];
            $video_id = getVideoId($vid_url);

            if ($video_id) {
                printf($video_id);
                $video_response =    wp_remote_retrieve_response_code(wp_remote_get('http://gdata.youtube.com/feeds/api/videos/' .
                    $video_id));
                printf($video_response);

                if ($video_response == 200) {
                    $video_url = $vid_url;
                } else {
                    $error_output .= 'Đây không phải là video YouTube hợp lệ<br/>';
                }
            } else {
                $error_output .= 'Đây không phải là video YouTube hợp lệ<br/>';
            }
        } else {
            $error_output .= 'Đây không phải là video YouTube hợp lệ<br/>';
        }

        $tags = $_POST['post_tags'];

        // Thêm nội dung của biểu mẫu vào $post dưới dạng mảng

        $new_post = array(
            'post_title'    => $title,
            'post_content'  => $description,
            'tags_input'    => array($tags),
            'post_category' => array(12),
            'post_status'   => 'publish',
            // Chọn: publish, preview, future, draft, v.v.
            'post_type' => fod_videos
            // Sử dụng kiểu bài viết tùy chỉnh nếu bạn muốn
        );

        // Nếu không có lỗi, lưu bài đăng và chuyển hướng

        if ($error_output == null) {
            $pid = wp_insert_post($new_post);
            update_post_meta($pid,'video_code',$video_url);
            wp_redirect( get_permalink($pid));

        // Nếu có lỗi, trả về lỗi để hiển thị trong mẫu

        }
    }

    do_action('wp_insert_post', 'wp_insert_post');
}

