Hạn chế chỉnh sửa, nhưng cho phép xem trước về trạng thái bài viết tùy chỉnh Tôi đang phát triển một trang web Wordpress với plugin **Edit Flow**, cho phép tôi tạo các trạng thái bài viết tùy chỉnh để quản lý bài viết của tác giả và cộng tác viên dễ dàng hơn. Vì vậy tôi đã tạo trạng thái bài viết tùy chỉnh và có bộ lọc sau để hạn chế khả năng chỉnh sửa bài viết đó. Nó hoạt động tốt, nhưng vấn đề là người dùng (ngoại trừ quản trị viên) không thể xem trước bài viết. Những người dùng khác vẫn có thể nhìn thấy liên kết _"Xem trước"_ trong danh sách bài viết trên bảng điều khiển, nhưng nếu họ nhấp vào nó và truy cập trang xem trước bài viết (`../post-with-custom-status/?preview=true`) thì nó sẽ hiển thị rằng bài viết không thể tìm thấy.

function restrict_edit_custom_status_posts( $allcaps, $cap, $args ) {
  // Ngừng nếu chúng ta không yêu cầu chỉnh sửa bài viết
  if( 'edit_post' != $args[0]
    // ... hoặc người dùng là quản trị viên
    || !empty( $allcaps['manage_options'] )
    // ... hoặc người dùng không thể chỉnh sửa bài viết
    || empty( $allcaps['edit_posts'] ))
    return $allcaps;

  // Tải dữ liệu bài viết:
  $post = get_post( $args[2] );

  // Nếu bài viết có trạng thái tùy chỉnh
  if( 'my_custom_status' == $post->post_status ) {
    // Thì không cho phép chỉnh sửa
    $allcaps["edit_posts"] = FALSE;
    return $allcaps;
  }

  return $allcaps;
}

add_filter( 'user_has_cap', restrict_edit_custom_status_posts10, 3 );

