function set_youtube_as_featured_image($post_id) {
    // chỉ muốn thực hiện điều này nếu bài viết không có hình thu nhỏ
    if(!has_post_thumbnail($post_id)) {
        // tìm URL của YouTube
        $post_array = get_post($post_id, ARRAY_A);
        $content = $post_array['post_content'];
        $youtube_id = get_youtube_id($content);

        // tạo chuỗi hình thu nhỏ
        $youtube_thumb_url = 'http://img.youtube.com/vi/' . $youtube_id . '/0.jpg';

        // tiếp theo, tải xuống URL của hình ảnh YouTube
        media_sideload_image($youtube_thumb_url, $post_id, 'Hình ảnh mẫu của YouTube.');

        // tìm tập tin đính kèm gần đây nhất cho bài viết được cho
        $attachments = get_posts(
            array(
                'post_type' => 'attachment',
                'numberposts' => 1,
                'order' => 'ASC',
                'post_parent' => $post_id
            )
        );
        $attachment = $attachments[0];

        // và thiết lập nó làm hình thu nhỏ bài viết
        set_post_thumbnail( $post_id, $attachment->ID );
    } // kết thúc if
} // set_youtube_as_featured_image

add_action('save_post', 'set_youtube_as_featured_image');

