Truyền giá trị từ một widget đến một hàm trong một plugin Tôi có một plugin được xây dựng với nhiều widget. Một gói widget. Mỗi widget tạo ra mã CSS tùy chỉnh của riêng nó. Thay vì có mã nguồn lộn xộn nơi tôi hiển thị 15 bộ mã inline CSS khác nhau, tôi muốn truyền mã CSS tùy chỉnh được tạo từ mỗi widget vào một tệp CSS tùy chỉnh chính mà tôi đã tạo thông qua AJAX của WordPress. Tôi sẽ hiển thị các hàm mà tôi đã thiết lập để thực hiện điều này. # Tệp CSS được tạo bằng AJAX Tệp CSS bên dưới được tạo thông qua AJAX của WordPress. Nó cho phép tôi đặt các câu lệnh CSS tùy chỉnh trong tệp. Nó cũng chứa một bộ lọc nơi tôi hy vọng sẽ truyền mã CSS bổ sung được tạo từ các widget vào hàm này (tệp).      /**       * Đánh vần CSS cho kiểu widget tùy chỉnh       */      public function advanced_widget_pack_css() {          if(empty($_GET['action']) || $_GET['action'] != 'advanced_widget_pack_gen_css') return;          if(!isset($_GET['ver'])) return;           $css_text = '';           /* ============================= */         /* Widget Archive               */         /* ============================= */         $css_text .= ".awp_archives_colour { color:".awp_option('awp_archives_dropdown_inst_colour')." !important }
";          /**          * Bộ lọc cho bất kỳ CSS đến nào          */         $css_text = apply_filters('advanced_widget_pack_css', $css_text);          header("Content-type: text/css");         echo $css_text;         exit();     }      # Một trong các lớp widget với mã CSS tùy chỉnh được tạo ra Dưới đây là mã của một trong nhiều widget được sử dụng trong plugin. Widget tạo mã CSS tùy chỉnh và lưu trữ nó trong biến $sc_css. Điều tôi muốn làm ở đây là truyền nội dung của biến $sc_css hoặc thêm nội dung vào hàm advanced_widget_pack_css() mà tôi đã tạo trước đó.      class Advanced_Widget_Pack_Widget_Archives extends WP_Widget {          public function __construct(){             // Bộ lọc này gắn mã CSS tùy chỉnh được tạo vào hàm advanced_widget_pack_css             add_filter('advanced_widget_pack_css', array(&$this,'awp_pass_css_code'));         }          public function form($instance) {}          public function widget($args, $instance){              extract($args);              // Tất cả mã widget được chứa ở đây....              // Kiểu cho mã ngắt chuỗi             if($is_awp_sc == 'true'){                 /* Tạo ID duy nhất nếu mã ngắt chuỗi - được sử dụng cho kiểu */                $sc_id = mt_rand(1, 100000);                 $sc_css =  ".awp_archive_widget_sc".$sc_id." { border:".$awp_archives_border_width.' '.$awp_archives_border_style.' '.$awp_archives_border_color." !important }
";                 $sc_css .= $awp_archives_border_radius == 'round' ? '.awp_archive_widget_sc'.$sc_id.' { -moz-border-radius:5px; -webkit-border-radius:5px; border-radius:5px }' : ''.''." 
";                  $sc_css .= ".awp_archive_widget_sc".$sc_id." li a, .awp_archive_widget_sc".$sc_id." li { font-size:".$awp_archives_font_size." !important }
";                 $sc_css .= ".awp_archive_widget_sc".$sc_id." li a { color:".$awp_archives_link_std." !important }
";                 $sc_css .= ".awp_archive_widget_sc".$sc_id." li a:hover { color:".$awp_archives_link_hover." !important }
";                  // Điều này nên truyền biến                 echo $this->awp_pass_css_code($sc_css);             }              // Mã widget được xuất ở đây         }          // Hàm này được tạo để truyền nội dung của biến $sc_css vào hàm advanced_widget_pack_css         function awp_pass_css_code( $sc_css ) {             return $sc_css;         }     }      # Các vấn đề Tôi đã cố gắng đạt được điều này bằng cách truyền nội dung của biến $sc_css vào một hàm trong widget và sau đó gắn nó vào hàm advanced_widget_pack_css() thông qua một bộ lọc của WordPress. Vấn đề xảy ra là nội dung của biến luôn trống khi truyền chúng vào bảng phong cách được tạo bằng AJAX.

