/**
* Trả về ID của một bản gắn kèm bằng cách tìm kiếm cơ sở dữ liệu với URL tệp.
*
* Đầu tiên kiểm tra xem $url có trỏ đến tệp tồn tại trong
* thư mục wp-content hay không. Nếu có, chúng tôi sẽ tìm kiếm cơ sở dữ liệu để tìm
* sự phù hợp một phần bao gồm đường dẫn sau thư mục wp-content.
* Cuối cùng, nếu tìm thấy sự phù hợp, ID bản gắn kèm sẽ được trả về.
*
* http://frankiejarrett.com/get-an-attachment-id-by-url-in-wordpress/
*
* @return {int} $attachment
*/

function bck_getattachmentimagebyurl( $url ) {
// Chia $url thành hai phần với thư mục wp-content làm bộ phân cách.
$parse_url  = explode( parse_url( WP_CONTENT_URL, PHP_URL_PATH ), $url );
// Nhận tên miền của trang web hiện tại và tên miền của $url, bỏ qua www.
$this_host = str_ireplace( 'www.', '', parse_url( home_url(), PHP_URL_HOST ) );
$file_host = str_ireplace( 'www.', '', parse_url( $url, PHP_URL_HOST ) );
// Trả về không có gì nếu không có phần nào của $url hoặc nếu tên miền hiện tại và tên miền $url không khớp.
if ( !isset( $parse_url[1] ) || empty( $parse_url[1] ) || ( $this_host != $file_host ) ) {
return;
}
// Bây giờ chúng tôi sẽ nhanh chóng tìm kiếm DB để tìm bất kỳ GUID nào có sự phù hợp một phần với đường dẫn.
// Ví dụ: /uploads/2013/05/test-image.jpg
global $wpdb;
$prefix     = $wpdb->prefix;
$attachment = $wpdb->get_col( $wpdb->prepare( "SELECT ID FROM " . $prefix . "posts WHERE guid RLIKE %s;", $parse_url[1] ) );
// Trả về null nếu không tìm thấy bản gắn kèm nào.
return $attachment[0];
}

/*
* Thu hồi kích thước bản xem trước hình ảnh phù hợp
*/

function bck_getadditionalusermetathumb() {
$attachment_url = esc_url( get_the_author_meta( 'user_meta_image', $post->post_author ) );
// Lấy ID từ URL bằng hàm của Frankie Jarrett
$attachment_id = bck_getattachmentimagebyurl( $attachment_url );
// thu hồi kích thước bản xem trước của hình ảnh của chúng tôi
$image_thumb = wp_get_attachment_image_src( $attachment_id, 'thumbnail' );
// trả về hình ảnh bản xem trước
return $image_thumb[0];
}

