) );
}
else { // Nếu không có ID tác giả, gửi lại thông báo lỗi
$authormetaerror = 'Không có ID người dùng được cung cấp. Vui lòng thử lại.'; // Thông báo lỗi để gửi lại
$authormeta = json_encode( array( // Mã hóa thành JSON
