    function admin_init() {
        register_setting(
            'sample' // Tên nhóm thiết lập. Phải tồn tại trước khi gọi register_setting.
            , 'sample_options' // Tên của một tùy chọn để làm sạch và lưu.
            , array($this, 'set_options') // Một hàm callback để làm sạch giá trị của tùy chọn.
        );

        // Đăng ký nhóm trường thiết lập
        add_settings_section(
            'sample_section1', // Chuỗi dùng trong thuộc tính 'id' của thẻ.
