            '__return_false', // Hàm để điền nội dung vào phần. Hàm này phải hiển thị đầu ra của nó.
            'sample' // Loại trang thiết lập để hiển thị phần (general, reading, writing, ...).
        );

        // Đăng ký các trường thiết lập riêng lẻ
        add_settings_field(
            'color_scheme', // Chuỗi dùng trong thuộc tính 'id' của thẻ.
            'Color Scheme', // Tiêu đề của trường.
            array($this, 'color_scheme'), // Hàm để điền vào trường với các đầu vào mong muốn như một phần của biểu mẫu lớn hơn. Nhận một tham số duy nhất, mảng $args. Tên và ID của đầu vào nên khớp với $id được truyền cho hàm này. Hàm này phải hiển thị đầu ra của nó.
