            'sample_section1', // Phần của trang thiết lập để hiển thị hộp (default hoặc một phần bạn đã thêm bằng add_settings_section, hãy xem trang nguồn để biết các phần hiện có.)
            array() // $args - Các tham số bổ sung được truyền cho hàm callback. Khóa 'label_for' có thể được sử dụng để đặt nhãn cho trường khác với $title.
        );
    }

    function set_options() {

    }

    function color_scheme() {
        echo "<textarea type='text' rows='2' cols='80' name='sample_options[color_scheme]'>";
        echo time();
        echo "</textarea>";
    }

    function admin_menu() {
        add_options_page(
            __('sample'), // Tiêu đề trang
            __('sample'), // Tiêu đề menu
            'edit_posts', // Khả năng
