Hộp thả xuống mã ngắn của chúng tôi trong TinyMCE không hoạt động trong WordPress 3.9? Chào bạn, do phiên bản mới sắp được phát hành nên tôi nghĩ rằng mình sẽ tải nó xuống và xem chủ đề của mình có hoạt động tốt không. Mọi thứ hoạt động tuyệt vời ngoại trừ hộp thả xuống không còn hiển thị nữa. Đây là mã chúng ta đã sử dụng để hiển thị nó trong các phiên bản trước.
Mã PHP:

function register_ppp_shortcodes( $buttons ) {
    array_unshift( $buttons, "Shortcodes" );
    return $buttons;
}

function add_ppp_shortcodes( $plugin_array ) {
    $plugin_array['Shortcodes'] = get_template_directory_uri() . '/js/Shortcodes_js.js';
    return $plugin_array;
}

function ppp_shortcodes() {
    if ( ! current_user_can('edit_posts') && ! current_user_can('edit_pages') ) {
        return;
    }

    if ( get_user_option('rich_editing') == 'true' ) {
        add_filter( 'mce_external_plugins', 'add_ppp_shortcodes' );
        add_filter( 'mce_buttons', 'register_ppp_shortcodes' );
    }
}

add_action('init', 'ppp_shortcodes');

Mã JS:

/*global tinyMCE, tinymce*/
/*jshint forin:true, noarg:true, noempty:true, eqeqeq:true, bitwise:true, strict:true, undef:true, unused:true, curly:true, browser:true, devel:true, maxerr:50 */
(function() {
    "use strict";
    tinymce.create('tinymce.plugins.Shortcodes', {
        init : function(ed, url) {
            ed = ed;
            url = url;
        },
        createControl : function(n, cm) {
            if(n==='Shortcodes'){
                var mtb = cm.createListBox('Shortcodes', {
                    title : 'Shortcodes',
                    onselect : function(p) {
                        var selected = false;
                        var content = '';
                        switch (p){
                            case 'H1 Title':{
                                var h1titleclass = prompt("Bạn có muốn một lớp tùy chỉnh?", "");
                                selected = tinyMCE.activeEditor.selection.getContent();
                                if(h1titleclass != ''){
                                    h1titleclass = 'class= "'+h1titleclass+'"';
                                }
                                if (selected) {
                                    content = '[h1'+h1titleclass+']' + selected + '[/h1]';
                                } else {
                                    content = '[h1'+h1titleclass+'][/h1]';
                                }
                                tinymce.execCommand('mceInsertContent', false, content);
                            } // finished shortcode
                            break;
                            case 'H2 Title':{
                                var h2titleclass = prompt("Bạn có muốn một lớp tùy chỉnh?", "");
                                selected = tinyMCE.activeEditor.selection.getContent();
                                if(h2titleclass != ''){
                                    h2titleclass = 'class= "'+h2titleclass+'"';
                                }
                                if (selected) {
                                    content = '[h2'+h2titleclass+']' + selected + '[/h2]';
                                } else {
                                    content = '[h2'+h2titleclass+'][/h2]';
                                }
                                tinymce.execCommand('mceInsertContent', false, content);
                            } // finished shortcode
                            break;
                        }
                    }
                });
                // Thêm một số mục menu
                var my_shortcodes = ['H1 Title','H2 Title'];
                for(var i in my_shortcodes){
                    if (true) {mtb.add(my_shortcodes[i],my_shortcodes[i]);}
                }
                return mtb;
            }
            return null;
        }
    });
    tinymce.PluginManager.add('Shortcodes', tinymce.plugins.Shortcodes);
})();

