/*--------------------------------------------------------------------------*
* Hàm lưu
/*--------------------------------------------------------------------------*/
hàm kasparabi_left_menu_meta_save( $post_id, $post ) {
// Kiểm tra trạng thái lưu
$is_autosave = wp_is_post_autosave( $post_id );
$is_revision = wp_is_post_revision( $post_id );
$is_valid_nonce = ( isset( $_POST[ 'kasparabi-left-menu-meta_nonce' ] ) && wp_verify_nonce( $_POST[ 'kasparabi-left-menu-meta_nonce' ], basename( __FILE__ ) ) ) ? 'true' : 'false';

// Thoát khỏi kịch bản tùy thuộc vào trạng thái lưu
nếu ( $is_autosave || $is_revision || !$is_valid_nonce ) {
trả về $post_id;
}

/* Nhận đối tượng loại bài viết. */
$post_type = get_post_type_object( $post->post_type );

/* Kiểm tra xem người dùng hiện tại có quyền chỉnh sửa bài viết hay không. */
nếu ( !current_user_can( $post_type->cap->edit_post, $post_id ) )
trả về $post_id;

/* Nhận dữ liệu được đăng và làm sạch nó để sử dụng làm lớp HTML. */
$new_meta_value = ( isset( $_POST['left-menu-checkbox'] ) ? sanitize_html_class( $_POST['left-menu-checkbox'] ) : '' );
$meta_key = 'left_menu_checkbox';
$meta_value = get_post_meta( $post->ID, $meta_key, true);

/* Nếu một giá trị siêu dữ liệu mới được thêm và không có giá trị trước đó, hãy thêm nó. */
nếu ( $new_meta_value && '' == $meta_value )
add_post_meta( $post_id, $meta_key, $new_meta_value, true);

/* Nếu giá trị siêu dữ liệu mới không khớp với giá trị cũ, hãy cập nhật nó. */
nếu ( $new_meta_value && $new_meta_value != $meta_value )
update_post_meta( $post_id, $meta_key, $new_meta_value );

/* Nếu không có giá trị siêu dữ liệu mới nhưng có giá trị cũ, hãy xóa nó. */
nếu ( '' == $new_meta_value && $meta_value )
delete_post_meta( $post_id, $meta_key, $meta_value );
}
add_action( 'save_post', 'kasparabi_left_menu_meta_save' );

