Dùng ngày tháng của sự kiện thay vì ngày tháng xuất bản cho permalink Trang web http://www.bikefun.org đang hoạt động, nhưng các liên kết vĩnh viễn không chính xác. Đó là một trang lịch sự kiện. Các sự kiện được lưu trữ như một loại bài viết tùy chỉnh "bf_events", với ngày tháng được lưu trữ như các giá trị postmeta số nguyên - số nguyên được tạo ra bởi strtime(). Tôi đang sử dụng cấu trúc liên kết vĩnh viễn "/events/2014/09/cyclewise-confidence-training-intermediate-2/" trong đó năm và tháng là của ngày tổ chức sự kiện, không phải là ngày xuất bản bài viết. Điều này hoạt động khá tốt, nhưng thực tế chỉ có tiêu đề sự kiện được sử dụng bởi WP, và số "2" ở cuối đã được thêm vào bởi WP để giữ cho liên kết vĩnh viễn duy nhất. Nếu bạn thay đổi năm hoặc tháng, cùng một trang sẽ được tải, trong khi bạn nên nhận được mã 404. Đây là mã:

function event_rewrite_rules() {
    global $wp_rewrite;
    $wp_rewrite->add_rewrite_tag( '%eventyear%', '([0-9]{4})', 'bf_events_year=' );
    $wp_rewrite->add_rewrite_tag( '%eventmonth%', '([0-9]{2})', 'bf_events_month=' );
    // $wp_rewrite->add_permastruct('bf_events', '/events/%bf_events_year%/%bf_events_month%/%postname%', false);
    add_rewrite_rule( '^events/([0-9]{4})/([0-9]{2})/([^/]+)?', 'index.php??post_type=bf_events&pagename=$matches[2]', 'top' );
}
add_action('init', 'event_rewrite_rules');
Tôi đã bỏ qua cuộc gọi add_permastruct vì nó phá hỏng mọi thứ.

add_filter('post_type_link', 'event_permalink', 10, 4);

function event_permalink($permalink, $post, $leavename) {
    if ( get_post_type( $post ) === "bf_events" ) {
        $sd = get_post_meta( $post->ID, 'bf_events_startdate', true );
        $year = date('Y', $sd + get_option( 'gmt_offset' ) * 3600 );
        $month = date('m', $sd + get_option( 'gmt_offset' ) * 3600 );
        $rewritecode = array(
            '%eventyear%',
            '%eventmonth%',
            $leavename? '' : '%postname%',
        );
        $rewritereplace = array(
            $year,
            $month,
            $post->post_name
        );
        $permalink = str_replace($rewritecode, $rewritereplace, $permalink);
    }
    return $permalink;
}

Để có thể cho phép WP sử dụng năm và tháng trong liên kết vĩnh viễn, chúng được lưu trữ như các giá trị postmeta bổ sung trong hàm meta-save:

update_post_meta($post->ID, "bf_events_startdate", $updatestartd );
update_post_meta($post->ID, "bf_events_year", date("Y", $updatestartd ) );
update_post_meta($post->ID, "bf_events_month", date("m", $updatestartd ) );

