Nó không liên quan gì đến dòng cuối cùng phải không? Nơi tôi gọi hàm add_meta_box và truyền kiểu bài viết tùy chỉnh là "SẢN PHẨM" và không chỉ định trang hoặc bài viết? Chỉ là một suy nghĩ. Đây là mã của tôi để tải lên tệp PDF trong hộp meta:

// Tải lên tệp PDF

foreach ($meta_box_pdf_uploads['fields'] as $pdf_field) {
    // Đặt mảng tập tin vào biến
    $pdf = $_FILES[$pdf_field['name']];

    // Nếu mảng được thiết lập và không có lỗi
    if (isset($pdf['error']) && $pdf['error'] > 0) {
        // Xử lý lỗi dựa trên mã lỗi
        wp_die('Lỗi khi tải lên tập tin: Mã lỗi là ' . $pdf['error']);
    } else {
        // Đã vượt qua
        // Thiết lập loại tập tin được phép
        $supported_file_type = array('application/pdf');

        // Lấy loại tập tin
        $uploaded_file_type = $pdf['type'];

        // Kiểm tra xem loại tập tin có được phép hay không
        if (in_array($uploaded_file_type, $supported_file_type)) {
            // Tải lên tập tin
            $uploaded_file = wp_upload_bits($_FILES[$pdf_field['name']], null, file_get_contents($_FILES[$pdf_field['tmp_name']]));

            print_r($uploaded_file);

            wp_die('Có tải lên được không?');

            add_post_meta($post_id, $pdf_field['id'], $uploaded_file);
            update_post_meta($post_id, $pdf_field['id'], $uploaded_file);
        } else {
            // KHÔNG PHẢI TẬP TIN PDF
            wp_die('Tập tin bạn cố gắng tải lên không phải là tệp PDF');
        }
    }
}

