function firstImg( $post ) {
    $matches = array();
    $output = preg_match_all( '/<img.+src=[\'"]([^\'"]+)[\'"].*>/i', $post->post_content, $matches );
    if ( isset( $matches[1][0] ) ) {
        $first_img = $matches[1][0];
    }
    if ( empty( $first_img ) ) {
        return '';
    }
    return $first_img;
}
