function the_producers($post_id = false) {
if ($post_id == false) {
$post_id = get_the_ID();
}
$producers = get_the_terms($post_id, 'producers');
$prods = array();
foreach ($producers as $producer) {
$prods[] = $producer->name;
}
$str = array_pop($prods);
if ($prods) {
$str = implode(', ', $prods).' & '.$str;
return $str;
} else {
return false;
}
}

