Bài viết vòng lặp được tạo ra thông qua mã ngắn không hiển thị mã ngắn trong nội dung Tôi đã suy nghĩ về việc này. Đây là một đoạn mã vòng lặp shortcode mà tôi đã tạo ra để hiển thị một loại bài viết cụ thể:

function faq_shortcode($atts, $content = NULL) {
    extract(shortcode_atts(array(
        'faq_topic' => '',
        'faq_tag'   => '',
        'faq_id'    => '',
        'limit'     => '10',
    ), $atts));

    $faq_topic = preg_replace('~&#x0*([0-9a-f]+);~ei', 'chr(hexdec("\\1"))', $faq_topic);
    $faq_tag = preg_replace('~&#x0*([0-9a-f]+);~ei', 'chr(hexdec("\\1"))', $faq_tag);

    $faqs = new WP_Query(array(
        'p' => $faq_id,
        'faq-topic' => $faq_topic,
        'faq-tags' => $faq_tag,
        'post_type' => 'question',
        'posts_per_page' => $limit,
        'orderby' => 'menu_order',
        'order' => 'ASC'
    ));

    $displayfaq = '<div class="faq_list">';
    while ($faqs->have_posts()) : $faqs->the_post();
        $displayfaq .= '<div class="single_faq">';
        $displayfaq .= '<h3 class="faq_question">' . get_the_title() . '</h3>';
        $displayfaq .= '<p class="faq_answer">' . get_the_content() . '</p>';
        $displayfaq .= '</div>';
    endwhile;
    wp_reset_query();
    $displayfaq .= '</div>';

    return $displayfaq;
}

add_shortcode('faq', 'faq_shortcode');

