$DEMenu = new DEMenu();

class DEMenu {
    function DEMenu() {
        if (is_admin()) {
            add_action('admin_menu', array(&$this, 'admin'));
        } else {
            add_action('init', array(&$this, 'core'));
        }
    }

    public function admin() {
        /* Không quan trọng */
    }

    public function core() {
        add_filter('wp_nav_menu_args', array(&$this, 'add_walker'));
    }

    public function add_walker( $args ) {
        $args['walker'] = 'DEMenu_Walker';
        return $args;
    }
}

class DEMenu_Walker extends Walker_Nav_Menu {
    function __construct() {
        die("Chúng tôi đã đến được hàm xây dựng!");
    }
}

Như đã đề cập ở trên, tôi nhận được lỗi sau:

**Lỗi nghiêm trọng**: Sử dụng $this khi không ở ngữ cảnh đối tượng trong
**/home/coupon/public_html/wp-includes/class-wp-walker.php** trên dòng **185**

Vì `test.php` bị lỗi và vì lớp `Walker_Nav_Menu` không bao giờ gặp lỗi này cho đến khi tôi thêm plugin của mình, nên tôi nghĩ vấn đề nằm ở một trong các lệnh gọi `add_action()` hoặc `add_filter()` của tôi. Tuy nhiên, vì nó vẫn chưa hoạt động đúng, nên tôi không chắc vấn đề ở đâu...

SỬA ĐỔI CUỐI CÙNG - Khi đọc kỹ lại hàm `walk_nav_menu_tree()`, tôi đã tìm ra vấn đề với lớp walker của tôi...

function walk_nav_menu_tree( $items, $depth, $r ) {
    $walker = ( empty($r->walker) ) ? new Walker_Nav_Menu : $r->walker;
    $args = array( $items, $depth, $r );
    return call_user_func_array( array(&$walker, 'walk'), $args );
}

Vì `$walker` được đặt thành `$r->walker` nên nó là một chuỗi, không phải là một đối tượng của lớp. Do đó, phương thức lớp được gọi một cách tĩnh thay vì thông qua một đối tượng của lớp. Thay vì:

$args['walker'] = 'DEMenu_Walker';

Tôi nên có:

$args['walker'] = new DEMenu_Walker();

* * *

**Nhiệm vụ**: Gọi một phương thức lớp như một hook cho plugin WordPress để biến `$this` không bị hỏng

echo hoặc print_r trong một hàm quản trị Tôi đang viết plugin đầu tiên (để xử lý CPT) và đang trong quá trình lưu giá trị của một hộp meta. Tôi muốn thêm dấu gạch dưới (`_`) vào khóa meta để nó được ẩn trong phần trường tùy chỉnh. Tôi gặp khó khăn khi lưu dữ liệu khi thêm dấu gạch dưới này (không có vấn đề khi không có dấu gạch dưới). Vì vậy tôi thử điều tra những gì xảy ra trong mảng meta, nhưng tôi không thể thực hiện `echo` hoặc `print_r` trong một hàm trong plugin của tôi sẽ in trên trang quản trị viên của tôi. Tôi đã viết hàm sau đây:

```php
function ccp_portfolio_item_info_meta_box_save( $post_id, $post ) {
