function catch_that_image() {
global $post, $posts;
$first_img = '';
ob_start();
ob_end_clean();
$output = preg_match_all('/<img.+src=[\'"]([^\'"]+)[\'"].*>/i', $post->post_content, $matches);
$first_img = $matches [1] [0];
if(empty($first_img)){ //Định nghĩa hình ảnh mặc định
$first_img = "http://static.purseblog.com/default.jpg";
}
return $first_img;
}

