var ajax_url = $('.loadAll').attr('data-url');
var cat = $('.loadAll').attr('data-cat');
var offset = -3;
$('#infinite-load').waypoint(function (direction) {
    if (direction === 'down') {
        offset = parseInt(offset) + 3;
        $.ajax({
            dataType: "HTML",
            url: ajax_url,
            type: 'POST',
            data: {
                action: 'data_scroll_all',
                cat: cat,
                offset: offset
            },
            beforeSend: function () {
                $(".loading").show(); // hiển thị hình ảnh đang tải
            },
            success: function (data) {
                $(".loading").hide();
                $('#infinite-load').append(data);
                $.waypoints('refresh');
            }
        });
    }
}, {
    offset: 'bottom-in-view'
});

