/**
* Bước 2: Xử lý hành động hàng loạt tùy chỉnh
*
* Dựa trên bài viết http://wordpress.stackexchange.com/questions/29822/custom-bulk-action
*/
function custom_bulk_action() {
global $typenow,$pagenow;
$post_type = $typenow;

//if($post_type == 'post') {
if($pagenow == 'upload.php') {
// lấy hành động
$wp_list_table = _get_list_table('WP_Media_List_Table'); // tùy thuộc vào loại tài nguyên, có thể là WP_Users_List_Table, WP_Comments_List_Table, vv
$action = $wp_list_table->current_action();

$allowed_actions = array("appr_1","appr_2");
if(!in_array($action, $allowed_actions)) return;

// kiểm tra bảo mật
check_admin_referer('bulk-posts');

// đảm bảo rằng các IDs được gửi đi. Tùy thuộc vào loại tài nguyên, điều này có thể là 'media' hoặc 'ids'
if(isset($_REQUEST['post'])) {
$post_ids = array_map('intval', $_REQUEST['post']);
}

if(empty($post_ids)) return;

// điều này dựa trên wp-admin/edit.php
$sendback = remove_query_arg( array('exported', 'untrashed', 'deleted', 'ids'), wp_get_referer() );
if ( ! $sendback )
//$sendback = admin_url( "edit.php?post_type=$post_type" );
$sendback = admin_url( "post.php" );

$pagenum = $wp_list_table->get_pagenum();
$sendback = add_query_arg( 'paged', $pagenum, $sendback );

switch($action) {
case 'appr_1':
// nếu chúng ta thiết lập quyền người dùng/năng lực, mã có thể trông giống như:
// if ( !current_user_can($post_type_object->cap->export_post, $post_id) )
// wp_die( __('You are not allowed to export this post.') );
$exported = 0;
foreach( $post_ids as $post_id ) {
if ( !$this->perform_export($post_id) )
wp_die( __('Error exporting post.') );
$exported++;
}
$sendback = add_query_arg( array('exported' => $exported, 'ids' => join(',', $post_ids) ), $sendback );
break;
default: return;
}

$sendback = remove_query_arg( array('action', 'action2', 'tags_input', 'post_author', 'comment_status', 'ping_status', '_status',
'post', 'bulk_edit', 'post_view'), $sendback );
wp_redirect($sendback);
exit();
}
}

/**
* Bước 3: hiển thị thông báo quản trị viên trên trang Bài viết sau khi xuất
*/
function custom_bulk_admin_notices() {
global $post_type, $pagenow;

if($pagenow == 'upload.php' && isset($_REQUEST['exported']) && (int) $_REQUEST['exported']) {
$message = sprintf( _n( 'Post exported.', '%s posts exported.', $_REQUEST['exported'] ), number_format_i18n( $_REQUEST['exported'] ) );
echo "<div class=\"updated\"><p>{$message}</p></div>";
}
}

