Lọc móc trả về rỗng khi sử dụng hai lần Đây là một câu hỏi khá dài, vì vậy hãy kiên nhẫn với tôi. Trong một plugin mà tôi đã viết cho phép người dùng dễ dàng tạo các hộp meta mới, tôi có một hàm sử dụng một công tắc () để trả về HTML phù hợp cho loại trường meta đang được thêm vào. Hàm trông giống như thế này:

// hiển thị trường được yêu cầu

hàm ecpt_render_field ($ field, $ meta) {

global $ wp_version, $ post, $ ecpt_options;

chuyển đổi ($ field ['type']) :

trường hợp 'text':

$ field_html = '<input type="text" name="' . $ field ['id'] . '" id="' . $ field ['id'] . '" value="' . stripslashes ($ meta) . '" kích thước "30" style="width: 97%" /><br/>' . __ (stripslashes ($ field ['desc']));

phá vỡ;

/ * * /

* nhiều tuyên bố trường hợp ở đây đã bị xóa bỏ vì ví dụ

* /

trường hợp 'checkbox':

$ field_html = '<input type="checkbox" name="' . $ field ['id'] . '" id="' . $ field ['id'] . '" ' . kiểm tra (! trống ($ meta), true, false) .' /> <div class="ecpt_description"> __ (stripslashes ($ field ['desc'])) </ div>';

phá vỡ;

endswitch;

nếu (has_filter ('ecpt_fields_html')) {

// điều này thêm bất kỳ trường bổ sung (từ plugin) vào mảng

$ field_html = apply_filters ('ecpt_fields_html', $ field, $ field_html, $ meta);

}

// trả về trường cuối cùng

trả về $ field_html;

}

$ field là một mảng chứa tất cả thông tin về trường (id, kiểu, lớp, v.v.). $ meta là giá trị được lưu trữ trong bài đăng meta. Ở cuối hàm có một kiểm tra sự tồn tại của bộ lọc "ecpt_fields_html". Đây là một bộ lọc mà tôi đã thiết lập để cho phép các loại trường meta bổ sung được đăng ký thông qua các plugin khác. Một hàm ví dụ đăng ký các loại trường bổ sung (thành công), trông giống như thế này:

// tạo HTML cho các trường bổ sung

hàm ecpt_bonus_fields_html ($ field, $ field_html, $ meta) {

chuyển đổi ($ field ['type']) :

trường hợp 'taxonomy':

// trả về html tùy chọn cho các trường chọn

$ field_options = ecpt_get_field_options ($ field, $ meta);

$ field_html = '<select name="' . $ field ['id'] . '" id="' . $ field ['id'] . '">' . $ field_options . '</select><br/>' . $ field ['desc'];

phá vỡ;

trường hợp 'separator':

$ field_html = '<hr />';

phá vỡ;

trường hợp 'colorpicker':

nếu (trống ($ meta)) $ meta = '#';

$ field_html = "<input class='ecpt-color' type='text' name='" . $ field ['id'] . "' id='" . $ field ['id'] . "' value='" . $ meta . "' kích thước "8" />

<a href='#' class='ecpt-color-select' rel='" . $ field ['id'] . "'>" __ ("Chọn một màu") "</a>

<a href='#' class='ecpt-color-select' style='display: none;'>" __ ("Ẩn Picker") "</a>

<div style='display: none; vị trí: tuyệt đối; nền: # f0f0f0; biên giới: 1px rắn # ccc; z-index: 100; 'class='ecpt-color-picker' rel='" . $ field ['id'] . "'></div>";

phá vỡ;

mặc định:

$ field_html = $ field_html;

endswitch;

trả về $ field_html;

}

add_filter ('ecpt_fields_html', 'ecpt_bonus_fields_html', 10, 3);

Hàm này để đăng ký các loại trường bổ sung hoạt động chính xác giống như hàm đầu tiên. Bây giờ, hãy nói rằng tôi có hàm trên được kích hoạt trong một plugin bổ sung (mọi thứ hoạt động tốt), và sau đó tôi thiết lập một plugin thứ hai có hàm thứ hai đăng ký nhiều loại trường hơn (hàm mới này được cấu trúc chính xác giống như hàm bộ lọc trên). Nếu tôi làm điều này, cả hai hàm bộ lọc đăng ký các loại trường mới đều hoàn toàn thất bại. Chúng không ném bất kỳ lỗi nào, nhưng câu lệnh "return $ field_html;" chỉ đơn giản là trả về không có gì cả. Hàm bộ lọc thứ hai trông giống như thế này:

// tạo HTML cho các trường bổ sung

hàm ecpt_sample_fields_html ($ field, $ field_html, $ meta) {

chuyển đổi ($ field ['type']) :

trường hợp 'textblock':

$ field_html = 'nội dung này nên được hiển thị trong hộp meta, nhưng không phải là';

phá vỡ;

endswitch;

trả về $ field_html;

}

add_filter ('ecpt_fields_html', 'ecpt_sample_fields_html', 10, 3);

Cả hai hàm bộ lọc hoạt động hoàn hảo khi hàm khác không tích cực, nhưng nếu cả hai đều tích cực, thì * $ field_html = apply_filters ('ecpt_fields_html', $ field, $ field_html, $ meta); * trong hàm đầu tiên chỉ trả về không có gì cả. Được rồi, bây giờ là nơi nó trở nên lạ hơn. Tôi có một tập hợp gần giống nhau của các hàm / bộ lọc thiết lập hiển thị nhãn cho các loại trường trong hộp meta. Chúng hoạt động hoàn hảo. Trong plugin lõi, hàm thiết lập nhãn cho từng trường trông giống như thế này:

// chạy nhãn qua một bộ lọc. Điều này cho phép chúng tôi sửa đổi / xóa nhãn cho bất kỳ loại trường nào

hàm ecpt_field_label ($ field) {

$ label = '<label for="' . $ field ['id'] . '">' . __ (stripslashes ($ field ['name'])) . '</label>';

// bộ lọc ecpt_field_label cho phép đầu ra nhãn trường được thay đổi cho bất kỳ loại trường nào

nếu (has_filter ('ecpt_field_label_filter')) {

$ label = apply_filters ('ecpt_field_label_filter', $ label, $ field);

}

trả về $ label;

}

Và hàm bộ lọc cho phép HTML nhãn được thay đổi cho các trường được đăng ký với các plugin khác trông giống như thế này:

// sửa đổi nhãn cho các trường thưởng (nếu cần)

hàm ecpt_bonus_fields_labels ($ label, $ field) {

nếu ($ field ['type'] == 'separator') {

// xóa nhãn cho trường separator

trả về;

}

nếu ($ field ['type'] == 'header') {

trả về '<h4>' . $ label . '</h4>';

}

trả về $ label;

}

add_filter ('ecpt_field_label_filter', 'ecpt_bonus_fields_labels', 10, 2);

Điều này hoạt động hoàn hảo, ngay cả khi tôi thiết lập một _hàm bộ lọc nhãn thứ hai_ (nhớ rằng việc thiết lập hàm thứ hai cho các loại trường là nguyên nhân khiến nó bị hỏng). Vì vậy, hàm bộ lọc nhãn thứ hai của tôi trông giống như thế này:

// sửa đổi nhãn cho các trường thưởng (nếu cần)

hàm ecpt_sample_field_labels ($ label, $ field) {

nếu ($ field ['type'] == 'textblock') {

trả về '<strong>' . $ label . '</strong>';

}

trả về $ label;

}

add_filter ('ecpt_field_label_filter', 'ecpt_sample_field_labels', 10, 2);

