Offset hoạt động như thế nào trong phân trang? Tôi đã làm theo liên kết này và tạo ra câu lệnh truy vấn tùy chỉnh của riêng mình với phân trang, nhưng tôi không thực sự hiểu cách thức hoạt động của offset. Phân trang này không hoạt động tốt, và tôi nhận được giá trị zero cho offset:

function spiciest() {
    global $wpdb, $paged, $max_num_pages;
    $paged = (get_query_var('paged')) ? get_query_var('paged') : 1;
    $post_per_page = intval(get_query_var('posts_per_page')); //6
    $offset = ($paged - 1) * $post_per_page;
    /* Câu lệnh SQL tùy chỉnh ở đây. Tôi bỏ qua những phần quan trọng và xóa nội dung bài viết vì nó sẽ cụ thể hơn khi bạn có nội dung của riêng bạn. */
    $sql = "
        SELECT DISTINCT * FROM $wpdb->posts
        INNER JOIN (SELECT *, SUBSTRING(name, 6) as 'post_ID',
        votes_up AS votes_balance,
        votes_up + votes_down AS votes_total
        FROM thumbsup_items) AS thumbsup
        ON $wpdb->posts.ID = thumbsup.post_ID
        WHERE $wpdb->posts.post_status = 'publish'
        AND $wpdb->posts.post_type = 'post'
        AND $wpdb->posts.post_password = ''
        ORDER BY votes_up DESC, votes_balance DESC
        LIMIT " . $offset . ", " . $post_per_page . ";";
    $sql_result = $wpdb->get_results( $sql, OBJECT );
    /* Xác định tổng số kết quả tìm thấy để tính toán $max_num_pages cho điều hướng next_posts_link */
    $sql_posts_total = $wpdb->get_var( "SELECT FOUND_ROWS();" );
    $max_num_pages = ceil($sql_posts_total / $post_per_page);
    print_r("offset " . $offset . "\n");
    print_r("\nsql_posts_total " . $sql_posts_total . "\n");
    print_r("\nmax_num_pages " . $max_num_pages . "\n");
    return $sql_result;
}

Folder tải lên cụ thể cho PDF trong bài viết tùy chỉnh trong WP đa trang web Tôi cần lọc các tập tin tải lên vào một thư mục cụ thể dành riêng cho loại bài viết tùy chỉnh gọi là "document" chỉ dành cho PDF. Cho đến nay, tôi đã có:

function custom_upload_directory( $args ) {
$base_directory = '/home/xxx/my_uploadfolder';
$base_url = 'http://xxxx/wp-content/uploads/my_uploadfolder';
$id = $_REQUEST['post_id'];
$parent = get_post( $id )->post_parent;
// Kiểm tra loại bài viết của bài viết hiện tại
if( "document" == get_post_type( $id ) || "document" == get_post_type( $parent ) ) {
$args['path'] = $base_directory;
$args['url']  = $base_url;
$args['basedir'] = $base_directory;
$args['baseurl'] = $base_url;
}
return $args;
}
add_filter( 'upload_dir', 'custom_upload_directory' );

Nó hoạt động, nhưng với một số vấn đề: mọi loại tập tin nào cũng bị chuyển hướng vào my_uploadfolder. Ngoài ra, tôi không thể xóa những tập tin này từ phần quản trị viên WP sau khi chúng được tải lên. Ai có thể giúp tôi không?

