Tải lên phương tiện truyền thông không hoạt động trên tùy chọn chủ đề trong WordPress 3.8.1 Tôi có đoạn mã jQuery sau đây trong plugin của mình để hiển thị một hộp đa phương tiện để tải lên hình ảnh hoặc chọn một hình ảnh từ thư viện đa phương tiện:

(function($) {
    jQuery(document).ready(function() {
        $('#upload_image_button').click(function(e) {
            e.preventDefault();

            // Nếu đối tượng uploader đã được tạo, hãy mở lại hộp thoại
            if (custom_uploader) {
                custom_uploader.open();
                return;
            }

            // Mở rộng đối tượng wp.media
            custom_uploader = wp.media.frames.file_frame = wp.media({
                title: 'Chọn Hình Ảnh',
                button: {
                    text: 'Chọn Hình Ảnh'
                },
                multiple: false
            });

            // Khi một tập tin được chọn, lấy URL và đặt nó làm giá trị trường văn bản
            custom_uploader.on('select', function() {
                attachment = custom_uploader.state().get('selection').first().toJSON();
                $('#upload_image').val(attachment.url);
            });

            // Mở hộp thoại uploader
            custom_uploader.open();
        });
    });
})(jQuery);

