Dưới đây là hàm `get_custom_field_value`:

function get_custom_field_value($szKey, $prefix = '', $bPrint = false) {
    global $post;
    $szValue = get_post_meta($post->ID, $szKey, true);
    if ( $bPrint == false ) return (empty($szValue) ? "" : $prefix . $szValue); else echo (empty($szValue) ? $szValue : $prefix . $szValue);
}

Hook hành động 'save_post' kích hoạt khi xóa bài viết Tôi đã viết một plugin tùy chỉnh để tự động sửa đổi nội dung của bài viết, tuy nhiên khi tôi chuyển một bài viết vào thùng rác thì hàm 'save_post' sẽ được kích hoạt và bài viết không bị xóa. Dưới đây là phiên bản đơn giản của mã nguồn của tôi :
add_action('save_post', 'rewrite_post', 10, 2);
function rewrite_post($post_id) {
remove_action('save_post', 'rewrite_post');
$title = preg_replace('/\_/', ' ', get_the_title($post_id));
$my_post = array();
$my_post['ID'] = $post_id;
$my_post['post_title'] = $title;
$my_post['post_status'] = 'publish';
wp_update_post($my_post);
add_action('save_post', 'rewrite_post');
}
