Đặt post_parent trong posts tùy chỉnh tự động dựa trên tên trang cpt Tôi đang cố gắng viết một hàm sẽ "pair" loại bài viết tùy chỉnh với một trang có cùng tên với loại bài viết tùy chỉnh. Mục tiêu là khi một loại bài viết tùy chỉnh được lưu, nó kiểm tra xem có một trang nào có cùng tên với bài viết tùy chỉnh hay không, và nếu đúng, nó sẽ lấy id từ trang đó và đặt nó làm id cha cho bài viết tùy chỉnh. Đây là cách tôi giữ liên kết giữa chúng (các bài viết tùy chỉnh thừa hưởng các giá trị khác nhau từ trang). Tuy nhiên, tôi không thể khiến nó hoạt động, nó đưa ra một id, nhưng đó là id sai (nó lấy id của trang có id cao nhất), không chắc tôi đang làm sai điều gì. Dưới đây là mã hiện tại:

function find_parent_for_cpt( $data , $postarr ) {
    global $post;
    if ($post->post_type != 'post' || 'page'){
        $post_type = $post->post_type;
        $mypages = get_pages();
        foreach($mypages as $page){
            if($page->post_title==$post_type) {
                $data[ 'post_parent' ] = $page->ID;
                return $data;
            }
        }
    }
}
add_filter( 'wp_insert_post_data' , 'find_parent_for_cpt' , '99', 2 );

