Cho phép người dùng truy cập vào Bảng điều khiển chỉ! Cập nhật: Đoạn mã sau đây cũng loại bỏ menu cho tài khoản quản trị viên của tôi:

function remove_menu_items() {
    global $menu;
    global $user_ID;
    if( $user_ID ) :
        /* Chỉ truy cập bảng điều khiển */
        if( current_user_can( 'Dashboardvisitors' ) ) :
            $restricted = array(
                __('Bài viết'),
                __('Phương tiện truyền thông'),
                __('Trang'),
                __('Liên kết'),
                __('Xu hướng'),
                __('Công cụ'),
                __('Người dùng'),
                __('Cài đặt'),
                __('Bình luận'),
                __('Plugin')
            );
        endif;
    endif;
    end($menu);
    while ( prev($menu) ) :
        $value = explode(' ', $menu[key($menu)][0]);
        if( in_array( $value[0] != NULL?$value[0]:"" , $restricted ) ) :
            unset($menu[key($menu)]);
        endif;
    endwhile;
}
add_action('admin_menu', 'remove_menu_items');

