Dấu phẩy trong permalink dẫn đến trang không tìm thấy Tôi đang thực hiện một cuộc di cư từ Drupal sang một mạng lưới đa trang web WP, tôi có một trường siêu dữ liệu bài đăng chứa URL của bài đăng cũ (chủ yếu để duy trì số lượng xã hội và như vậy) mà tôi đang sử dụng cho cấu trúc liên kết vĩnh viễn. Tôi đang làm điều này với các mã sau đây:

add_filter('post_link', 'migration_permalinks', 10, 3 );

function migration_permalinks( $permalink, $post, $leavename ) {
if( ($post->post_type == 'post' ) && ( $the_link = get_post_meta( $post->ID, '_the_old_site_permalink', true) ) ) {
$url = parse_url( $the_link );
$permalink = site_url() . $url['path'];
}
return $permalink;
}

Vấn đề tôi gặp phải là nếu tiêu đề bài đăng chứa dấu nháy đơn, `’` (không phải dấu nháy đơn thẳng `'`), URL bài đăng không hoạt động. Mã hóa, nó chuyển đổi thành `%E2%80%99`. Ở thanh địa chỉ trình duyệt, nếu tôi thay đổi dấu nháy đơn thành dấu nháy đơn thẳng, URL hoạt động và bài đăng được hiển thị. Trang web Drupal hiện tại chứa dấu nháy đơn (`%E2%80%99`) mà không gặp vấn đề gì. Duy trì URL như hiện tại rất quan trọng vì tôi không muốn bất kỳ liên kết nào đến trang bị lỗi 404 khi di cư xảy ra. Tại sao liên kết không hoạt động khi nó chứa dấu nháy đơn?

Lượt xem tùy chỉnh không được cập nhật đúng cách Tôi đang cố gắng thêm một số tùy chỉnh xem/lọc vào danh sách bài viết cho một loại bài viết tùy chỉnh trong quản trị viên. Tuy nhiên, truy vấn mà đếm số lượng bài viết đang cập nhật số lượng bài viết cho tất cả các bộ lọc cùng một lúc, chỉ khi tôi đang ở một trong những bộ lọc tùy chỉnh đó. Đây là cách tôi đã thiết lập truy vấn để nhận được số lượng bài viết:

add_action( 'views_edit-movies', array($this, 'custom_views') );

public function custom_views($views) {

    //$directors là một mảng hợp lệ trả về từ hàm riêng biệt, đã được loại bỏ vì sự rõ ràng

    foreach ($directors as $key => $value) {

        $director = $value;

        $query = array(

            'post_type' => 'movies',

            'meta_key' => 'director',

            'meta_value' => $director

        );

        $result = new WP_Query($query);

        $class = ($wp_query->query_vars['meta_value'] == $director) ? ' class="current"' : '';

        $views["$director"] = sprintf(__('<a href="%s"'. $class .'>' . $director . ' <span class="count">(%d)</span></a>'),

            admin_url('edit.php?&post_type=movies&director='.$director),

            $result->found_posts);

    } //end foreach

}

Điều này hoạt động tốt nếu tôi đang ở "Tất cả", "Đã xuất bản" hoặc "Thùng rác" xem mặc định, và mỗi bộ lọc giám đốc có số lượng bài viết chính xác trên những lượt xem đó. Khi tôi sau đó nhấp vào một giám đốc, tất cả các giám đốc khác có cùng số lượng bài viết như người mà tôi đang ở hiện tại. Điều này có phải là vì tôi đang gán các lượt xem trong một vòng lặp foreach, dựa trên một biến? Hoặc bởi vì tôi đang thay đổi truy vấn để hiển thị lượt xem với mã dưới đây? Đây là mã thực sự hiển thị các lượt xem:

add_action( 'pre_get_posts', array($this, 'filters') );

public function filters($query)

{

    if ( isset($_GET['director']) ) {

        $query->set( 'meta_key', 'director' );

        $query->set( 'meta_value', $_GET['director'] );

    }

    return $query;

}

Cách tiếp cận đúng đắn để di chuyển toàn bộ trang từ một miền sang miền khác và bảo tồn các tiện ích Tôi tự xem mình khá thông thạo về vấn đề này, tuy nhiên gần đây tôi đã gặp hàng loạt các vấn đề khi di chuyển trang web. Tôi có thể di chuyển trang web thành công, chỉnh sửa wp-config.php, di chuyển cơ sở dữ liệu, v.v. Sau khi di chuyển cơ sở dữ liệu, tôi thực hiện các truy vấn sau:
UPDATE wp_options SET option_value = replace(option_value, 'http://olddomain.com', 'http://newdomain.com');
UPDATE wp_posts SET guid = replace(guid, 'http://olddomain.com','http://newdomain.com');
UPDATE wp_posts SET post_content = replace(post_content, 'http://olddomain.com', 'http://newdomain.com');
UPDATE wp_postmeta SET meta_value = replace(meta_value, 'http://olddomain.com', 'http://newdomain.com');
Điều này sẽ cập nhật tất cả các liên kết, tham chiếu hình ảnh, v.v. của tôi một cách chính xác - tuy nhiên tôi lại gặp một vấn đề khác: một số tiện ích bị hỏng (ví dụ như tiện ích WP Text Widget và tiện ích mở rộng WYSIWYG Widget). Chúng hoàn toàn không hoạt động. Tức là tiện ích không còn hiển thị dưới thanh bên nữa và tôi phải xây dựng lại chúng từ đầu (các plugin hoạt động tốt, chỉ có tiện ích biến mất khỏi thanh bên). Tôi đã tìm kiếm trên WP-SO và thấy một số bình luận cảnh báo về phương pháp cập nhật cơ sở dữ liệu này, nhưng tôi muốn biết liệu có cách nào để giải quyết vấn đề này hay không và cách đó là gì.

