Thay đổi một chức năng của WordPress mà không cần hack vào mã nguồn Tôi đang muốn thay đổi một dòng trong một hàm cốt lõi. Hàm đó là `wp_allow_comment()` nằm trong `/wp-includes/comment.php`

function wp_allow_comment($commentdata) {     global $wpdb;     extract($commentdata, EXTR_SKIP);          // Kiểm tra đơn giản xem có trùng không     // expected_slashed ($comment_post_ID, $comment_author, $comment_author_email, $comment_content)     $dupe = $wpdb->prepare( "SELECT comment_ID FROM $wpdb->comments WHERE comment_post_ID = %d AND comment_parent = %s AND comment_approved != 'trash' AND ( comment_author = %s ", wp_unslash( $comment_post_ID ), wp_unslash( $comment_parent ), wp_unslash( $comment_author ) );     if ( $comment_author_email )         $dupe .= $wpdb->prepare( "OR comment_author_email = %s ", wp_unslash( $comment_author_email ) );     $dupe .= $wpdb->prepare( ") AND comment_content = %s LIMIT 1", wp_unslash( $comment_content ) );     if ( $wpdb->get_var($dupe) ) {         /**          * Bật ngay sau khi phát hiện ra một bình luận trùng lặp.          *          * @since 3.0.0          *          * @param array $commentdata Dữ liệu của bình luận.          */         do_action( 'comment_duplicate_trigger', $commentdata );         if ( defined('DOING_AJAX') )             die( __('Duplicate comment detected; it looks as though you&#8217;ve already said that!') );              wp_die( __('Duplicate comment detected; it looks as though you&#8217;ve already said that!') );     }          /**      * Bật ngay trước khi đánh dấu một bình luận là được chấp thuận.      *      * Cho phép kiểm tra tràn bình luận.      *      * @since 2.3.0      *      * @param string $comment_author_IP    Địa chỉ IP của tác giả bình luận.      * @param string $comment_author_email Email của tác giả bình luận.      * @param string $comment_date_gmt     Ngày GMT mà bình luận được đăng.      */     do_action( 'check_comment_flood', $comment_author_IP, $comment_author_email, $comment_date_gmt );          if ( ! empty( $user_id ) ) {         $user = get_userdata( $user_id );         $post_author = $wpdb->get_var($wpdb->prepare("SELECT post_author FROM $wpdb->posts WHERE ID = %d LIMIT 1", $comment_post_ID));     }          if ( isset( $user ) && ( $user_id == $post_author || $user->has_cap( 'moderate_comments' ) ) ) {         // Tác giả và các quản trị viên sẽ được tôn trọng.         $approved = 1;     } else {         // Bình luận của mọi người khác sẽ được kiểm tra.         if ( check_comment($comment_author, $comment_author_email, $comment_author_url, $comment_content, $comment_author_IP, $comment_agent, $comment_type) )             $approved = 1;         else             $approved = 0;         if ( wp_blacklist_check($comment_author, $comment_author_email, $comment_author_url, $comment_content, $comment_author_IP, $comment_agent) )             $approved = 'spam';     }          /**      * Lọc trạng thái chấp thuận của một bình luận trước khi nó được đặt.      *      * @since 2.1.0      *      * @param bool|string $approved    Trạng thái chấp thuận. Chấp nhận 1, 0, hoặc 'spam'.      * @param array       $commentdata Dữ liệu của bình luận.      */     $approved = apply_filters( 'pre_comment_approved', $approved, $commentdata );     return $approved;     }

Tôi muốn thay đổi `$approved = 'spam';` thành `$approved = 'trash';` - đây là một việc có thể thực hiện được mà không cần hack vào phần cốt lõi? Tôi đang cố gắng tìm hiểu về bộ lọc như một giải pháp khả thi nhưng không may là tôi chưa tìm ra cách nào cả. Tôi đã thử điều gì đó như thế này:

add_filter('pre_comment_approved', 'custom_blacklist',1, 0);          function custom_blacklist() {         if ( wp_blacklist_check($comment_author, $comment_author_email, $comment_author_url, $comment_content, $comment_author_IP, $comment_agent) )             $approved = 'trash';     }

nhưng kết quả là nó đã vô hiệu hóa hoàn toàn bộ lọc spam, tôi chắc chắn rằng tôi chưa sử dụng bộ lọc đúng cách.

