Vấn đề thêm Taxonomy vào Custom Post Type sử dụng Function Tôi đang sử dụng WordPress 3.7.1 và PHP 5.4.12, tôi đang cố gắng thêm Custom Post Type và Taxonomy vào chủ đề của mình, cho đến nay phương pháp kiểu bài viết tùy chỉnh hoạt động nhưng Category không được thêm vào Bảng điều khiển Admin. Đây là mã tôi có:
            <?php
function add_post_type($name, $args = array()) {
    add_action('init', function() use($name, $args) {
        $upper = ucwords($name);
        $name = strtolower(str_replace(' ','_',$name));
        $args = array_merge(
            array(
                'public'=> true,
                'label' => "All $upper" . 's',
                'labels' => array('add_new_item' => "Add New $upper"),
                'support' => array('title', 'editor', 'author', 'thumbnail', 'excerpt', 'comments')
            ),
            $args
        );
        register_post_type('$name', $args);
    });
}

function add_taxonomy($name, $post_type, $args = array()) {
    $name = strtolower($name);
    add_action('init', function() use($name, $post_type, $args) {
        $args = array_merge(
            array(
                'label' => ucwords($name),
            ),
            $args
        );
        register_taxonomy($name, $post_type, $args);
    });
}

add_post_type('book', array(
    'supports' => array('title', 'editor', 'author', 'thumbnail', 'excerpt', 'comments')
));

add_taxonomy('fun', 'book');
?>

