WordPress xử lý tương tác HTML Tables với jQuery như thế nào? Tôi có một đoạn mã JavaScript để thu nhỏ kích thước phông chữ của bảng cho đến khi chiều rộng của bảng nhỏ hơn hoặc bằng với phần tử div cha. Mã bên dưới chỉ thể hiện nguyên lý hoạt động của nó. Tuy nhiên, trong WordPress, kích thước phông chữ bị giảm xuống 0px và bảng vẫn giữ nguyên kích thước, nhưng vẫn lớn hơn so với phần tử div cha. Ngoài WordPress, trình duyệt sẽ tự điều chỉnh chiều rộng bảng để phù hợp với văn bản bên trong. Vậy làm thế nào để WordPress xử lý các bảng HTML khác biệt?

function ShrinkTable() {
    var FontSize = parseInt($("#tbl").css('font-size').replace('px', ''), 10);
    var TabWidth = jQuery("#tbl").width();
    var DivWidth = jQuery("#narrorColumn");

    if (parseInt(DivWidth.css('width').replace('px', ''), 10) <= TabWidth) {
        jQuery("#tbl").css('font-size', FontSize - 1 + 'px'); // bạn có thể thay đổi số 4 thành bất kỳ số nào, số càng nhỏ thì kết quả càng tốt, nhưng có thể cần nhiều vòng lặp hơn
        // thu nhỏ kích thước phông chữ cho đến khi chiều rộng của div nhỏ hơn hoặc bằng với chiều rộng của bảng
        ShrinkTable();
    }
}

