Plugin tạo trang nội dung bài viết Mã của tôi đang tạo một bài đăng trùng lặp ngay cả khi tôi đã chỉ định rõ ràng rằng loại bài đăng nên là một trang. Nó cũng bỏ qua $post_title, điều mà tôi không muốn tạo một bài đăng trùng lặp nếu tiêu đề đã tồn tại. Ai có thể tìm ra lý do tại sao nó lại tạo một bài đăng thay vì một trang?

function av_generate_page($post_id) {
    $post_info = get_post($post_id);
    $post_slug = $post_info->post_name;
    $post_title = $post_info->post_title;
    $page_exists = get_page_by_title($post_title);
    if($page_exists){ exit(); }
    $detail_level = get_post_meta($post_id, 'detail_level', true);
    $formats = wp_get_post_terms($post_id, 'formats', array('fields'=>'slugs'));
    $page = array(
        'post_type' => 'page',
        'post_title' => $post_title,
        'post_content' => '[['.$post_slug.']]',
        'post_status' => 'publish',
        'post_parent' => 8800
    );
    if( !$page_exists ) {
        if (in_array('brief-segment',$formats)){
            // Không tạo trang cho các phân đoạn tóm tắt
        }else{
            $new_page_id = wp_insert_post($page, false);
            update_post_meta($new_page_id,'suf_hide_page_title','on');
            update_post_meta($new_page_id,'_wp_page_template','no-sidebars-no-comments.php');
            if(in_array('internal-only',$formats)){
                add_post_meta($new_page_id,'InternalOnly','yes',true);
            }
        }
    }else{
        // Không tạo trang
    }
}
add_action('publish_post', av_generate_page, 12);

**SỬA ĐỔI** Tôi sẽ truyền ID bài viết hiện tại như thế nào để sử dụng làm ID của tôi để tạo một trang? Về lý do tại sao tôi nhúng một bài viết vào một trang (với giả định rằng trang đó chưa được tạo), tôi đang tạo một **cây trình tự phân cấp của các trang**. Bởi vì các bài viết là phẳng, tôi cần tạo một trang mỗi khi tôi tạo một bài viết và di chuyển nó đến vị trí phù hợp trong hệ thống phân cấp. Tại sao tôi không đơn giản tạo một trang thay vì vậy? Bởi vì tôi cần tạo nhiều trang cho mỗi bài viết dựa trên nhiều danh mục mà chúng áp dụng. Vâng, chúng được gắn thẻ với các danh mục trong bài viết, nhưng tôi vẫn cần cung cấp danh sách các trang mà tôi không thể thực hiện với một bài viết. Do đó, tôi đang tạo một trang có thể sống trong một hệ thống phân cấp và tham chiếu đến một bài viết mà tôi có thể tham chiếu trong các trang khác.

