function custom_gallery_shortcode( $attr = array(), $content = '' ) {
    $attr['itemtag'] = "li";
    $attr['icontag'] = "";
    $attr['captiontag'] = "p";

    // Gọi hàm callback của mã gallery gốc:
    $html = gallery_shortcode( $attr );

    // Xóa tất cả các thẻ ngoại trừ a, img, li, p
    $html = strip_tags( $html, '<a><img><li><p>' );

    // Một số thay thế đơn giản:
    $from = array(
        'class="gallery-item"',
        'class="gallery-icon landscape"',
        'class="attachment-thumbnail"',
        'a href=',
    );

    $to = array(
        '',
        '',
        '',
        'a data-caption="" class="ilightbox" href=',
    );

    $html = str_replace( $from, $to, $html );

    // Xóa thuộc tính width/height:
    $html = preg_replace( '/(width|height)=\"\d*\"\s/', "", $html );

    // Đóng gói kết quả trong thẻ ul:
    $html = sprintf( '<ul class="gallery">%s</ul>', $html );

    return $html;
}

add_shortcode( 'gallery', 'custom_gallery_shortcode' );
add_filter( 'use_default_gallery_style', '__return_false' );

