làm cho giá trị của PHP trở thành số Tôi đã sử dụng một số mã từ trang này trên Stack Overflow: Sử dụng wp_query có thể orderby taxonomy không? Nó nói về chức năng để sắp xếp một truy vấn theo giá trị của taxonomy. Mặc dù nó hoạt động hoàn hảo, tôi muốn tiến xa hơn một bước. Giá trị tôi lấy được từ thuật ngữ của taxonomy là một con số. Tuy nhiên, khi sắp xếp theo số đó, nó lại cho ra thứ tự như sau: 1 10 11 2 21 22 và cứ thế tiếp tục. Tôi muốn nó được sắp xếp 'bình thường', tức là 1 2 3 5 9 11 15 21 22 v.v... Theo Google thì tôi cần thêm 0 vào giá trị đó để biến nó thành một giá trị số, nhưng tôi không biết nên đặt nó ở đâu trong mã này. Nơi nào đó, nó nên nói là value + 0. Bạn có ý tưởng nên đặt nó ở đâu không? Nó liên quan đến mã sau:

function orderby_tax_clauses( $clauses, $wp_query ) {
    global $wpdb;
    $taxonomies = get_taxonomies();
    foreach ($taxonomies as $taxonomy) {
        if ( isset( $wp_query->query['orderby'] ) && $taxonomy == $wp_query->query['orderby'] ) {
            $clauses['join'] .=<<<SQL
                LEFT OUTER JOIN {$wpdb->term_relationships} ON {$wpdb->posts}.ID={$wpdb->term_relationships}.object_id
                LEFT OUTER JOIN {$wpdb->term_taxonomy} USING (term_taxonomy_id)
                LEFT OUTER JOIN {$wpdb->terms} USING (term_id)
            SQL;
            $clauses['where'] .= " AND (taxonomy = '{$taxonomy}' OR taxonomy IS NULL)";
            $clauses['groupby'] = "object_id";
            $clauses['orderby'] = "GROUP_CONCAT({$wpdb->terms}.name ORDER BY name ASC) ";
            $clauses['orderby'] .= ( 'DESC' == strtoupper( $wp_query->get('order') ) ) ? 'ASC' : 'DESC';
        }
    }
    return $clauses;
}
add_filter('posts_clauses', 'orderby_tax_clauses', 10, 2 );

Cách thay đổi giá trị trong wp-include/taxonomy.php mà không cần thay đổi file wordpress-core Tôi gặp vấn đề là thẻ của các bài viết riêng tư không hiển thị trong tiện ích đám mây thẻ mặc dù người dùng đã đăng nhập. Nguyên nhân dường như là do giá trị "post_status" trong hàm _update_post_term_count trong wp-include/taxonomy.php. Ít nhất khi tôi thay đổi giá trị này thành "private", các thẻ riêng tư được hiển thị. Câu hỏi của tôi là: Làm thế nào để thay đổi giá trị này mà không chỉnh sửa taxonomy.php, tức là không chỉnh sửa phần cốt lõi? Đây là hàm đã chỉnh sửa (thay đổi ở > ****...**** ):

function _update_post_term_count( $terms, $taxonomy ) {
global $wpdb;
$object_types = (array) $taxonomy->object_type;
foreach ( $object_types as &$object_type )
list( $object_type ) = explode( ':', $object_type );
$object_types = array_unique( $object_types );
if ( false !== ( $check_attachments = array_search( 'attachment', $object_types ) ) ) {
unset( $object_types[ $check_attachments ] );
$check_attachments = true;
}
if ( $object_types )
$object_types = esc_sql( array_filter( $object_types, 'post_type_exists' ) );
foreach ( (array) $terms as $term ) {
$count = 0;
// Attachments có thể ở trạng thái 'inherit', chúng ta cần dựa vào trạng thái của phần tử cha nếu đúng
if ( $check_attachments )
$count += (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM $wpdb->term_relationships, $wpdb->posts p1 WHERE p1.ID = $wpdb->term_relationships.object_id AND ( post_status = 'private' OR ( post_status = 'inherit' AND post_parent > 0 AND ( SELECT post_status FROM $wpdb->posts WHERE ID = p1.post_parent ) = 'private' ) ) AND post_type = 'attachment' AND term_taxonomy_id = %d", $term ) );
if ( $object_types )
$count += (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM $wpdb->term_relationships, $wpdb->posts WHERE $wpdb->posts.ID = $wpdb->term_relationships.object_id AND post_status = 'private' AND post_type IN ('" . implode("', '", $object_types ) . "') AND term_taxonomy_id = %d", $term ) );
do_action( 'edit_term_taxonomy', $term, $taxonomy );
$wpdb->update( $wpdb->term_taxonomy, compact( 'count' ), array( 'term_taxonomy_id' => $term ) );
do_action( 'edited_term_taxonomy', $term, $taxonomy );
}

