function post_navigation() {
    global $wp_query;
    if ($wp_query->is_home || $wp_query->is_archive || $wp_query->is_search) {
        if ($wp_query->max_num_pages > 1) {
            $previous = 'Previous Entries';
            $next = 'Next Entries';
            echo "\t\t\t<div class=\"prev_next\">\n";
            if ($wp_query->query_vars['paged'] <= 1) {
                echo "\t\t\t\t<p class=\"previous\">";
                next_posts_link($previous);
                echo "</p>\n";
            }
            elseif ($wp_query->query_vars['paged'] < $wp_query->max_num_pages) {
                echo "\t\t\t\t<p class=\"previous floated\">";
                next_posts_link($previous);
                echo "</p>\n";
                echo "\t\t\t\t<p class=\"next\">";
                previous_posts_link($next);
                echo "</p>\n";
            }
            elseif ($wp_query->query_vars['paged'] >= $wp_query->max_num_pages) {
                echo "\t\t\t\t<p class=\"next\">";
                previous_posts_link($next);
                echo "</p>\n";
            }
            echo "\t\t\t</div>\n\n";
        }
    }
}

làm thế nào để nhóm các bài viết tùy chỉnh theo thuật ngữ phân loại tùy chỉnh Tôi sẽ rất cảm kích nếu bạn có thể giúp tôi :) Tôi đang gặp khó khăn và không biết phải làm thế nào. Tôi có một kiểu bài viết tùy chỉnh được gọi là "event" và 2 phân loại tùy chỉnh được đăng ký cho nó:

1. "event_type" với chức năng giống như thẻ (ví dụ về loại sự kiện: yoga, giọng nói)
2. "event_location" với chức năng giống như danh mục (ví dụ về địa điểm tổ chức sự kiện: uk->brighton, london; europe->paris). Có những trang trên trang web như "Yoga -> Upcoming events"; "Voice work -> Upcoming workshops". Tùy thuộc vào trang nào chúng ta đang ở, tôi muốn hiển thị các sự kiện phù hợp. Ví dụ, nếu chúng ta đang ở trang "Yoga -> Upcoming events", tôi muốn hiển thị tất cả các bài viết tùy chỉnh "event" với "event_type" là yoga và sau đó nhóm kết quả theo các thuật ngữ phân loại "event_location". Ví dụ, liệt kê tất cả các sự kiện yoga cho UK, Brighton sau đó là UK, London và sau đó là Europe, Paris, v.v.

Điều tôi hiện đang làm trong mẫu như sau:

1. Tôi nhận được slug của trang hiện tại và các trang tổ tiên của nó.
2. Tôi nhận được slug của tất cả các thuật ngữ trong phân loại "event_type", có các sự kiện liên quan đến chúng.
3. Tôi xác định loại sự kiện nào để hiển thị, bằng cách giao nhau các giá trị đã thu thập trước đó.
4. Sau đó, tôi tạo một WP_Query để nhận được các bài viết "event" với các thuật ngữ phân loại "event_type" đã xác định. Điều này dường như hoạt động tốt. Tuy nhiên, kết quả trả về không được sắp xếp và tôi muốn chúng được sắp xếp theo các thuật ngữ phân loại "event_location". Ví dụ:

* UK
  * Brighton
    * Sự kiện 1
    * Sự kiện 2
  * London
    * Sự kiện 3
* Châu Âu
  * Paris
    * Sự kiện 4

Tôi cũng muốn hiển thị chỉ các bài viết "event" chưa hết hạn và sắp xếp chúng theo "event_date". Giá trị "event_date" được lưu trữ dưới dạng giá trị siêu dữ liệu cùng với các chi tiết bài viết "event" khác dưới một meta_key duy nhất.

**Đây là mã của tôi cho đến nay:**

// Nhận các sự kiện phù hợp tùy thuộc vào loại trang: yoga/voice work

/* Nhận slug của các trang tổ tiên và trang hiện tại */
// Thu thập các trang tổ tiên
$relations = get_post_ancestors($post->ID);

// Thêm trang hiện tại vào các trang
array_push($relations, $post->ID);

// Nhận slug của các trang
$relations_slugs = array();
foreach ($relations as $page_ID) {
    $page = get_page($page_ID);
    array_push($relations_slugs, $page->post_name);
}

/* Nhận slug của các thuật ngữ (không rỗng) cho phân loại event_type */
// Nhận các giá trị phân loại event_type
$event_types = get_terms('event_type', 'hide_empty=true');
$event_types_slugs = array();
foreach ($event_types as $event_type) {
    array_push($event_types_slugs, $event_type->slug);
}

/* Tìm loại sự kiện nào để hiển thị trên trang hiện tại */
$page_event_types = array_intersect($relations_slugs, $event_types_slugs);
$page_event_types_string = implode(",", $page_event_types);

/* Tìm các sự kiện của loại sự kiện để hiển thị trên trang hiện tại */
$args = array(
    'post_type' => 'event',
    'tax_query' => array(
        array(
            'taxonomy' => 'event_type',
            'field' => 'slug',
            'terms' => $page_event_types_string
        )
    )
);

$temp = $wp_query; // Gán truy vấn ban đầu cho biến tạm để sử dụng sau này
$wp_query = null;
$wp_query = new WP_Query($args);

/* Chạy vòng lặp để đầu ra chi tiết sự kiện */
get_template_part('loop', 'event-details');

Tôi không giỏi xây dựng các câu lệnh SQL. Tôi sẽ rất cảm kích nếu bạn có thể giúp tôi. Cảm ơn bạn rất nhiều!!!

