* BackPress API thủ tục cho các phong cách.
*
* @package BackPress
* @since r79
*/
/**
* Hiển thị các phong cách đang trong hàng đợi hoặc là một phần của $handles.
*
* @since r79
* @uses do_action() Gọi móc 'wp_print_styles'.
* @global object $wp_styles Đối tượng WP_Styles để in các phong cách.
*
* @param array|bool $handles Các phong cách để in. Một mảng rỗng in hàng đợi,
* một mảng với một chuỗi in phong cách đó, và một mảng của các chuỗi in những phong cách đó.
* @return bool Đúng trên thành công, sai khi thất bại.
*/
hàm wp_print_styles( $handles = false ) {
nếu ( '' === $handles ) // cho wp_head
$handles = false;
nếu ( ! $handles )
do_action( 'wp_print_styles' );
global $wp_styles;
nếu ( ! is_a( $wp_styles, 'WP_Styles' ) ) {
nếu ( ! did_action( 'init' ) )
_doing_it_wrong( __FUNCTION__, sprintf( __( 'Các tập lệnh và phong cách không nên được đăng ký hoặc xếp hàng cho đến móc %1$s, %2$s, hoặc %3$s.' ),
'<code>wp_enqueue_scripts</code>', '<code>admin_enqueue_scripts</code>', '<code>init</code>' ), '3.3' );
nếu ( !$handles )
trả về mảng(); // Không cần phải thể hiện nếu không có gì ở đó.
khác
$wp_styles = new WP_Styles();
}
trả về $wp_styles->do_items( $handles );
}
/**
* Thêm CSS bổ sung.
*
* Chỉ hoạt động nếu bảng phong cách đã được thêm trước đó.
* Chấp nhận một chuỗi $data chứa CSS. Nếu hai hoặc nhiều khối mã CSS được
* thêm vào cùng một bảng phong cách $handle, chúng sẽ được in theo thứ tự
* chúng đã được thêm vào, nghĩa là các phong cách được thêm sau này có thể tuyên bố lại trước đó.
*
* @since 3.3.0
* @see WP_Scripts::add_inline_style()
*/
hàm wp_add_inline_style( $handle, $data ) {
global $wp_styles;
nếu ( ! is_a( $wp_styles, 'WP_Styles' ) ) {
nếu ( ! did_action( 'init' ) )
_doing_it_wrong( __FUNCTION__, sprintf( __( 'Các tập lệnh và phong cách không nên được đăng ký hoặc xếp hàng cho đến móc %1$s, %2$s, hoặc %3$s.' ),
'<code>wp_enqueue_scripts</code>', '<code>admin_enqueue_scripts</code>', '<code>init</code>' ), '3.3' );
$wp_styles = new WP_Styles();
}
trả về $wp_styles->add_inline_style( $handle, $data );
}
/**
* Đăng ký tệp phong cách CSS.
*
* @since r79
* @see WP_Styles::add() Để thông tin bổ sung.
* @global object $wp_styles Đối tượng WP_Styles để in các phong cách.
* @link http://www.w3.org/TR/CSS2/media.html#media-types Danh sách các loại phương tiện CSS.
*
* @param string $handle Tên của bảng phong cách.
* @param string|bool $src Đường dẫn đến bảng phong cách từ thư mục gốc của WordPress. Ví dụ: '/css/mystyle.css'.
* @param array $deps Mảng các xử lý mà bảng phong cách này phụ thuộc vào.
* (Các bảng phong cách phải được tải trước bảng phong cách này.) Truyền một mảng rỗng nếu không có phụ thuộc.
* @param string|bool $ver Chuỗi chỉ định số phiên bản bảng phong cách. Thiết lập thành null để vô hiệu hóa.
* Sử dụng để đảm bảo rằng phiên bản chính xác được gửi đến khách hàng bất kể lưu trữ.
* @param string $media Phương tiện mà bảng phong cách này đã được xác định.
*/
hàm wp_register_style( $handle, $src, $deps = array(), $ver = false, $media = 'all' ) {
global $wp_styles;
nếu ( ! is_a( $wp_styles, 'WP_Styles' ) ) {
nếu ( ! did_action( 'init' ) )
_doing_it_wrong( __FUNCTION__, sprintf( __( 'Các tập lệnh và phong cách không nên được đăng ký hoặc xếp hàng cho đến móc %1$s, %2$s, hoặc %3$s.' ),
'<code>wp_enqueue_scripts</code>', '<code>admin_enqueue_scripts</code>', '<code>init</code>' ), '3.3' );
