}
$wp_styles->add( $handle, $src, $deps, $ver, $media );
}
/**
* Xóa một tệp phong cách đã đăng ký.
*
* @since r79
* @see WP_Styles::remove() Để thông tin bổ sung.
* @global object $wp_styles Đối tượng WP_Styles để in các phong cách.
*
* @param string $handle Tên của bảng phong cách.
*/
hàm wp_deregister_style( $handle ) {
