function clearDuplicatePosts() {
    global $wpdb;
    $prefix = $wpdb->prefix;
    $wpdb->query("DELETE bad_rows.* FROM $prefixposts AS bad_rows INNER JOIN (
        SELECT $prefixposts.post_title, MIN($prefixposts.ID) AS min_id
        FROM $prefixposts
        GROUP BY post_title
        HAVING COUNT(*) > 1
    ) AS good_rows ON (good_rows.post_title = bad_rows.post_title AND good_rows.min_id <> bad_rows.ID)");
}

