Lọc yêu cầu meta Tôi đã có một trang web đa trang nơi tôi truy vấn các loại bài viết tùy chỉnh cụ thể từ một blog cụ thể. Nó trông như thế này:

function unify_results_filter( $input ) {
    global $wpdb;
    $blog_id = get_current_blog_id();
    $blog_source_id = '2';
    $db_source_prefix = str_replace($blog_id, $blog_source_id, $wpdb->prefix);

    // nếu blog không phải là 2 và loại bài viết là kết quả, truy vấn ID blog 2
    if ( strpos($input, "post_type = 'results'") !== false )
        $input = str_replace( $wpdb->posts, $db_source_prefix . 'posts', $input );

    return $input;
}

add_filter( 'posts_request', 'unify_results_filter' );

