function remove_menus () {     toàn cầu $menu;         $restricted = array(__('Dashboard'), __('Media'), __('Links'),      __('Appearance'), __('Tools'), __('Users'), __('Settings'), __('Profile'),__('Plugins'));         kết thúc ($menu);         trong khi (prev($menu)){             $value = explode(' ',$menu[key($menu)][0]);             nếu(in_array($value[0] != NULL?$value[0]:"" , $restricted)){unset($menu[key($menu)]);}         }     }     add_action('admin_menu', 'remove_menus');

