nhãn phân loại tùy chỉnh trong tiếng hebrew Tôi đang cố gắng thêm một phân loại tùy chỉnh sử dụng mã sau:

function cities_custom_taxonomies() {
    register_taxonomy(
        'city', // tên nội bộ = tên phân loại có thể đọc được trên máy
        'post', // loại đối tượng = bài viết, trang, liên kết hoặc loại bài viết tùy chỉnh
        array(
            'hierarchical' => false, // true cho phân cấp như danh mục, false cho dạng phẳng như thẻ
            'label' => 'City', // tên phân loại có thể đọc được bởi con người
            'query_var' => true, // bật truy vấn đặc thù phân loại
            'rewrite' => true // liên kết vĩnh viễn cho phân loại của bạn?
        )
    );
}
add_action('init', 'cities_custom_taxonomies', 0);

