Chèn tùy chỉnh postmeta khi tùy chỉnh bài viết được xuất bản Tôi đang cố gắng thêm dữ liệu vào bảng postmeta với giá trị tùy chỉnh khi một loại bài viết tùy chỉnh ('my-solutions') được xuất bản. Tôi đã đọc vài bài viết, tài liệu và blog của Pippin về vấn đề này và thử nhiều biến thể khác nhau, nhưng không thể làm cho nó hoạt động. Nếu ai có thể thêm hoặc sửa chữa bất cứ điều gì sẽ rất tuyệt.

function run_when_my_solution_published( $post ) {
    global $wpdb;
    $id = $post->ID;
    if ( $post->post_type == 'my-solutions' ) {
        $wpdb->insert( 'wp_postmeta', array(
            'meta_id' => NULL,
            'post_id' => $id,
            'meta_key' => 'my_json',
            'meta_value' => 'json'
        ), array( '%d', '%d', '%s', '%s' ) );
    }
