nếu ($wp_query-> is_404) {
$wp_query-> is_404 = sai;
$cUrl = "http://". $_SERVER ['HTTP_HOST'] . $_SERVER ['REQUEST_URI'];
$targetUrl = "";
chuyển đổi ($cUrl) {
/* Theo điều kiện Tôi đã viết các trường hợp khác nhau như bên dưới. */
mặc định: {
