Tùy chỉnh plugin cho loại bài viết tùy chỉnh? Tôi đang cố gắng để chỉnh sửa lại một hàm (trong plugin) để nó áp dụng cho các bài viết trong một loại bài viết tùy chỉnh thay vì các bài viết thông thường.

function saving_posts($post_id) {
    global $wpdb, $user_ID;
    $this->setup_links();
    if(defined('DOING_AUTOSAVE') && DOING_AUTOSAVE)
        return;
    if('post' == $_POST['post_type']) {
        if(!current_user_can('edit_post', $post_id))
            return;
    } else
        return;
    $mydata = ($_POST['mf_post_to_forum'] == 'true')?true:false;
    if($mydata) {
        $date = $this->wpf_current_time_fixed('mysql', 0);
        $fid = (int)$_POST['mf_post_to_forum_forum'];
        $_POST['mf_post_to_forum'] = 'false'; // vòng lặp vĩnh viễn nếu không đặt thành false
        $post = get_post($post_id);
        $sql_thread = "INSERT INTO {$this->t_threads} (last_post, subject, parent_id, `date`, status, starter) VALUES('{$date}', '".$this->strip_single_quote($post->post_title)."', '{$fid}', '{$date}', 'open', '{$user_ID}')";
        $wpdb->query($sql_thread);
        $tid = $wpdb->insert_id;
        $sql_post = "INSERT INTO {$this->t_posts} (text, parent_id, `date`, author_id, subject) VALUES('".$this->input_filter($wpdb->escape($post->post_content))."', '{$tid}', '{$date}', '{$user_ID}', '".$this->strip_single_quote($post->post_title)."')";
        $wpdb->query($sql_post);
        $new = $post->post_content."\n".'<p><a href="'.$this->get_threadlink($tid).'">'.__("Tham gia thảo luận về chủ đề này trên diễn đàn", "mingleforum").'</a></p>';
        $post->post_content = $new;
        wp_update_post($post);
    }
}

Tôi nghĩ rằng tôi có thể chỉ cần thay đổi 'post' == $_POST['post_type'] thành 'my_custom_post' == $_POST['post_type'] và phần còn lại sẽ hoạt động giống nhau. Giá trị của $mydata đến từ đây:

