<?php }
}
Tôi đã thử lấy hình thu nhỏ bằng cách sử dụng meta **_thumbnail_id**. Kết quả tương tự. Mã này được đặt trong tệp chức năng, tôi tin rằng vấn đề là nó đang cố gắng lấy hình ảnh nổi bật của vòng lặp/bài viết. Cảm ơn bạn trước.

Ẩn menu tùy chỉnh khi không có menu nào được chọn Tiêu đề có thể không chính xác 100%, vui lòng chỉnh sửa nếu cần... Tôi đang xây dựng một chủ đề tùy chỉnh có một vài vị trí chủ đề cho các menu (1 menu chính, 1 menu chân trang, 1 nút "Theo dõi trực tiếp"). Chúng được chỉ định là Vị trí Chủ đề trong bảng điều khiển Menu. Tôi gặp vấn đề với menu chân trang: khi vị trí chủ đề đó không có menu được chọn, nó sẽ hiển thị tất cả các trang. Tôi muốn nó không hiển thị gì khi không được liên kết với menu. Menu được định nghĩa trong functions.php như sau:

add_action('init', 'add_footer');

add_footer() {
    register_nav_menus(
        array('footer-menu' => __('Footer Navigation'),));
}

Và nó được hiển thị trên trang như sau:

<?php
wp_nav_menu( array(
    'theme_location' => 'footer-menu',
    'menu_class' => 'false',
    'container' => 'false',
    'fallback_cb' => 'wp_page_menu',
));
?>

Tôi đã thử xóa tùy chọn fallback_cb nhưng điều đó không giúp ích.

Có thể thêm một hành động vào hành động đang chạy không? Câu hỏi của tôi rất đơn giản nhưng tôi chưa tìm được câu trả lời cho nó. Dưới đây là ví dụ:

class MyClass {
    public function __construct(){
        add_action('init', array($this, 'init'));
        add_action('wp_footer', array($this, 'footer'));
    }

    public function init(){
        add_action('init', array($this, 'register_scripts'));
    }

    public function register_scripts(){
        wp_register_script('my-script', plugins_url('/script.js', __FILE__));
    }

    public function footer(){
        echo('<div class="style-me">Rawr this is my plugin.</div>');
    }
}

Đây là mã code của tôi và nó không hoạt động. Nó hiển thị div nhưng JavaScript không được áp dụng. Vì vậy tôi tự hỏi liệu vấn đề có phải là chạy hàm `init()` trong hành động init và sau đó thêm `register_scripts()` vào hành động init hay không, mặc dù tôi đã thực hiện hành động đó rồi. Điều này có thể không?

WordPress SimplePie sửa đổi Tôi đang sử dụng hàm fetch_feed() được cung cấp trong WordPress để tạo đối tượng SimplePie. Mã từ WP là như sau:

function fetch_feed($url) {
    require_once (ABSPATH . WPINC . '/class-feed.php');

    $feed = new SimplePie();

    $feed->set_sanitize_class( 'WP_SimplePie_Sanitize_KSES' );

    // Chúng ta phải ghi đè lên $feed->sanitize một cách thủ công vì hàm tạo của SimplePie thiết lập nó trước khi chúng ta có cơ hội thiết lập lớp khử trùng.
    $feed->sanitize = new WP_SimplePie_Sanitize_KSES();

    $feed->set_cache_class( 'WP_Feed_Cache' );

    $feed->set_file_class( 'WP_SimplePie_File' );

    $feed->set_feed_url($url);

    $feed->set_cache_duration( apply_filters( 'wp_feed_cache_transient_lifetime', 12 * HOUR_IN_SECONDS, $url ) );

    do_action_ref_array( 'wp_feed_options', array( &$feed, $url ) );

    $feed->init();

    $feed->handle_content_type();

    if ( $feed->error() )
        return new WP_Error('simplepie-error', $feed->error());

    return $feed;
}

Làm thế nào tôi có thể thay đổi các thẻ HTML bị xóa bỏ trong quá trình nhập feed? SimplePie trong tài liệu nói rằng có một hàm strip_htmltags(), nhưng tôi không biết làm thế nào để sử dụng nó trong ngữ cảnh của WordPress. Đây là đoạn mã tôi đã thử nhưng không hoạt động:

function wpse87359_feed_options( $feed) {
    $feed->strip_htmltags(array_merge($feed->strip_htmltags, array('h1', 'a', 'img','em')));
}

add_action( 'wp_feed_options', 'wpse87359_feed_options' );

