Tự động thêm trang vào menu phân loại Tôi đã tạo ra một loại bài viết tùy chỉnh được gọi là Sản phẩm, trên trang sản phẩm tôi có một menu trong thanh bên trái. Menu này được tạo thành từ các danh mục của sản phẩm. Liệu có khả năng cho sản phẩm của tôi tự động thêm vào menu danh mục dựa trên danh mục của sản phẩm không? Ví dụ: tôi tạo một sản phẩm, tôi đặt cho nó một danh mục là màu xanh. Khi màu xanh xuất hiện trong menu thì sản phẩm sẽ tự động được thêm vào bên dưới màu xanh. Điều đó có khả thi không? Cảm ơn Cập nhật: Để rõ hơn thì tôi đang sử dụng một plugin gọi là Jquery Accordion Menu và menu sử dụng một widget. Nó vẫn sử dụng hệ thống menu tích hợp của WordPress. Widget Jquery Accordion chỉ định kiểu cho menu, trong cài đặt widget bạn chọn menu nào bạn muốn nó hiển thị. Tôi đã tìm thấy mã này bên trong tập tin plugin sau những bình luận bên dưới. Tôi không biết liệu nó có hữu ích gì không.

function widget($args, $instance) {
    extract( $args );
    // Get menu
    if(! isset($instance['speed']) ){
        $instance['speed'] = 'slow';
    }
    $widget_options = wp_parse_args( $instance, $this->defaults );
    extract( $widget_options, EXTR_SKIP );
    $nav_menu = wp_get_nav_menu_object( $instance['nav_menu'] );
    if (!$nav_menu)
        return;
    $instance['title'] = apply_filters('widget_title', $instance['title'], $instance, $this->id_base);
    $classMenu = ($instance['classMenu'] != '') ? $instance['classMenu'] : 'menu';
    echo $args['before_widget'];
    if ( !empty($instance['title']) )
        echo $args['before_title'] . $instance['title'] . $args['after_title'];
    ?>
    <div class="dcjq-accordion" id="<?php echo $this->id.'-item'; ?>">
        <?php
        wp_nav_menu(
            array(
                'fallback_cb' => '',
                'menu' => $nav_menu,
                'container' => false,
                'menu_class' => $classMenu
            )
        );
        ?>
    </div>
    <?php
    echo $args['after_widget'];
}

