function save_title_meta($post_id, $post) {
// xác minh rằng nó đến từ màn hình của chúng tôi và với quyền ủy quyền thích hợp,
// vì save_post có thể được kích hoạt vào những thời điểm khác
if ( !wp_verify_nonce( $_POST['meta_noncename'], plugin_basename(__FILE__) )) {
return $post->ID;
}

// Người dùng có được phép chỉnh sửa bài viết hoặc trang không?
if ( !current_user_can( 'edit_post', $post->ID ))
return $post->ID;

// OK, chúng tôi đã được xác thực: chúng tôi cần tìm và lưu dữ liệu
// Chúng tôi sẽ cho nó vào một mảng để dễ dàng lặp qua.
$project_meta['_title'] = $_POST['_title'];

// Thêm các giá trị của $project_meta làm trường tùy chỉnh
foreach ($project_meta as $key => $value) { // Lặp qua mảng $project_meta!
if( $post->post_type == 'revision' ) return; // Không lưu dữ liệu tùy chỉnh hai lần
$value = implode(',', (array)$value); // Nếu $value là một mảng, hãy biến nó thành CSV (hiếm khi xảy ra)
if(get_post_meta($post->ID, $key, FALSE)) { // Nếu trường tùy chỉnh đã có giá trị
update_post_meta($post->ID, $key, $value);
} else { // Nếu trường tùy chỉnh chưa có giá trị
add_post_meta($post->ID, $key, $value);
}
if(!$value) delete_post_meta($post->ID, $key); // Xóa nếu trống
}
}

