get_var result trống cho truy vấn của bảng tùy chỉnh trong plugin quản trị viên Tôi đang sử dụng một plugin tùy chỉnh cho một trang web đa miền và đang cố gắng truy vấn một bảng tùy chỉnh từ plugin đó, nhưng get_var trả về giá trị rỗng. Tôi đã thử cả get_row và get_results cũng trả về giá trị rỗng. Đây là một nút xuất bản/không xuất bản trong phần quản trị của trang con sử dụng jquery/ajax. Hàm xuất bản hoạt động, tạo một bài viết mới trong blog của người dùng trang con và chèn ID bài viết, ID blog và mã duy nhất vào bảng tùy chỉnh. Hàm không xuất bản cũng hoạt động khi tôi có thể xóa đúng dòng từ bảng tùy chỉnh. Tuy nhiên, vấn đề là trong hàm không xuất bản, trước khi xóa dòng từ bảng tùy chỉnh, tôi cần lấy ID bài viết và xóa bài viết khỏi blog của người dùng trang con, nhưng truy vấn get_var cho ID bài viết trả về giá trị rỗng. Dưới đây là một phần liên quan của hàm không xuất bản, hiển thị truy vấn get_var và xóa đúng dòng, cùng với các kiểm tra print_r ở cuối:

global $wpdb;
$customtable = $wpdb->$table_prefix.'customtable'; // hoạt động cho $wpdb->delete nhưng không hoạt động cho $wpdb->get_var
$user_blog_id = get_current_blog_id(); // hoạt động
$uniquecode = $_POST[uniquecode]; // hoạt động thông qua jquery-ajax, giá trị được lấy từ cơ sở dữ liệu bên ngoài
$post_id = $wpdb->get_var($wpdb->prepare('SELECT post_id FROM '.$customtable.' WHERE uniquecode = '.$uniquecode.' AND blog_id = '.$user_blog_id.'')); // không hoạt động, trả về giá trị rỗng
wp_delete_post ($post_id, true); // $post_id = $wpdb->get_var trả về giá trị rỗng, ngăn wp_delete_post hoạt động
$wpdb->delete( $customtable, array // hoạt động - xóa dòng từ $customtable
(
'blog_id'=>$user_blog_id,
'uniquecode'=>$uniquecode
),
array('%d','%s')
);
echo 'Post ID#';
