// Lưu dữ liệu meta cho loại bài viết Project
function save_project_meta($post_id) {
    if (!isset($_POST['project_meta_box_nonce']) || !wp_verify_nonce($_POST['project_meta_box_nonce'], basename(__FILE__))) {
        return;
    }

    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
        return;
    }

    if (!current_user_can('edit_post', $post_id)) {
        return;
    }

    // Kiểm tra quyền truy cập
    if ('page' == $_POST['post_type']) {
        if (!current_user_can('edit_page', $post_id)) {
            return;
        }
    }

    // Làm sạch dữ liệu đầu vào của người dùng
    $project_meta = array();
    if (isset($_POST['start'])) {
        $project_meta['start'] = sanitize_text_field($_POST['start']);
    }
    if (isset($_POST['mainimage'])) {
        $project_meta['mainimage'] = sanitize_text_field($_POST['mainimage']);
    }

    // Lưu dữ liệu meta
    update_post_meta($post_id, 'project_meta', $project_meta);
}
add_action('save_post', 'save_project_meta');

// Lưu dữ liệu meta cho loại bài viết Product
function save_product_meta($post_id) {
    if (!isset($_POST['product_meta_box_nonce']) || !wp_verify_nonce($_POST['product_meta_box_nonce'], basename(__FILE__))) {
        return;
    }

    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
        return;
    }

    if (!current_user_can('edit_post', $post_id)) {
        return;
    }

    // Kiểm tra quyền truy cập
    if ('page' == $_POST['post_type']) {
        if (!current_user_can('edit_page', $post_id)) {
            return;
        }
    }

    // Làm sạch dữ liệu đầu vào của người dùng
    $product_meta = array();
    if (isset($_POST['start'])) {
        $product_meta['start'] = sanitize_text_field($_POST['start']);
    }
    if (isset($_POST['google_checkout'])) {
        $product_meta['google_checkout'] = sanitize_text_field($_POST['google_checkout']);
    }

    // Lưu dữ liệu meta
    update_post_meta($post_id, 'product_meta', $product_meta);
}
add_action('save_post', 'save_product_meta');
