Cách xóa dữ liệu người dùng mồ côi từ mảng trong wp-options Tôi có một tùy chọn đăng ký thành viên vào thông báo email của diễn đàn. Danh sách email được lưu trong một mảng như giá trị tùy chọn. Tất cả đều hoạt động tốt và việc đăng ký và hủy đăng ký đều được thực hiện bằng `update_option();` Vấn đề của tôi là nếu một người dùng bị xóa, sẽ khó để hủy đăng ký anh ta mà không cần truy cập vào cơ sở dữ liệu. Vì vậy tôi nghĩ rằng hàm này sẽ xử lý vấn đề nhưng tôi đã bỏ lỡ điều gì đó:

add_action( 'delete_user', 'forum_remove_deleted_user' );

function forum_remove_deleted_user($user_id)
{
    $user_obj = get_userdata($user_id);
    $subscbr_email = $user_obj->user_email;

    if(!empty($subscbr_email)) {
        $list = (array)get_option('mf_forum_subscribers_1');

        if(!empty($list) && is_subscribed($subscbr_email)) {
            $key = array_search($subscbr_email, $list);
            unset($list[$key]);
        }
    }
}

function is_subscribed($subscbr_email)
{
    if($subscbr_email)
    {
        $list = (array)get_option('mf_forum_subscribers_1');

        if(in_array($subscbr_email , $list)) {
            return true;
        }
        return false;
    }
}

