            if($ff != '.' && $ff != '..') {
                echo '<li>'.$ff;
                if(is_dir($dir.'/'.$ff))
                    listFolderFiles($dir.'/'.$ff);
                echo '</li>';
            }
        }
        echo '</ol>';
    }
}

