AJAX - Trả về 2 đối tượng JSON với một hàm PHP Làm thế nào để trả về hai đối tượng JSON với một cuộc gọi AJAX và hàm PHP? Tôi rất cảm kích nếu có ai giúp tôi. Đây là hàm PHP:

function get_ldap_attr() {
    header("Content-type: application/json");
    $lan = $_POST['lan'];
    $dn = get_site_option ( "ldapServerOU" );
    $usr = get_site_option ( "ldapServerCN" );
    $pw = get_site_option ( "ldapServerPass" );
    $addr = get_site_option ( "ldapServerAddr" );
    $ad = ldap_connect ( $addr ) or die ( "Connection error." );
    ldap_set_option ( $ad, LDAP_OPT_PROTOCOL_VERSION, 3 );
    ldap_set_option ( $ad, LDAP_OPT_REFERRALS, 0 );
    $bind = ldap_bind ( $ad, $usr, $pw );
    if ( $bind ) {
        $SearchFor ="cn=".$lan;
        $result = ldap_search ( $ad,$dn,$SearchFor );
        $entry = ldap_first_entry ( $ad, $result );
        if ( $entry != false ) {
            $info = ldap_get_attributes ( $ad, $entry );
        }
        $comm  = stripos ( $info['manager'][0], ',' ); // tìm vị trí của dấu phẩy đầu tiên trong CN=Mxxxxxx,OU=Users,OU=MCR,DC=mfad,DC=mfroot,DC=org (trường directReports)
        $eq = stripos ( $info['manager'][0], '=' ); // tìm vị trí của dấu bằng đầu tiên
        $s_lanid = substr ( $info['manager'][0], $eq+1, ( ( $comm-1 ) - ( $eq ) ) ); // lấy chuỗi giữa dấu bằng và dấu phẩy... để lanid hạnh phúc..
        $sup = getLDAPInfo ( $s_lanid, $bind, $ad, $dn ); // lấy thông tin của người giám sát...
    }
    echo json_encode($sup);
    die();
}

