function my_meta_setup()
{
global $post;
$meta = get_post_meta($post->ID,'_my_meta',TRUE);
include(MY_THEME_FOLDER . '/meta.php');
echo '<input type="hidden" name="my_meta_noncename" value="' . wp_create_nonce(__FILE__) . '" />';
}

function my_meta_save($post_id)
{
if (!wp_verify_nonce($_POST['my_meta_noncename'],__FILE__)) return $post_id;
if ($_POST['post_type'] == 'page')
{
if (!current_user_can('edit_page', $post_id)) return $post_id;
}

$current_data = get_post_meta($post_id, '_my_meta', TRUE);
$new_data = $_POST['_my_meta'];
my_meta_clean($new_data);

if ($current_data)
{
if (is_null($new_data)) delete_post_meta($post_id,'_my_meta');
else update_post_meta($post_id,'_my_meta',$new_data);
}
elseif (!is_null($new_data))
{
add_post_meta($post_id,'_my_meta',$new_data,TRUE);
}
return $post_id;
}

function my_meta_clean(&$arr)
{
if (is_array($arr))
{
foreach ($arr as $i => $v)
{
if (is_array($arr[$i]))
{
my_meta_clean($arr[$i]);
if (!count($arr[$i]))
{
unset($arr[$i]);
}
}
else
{
if (trim($arr[$i]) == '')
{
unset($arr[$i]);
}
}
}
if (!count($arr))
{
$arr = NULL;
}
}
}

Bạn có thể giúp tôi hiểu vấn đề này không? Tôi không thể tìm ra nguyên nhân và điều này khiến tôi rất thất vọng. Mã không thay đổi chút nào, đầu ra của hộp meta của tôi nằm trong một file php khác trong thư mục gốc của chủ đề, không có gì thay đổi thực sự. Điều duy nhất tôi nghĩ đến là khi phát triển trang web trên một subdomain, khi tôi sao chép các tập tin sang thư mục gốc, tôi không tạo một cơ sở dữ liệu mới vì tôi không cần và đã sử dụng cơ sở dữ liệu cũ và sau đó sử dụng một plugin để thay đổi tất cả các URL. Và sau đó tôi đã sử dụng một plugin để tìm kiếm và thay thế các giá trị URL trong cơ sở dữ liệu, nhưng điều này xảy ra trước khi thay đổi cơ sở dữ liệu. Tôi không thể nghĩ ra cách giải quyết vấn đề này. Khi tôi chỉnh sửa hộp meta ở backend, tôi không gặp lỗi nào, bài viết/trang được cập nhật, nhưng rõ ràng cơ sở dữ liệu không lưu trữ các giá trị mới và sau khi chỉnh sửa các trường trống. Đây là những gì tôi có trong meta.php:

