Xóa site và người dùng tự động trong multisite Tôi đang cố gắng tạo một chức năng xóa các trang web và người dùng của họ trong WordPress đa trang. Mã tôi viết thành công trong việc xóa các trang web nhưng không phải người dùng, ai có thể cung cấp một giải pháp?

<?php
register_activation_hook( __FILE__, 'wpchat_clear_sites_activation' );

/**
* Khi kích hoạt, thiết lập thời gian, tần suất và tên của một hook hành động để được lên lịch.
*/
function wpchat_clear_sites_activation() {
    wp_schedule_event( 1386979200, 'daily', 'daily_clear_sites_hook' );
}

add_action( 'daily_clear_sites_hook', 'wpchat_clear_out_sites_daily' );

/**
* Xóa tất cả các trang web và người dùng
*/
function wpchat_clear_out_sites_daily() {
    require_once( ABSPATH . 'wp-admin/includes/admin.php' );
    require_once( ABSPATH . 'wp-admin/includes/user.php' );

    if( ! function_exists( 'wpmu_delete_blog' ) ) return;

    $users_to_keep = array( '1','4','43' );
    $blogs_to_keep = array( '1','4' );

    $all_sites = wp_get_sites();

    // Xóa tất cả các blog ngoại trừ blog chính và blog mẫu
    foreach ( $all_sites as $key => $val ) {
        $users = get_users( array( 'blog_id' => $val['blog_id'], 'fields' => ID ) );

        // Xóa tất cả người dùng ngoại trừ quản trị viên trang thử nghiệm
        foreach ( $users as $user) {
            if ( ! in_array( $user['ID'], $users_to_keep ) ) {
                wpmu_delete_user( $user['ID'] );
            }
        }

        if ( ! in_array( $val['blog_id'], $blogs_to_keep ) ) {
            wpmu_delete_blog( $val['blog_id'], true );
        }
    }
}

Các trang web được xóa thông qua cron hoặc gọi trực tiếp hàm, vì vậy cron không phải là vấn đề ở đây, nó là cách tôi đang cố gắng xóa người dùng.

