function remove_menus() {
  global $menu;
  global $current_user;
  get_currentuserinfo();

  if($current_user->user_login != 'admin') {
    $restricted = array(__('Posts'),
      __('Media'),
      __('Links'),
      __('Pages'),
      __('Comments'),
      __('Appearance'),
      __('Plugins'),
      __('Users'),
      __('Tools'),
      __('Settings')
    );

    end($menu);
    while (prev($menu)) {
      $value = explode(' ',$menu[key($menu)][0]);
      if(in_array($value[0] != NULL?$value[0]:"" , $restricted)) {unset($menu[key($menu)]);}
    }// end while
  }// end if
}

