Trong khi tìm kiếm trên Google, tôi đã tìm thấy nhiều bài viết, vấn đề:

* Permalinks 404 với Custom Post Type

* Custom Permalinks cho Custom Post Types trong WordPress 3.0+

* custom post type với post_id trong cấu trúc permalink nhưng gần như đã lãng phí 4 tiếng đồng hồ cuộc sống của tôi sau đó sau khi hoàn thành nghiên cứu và phát triển cuối cùng tôi đã tìm thấy

* Custom Post Type Permalinks mà có thể chuyển đổi permalink của bài viết của tôi theo yêu cầu của tôi nhưng nếu tôi truy cập vào liên kết đó tôi nhận được lỗi 404. Đây là đoạn mã được sửa đổi phù hợp nhất với mã trên của tôi:

// Thêm bộ lọc vào hàm plugin init

add_filter('post_type_link', 'gallery_permalink', 10, 3);

// Được chuyển đổi từ hàm get_permalink trong wp-includes/link-template.php

function gallery_permalink($permalink, $post_id, $leavename) {
    $post = get_post($post_id);

    $rewritecode = array(
        '%year%',
        '%monthnum%',
        '%day%',
        '%hour%',
        '%minute%',
        '%second%',
        $leavename? '' : '%postname%',
        '%post_id%',
        '%category%',
        '%author%',
        $leavename? '' : '%pagename%',
    );

    if ( '' != $permalink && !in_array($post->post_status, array('draft', 'pending', 'auto-draft')) ) {
        $unixtime = strtotime($post->post_date);
        $category = '';

        if ( strpos($permalink, '%category%') !== false ) {
            $cats = get_the_category($post->ID);

            if ( $cats ) {
                usort($cats, '_usort_terms_by_ID'); // sắp xếp theo ID
                $category = $cats[0]->slug;

                if ( $parent = $cats[0]->parent )
                    $category = get_category_parents($parent, false, '/', true) . $category;
            }

            // hiển thị danh mục mặc định trong permalinks, mà không cần phải gán nó một cách rõ ràng
            // nếu rỗng
            if ( empty($category) ) {
                $default_category = get_category( get_option( 'default_category' ) );
                $category = is_wp_error( $default_category ) ? '' : $default_category->slug;
            }
        }

        $author = '';

        if ( strpos($permalink, '%author%') !== false ) {
            $authordata = get_userdata($post->post_author);
            $author = $authordata->user_nicename;
        }

        $date = explode(" ",date('Y m d H i s', $unixtime));

        $rewritereplace =
            array(
                $date[0],
                $date[1],
                $date[2],
                $date[3],
                $date[4],
                $date[5],
                $post->post_name,
                $post->ID,
                $category,
                $author,
                $post->post_name,
            );

        $permalink = str_replace($rewritecode, $rewritereplace, $permalink);
    } else { // nếu họ không sử dụng tùy chọn permalink đẹp mắt
    }

    return $permalink;
}

