function my_content_filter() {
    global $post;
    $mykeyword = 'find this phrase';
    $post->post_content = preg_replace_callback("/\b($mykeyword)\b/","doReplace", $post->post_content);
}

// Hàm callback
function doReplace($matches) {
    static $count = 0;
    switch($count++) {
        case 0: return '<b>'.$matches[1].'</b>'; // Trường hợp đầu tiên, bọc trong chữ đậm
        case 1: return '<em>'.$matches[1].'</em>'; // Trường hợp thứ hai, bọc trong chữ nghiêng
        case 2: return '<u>'.$matches[1].'</u>'; // Trường hợp thứ ba, bọc trong gạch chân
        default: return $matches[1]; // Không thay đổi những trường hợp khác.
    }
}

