Sử dụng thư mục tải lên riêng cho tải lên đính kèm bài viết tùy chỉnh Vậy, tôi đang cố tìm cách sử dụng hai thư mục tải lên riêng biệt, là mặc định một `wp-content/uploads` cho các bản tải lên phương tiện truyền thông chung, và một thứ hai nói `wp-content/custom` cho một loại đính kèm cụ thể (tệp PDF đính kèm với một post_type cụ thể). Điều đó rất quan trọng để giữ chúng tách biệt cả về tổ chức và bảo mật dữ liệu vì các tệp PDF sẽ chứa dữ liệu nhạy cảm mà chỉ nên được truy cập bởi hai vai trò người dùng tùy chỉnh, trong khi phương tiện truyền thông chung thì, tốt thôi. Tôi có chút bối rối khi cho bạn thấy mã tôi đã vận hành, bởi nó thật tệ, nhưng đây là nó:

function custom_post_type_metabox_save_function($post_id) {
    global $post;

    // Xác minh tự động lưu, các nonce, quyền và v.v... sau đó:
    update_post_meta($post_id, "meta_key1", $_POST["value1"]);
    update_post_meta($post_id, "meta_key2", $_POST["value2"]);

    // Đây là nơi nó trở nên khó khăn. Tôi thay đổi 'upload_path' thành mong muốn của tôi cho loại bài viết này
    update_option('upload_path', 'wp-content/custom-upload-dir');

    // sau đó tải tệp lên nó
    wp_upload_bits($_FILES["pdfexame"]["name"], null, file_get_contents($_FILES["pdfexame"]["tmp_name"]));

    // và sau đó thay đổi nó lại thành mặc định... :$
    update_option('upload_path', '');
}
add_action('save_post', 'custom_post_type_metabox_save_function');

