Xóa hình ảnh từ post_content khi lưu bài viết Tôi đang cố gắng thiết lập một hàm trong functions.php để xóa hình ảnh khỏi post_content khi lưu bài viết. Mọi thứ hoạt động tốt cho đến khi tôi cố gắng lưu nội dung, trang chỉ treo và tôi nhận được lỗi '500 Internal Server'.

function remove_post_image( $post_ID ){
    // lấy bài viết
    $the_post = get_post($post_ID);
    // lấy nội dung bài viết
    $post_content = $the_post->post_content;
    // thay thế bất kỳ hình ảnh nào
    $content = preg_replace("/<img[^>]+\>/i", "", $post_content);
    // lưu bài viết
    $my_post = array();
    $my_post['ID'] = $post_ID;
    $my_post['post_content'] = $content;
    // Cập nhật bài viết vào cơ sở dữ liệu
    wp_update_post( $my_post );
    return $post_ID;
}
add_action('save_post', 'remove_post_image');

