Tôi đang cố gắng mở rộng phạm vi của thuật toán tìm kiếm mặc định của WP. Tôi đang làm sai điều gì? Tôi biết rằng có một plugin sẽ làm điều này, nhưng nó quá rộng so với những gì tôi muốn thêm vào. Dưới đây là lần thử đầu tiên của tôi để mở rộng tìm kiếm để truy vấn các trường tùy chỉnh, nhưng nó không trả về kết quả nào. Tôi đã viết mã trong quá khứ để tạo ra các truy vấn, nhưng đây là lần đầu tiên tôi cố gắng sửa đổi một truy vấn hiện có và tôi rõ ràng đang bỏ lỡ điều gì đó.

function st_search_all( $query ) {
    if ( $query->is_search ) {
        $query->set( 'post_type', array( 'page', 'attachment', 'post' ) );
        $query->set( 'post_status', 'inherit' );
        $query->set( 'meta_query', array(
            array(
                'key'       => '_st_plaintext',
                'value'     => "{$query->get('s')}",
                'compare'   => 'LIKE'
            ),
            array(
                'key'       => 'Training Classes',
                'value'     => "{$query->get('s')}",
                'compare'   => 'LIKE'
            ),
            array(
                'key'       => 'External Content',
                'value'     => "{$query->get('s')}",
                'compare'   => 'LIKE'
            )
        ) );
    }
    return $query;
}

add_filter( 'pre_get_posts', 'st_search_all' );

