<?php

class WP_PM {
public $currentId;

public function __construct() {
$this->addActions();
$this->showId();
}

private function addActions() {
add_action('wp_loaded', array(&$this, 'getId'));
}

public function getId() {
global $current_user;

$this->currentId = $current_user->ID;
//$this->currentId = 'hello'; // chúng ta có một kết quả
echo $this->currentId; // chúng ta có một kết quả
return $this->currentId;
}

public function showId() {
echo $this->currentId; // không có kết quả
echo $this->getId(); // không có kết quả
}

}

