function yoursite_posts_where($where,$query) {
    global $wpdb;
    $new_where = " TRIM(IFNULL({$wpdb->postmeta}.meta_value,''))<>'' ";
    if (empty($where))
        $where = $new_where;
    else
        $where = "{$where} AND {$new_where} AND post_date > '" . date('Y-m-d', strtotime('-5 days')) . "'";
