function ks_meta_box_callback( $post ) {
    global $post;
    $values = get_post_custom( $post->ID );
    $check = isset( $values['full_width_post'] ) ? esc_attr( $values['full_width_post'][0] ) : '';
    wp_nonce_field( 'ks_meta_box_nonce', 'meta_box_nonce' );

