        <label><input type="checkbox" name="share_buttons" value="open" <?php checked($post->share_buttons, 'open'); ?> /> <?php _e( 'Show Share Buttons.' ) ?></label><br />
        <label><input type="checkbox" name="author_box" value="open" <?php checked($post->author_box, 'open'); ?> /> <?php _e( 'Show Author Information.' ) ?></label>
    </p>
    <?php
}

add_action( 'save_post', 'wpsb_meta_box_save' );

function wpsb_meta_box_save( $post_id ) {
    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
        return $post->ID;
    }

    if( !isset( $_POST['meta_box_nonce'] ) || !wp_verify_nonce( $_POST['meta_box_nonce'], 'ks_meta_box_nonce' ) ) return;

    if( !current_user_can( 'edit_post' ) ) return;

    $chk = ( isset( $_POST['full_width_post'] ) && $_POST['full_width_post'] ) ? 'on' : 'off';

    update_post_meta( $post_id, 'full_width_post', $chk );

    update_post_meta( $post_id, "share_buttons", $_POST["share_buttons"] );

    update_post_meta( $post_id, "author_box", $_POST["author_box"] );
}

