Đếm hình ảnh trong bài viết sau đó thêm class nếu chỉ có một Tôi đang cố gắng thêm một chức năng vào trang web của tôi để đếm số lượng hình ảnh đính kèm với một bài viết, và nếu chỉ có một hình ảnh, thêm một lớp cho thẻ <img> hoặc cho thẻ <a> bao chứa nó. Tôi nghĩ mình đã khá gần với mục tiêu, nhưng chưa đủ kỹ năng PHP để hoàn thành. Mã mà tôi đã ghép lại từ nhiều chủ đề khác nhau là:

/**
* Bài viết có một hình ảnh sẽ nhận được tên lớp riêng biệt
*/
add_filter( 'the_content', 'single_image_content_filter', 20 );

// Đếm hình ảnh trong bài viết
function single_image_content_filter( $content ) {
$attachments = get_children(array('post_parent'=>$post->ID));
$imgcount = count($attachments);

// Nếu chỉ có một hình ảnh đính kèm, thêm một lớp CSS mới
if ( $imgcount === 1 ) {
global $post;
$classes = 'single-img'; // cách nhau bằng dấu cách, ví dụ như 'img image-link'

// Kiểm tra xem có lớp nào được gán cho thẻ neo hay không, và/hoặc thêm một lớp thông qua $classes
if ( preg_match('/<a.*? class=".*?">/', $content) ) {
$content = preg_replace('/(<a.*? class=".*?)(".*?>)/', '$1 ' . $classes . '$2', $content);
} else {
$content = preg_replace('/(<a.*?)>/', '$1 class="' . $classes . '" >', $content);
}

return $content;
}
}

