function tdd_add_rewrite_rules() {
    global $wp_rewrite;
    $wp_rewrite->add_rewrite_tag('%listing%', '([^/]+)', 'listing=');
    $wp_rewrite->add_rewrite_tag('%VARIABLE1%', '([^/]+)', 'VARIABLE1=');
    $wp_rewrite->add_permastruct('listing', '/%VARIABLE1%/%listing%', false);
}

function tdd_permalinks($permalink, $post, $leavename) {
    global $post;
    $no_data = 'no-data';
    $post_id = $post->ID;
    if ($post->post_type != 'listing' || empty($permalink) || in_array($post->post_status, array('draft', 'pending', 'auto-draft'))) {
        return $permalink;
    }
    $var1 = get_post_meta($post_id, 'city', true);
    $var1 = sanitize_title($var1);
    if (!$var1) {
        $var1 = $no_data;
    }
    $permalink = str_replace('%VARIABLE1%', $var1, $permalink);
    return $permalink;
}

