      <?php
      // Chọn tất cả các ID của thẻ bài viết
      $the_tags = $wpdb->get_col("SELECT term_id
      FROM $wpdb->term_taxonomy WHERE taxonomy = 'post_tag'" );

      // Vòng lặp qua mỗi ID, và lấy dữ liệu liên quan
      foreach($the_tags as $tag_id) {
