Vấn đề đổi tên hình ảnh trong khi tải lên Lý do chính cho việc thêm đoạn mã này là tất cả về SEO. Những người mà tôi đôi khi làm trang web cho thường không phải là những người thông thái với WP và có xu hướng tải lên các thứ của họ chỉ như vậy. Vì đây thường là các trang web liên quan đến phương tiện truyền thông, tôi cố gắng giúp họ một chút bằng cách đổi tên tự động các tập tin tải lên từ "DSC_0010.JPG" thành "my-optimized-post-title-001.JPG", v.v... Tôi hiện đang sử dụng đoạn mã này để đổi tên các tập tin của tôi trong quá trình tải lên.

add_filter( 'wp_handle_upload_prefilter', 'my_modify_uploaded_file_names', 1, 1 );

function my_modify_uploaded_file_names( $image_name ) {
  // lấy ID bài viết cha, nếu có

  if ( isset( $_GET['post_id'] ) ) {
    $post_id = $_GET['post_id'];
  } elseif ( isset( $_POST['post_id'] ) ) {
    $post_id = $_POST['post_id'];
  }

  // chỉ thực hiện điều này nếu chúng tôi nhận được ID bài viết, nếu không họ có thể ở phần truyền thông thay vì tải lên hình ảnh từ một bài viết

  if ( is_numeric( $post_id ) ) {
    // lấy slug bài viết

    $post_obj  = get_post( $post_id );
    $post_slug = $post_obj->post_name;

    // nếu chúng tôi tìm thấy một slug

    if ( $post_slug ) {
      $random_number = rand( 10000, 99999 );
      $image_name['name'] = $post_slug . '-' . $random_number . '.jpg';
    }
  }

  return $image_name;
}

