Thiết lập trang cho bài viết Đây là hàm API REST JSON của tôi. Khi được gọi, nó trả về 24 bài đăng, nhưng có nhiều bài đăng hơn tổng số đó. Làm thế nào để tôi có thể phân trang phản hồi để tôi có thể thay đổi trang với điều gì đó như `?page=2` được thêm vào đường dẫn yêu cầu cuộn?

public function posts() {
    $args = array(
        'posts_per_page' => 24,
        'offset' => 0,
        'meta_key' => $meta_key,
        'orderby' => $orderby,
        'order' => 'DESC',
        'post_type' => 'videos',
        'post_status' => 'publish',
        'suppress_filters' => true
    );

    $posts_array = get_posts( $args );

    foreach ( $posts_array as $rate_posts ) {
        $get_author_id = $rate_posts->post_author;
        $author_data = get_userdata( $get_author_id );
        $city = get_the_author_meta( 'city', $author_data->ID );
        $phone = get_the_author_meta( 'phone', $author_data->ID );

        $data['User_id'] = $get_author_id;
        $data['Username'] = $author_data->user_nicename;
        $data['City'] = $city;
        $data['Phone'] = $phone;
        $data['Post_id'] = $rate_posts->ID;
    }

    return $data;
}

Tạo plugin WordPress dành riêng cho bảng điều khiển quản trị với menu và submenu Tôi đang cố gắng tạo một plugin WordPress cho phép khách hàng sử dụng để giúp đỡ và các nguồn lực khác trong một giao diện thân thiện. Nếu tôi có thể được hướng dẫn về việc tạo một plugin WordPress với menu bảng điều khiển chính và các menu con trên đó có thể chứa nội dung HTML thì đó sẽ là điều tuyệt vời. Vì tôi mới bắt đầu phát triển WordPress, nên tôi thấy khó hiểu WP Codex.

Đây là mã plugin:

/** Thêm menu */
add_action( 'admin_menu', 'my_plugin_menu', 'my_magic_function' );
add_submenu_page( 'my_plugin_menu', 'Tiêu đề trang', 'Tiêu đề menu con', 'manage_options', 'my-submenu-handle', 'my_magic_function');

hàm my_plugin_menu() {
add_options_page( 'Tùy chọn Plugin của tôi', 'Plugin của tôi', 'manage_options', 'my-unique-identifier', 'my_plugin_options' );
}

hàm my_plugin_menu() {
add_options_page( 'Trang con', 'Plugin của tôi', 'manage_options', 'my-submenu-handle', 'my_plugin_options' );
}

/** html */
hàm my_plugin_options() {
nếu (!current_user_can('manage_options')) {
wp_die(__('Bạn không có quyền truy cập trang này.'));
}
echo '<div class="wrap">';
echo '<p>Trang chính</p>';
echo '</div>';
}

hàm my_plugin_options() {
nếu (!current_user_can('manage_options')) {
wp_die(__('Bạn không có quyền truy cập trang này.'));
}
echo '<div class="wrap">';
echo '<p>Trang con</p>';
echo '</div>';
}

Thêm nút hoặc nút hình ảnh gọi các chức năng wp trong wp-admin Tôi có một loại bài viết tùy chỉnh của sản phẩm mà tôi đã thiết lập để tải lên PDF bằng các hộp meta. Khi tôi tạo ra các hộp meta trên wp-admin, tôi kiểm tra xem hộp meta đã có một tập tin PDF nào chưa. Nếu có, tôi sẽ tạo ra một liên kết đến tập tin PDF đó. Còn nếu không thì tôi sẽ tạo ra một thanh điều khiển để họ có thể chọn một tập tin để tải lên nếu muốn. Đây là hàm của tôi tạo ra các meta data đó.

function products_pdf_uploads_show_meta() {
    global $meta_box_pdf_uploads, $post, $prefix;

    echo '<table class="form-table">';
    echo '<p class="description">Tải lên các tập tin PDF của bạn ở đây</p>';

    foreach ($meta_box_pdf_uploads['fields'] as $field) {
        // Lấy dữ liệu meta hiện tại
        $pdf_array = get_post_meta($post->ID, $field['id'], true);

        // Lấy tên tập tin từ cuối đường dẫn
        $pdf_filename = substr(strrchr($pdf_array['url'], "/"), 1);

        echo '<tr>',
            '<td>';

        // Nếu trống, hiển thị hộp thoại tải tập tin lên
        if (empty($pdf_array)) {
            echo '<input type="file" style="width: 700px;" name="' . $field['id'] . '" id="' . $field['id'] . '" />';
        } else {
            // Nếu PDF tồn tại, hiển thị liên kết đến tập tin PDF và thêm nút XÓA
            echo '<li><a href="' . $pdf_array['url'] . '" target="_blank">' . $pdf_filename . '</a></li>';
            // Tôi muốn thêm nút xóa sau đoạn mã trên
            echo '<input type="button" value="Xóa" class="button" id="' . $field['id'] . '" />';
        }

        echo '</td>',
            '</tr>';
    }

    echo '</table>';
}

Điều tôi muốn làm là nếu có một dữ liệu meta PDF (có nghĩa là đã có một tập tin PDF được tải lên), tôi muốn đặt nút XÓA bên cạnh liên kết PDF.

} else {
    // Nếu PDF tồn tại, hiển thị liên kết đến tập tin PDF và thêm nút XÓA
    echo '<li><a href="' . $pdf_array['url'] . '" target="_blank">' . $pdf_filename . '</a></li>';
    // Tôi muốn thêm nút xóa sau đoạn mã trên
    echo '<input type="button" value="Xóa" class="button" id="' . $field['id'] . '" />';
}

Nút xóa sẽ xóa tất cả dữ liệu meta từ loại bài viết SẢN PHẨM và xóa tập tin khỏi máy chủ. Vậy câu hỏi của tôi là làm thế nào để tạo một nút có thể tích hợp với các hàm của WordPress như 'delete_post_meta'? Tôi sử dụng 'wp_upload_bits()' để tải lên các tập tin PDF vì tôi không muốn các tập tin PDF được thêm vào thư viện đa phương tiện, chỉ muốn tải chúng lên máy chủ và lấy đường dẫn. Cảm ơn!

__autoload trong một plugin ném ra lỗi trong WP - không thể tìm thấy translation_entry.class.php Được rồi, tôi sẽ cố gắng giải thích vấn đề này đơn giản nhất có thể. Tôi đang cố gắng sửa đổi một plugin được gọi là smart-lencioni-image-resizer v2.0 để sử dụng trong WP-Multisite. Tôi đang cố gắng hiển thị một hình ảnh thông qua SLIR bằng cách sử dụng URL sau: http://subsite.mainsite.no/wp-content/plugins/wp-filebrowser/slir/?w=90&h=90&c=1:1&i=http://bekkelaget.stiengenterprises.no/files/seniorsenter/DSC_3535.jpg Tôi đã thực hiện thành công điều này trong v.1.4.2. Tuy nhiên, v2.0 sử dụng một phương pháp khác để bao gồm các tệp. Tệp `index.php` trông giống như thế này:

```php
function __autoload($className)
{
    var_dump($className);
    require_once strtolower($className) . '.class.php';
}

new SLIR();
```

Bây giờ, bất cứ nơi nào tôi cố gắng bao gồm tiêu đề WP:

```php
require_once($_SERVER['DOCUMENT_ROOT'].'/wp-blog-header.php');
```

Tôi nhận được thông báo lỗi sau:

* **Cảnh báo: require_once(translation_entry.class.php) [function.require-once]: không thể mở luồng: Không có thư mục như vậy trong I:\Development\wamp\www\mysite\wp-content\plugins\wp-filebrowser\slir\index.php trên dòng 43***

Dòng 43 trong tệp `index.php` là:

```php
require_once strtolower($className) . '.class.php';
```

Vì một lý do nào đó, hàm `__autoload` khiến WP tìm kiếm các tệp trong thư mục SLIR. Điều này tất nhiên là sai :(

**CẬP NHẬT** Tôi đã tìm thấy một giải pháp trên web hoạt động khá tốt:

```php
function __autoload($className)
{
    if (file_exists(strtolower($className) . '.class.php')) {
        require_once strtolower($className) . '.class.php';
    }
}
```

Điều này cho phép tệp tiêu đề WP được tải. Nhưng vì một lý do nào đó nó tải `mainsite.no` và bỏ qua việc thực thi URL tôi đã thêm ở trên. Có cách nào khác để giải quyết vấn đề này không?

**CẬP NHẬT 2** Có một tệp .htaccess trong thư mục SLIR. Tệp này trông như thế này:

```
<IfModule mod_rewrite.c>
    RewriteEngine On
    RewriteRule . index.php [L]
</IfModule>

# Ngăn chặn việc xem tệp nhật ký lỗi ở vị trí mặc định
<Files slir-error-log>
    Order Deny,Allow
    Deny from All
</Files>
```

Có thể khi tôi bao gồm tệp tiêu đề WP, nó bỏ qua tệp .htaccess từ SLIR không?

Chuyển các hoạt động fopen/fwrite thành WP_filesystem Trong hàm bên dưới, tôi đang cố gắng chuyển đổi các phương thức fopen/fwrite/fclose thành các phương thức được ưu tiên của WP_filesystem. Mọi thứ hoạt động như mong đợi khi sử dụng khối lệnh đã bị bỏ qua, tuy nhiên các phương thức của WP_filesystem luôn trả về khối lỗi. Có ý tưởng nào về việc tôi đang làm sai không?

function so_doHtaccess() {
    if ( !current_user_can( 'manage_options' ) ) return;

    if ( file_exists( get_home_path() . ".htaccess" ) ) {
        $htaccess_file = get_home_path() . ".htaccess";
        $htaccessnew   = get_option('my_updated_htaccess');

        /*
        if ( is_writeable( $htaccess_file ) ) {
            $f = fopen( $htaccess_file, 'w+' );
            fwrite( $f, $htaccessnew );
            fclose( $f );
        }
        */

        WP_Filesystem();
        global $wp_filesystem;

        $f = $wp_filesystem->get_contents($htaccess_file);

        if ( ! $wp_filesystem->put_contents( $f, $htaccessnew, 0644) ) {
            echo "Có lỗi xảy ra khi lưu tập tin htaccess. Do đó, không có thay đổi nào được thực hiện";die;
        }

    }

    return;
}

