Hàm tùy chỉnh wp_trim_words() không cắt bớt bên phải Tôi có tùy chỉnh hàm `wp_trim_words()` để chỉ hiển thị trích đoạn giới thiệu 20 từ, và hầu hết thời gian nó hoạt động tốt. Tuy nhiên, không hiểu vì lý do gì đó, đối với các bài viết chứa danh sách, nó lại hiển thị nhiều hơn 20 từ (xem các bài viết ở cuối trang này). Làm thế nào để sửa lỗi này? Tôi đã thử xóa `<ul>,<ol>,<li>` từ hàm `insight_allowedtags()` nhưng không có tác dụng. Tôi muốn hiển thị ít nhất 20 từ trong đoạn trích và kết thúc ở cuối một câu, bất kể bài viết có chứa danh sách hay không. Đây là hàm tùy chỉnh mà tôi đang sử dụng (như được đề xuất trong bài viết này):

// Hàm trích đoạn tùy chỉnh cho các bài viết Insights trên trang Insights và trang danh mục

function insight_allowedtags() {
// Thêm thẻ tùy chỉnh vào chuỗi này
return '<script>,<style>,<span>,<ul>,<ol>,<li>,<a>,<p>';
}

if ( ! function_exists( 'insight_custom_wp_trim_excerpt' ) ) :

function insight_custom_wp_trim_excerpt($insight_excerpt) {
global $post;
$raw_excerpt = $insight_excerpt;

if ( '' == $insight_excerpt ) {
$insight_excerpt = get_the_content('');
$insight_excerpt = strip_shortcodes( $insight_excerpt );
$insight_excerpt = apply_filters('the_content', $insight_excerpt);
$insight_excerpt = str_replace(']]>', ']]&gt;', $insight_excerpt);
$insight_excerpt = strip_tags($insight_excerpt, insight_allowedtags()); /* NẾU bạn cần cho phép chỉ một số thẻ nhất định. Xóa nếu tất cả các thẻ đều được cho phép */

// Thiết lập số từ trong đoạn trích và chỉ ngắt câu sau khi câu hoàn chỉnh
$excerpt_word_count = 20;
$excerpt_length = apply_filters('excerpt_length', $excerpt_word_count);
$tokens = array();
$excerptOutput = '';
$count = 0;

// Chia chuỗi thành các token: thẻ HTML, hoặc từ, tiếp theo là ký tự khoảng trắng
preg_match_all('/(<[^>]+>|[^<>\s]+)\s*/u', $insight_excerpt, $tokens);

foreach ($tokens[0] as $token) {
if ($count >= $excerpt_word_count && preg_match('/[\,\;\?\.\!]\s*$/uS', $token)) {
// Giới hạn đã đạt, tiếp tục cho đến khi , ; ? . hoặc ! xảy ra ở cuối câu
$excerptOutput .= trim($token);
break;
}

// Thêm từ để hoàn chỉnh câu
$count++;

// Thêm phần còn lại của token
$excerptOutput .= $token;
}

$insight_excerpt = trim(force_balance_tags($excerptOutput));

// $excerpt_end = ' <a href="'. esc_url( get_permalink() ) . '">' . sprintf(__( 'Đọc thêm về %s &nbsp;&raquo;', 'wpse' ), get_the_title()) . '</a>';
// $excerpt_more = apply_filters('excerpt_more', ' ' . $excerpt_end);

// $pos = strrpos($wpse_excerpt, '</');

//if ($pos !== false)
// Bên trong thẻ HTML cuối cùng
// $wpse_excerpt = substr_replace($wpse_excerpt, $excerpt_end, $pos, 0); /* Thêm "Đọc thêm" bên cạnh từ cuối cùng */

//else
// Sau nội dung
$insight_excerpt .= $excerpt_end; /* Thêm "Đọc thêm" vào đoạn mới */

return $insight_excerpt;
}

return apply_filters('insight_custom_wp_trim_excerpt', $insight_excerpt, $raw_excerpt);
}

endif;

