Settings API - làm thế nào để cập nhật nhiều tùy chọn một cách thủ công? Tôi đang lưu trữ tất cả các tùy chọn của mình bằng cách sử dụng API Cài đặt:

function registerSettings() {
register_setting('XX_theme_settings', 'XX_theme_settings', 'setting_validate');
add_settings_section('theme_options', 'Theme Options', 'theme_options_generate', 'page1');
add_settings_field('XX_Option1', 'Option 1', 'text_input', 'page1', 'theme_options', 'XX_Option1');
add_settings_field('XX_Option2', 'Option 2', 'text_input', 'page1', 'theme_options', 'XX_Option2');
};

add_action('admin_init', 'registerSettings');

Giả sử tôi muốn cập nhật tất cả các tùy chọn một cách thủ công (không sử dụng biểu mẫu, nhưng thông qua PHP), tôi nên làm như thế nào? Đây là cách cập nhật trông giống như cho một cài đặt:

$my_options= get_option('XX_theme_settings');//lấy tất cả các tùy chọn
$my_options['XX_Option2'] = 'giá trị mới của tôi'; //sửa đổi giá trị trong mảng(s)
update_option('XX_theme_settings', $my_options); //cập nhật tùy chọn mảng

Tôi hoàn toàn không có ý tưởng về cách thực hiện nó cho nhiều trường ( ban đầu tôi có trên 50) trường cài đặt. Tôi đã thử cách này:

$current_options = get_option('XX_theme_settings');
$imported_options = array_merge($current_options , array_intersect_key($_POST["import"], $current_options ));
// $imported_options = $_POST["import"]; - đơn giản
update_option('XX_theme_settings', $imported_options);

Và nó không hoạt động, tất nhiên "nhập" không phải là một chuỗi mà là một mảng. Đây là câu hỏi liên quan (của riêng tôi): API Cài đặt - cách cập nhật thủ công các tùy chọn? Tôi đoán tôi vẫn cần tạo một vòng lặp foreach PHP và lặp qua tất cả các cài đặt, sau đó liệt kê chúng, sau đó thêm từng người thông qua update_option? Làm thế nào? Nó sẽ chậm, vì nó nghe có vẻ như vậy?

**CẬP NHẬT** Mã này dường như không cập nhật các cài đặt:

$current_options = get_option( 'XX_theme_settings', array() );
$desired_options = array("existing_field" => "new value");
// $desired_options = array("XX_theme_settings" => array("existing_field" => "new value")); tôi đã thử điều này, nhưng cũng không may mắn
$merged_options = wp_parse_args( $current_options, $desired_options );
update_option( 'XX_theme_settings', $merged_options );

**CẬP NHẬT II** Điều này thậm chí còn kỳ lạ hơn. Tôi đặt mã trên ở trang.php (chỉ vì lý do thử nghiệm):

$current_options = get_option( 'XX_theme_settings', array() );
$desired_options = array("existing_field" => "new value");
$merged_options = wp_parse_args( $current_options, $desired_options );
update_option( 'XX_theme_settings', $merged_options );

Tôi làm mới một trong những trang. Không có gì xảy ra. Sau đó tôi thay đổi mã thành điều này:

$current_options = get_option( 'XX_theme_settings', array() );
$desired_options = array("existing_field" => "new value");
$merged_options[] = wp_parse_args( $current_options, $desired_options ); //đây là sự thay đổi
update_option( 'XX_theme_settings', $merged_options );

Một lần làm mới khác, "existing_field" bây giờ trống. Sau đó tôi một lần nữa dán mã đầu tiên và làm mới lần thứ ba và nó hoạt động.

wp-custom-menu loại bỏ lớp hiện tại_page_item Sau khi thêm plugin wp-custom-menu-filter - để ẩn một số mục menu cho người dùng chưa đăng nhập, lớp current_page_item biến mất khỏi menu của tôi. $item->classes trong walker là một mảng rỗng, thay vì thông thường "page-item-$id", "current_page_item". Tôi đã kiểm tra mã nguồn, nhưng nó không chỉnh sửa mảng classes, vì vậy tôi không biết điều gì đang xảy ra. Đây là phần mã liên quan.

function wps_custom_nav_menu_items( $args ){
    global $wpcmfp_settings;
    $nav_item_db_id = $args[1]->ID;
    $nav_menu = wp_get_object_terms( $nav_item_db_id, 'nav_menu' );
    $menu_id = $nav_menu[0]->term_id;

    // Lấy lớp để loại trừ
    if ( !is_user_logged_in() ) {
        $exclusion_class = $wpcmfp_settings[ 'menu-' . $menu_id . '-loggedout' ];
    } else {
        $exclusion_class = $wpcmfp_settings[ 'menu-' . $menu_id . '-loggedin' ];
    }

    $nav_items = wp_get_nav_menu_items( $menu_id );

    // Duyệt qua tất cả các nav_items
    foreach ( $nav_items as $nav_item ) {

        // Duyệt qua tất cả các lớp
        for ( $i=0; $i < count( $nav_item->classes ); $i++ ) {
            $exclude = false;

            // nếu không có gì ở đó hãy thiết lập để thêm
            if ( strlen ( $nav_item->classes[ $i ] ) < 1 ) {
                $exclude = false;
            } else {

                // nếu khớp với nhau, thêm vào mảng loại trừ và thoát vòng lặp
                if ( $nav_item->classes[ $i ] == $exclusion_class ) {
                    $excluded_nav_items[] = $nav_item;
                    $exclude = true;
                    break;
                }
            }
        }

        if ( $exclude != true )
            $modified_nav_items[] = $nav_item;
    }

    return $modified_nav_items;
}

add_filter( 'wp_nav_menu_objects', 'wps_custom_nav_menu_items' , 10 , 3);

Tôi sử dụng bộ tạo trang tùy chỉnh, tôi đã thử sử dụng bộ tạo trang mặc định mà không có tác dụng, và bộ tạo trang tùy chỉnh hoạt động tốt mà không cần plugin này. Đây là mã của bộ tạo trang:

class My_Walker_Page extends Walker_Nav_Menu {
    protected $_counter = 0;
    protected $_itemsPerColumn = 1;

    function start_lvl(&$output, $depth) {
        $this->_counter = 0;
        $output .= '<some html>';
    }

    function end_lvl(&$output, $depth) {
        $output .= '<some html>';
        $this->_counter = 0;
    }

    function start_el(&$output, $page, $depth, $args, $current_page = null) {
        $args = ( array ) $args;
        if ($depth == 0) {
            return parent::start_el ( $output, $page, $depth, $args, $current_page );
        }

        if ($depth == 1) {
            extract ( $args, EXTR_SKIP );
            $output .= '<dt><a href="' . esc_attr ( $page->url ) . '" title="' . esc_attr ( wp_strip_all_tags ( apply_filters ( 'the_title', $page->title, $page->ID ) ) ) . '">' . $link_before . apply_filters ( 'the_title', $page->title, $page->ID ) . $link_after . '</a>';
            if (! empty ( $page->description )) {
                $output .= '<span class="menu_item_description">' . $page->description . '</span>';
            }
            $output .= '</dt>';
            $this->_counter ++;
            if ($this->_counter % $this->_itemsPerColumn == 0) {
                $output .= '</dl><dl>';
            }
        }
    }

    function end_el(&$output, $page, $depth) {
        if ($depth == 0) {
            return parent::end_el ( &$output, $page, $depth );
        }
    }

    function display_element($element, &$children_elements, $max_depth, $depth = 0, $args, &$output) {
        if (! $element)
            return;
        $id_field = $this->db_fields ['id'];
        if ($depth == 0) {
            $this->_itemsPerColumn = ceil ( count ( $children_elements [$element->$id_field] ) / 4 );
        }
        return parent::display_element ( $element, $children_elements, $max_depth, $depth, $args, $output );
    }
}

Tôi chấp nhận đi theo cách khác để ẩn các mục menu cho người dùng chưa đăng nhập, thay vì sửa chữa plugin, nhưng vì tôi chưa bao giờ sử dụng "wp_nav_menu_objects" nên tôi thực sự không biết chuyện gì đang xảy ra.

