tax_query không hoạt động trên truy vấn chính Tôi đang sử dụng đoạn mã sau để thực hiện một truy vấn thuế và nó dường như không hoạt động nữa. Ở một thời điểm nào đó nó hoạt động và tôi không thể làm cho nó hoạt động được nữa.

<?php
global $pf_override;
class PF_override {
public $site_terms = array();
function __construct() {
// thêm bộ lọc
add_filter( 'init', array( &$this, 'populates_site_terms' ) );
add_filter( 'pre_get_posts', array( &$this, 'filter_query' ) );
}
function populates_site_terms() {
// hàm thực tế của tôi thực hiện một số xử lý và
// kiểm tra bộ nhớ đệm và kết hợp ID từ nhiều nguồn khác nhau
// và sau đó đặt site_terms
$this->site_terms = array( 1, 2, 3 );
}
function filter_query( $query ) {
// không phải là truy vấn chính?
if ( !$query->is_main_query() ) {
return $query;
}
// có thuật ngữ để lọc theo?
if ( !empty( $this->site_terms ) ) {
// xây dựng truy vấn thuế
$tax_query = array(
'taxonomy' => 'site_category',
'field' => 'id',
'terms' => $this->site_terms,
'operator' => 'IN'
);
// điều này cần phải là một mảng của các mảng
$taxquery = array(
$tax_query
);
// đặt điều này..
$query->set( 'tax_query', $taxquery );
}
// trả về đối tượng truy vấn mới
return $query;
}
}
// không phải là quản trị viên? khởi tạo lớp
if ( !is_admin() ) {
$pf_override = new PF_override();
}
?>

