function auto_hashtag( $menu_item ) {
     if ( ! is_admin() && $menu_item->post_parent > 0) {
         // url
          $url = $menu_item->url;
         // slug
          $slug = $menu_item->post_name;
         $menu_item->url = str_replace($slug, "#"+$slug, $url);
     }
     return $menu_item;
}
add_filter( 'wp_setup_nav_menu_item', 'auto_hashtag' );

