Có thể vô hiệu hóa bộ nhớ đệm của một tùy chọn khi sử dụng w3 total cache không? Tôi đang làm một plugin và nó có xung đột với W3 Total Cache. Cụ thể hơn, trong mã của tôi là:

static function get_instance() {
    if( self::$_instance === NULL ) {
        // lấy cài đặt từ cơ sở dữ liệu
        self::$_instance = get_option( 'ai1ec_settings' );
        // nếu không có cài đặt trong cơ sở dữ liệu
        // lưu các giá trị mặc định cho cài đặt
        if( ! self::$_instance ) {
            self::$_instance = new self();
            delete_option( 'ai1ec_settings' );
            add_option( 'ai1ec_settings', self::$_instance );
        } else {
            self::$_instance->set_defaults(); // thiết lập cài đặt mặc định
        }
    }

    return self::$_instance;
}

Vấn đề nằm ở dòng `self::$_instance = get_option( 'ai1ec_settings' );` vì một đối tượng chưa hoàn chỉnh được trả về (chỉ xảy ra khi sử dụng W3 Total Cache, tôi đã khai báo một hàm tự động nạp, nhưng khi thực hiện debug thì dường như đối tượng chưa hoàn chỉnh được lưu trữ trong bộ nhớ cache) Đây là thông báo lỗi > Ai1ec_Settings::get_instance(): Script cố gắng thực thi một phương thức hoặc truy cập vào thuộc tính của một đối tượng chưa hoàn chỉnh. Vui lòng đảm bảo rằng định nghĩa lớp "Ai1ec_Settings" của đối tượng bạn đang cố gắng thực thi được nạp trước khi unserialize() được gọi hoặc cung cấp một hàm __autoload() để nạp định nghĩa lớp

1) Có cách nào để nói với W3 Total Cache không lưu trữ tùy chọn đó không?

2) Nếu không, việc xử lý như sau có đúng không?

try {
    self::$_instance = self::getOptionsFromDb();
} catch (Exception $e) {
    // Hiển thị trang lỗi thân thiện
}

private static function getOptionsFromDb(){
    $ai1ec_settings =  get_option( 'ai1ec_settings' );
    if ( ! $ai1ec_settings instanceof self ) {
        if (false === $ai1ec_settings) {
            return false; // tùy chọn không được thiết lập trong cơ sở dữ liệu
        } elseif( class_exists('W3_Plugin_TotalCacheAdmin') ){
            // xóa bộ nhớ cache và thử lại
            $plugin_totalcacheadmin = & w3_instance('W3_Plugin_TotalCacheAdmin');
            $plugin_totalcacheadmin->flush_all();
            $ai1ec_settings =  get_option( 'ai1ec_settings' );
            if ( $ai1ec_settings instanceof self ) {
                return $ai1ec_settings;
            } else {
                throw new Exception();
            }
        } else {
            throw new Exception();
        }
    }
}

