Thêm lớp Unique vào Next và Previous trong WP_LINK_PAGES Tôi đang sử dụng hàm dưới đây cho wp_link_pages. Nó có thể được xem khi sử dụng ở đây. Tôi muốn thêm một lớp vào liên kết trước và một lớp vào liên kết tiếp theo để chúng có thể được định kiểu riêng biệt. Tôi không phải là chuyên gia về các chức năng WP và tôi tò mò cách thực hiện đúng đắn là gì. Tôi luôn có thể đơn giản là echo divs xung quanh mỗi người, nhưng dường như có thể có một cách tốt hơn để làm điều này.
// WP_LINK_PAGES: Thêm liên kết trước và tiếp theo vào danh sách liên kết có số thứ tự
add_filter('wp_link_pages_args', 'wp_link_pages_args_prevnext_add');
hàm wp_link_pages_args_prevnext_add($args) {
toàn cầu $page, $numpages, $more, $pagenow;
$args ['before'] = '<div id="link_wrap">';
$args ['after'] = '</div>';
$args ['link_before'] = '<span class="classlinks">';
$args ['link_after'] = '</span>';
nếu ($page-1) // có trang trước
$args ['before'] .= ' '. _wp_link_page ($page-1) . $args ['link_before'] . $args ['previouspagelink'] . $args ['link_after'] . '</a>' . ' ';
nếu ($page<$numpages) // có trang tiếp theo
$args ['after'] = ' '. _wp_link_page ($page + 1) . $args ['link_before'] . $args ['nextpagelink'] . $args ['link_after'] . '</a></div>';
