index.php?attachment=$matches1&tb=1 matches
wedstrijd/[0-9]{4}/%month%/[0-9]{1,2}/[^/]+/attachment/([^/]+)/feed/(feed|rdf|rss|rss2|atom)/?$
index.php?attachment=$matches1&feed=$matches[2] matches
wedstrijd/[0-9]{4}/%month%/[0-9]{1,2}/[^/]+/attachment/([^/]+)/(feed|rdf|rss|rss2|atom)/?$
index.php?attachment=$matches1&feed=$matches[2] matches
wedstrijd/[0-9]{4}/%month%/[0-9]{1,2}/[^/]+/attachment/([^/]+)/comment-page-([0-9]{1,})/?$
index.php?attachment=$matches1&cpage=$matches[2] matches

