rewrite_rules() không áp dụng các quy tắc khi kích hoạt plugin chỉ sau khi bấm vào menu permalinks Cảm ơn Roman đã chỉ cho tôi hướng đi đúng đắn, plugin của tôi gần như đã sẵn sàng. Vấn đề duy nhất mà tôi đang gặp phải là tôi không thể áp dụng các quy tắc viết lại (rewrite rules) khi kích hoạt, chúng chỉ hoạt động sau khi tôi truy cập vào trang cài đặt permalinks và nhấp vào nút Lưu thay đổi. Tôi đang sử dụng phương thức rewrite_rules_array để đặt các quy tắc viết lại của plugin ở vị trí đầu tiên, nhưng nó không được gọi khi kích hoạt plugin vì hàm addRewriteRules mong đợi một mảng từ bộ máy WordPress. Tôi rất biết ơn nếu có ai đó chỉ cho tôi cách kích hoạt nó. Dưới đây là phiên bản rút gọn của mã plugin. Cảm ơn trước, Chris.

class JFormerForWP
{
    static $errors = false; /* dùng cho mục đích gỡ lỗi */
    const DB_VERSION = 1; // Số này đại diện cho phiên bản hiện tại của cấu trúc bảng trong plugin. Tăng số này mỗi khi bạn thay đổi cấu trúc bảng cơ sở dữ liệu mà plugin tạo ra.
    static $pluginPath;
    static $pluginUrl;
    static $registry;

    /* được gọi mỗi lần yêu cầu */
    public static function init()
    {
        self::$pluginPath = dirname(__FILE__); // Thiết lập đường dẫn đến thư mục plugin
        self::$pluginUrl = WP_PLUGIN_URL . '/jformer-for-wp/'; // Thiết lập URL của plugin
        add_filter( 'rewrite_rules_array', array(__CLASS__,'addRewriteRules'));
        add_filter( 'query_vars', array(__CLASS__, 'addQueryVars'));
        add_action( 'template_redirect', array(__CLASS__, 'formDisplay'));
        add_action('wp_print_styles', array(__CLASS__, 'styles'));
        add_action('wp_print_scripts', array(__CLASS__, 'scripts') );
        add_shortcode('jformer', array(__CLASS__, 'shortcodeHandler'));

        /* cho chức năng AJAX */
        add_action('wp_ajax_nopriv_jFormerForWp', array(__CLASS__, 'ajaxHandler'));
        add_action('wp_ajax_jFormerForWp', array(__CLASS__, 'ajaxHandler'));

        self::$errors = new WP_Error();
    }

    public static function addRewriteRules($rules)
    {
        $newRules = array(
            'forms/?([^/]*)' => 'index.php?formid=$matches[1]',
        );
        return $newRules + $rules; // Thêm các quy tắc vào đầu mảng
    }

    public static function addQueryVars($vars)
    {
        $vars[] = 'formid';
        return $vars;
    }

    public static function formDisplay()
    {
        if( $formid = get_query_var( 'formid' ) )
        {
            $formCode = self::getForm($formid);
            if($formCode != -1)
            {
                include ( self::$pluginPath . '/html/redirect-page-header.php' );
                echo $formCode;
                include ( self::$pluginPath . '/html/redirect-page-footer.php' );
                exit;
            }
        }
    }

    public static function activate()
    {
        flush_rewrite_rules();
    }

    /* Hàm này sẽ được gọi khi người dùng vô hiệu hóa plugin từ màn hình quản lý plugin của WordPress. Bạn có thể thêm mã để xóa các bảng và tùy chọn mà plugin tạo ra, tuy nhiên, nếu làm như vậy thì khi người dùng kích hoạt lại plugin, họ sẽ mất tất cả dữ liệu và cài đặt trước đó. Một cách khác là tạo một file uninstall.php và đặt mã dọn dẹp vào đó. Mã này sẽ được thực thi khi người dùng xóa plugin. Mở file uninstall.php để xem cách hoạt động của nó. */
    public static function deactivate()
    {
        flush_rewrite_rules();
    }
}

register_activation_hook(__FILE__, array('JFormerForWP','activate'));
register_deactivation_hook(__FILE__, array('JFormerForWP','deactivate'));
add_action('init', 'JFormerForWP::init');

