function jh_save_dedication($post_id, $post) {
/* Kiểm tra nonce trước khi tiếp tục. */
if ( !isset( $_POST["dedicationDate_nonce"] ) || !wp_verify_nonce( $_POST["dedicationDate_nonce"], basename( __FILE__ ) ) )
return $post_id;
if ( !isset( $_POST["dedicationName_nonce"] ) || !wp_verify_nonce( $_POST["dedicationName_nonce"], basename( __FILE__ ) ) )
return $post_id;
if ( !isset( $_POST["dedicationOccasion_nonce"] ) || !wp_verify_nonce( $_POST["dedicationOccasion_nonce"], basename( __FILE__ ) ) )
return $post_id;

/* Lấy đối tượng loại bài viết. */
$post_type = get_post_type_object( $post->post_type );

/* Kiểm tra xem người dùng hiện tại có quyền chỉnh sửa bài viết hay không. */
if ( !current_user_can( $post_type->cap->edit_post, $post_id ) )
return $post_id;

/* Lấy dữ liệu đã đăng và làm sạch nó để sử dụng làm lớp HTML. */
$new_meta_value = ( isset( $_POST['dedicationDate'] ) ? sanitize_html_class( $_POST['dedicationDate'] ) : '' );

/* Lấy khóa meta. */
$meta_key = 'dedicationDate';

/* Lấy giá trị meta của khóa trường tùy chỉnh. */
$meta_value = get_post_meta( $post_id, $meta_key, true );

/* Nếu có giá trị meta mới được thêm và không có giá trị trước đó, hãy thêm nó. */
if ( $new_meta_value && '' == $meta_value )
add_post_meta( $post_id, $meta_key, $new_meta_value, true );

/* Nếu giá trị meta mới không khớp với giá trị cũ, hãy cập nhật nó. */
elseif ( $new_meta_value && $new_meta_value != $meta_value )
update_post_meta( $post_id, $meta_key, $new_meta_value );

/* Nếu không có giá trị meta mới nhưng có giá trị cũ, hãy xóa nó. */
elseif ( '' == $new_meta_value && $meta_value )
delete_post_meta( $post_id, $meta_key, $meta_value );
}

Cách xóa nút từ tinyMCE trong wp_editor được thêm vào thông qua AJAX Tôi đã tạo một plugin với một kiểu bài viết tùy chỉnh sử dụng trình soạn thảo chuẩn. Ngoài ra, trên trang của tôi còn có một nút bấm làm cho một cửa sổ thoại jQuery bật lên và cũng chứa trình soạn thảo tinymce được tạo bằng `wp_editor`. Tôi muốn thay đổi danh sách các nút trên thanh công cụ nhưng chỉ dành cho trình soạn thảo thứ HAI (trình soạn thảo trong cửa sổ thoại). Đây là những gì tôi đã thực hiện:

class MyPlugin {
    function MyPlugin() {
        // Hành động AJAX khởi tạo trình soạn thảo thứ hai
        add_action( 'wp_ajax_show_my_editor', array( &$this, 'show_my_editor' );

        // Đăng ký JavaScript hiển thị trình soạn thảo trong cửa sổ thoại
        add_action( 'admin_enqueue_scripts', array( &$this, 'admin_enqueue_scripts' ) );

        /**
         * Những điều tôi đã thử để loại bỏ các nút không mong muốn
         */

        // Lọc trực tiếp các nút
        add_filter( 'mce_buttons', array( &$this, 'mce_buttons' ), 10, 2 );

        // Lọc cài đặt tinymce trước khi khởi tạo
        add_filter( 'tiny_mce_before_init', array( &$this, 'tiny_mce_before_init' ), 10, 2 );
    }

    /**
     * Đăng ký JavaScript/CSS hiển thị trình soạn thảo trong cửa sổ thoại
     */
    function admin_enqueue_scripts() {
        wp_enqueue_script( 'editor_dialog_js', plugins_url( 'js/editor_dialog.js', __FILE__ ), array( 'jquery', 'jquery-ui-dialog' ), false, true );
        wp_enqueue_style( 'jquery_ui_smoothness', 'http://ajax.googleapis.com/ajax/libs/jqueryui/1.8.7/themes/smoothness/jquery-ui.css' );
    }

    /**
     * Khởi tạo một instance của wp_editor qua cuộc gọi AJAX
     */
    function show_my_editor() {
        wp_editor( '', 'myeditor', array(
            'media_buttons' => false,
            'textarea_rows' => 5,
            'teeny'         => false,
            'quicktags'     => true,
            'tinymce'       => array(
                'skin'            => 'wp_theme',
                'plugins'         => 'wordpress, wplink',
                // Đặt nút ở đây sẽ hoạt động, nhưng không hiệu quả
                'theme_advanced_buttons1' => 'bold,italic',
                'theme_advanced_buttons2' => '',
                'theme_advanced_buttons3' => ''
            )
        ));
        exit;
    }

    /**
     * Được thiết kế để lọc các nút không mong muốn
     * Có thể trùng lặp vì 'theme_advanced_buttons1' được thiết lập ở trên
     */
    function mce_buttons( $buttons, $editor ) {
        // Lọc các nút chỉ dành cho trình soạn thảo được tải qua AJAX
        if ( 'myeditor' == $editor ) {
            $buttons = array_diff( $buttons, array( 'strikethrough' /* ...các nút khác */ ) );
        }
        return $buttons;
    }

    /**
     * Được thiết kế để lọc các nút không mong muốn
     * Có thể trùng lặp vì 'theme_advanced_buttons1' được thiết lập ở trên
     */
    function tiny_mce_before_init( $settings, $editor ) {
        // Lọc các nút chỉ dành cho trình soạn thảo được tải qua AJAX
        if ( 'myeditor' == $editor ) {
            $settings[ 'theme_advanced_buttons1' ] = 'bold,italic';
        }
        return $settings;
    }
}
// Kết thúc lớp MyPlugin

Tập tin `editor_dialog.js` của tôi trông như thế này:

jQuery( document ).ready( function( $ ) {
    $( '#show_editor_dialog_button' ).click( function() {
        $.get( ajaxurl, { action: 'show_my_editor' } )
        .success( function( editor ) {
            $( '<div></div>' ).html( editor )
            .dialog({
                modal: true,
                buttons: { 'OK': function() { $( this ).dialog( 'close' ); } },
                width: 500
            });
            tinymce.execCommand( 'mceAddControl', true, 'myeditor' );
            quicktags( { id: 'myeditor' } );
        });
    });
});

Đây là những gì tôi đã tìm hiểu:

1. Nếu tôi xóa điều kiện `if ( 'myeditor' == $editor )`, các nút sẽ bị lọc khỏi tất cả các trình soạn thảo của tôi, chứ không chỉ trình soạn thảo AJAX như tôi mong muốn.

2. Nếu tôi sử dụng `print_r( $buttons )` hoặc `print_r( $settings[ 'theme_advanced_buttons1` ] )` trong bất kỳ bộ lọc nào, tôi có thể thấy rằng các bộ lọc của tôi hoạt động, chúng chỉ chạy khi trình soạn thảo AJAX được tải, và các nút tôi muốn lọc dường như đã được lọc.

3. Thử mọi tổ hợp của các bộ lọc này và cũng đặt tham số `theme_advanced_buttons1` trong hàm callback AJAX không có vẻ như hoạt động

