// Lưu dữ liệu hộp meta podcast
function save_podcast_meta($post_id, $post) {
    // Xác minh rằng điều này đến từ màn hình của chúng tôi và với quyền ủy quyền thích hợp,
    // bởi vì save_post có thể được kích hoạt vào những thời điểm khác
    if ( !wp_verify_nonce( $_POST['podcastmeta_noncename'], plugin_basename(__FILE__) )) {
        return $post->ID;
    }

    // Người dùng có được phép chỉnh sửa bài viết hoặc trang không?
    if ( !current_user_can( 'edit_post', $post->ID ))
        return $post->ID;

    // Được rồi, chúng tôi được xác thực: chúng tôi cần tìm và lưu dữ liệu
    // Chúng tôi sẽ đặt nó vào một mảng để dễ dàng lặp qua.
    $podcast_meta['_week'] = $_POST['_week'];
    $podcast_meta['_date'] = $_POST['_date'];
    $podcast_meta['_thumbnail'] = $_POST['_thumbnail'];
    $podcast_meta['_seriesimg'] = $_POST['_seriesimg'];
    $podcast_meta['_description'] = $_POST['_description'];

    // Thêm giá trị của $podcast_meta làm trường tùy chỉnh
    foreach ($podcast_meta as $key => $value) { // Lặp qua mảng $podcast_meta!
        if( $post->post_type == 'revision' ) return; // Không lưu dữ liệu tùy chỉnh hai lần
        $value = implode(',', (array)$value); // Nếu $value là một mảng, hãy biến nó thành CSV
        (không có khả năng)

        if(get_post_meta($post->ID, $key, FALSE)) { // Nếu trường tùy chỉnh đã có giá trị
            update_post_meta($post->ID, $key, $value);
        } else { // Nếu trường tùy chỉnh không có giá trị
            add_post_meta($post->ID, $key, $value);
        }

        if(!$value) delete_post_meta($post->ID, $key); // Xóa nếu trống
    }
}

add_action('save_post', 'save_podcast_meta', 1, 2); // lưu các trường tùy chỉnh

