function html5_insert_image($html, $id, $caption, $title, $align, $url, $size, $alt) {
  $src = wp_get_attachment_image_src( $id, $size, false );
  $html5 = "<figure>";
  $html5 .= "<img src='$src[0]' alt='$alt' />";
  if ($caption) {
