Loại trừ các thuật ngữ cụ thể từ tất cả truy vấn sử dụng posts_where hoặc tương tự như vậy Về cơ bản, điều tôi đang cố gắng làm là loại trừ tất cả các bài viết thuộc một tập hợp cụ thể các thuật ngữ khỏi hiển thị trong bất kỳ truy vấn nào trên toàn bộ bảng, TRỪ khi bạn đang xem bài viết hoặc trang đó. Về cơ bản giống như cách tính năng "không liệt kê" của YouTube hoạt động với video. Tôi tự hỏi cách tiếp cận tốt nhất để thực hiện điều này sẽ là gì. Dưới đây là mã tôi đang sử dụng hiện tại, mặc dù tôi cảm thấy điều này có thể được cải thiện về hiệu suất (SQL không phải là điểm mạnh của tôi).

add_filter( 'posts_where', 'exclude_terms_posts_where' );

function exclude_terms_posts_where( $clause = '' ) {
    global $wpdb;

    // Trả về một mảng các ID thuật ngữ cần loại trừ
    $excluded_terms = get_excluded_terms();

    if ( empty( $excluded_terms ) ) {
        return $clause;
    }

    // Lọc ra trang/bài viết hiện tại
    if ( false !== ( $key = array_search( $post->ID, $excluded_terms ) ) ) {
        unset( $excluded_terms[$key] );
    }

    $excluded_terms = implode( ',', $excluded_terms );

    $clause .= "
        AND {$wpdb->posts}.ID NOT IN (
            SELECT {$wpdb->posts}.ID FROM {$wpdb->posts}
            INNER JOIN {$wpdb->term_relationships} ON (
                {$wpdb->posts}.ID = {$wpdb->term_relationships}.object_id
            )
            INNER JOIN $wpdb->term_taxonomy ON (
                {$wpdb->term_relationships}.term_taxonomy_id = {$wpdb->term_taxonomy}.term_taxonomy_id
                AND {$wpdb->term_taxonomy}.taxonomy = 'placement'
                AND {$wpdb->term_taxonomy}.term_id IN ( {$excluded_terms} )
            )
        )
    ";

    return $clause;
}

