// Mã JS để thêm các trường cho các biến thể mới
add_action('woocommerce_product_after_variable_attributes_js', 'variable_fields_js');
// Lưu các trường
add_action('woocommerce_process_product_meta_variable', 'variable_fields_process', 10, 1);

function variable_fields($loop, $variation_data, $variation) {
    ?>
    <tr>
        <td>
            <div>
                <label><?php _e('My Custom Field', 'woocommerce'); ?></label>
                <input type="text" size="5" name="my_custom_field[<?php echo $loop; ?>]" value="<?php echo $variation_data['_my_custom_field'][0]; ?>"/>
                <?php
                if (isset($_POST['variable_sku'])) :
                    $variable_sku = $_POST['variable_sku'];
                    $variable_post_id = $_POST['variable_post_id'];
                    $variable_custom_field = $_POST['my_custom_field'];
                    for ($i = 0; $i < sizeof($variable_sku); $i++) :
                        $variation_id = (int) $variable_post_id[$i];
                        if (isset($variable_custom_field[$i])) {
                            update_post_meta($variation_id, '_my_custom_field', stripslashes($variable_custom_field[$i]));
                        }
                        echo get_post_meta($variation_id, '_my_custom_field', true) . ' - Test';
                    endfor;
                endif;
                // Làm việc
                echo get_post_meta(134, '_my_custom_field', true) . ' - Test 134';
                ?>
            </div>
        </td>
    </tr>
    <?php
}

function variable_fields_js() {
    ?>
    <tr>
        <td>
            <div>
                <label><?php _e('My Custom Field', 'woocommerce'); ?></label>
                <input type="text" size="5" name="my_custom_field[' + loop + ']" />
            </div>
        </td>
    </tr>
    <?php
}

function variable_fields_process($post_id) {
    if (isset($_POST['variable_sku'])) :
        $variable_sku = $_POST['variable_sku'];
        $variable_post_id = $_POST['variable_post_id'];
        $variable_custom_field = $_POST['my_custom_field'];
        for ($i = 0; $i < sizeof($variable_sku); $i++) :
            $variation_id = (int) $variable_post_id[$i];
            if (isset($variable_custom_field[$i])) {
                update_post_meta($variation_id, '_my_custom_field', stripslashes($variable_custom_field[$i]));
            }
        endfor;
    endif;
}

Lưu số không như giá trị meta Tôi có một meta_key gọi là "_ordre" và mỗi khi tôi tạo một bài viết tùy chỉnh mới, một giá trị meta_value mới được thiết lập cho meta_key đó. Vấn đề là, khi tôi thiết lập giá trị của '_ordre' thành 0, giá trị meta_value không được lưu vào cơ sở dữ liệu. Bất cứ thứ gì khác đều ổn ngoại trừ 0. Dưới đây là mã nguồn:

add_action( 'save_post', 'wp_audio_save_meta', 1, 2 );

function wp_audio_save_meta( $post_id, $post ) {
    if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE )
        return;
    if ( !isset( $_POST['wp_audio_posts_nonce'] ) )
        return;
    if ( !wp_verify_nonce( $_POST['wp_audio_posts_nonce'], plugin_basename( __FILE__ ) ) )
        return;
    if ( !current_user_can( 'edit_post', $post->ID ) )
        return;
    if ( $post->post_type == 'revision' )
        return;
    $value = $_POST['_ordre'];
    if ( get_post_meta( $post->ID, '_ordre', FALSE ) ) {
        update_post_meta( $post->ID, '_ordre', $value );
    } else {
        add_post_meta( $post->ID, '_ordre', $value );
    };
    if ( !$value ) delete_post_meta( $post->ID, '_ordre' );
}

