function mytheme_save_data($post_id, $post) {
    if ( !isset( $_POST['url_nonce'] ) || !wp_verify_nonce( $_POST['url_nonce'], basename( __FILE__ ) ) )
        return $post_id;

    $post_type = get_post_type_object( $post->post_type );

    /* Kiểm tra xem người dùng hiện tại có quyền chỉnh sửa bài viết hay không. */

    if ( !current_user_can( $post_type->cap->edit_post, $post_id ) )
        return $post_id;

    /* Lấy dữ liệu đã đăng và làm sạch nó để sử dụng làm lớp HTML. */

    $new_meta_value = ( isset( $_POST['upload_image'] ) ? sanitize_html_class( $_POST['upload_image'] ) : '' );

    /* Lấy khóa meta. */

    $meta_key = '_upload_image';

    /* Lấy giá trị meta của khóa trường tùy chỉnh. */

    $meta_value = get_post_meta( $post_id, $meta_key, true );

    /* Nếu một giá trị meta mới được thêm và không có giá trị trước đó, hãy thêm nó. */

    if ( $new_meta_value && '' == $meta_value )
        add_post_meta( $post_id, $meta_key, $new_meta_value, true );

    /* Nếu giá trị meta mới không khớp với giá trị cũ, hãy cập nhật nó. */

    elseif ( $new_meta_value && $new_meta_value != $meta_value )
        update_post_meta( $post_id, $meta_key, $new_meta_value );

    /* Nếu không có giá trị meta mới nhưng có giá trị cũ, hãy xóa nó. */

    elseif ( '' == $new_meta_value && $meta_value )
        delete_post_meta( $post_id, $meta_key, $meta_value );
}

