wp_localize_script( 'wpPluginjs', 'ajax_vars', array(
    'url' => admin_url( 'admin-ajax.php' ),
    'nonce' => wp_create_nonce( 'ajax-nonce' )
) );

Và đây là phần mã JavaScript:

var url = ajax_vars.url;
