Thư mục tải lên khác nhau dựa trên kiểu bài viết trong một chủ đề Tôi có rất nhiều tập tin hình ảnh và kích thước hình ảnh. Vì vậy sẽ tốt hơn nếu sắp xếp các tập tin đa phương tiện vào các thư mục dựa trên loại bài viết. Tôi vừa đọc hướng dẫn này, nhưng theo như tôi thấy thì nó hoạt động với các plugin. Làm thế nào để thay đổi điều này để sử dụng trong một theme? Cảm ơn.

function custom_upload_directory( $args ) {
    $id = $_REQUEST['post_id'];
    $parent = get_post( $id )->post_parent;

    // Kiểm tra loại bài viết của bài viết hiện tại
    if( "post-type" == get_post_type( $id ) || "post-type" == get_post_type( $parent ) ) {
        $args['path'] = plugin_dir_path(__FILE__) . "uploads";
        $args['url']  = plugin_dir_url(__FILE__) . "uploads";
        $args['basedir'] = plugin_dir_path(__FILE__) . "uploads";
        $args['baseurl'] = plugin_dir_url(__FILE__) . "uploads";
    }

    return $args;
}

add_filter( 'upload_dir', 'custom_upload_directory' );

