Sửa đổi bộ lọc bài viết để thiết lập số lượng bài viết tùy chỉnh trên mỗi trang và loại trừ các bài viết phụ Tôi có một loại bài viết tùy chỉnh được gọi là "galleries", nó là dạng phân cấp. Tôi đang sử dụng một hàm trong file functions.php để thay đổi số lượng bài viết hiển thị trên mỗi trang thành 48. Phần này hoạt động tốt, nhưng tôi cũng cần nó phải loại trừ tất cả các bài viết con, để chỉ có các bài viết bậc cha ở mức cao nhất tạo thành 48 bài viết được đưa vào trên mỗi trang. Đây là mã hiện tại: 

function projects_custom_number_of_posts( $query ) {
    if ( is_admin() || ! $query->is_main_query() )
        return;
    if ( is_post_type_archive( 'galleries' ) ) {
        // Hiển thị 48 bài viết cho một loại bài viết tùy chỉnh được gọi là 'galleries'
        $query->set( 'posts_per_page', 48 );
        return;
    }
}
add_action( 'pre_get_posts', 'projects_custom_number_of_posts', 1 );

Làm thế nào để tôi có thể sửa đổi thành phần $query->set để giới hạn bài viết chỉ ở các bài viết bậc cha ở mức cao nhất? Tôi đã thử mã sau đây, nhưng nó gây ra lỗi:

function projects_custom_number_of_posts( $query ) {
    if ( is_admin() || ! $query->is_main_query() )
        return;
    if ( is_post_type_archive( 'galleries' ) ) {
        // Hiển thị 48 bài viết cho một loại bài viết tùy chỉnh được gọi là 'galleries'
        $query->set( array ('posts_per_page'=>48, 'post_parent'=>0) );
        return;
    }
}
add_action( 'pre_get_posts', 'projects_custom_number_of_posts', 1 );

