get_avatar() trả về false, sử dụng với JSON-API Tôi đã cài đặt JSON-API và đang sử dụng một bộ điều khiển tùy chỉnh để lấy tất cả người dùng với vai trò "editor". Tôi cũng đã cài đặt WP-User-Avatar để các biên tập viên có thể tải lên hình ảnh của riêng họ thay vì sử dụng Gravatar. Tôi có hai cài đặt, một máy chủ thử nghiệm nơi API trả về hình ảnh và máy chủ sản xuất, nơi tôi nhận được 'false' cho hình ảnh. Đây là mã từ bộ điều khiển:

public function get_editors_with_image() {
    global $json_api, $wp_query;
    $args = array('role' => 'editor');
    $user_query = new WP_User_Query( $args );
    $user_results = $user_query->results;
    $editors = array();
    foreach ($user_results as $key => $value) {
        $current_id = $value->data->ID;
        $editors[$key]['id'] = $current_id;
        $editors[$key]['url'] = $value->data->user_url;
        $editors[$key]['display_name'] = $value->data->display_name;
        $editors[$key]['description'] = get_the_author_meta('description', $current_id);
        $editors[$key]['image'] = get_avatar($current_id, 400);
    }
    return array(
        "editors" => $editors
    );
}

