Lưu bài viết tùy chỉnh trong mẫu đơn tùy chỉnh Tôi đang cố gắng lưu một bài đăng tùy chỉnh trong một biểu mẫu tùy chỉnh. Khi tôi gửi biểu mẫu, tất cả dữ liệu được xử lý, và sau đó tôi cần lưu nó vào cơ sở dữ liệu. Tôi đang cố gắng thực hiện điều này bằng cách sử dụng "update_post_meta", nhưng nó yêu cầu một ID bài đăng mà tôi không có ở thời điểm đó. Làm thế nào để tôi có được nó? Hoặc tôi có nên sử dụng một phương pháp khác để lưu dữ liệu? Ngoài ra, khi lưu một bài đăng tùy chỉnh từ wp-admin, tôi đã gắn hàm "save" vào "edit_post". Vì đây là một biểu mẫu tùy chỉnh, không có móc mặc định nào. Tôi giả định rằng bài đăng đó, không có siêu dữ liệu, được lưu tự động ở đó, vì vậy tôi có cần phải tái tạo chức năng này trong hàm lưu của biểu mẫu tùy chỉnh của tôi không? Vì vậy, tôi thực sự muốn biết cách lưu một bài đăng tùy chỉnh (và các giá trị siêu dữ liệu) từ đầu (không có móc hoặc ID bài đăng). Mã:

function dating_user_create_account_validate() {
    $errors = array();

    // Xác minh sự thật
    if(!isset($_POST['dating_user_truth_field']))
        $errors[] = "Bạn phải xác nhận rằng bạn đã điền dữ liệu một cách trung thực. Đánh dấu vào hộp kiểm ở cuối biểu mẫu.";

    // Xác minh trường trống
    $fields = array('email','gender','sexuality','day','month','year','region','city');
    $unset_fields = array();
    foreach($fields as $field)
        if(!isset($_POST['dating_user_'.$field.'_field']) || $_POST['dating_user_'.$field.'_field'] === '')
            $unset_fields[] = $field;

    function alias($k) {
        $aliases = array(
            'email'     => 'Email',
            'password'  => 'Mật khẩu',
            'gender'    => 'Giới tính',
            'sexuality' => 'Khuynh hướng tình dục',
            'birthday'  => 'Ngày sinh',
            'region'    => 'Vùng',
            'city'      => 'Thành phố',
        );
        return $aliases[$k];
    }

    if(sizeof($unset_fields) > 0) {
        $errors[] = implode(', ', array_map('alias', $unset_fields)) . ' không được điền.';
        return $errors;
    }

    // Xác minh email
    if(!is_email($_POST['dating_user_email_field']))
        $errors[] = 'Vui lòng điền địa chỉ Email hợp lệ.';

    // Xác minh nonce
    $nonces = array('email','gender','sexuality','birthday','region','city');
    foreach($nonces as $nonce)
        if(!wp_verify_nonce($_POST['dating_user_'.$nonce.'_box_nonce'],'dating_user_'.$nonce.'_box'))
            die($nonce." nonce không hợp lệ");

    // Kiểm tra email trùng lặp
    $mail_args = array(
        'post_type'      => 'dating_user',
        'meta_key'       => '_email_meta_value_key',
        'meta_value'     => $_POST['dating_user_email_field'],
        'posts_per_page' => 10,
    );
    $mail_res = new WP_Query($mail_args);
    if($mail_res->have_posts()) {
        $errors[] = 'Địa chỉ Email này đã được sử dụng. Vui lòng chọn một địa chỉ khác hoặc tìm lại mật khẩu của bạn tại Tài khoản > Quên mật khẩu.';
        return $errors;
    }

    $password = generateRandomString(15);

    $final_data = array(
        'email'     => sanitize_text_field( $_POST['dating_user_email_field'] ),
        'password'  => wp_hash_password($password),
        'gender'    => $_POST['dating_user_gender_field'],
        'sexuality' => $_POST['dating_user_sexuality_field'],
        'birthday'  => $_POST['dating_user_day_field'].'-'.$_POST['dating_user_month_field'].'-'.$_POST['dating_user_year_field'],
        'region'    => $_POST['dating_user_region_field'],
        'city'      => $_POST['dating_user_city_field'],
    );

    // Tôi không có $post_id ở đây
    foreach($final_data as $data_key => $data_value)
        update_post_meta($post_id, '_'.$data_key.'_meta_value_key', $data_value);

    send_email($final_data['email'], $password);

    header('Location: '.$_SERVER['PHP_SELF'].'/account-aangemaakt/');
}

