WP Query - Thumbnail Bài viết Tôi đang sử dụng plugin: Series và mặc định nó chỉ nhận được các tiêu đề bài viết liên kết. Tôi muốn thêm cả hình thu nhỏ của bài viết vào. Tôi đã có thể hiển thị hình thu nhỏ, nhưng chúng xuất hiện bên ngoài widget. Tôi đã thêm phần the_post_thumbnail('thumbnail'). Mẫu đầy đủ được hiển thị bên dưới. Cảm ơn bạn vì sự giúp đỡ!

/**
* Hiển thị danh sách bài viết theo ID series.
*
* @since  0.1.0
* @param  array   $args
* @return string
*/
function series_list_posts( $args = array() ) {
if ( empty( $args['series'] ) )
return;
$out     = '';
$post_id = 0;
if ( in_the_loop() )
$post_id = get_the_ID();
else if ( is_singular() )
$post_id = get_queried_object_id();
$defaults = array(
'series' => '', // term slug
'order' => 'ASC',
'orderby' => 'date',
'posts_per_page' => -1,
'echo' => true,
);
$args = wp_parse_args( $args, $defaults );
$loop = new WP_Query( $args );
if ( $loop->have_posts() ) {
$out .= '<ul class="series-list">';
while ( $loop->have_posts() ) {
$loop->the_post();
$out .= $post_id === get_the_ID() ? the_title( '<li>' . the_post_thumbnail('thumbnail') . '</li>', false ) : the_title( '<li>' . the_post_thumbnail('thumbnail') . '<a href="' . get_permalink() . '">', '</a></li>', false );
}
$out .= '</ul>';
}
wp_reset_postdata();
if ( false === $args['echo'] )
return $out;
echo $out;
}

/**
* Hiển thị danh sách bài viết liên quan đến bài viết hiện tại dựa trên series đầu tiên.
*
* @since  0.1.0
* @param  array  $args
* @return string
*/
function series_list_related( $args = array() ) {
$post_id = 0;
if ( in_the_loop() )
$post_id = get_the_ID();
else if ( is_singular() )
$post_id = get_queried_object_id();
if ( !empty( $post_id ) )
$series = get_the_terms( $post_id, 'series' );
if ( empty( $series ) )
return;
$series = reset( $series );
$args['series'] = $series->slug;
return series_list_posts( $args );
}

