function save_user_custom($user_id) {
if ($user_id == false)
return false;

// Nếu trường tải lên có tệp trong đó
if (isset($_FILES['profile_photo'])) {
if (!function_exists('wp_handle_upload'))
require_once(ABSPATH . 'wp-admin/includes/file.php');

// Nhận loại tệp được tải lên. Điều này được trả về dưới dạng "loại/mở rộng"
$arr_file_type = wp_check_filetype(basename($_FILES['profile_photo']['name']));
$uploaded_file_type = $arr_file_type['type'];

// Thiết lập mảng chứa danh sách các định dạng được chấp nhận
$allowed_file_types = array('image/jpg', 'image/jpeg', 'image/gif', 'image/png');

// Nếu tệp tải lên có định dạng đúng
if (in_array($uploaded_file_type, $allowed_file_types)) {
// Tùy chọn mảng cho hàm wp_handle_upload. 'test_upload' => false
$upload_overrides = array(
'test_form' => false
);

// Xử lý việc tải lên bằng hàm wp_handle_upload của WP. Lấy tệp được đăng và một mảng tùy chọn
$uploaded_file = wp_handle_upload($_FILES['profile_photo'], $upload_overrides);

// Nếu cuộc gọi wp_handle_upload trả về đường dẫn cục bộ cho hình ảnh
if (isset($uploaded_file['file'])) {
// Hàm wp_insert_attachment cần đường dẫn hệ thống thực tế, được truyền lại từ wp_handle_upload
$file_name_and_location = $uploaded_file['file'];

// Tạo tiêu đề cho hình ảnh sẽ được sử dụng trong thư viện đa phương tiện
$file_title_for_media_library = 'tiêu đề của bạn ở đây';

// Thiết lập mảng tùy chọn để thêm tệp này dưới dạng tệp đính kèm
$attachment = array(
'post_mime_type' => $uploaded_file_type,
'post_title' => 'Hình ảnh được tải lên ' . addslashes($file_title_for_media_library),
'post_content' => '',
'post_status' => 'inherit'
);

// Chạy hàm wp_insert_attachment. Điều này thêm tệp vào thư viện đa phương tiện và tạo các bản xem trước. Nếu bạn muốn đính kèm hình ảnh này vào bài viết, bạn có thể truyền ID bài viết làm tham số thứ ba và nó sẽ xảy ra.
$attach_id = wp_insert_attachment($attachment, $file_name_and_location);

require_once(ABSPATH . "wp-admin" . '/includes/image.php');
$attach_data = wp_generate_attachment_metadata($attach_id, $file_name_and_location);
wp_update_attachment_metadata($attach_id, $attach_data);

update_user_meta($user_id, 'profile_photo', $attach_id);
}
}
}
}
