Trang đăng ký tùy chỉnh - ngăn chặn chuyển hướng đến wp-login.php?action=register Tôi đã có một tùy chỉnh đăng nhập được xây dựng với mã sau:
add_action('login_redirect', 'jwh_redirect_login', 10, 3);
function jwh_redirect_login($redirect_to, $url, $user) {
$url = current(explode('?', $url));
nếu ($user->errors['empty_password']) {
wp_redirect( $url . '?jwh_error=nopass');
}
khác nếu ($user->errors['empty_username']) {
wp_redirect( $url . '?jwh_error=nouser');
}
khác nếu ($user->errors['incorrect_password']) {
wp_redirect( $url . '?jwh_error=invalidpass');
}
khác nếu ($user->errors['invalid_username']) {
wp_redirect( $url . '?jwh_error=invaliduser');
}
khác nếu (!empty($user->data)) {
wp_redirect( $url);
}
khác {
wp_redirect($url . '?jwh_error="nothing');
}
exit;
}
