Cắt xén nội dung tùy chỉnh kiểu bài viết Tôi đang tùy chỉnh widget được sử dụng để hiển thị các nhận xét. Widget hoạt động tốt, ngoại trừ nó hiển thị tất cả nội dung và tôi muốn giới hạn văn bản/ký tự để chân trang của trang web trông cân đối hơn. Đây là đoạn mã widget:

function widget( $args, $instance ) {
    extract( $args );
    $title = $instance['title'] ;
    $count = $instance['count'];
    $url = $instance['url'];
    echo $before_widget;
    echo '<div class="testimonials-container">';
    if ( $title )
        echo '<h3 class="replace"><a href="' . $url . '">' . $title . '</a></h3>' ;
    ?>
    <?php
    $query = new WP_Query();
    $query->query('post_type=testimonial&posts_per_page='.$count);
    ?>
    <?php if ($query->have_posts()) : while ($query->have_posts()) : $query->the_post(); ?>
        <div class="testimonials-content">
        <?php limit_text(the_content(), 15); ?>
        <span class="testimonial-name"><em>
            <?php echo get_post_meta(get_the_ID(), 'pkb_author_name', true); ?></em></span>
        </div>
    <?php endwhile; endif;?>

Để cắt ngắn nó, tôi sử dụng hàm này:

function limit_text($text, $limit) {
    if (strlen($text) > $limit) {
        $words = str_word_count($text, 2);
        $pos = array_keys($words);
        $text = substr($text, 0, $pos[$limit]) . '...';
    }
    return $text;
}

