function property_save( $post_id )
{
    // Bail if we're doing an auto save
    if( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) return;

    // if our nonce isn't there, or we can't verify it, bail
    if( !isset( $_POST['meta_box_nonce'] ) || !wp_verify_nonce( $_POST['meta_box_nonce'], 'my_meta_box_nonce' ) ) return;

    // if our current user can't edit this post, bail
    if( !current_user_can( 'edit_post' ) ) return;

    // now we can actually save the data
    $allowed = array(
        'a' => array( // on allow a tags
            'href' => array() // and those anchors can only have href attribute
        )
    );

    // Make sure your data is set before trying to save it
    if( isset( $_POST['property_id'] ) )
        update_post_meta( $post_id, 'property_id', wp_kses( $_POST['property_id'], $allowed ) );

    if( isset( $_POST['address'] ) )
        update_post_meta( $post_id, 'address', esc_attr( $_POST['address'] ) );
}

Thực hành tốt nhất để đăng ký người dùng với Wordpress từ nền tảng MVC Vâng nên tôi đã từng phát triển trong Wordpress rất nhiều nhưng trong năm qua tôi đã chuyển sang sử dụng Codeigniter. Rõ ràng có những thời điểm mà Codeigniter phù hợp với một tình huống hơn Wordpress và ngược lại, nhưng tôi đã phải quay lại sử dụng Wordpress cho dự án tiếp theo của mình. Với MVC nó có rất nhiều ý nghĩa để có tất cả các "echo" trong các views và có tất cả các xử lý trong các controllers, v.v... nhưng bây giờ quay trở lại với Wordpress tôi cảm thấy lạ khi echo bên trong một hàm. Tôi đang tạo một trang đăng ký (hầu hết mã là từ đây nhưng tôi chưa thay đổi nó thành các trường tùy chỉnh của tôi, v.v.) nơi HTML nằm trong trang mẫu với một `do_action ('process_customer_registration_form');` và tất cả các xử lý VÀ ECHOING được thực hiện trong function.php:

```php
function registration_process_hook() {
    if (isset($_POST['adduser']) && isset($_POST['add-nonce']) && wp_verify_nonce($_POST['add-nonce'], 'add-user')) {
        // chết nếu nonce thất bại
        if (!wp_verify_nonce($_POST['add-nonce'], 'add-user')) {
            wp_die('Xin lỗi! Đó là an toàn, đoán bạn đang gian lận đúng không!');
        } else {
            // tự động tạo mật khẩu
            $user_pass = wp_generate_password();
            // thiết lập người dùng mới
            $userdata = array(
                'user_pass' => $user_pass,
                'user_login' => esc_attr($_POST['user_name']),
                'user_email' => esc_attr($_POST['email']),
                'role' => get_option('default_role'),
            );
            // thiết lập một số kiểm tra lỗi
            if (!$userdata['user_login']) {
                $error = 'Tên người dùng là bắt buộc cho việc đăng ký.';
            } elseif (username_exists($userdata['user_login'])) {
                $error = 'Xin lỗi, tên người dùng đó đã tồn tại!';
            } elseif (!is_email($userdata['user_email'], true)) {
                $error = 'Bạn phải nhập địa chỉ email hợp lệ.';
            } elseif (email_exists($userdata['user_email'])) {
                $error = 'Xin lỗi, địa chỉ email đó đã được sử dụng!';
            }
            // thiết lập người dùng mới và gửi thông báo
            else {
                $new_user = wp_insert_user($userdata);
                wp_new_user_notification($new_user, $user_pass);
            }
        }
    }

    if ($new_user) : ?>
        <p class="alert"> <!-- tạo một thông báo để hiển thị đăng ký thành công -->
        <?php
        $user = get_user_by('id', $new_user);
        echo 'Cảm ơn bạn đã đăng ký ' . $user->user_login;
        echo '<br/>Vui lòng kiểm tra địa chỉ email của bạn. Đó là nơi bạn sẽ nhận được mật khẩu đăng nhập.<br/>(Hãy đảm bảo kiểm tra thư mục spam)';
        ?>
        </p>
    <?php else : ?>
        <?php if ($error) : ?>
            <p class="error"> <!-- hiển thị lỗi nếu người dùng thất bại -->
                <?php echo $error; ?>
            </p>
        <?php endif; ?>
    <?php endif;
}

add_action('process_customer_registration_form', 'registration_process_hook');

