Làm thế nào để tạo một 'single' category widget cho woocommerce plugin WooCommerce cung cấp sẵn nhiều tiện ích, tuy nhiên tiện ích danh mục sản phẩm cho phép tìm kiếm tất cả các danh mục vào một tiện ích duy nhất. Tôi muốn có một tiện ích cho một danh mục duy nhất, ví dụ như "Mua sắm theo ý nghĩa" và một tiện ích khác "Mua sắm theo chữ cái" v.v... Tôi đã lấy mã nguồn của tiện ích widget-product_categories.php từ plugin WooCommerce với hy vọng tôi có thể dễ dàng chỉnh sửa mã nguồn cho danh mục kích thước mà tôi tạo trong plugin WooCommerce. Tuy nhiên, tôi nhanh chóng nhận ra rằng nó vượt quá khả năng của tôi. Vì tôi cần tạo 4 tiện ích khác nhau với chức năng tìm kiếm "Mua sắm theo xxx", tôi rất mong nhận được sự giúp đỡ. Dưới đây là mã nguồn của tiện ích WooCommerce hiển thị tất cả các danh mục trong một tiện ích duy nhất. Có cách nào để chỉnh sửa lại mã này để hiển thị kết quả cho một danh mục duy nhất không?

var $woo_widget_cssclass;
var $woo_widget_description;
var $woo_widget_idbase;
var $woo_widget_name;
var $cat_ancestors;
var $current_cat;

/**
* Hàm khởi tạo
*
* @access public
* @return void
*/
function WooCommerce_Widget_Product_Categories() {
/* Cài đặt biến cho tiện ích */
$this->woo_widget_cssclass = 'widget_product_categories';
$this->woo_widget_description = __( 'A list or dropdown of product categories.', 'woocommerce' );
$this->woo_widget_idbase = 'woocommerce_product_categories';
$this->woo_widget_name = __('WooCommerce Product Categories', 'woocommerce' );

/* Cài đặt cho tiện ích */
$widget_ops = array(
'classname' => $this->woo_widget_cssclass,
'description' => $this->woo_widget_description
);

/* Tạo tiện ích */
$this->WP_Widget('product_categories', $this->woo_widget_name, $widget_ops);
}

/**
* Hàm hiển thị tiện ích
*
* @see WP_Widget
* @access public
* @param array $args
* @param array $instance
* @return void
*/
function widget( $args, $instance ) {
extract( $args );

$title = apply_filters('widget_title', empty( $instance['title'] ) ? __( 'Product Categories', 'woocommerce' ) : $instance['title'], $instance, $this->id_base);
$c = $instance['count'] ? '1' : '0';
$h = $instance['hierarchical'] ? true : false;
$s = (isset($instance['show_children_only']) && $instance['show_children_only']) ? '1' : '0';
$d = $instance['dropdown'] ? '1' : '0';
$o = isset($instance['orderby']) ? $instance['orderby'] : 'order';

echo $before_widget;
if ( $title ) echo $before_title . $title . $after_title;

$cat_args = array('show_count' => $c, 'hierarchical' => $h, 'taxonomy' => 'product_cat');

if ( $o == 'order' ) {
$cat_args['menu_order'] = 'asc';
} else {
$cat_args['orderby'] = 'title';
}

if ( $d ) {
// Bị mắc kẹt với vấn đề này cho đến khi có bản vá lỗi cho http://core.trac.wordpress.org/ticket/13258
woocommerce_product_dropdown_categories( $c, $h, 0 );
?>
<script type='text/javascript'>
/* <![CDATA[ */
var dropdown = document.getElementById("dropdown_product_cat");
function onCatChange() {
if ( dropdown.options[dropdown.selectedIndex].value !=='' ) {
location.href = "<?php echo home_url(); ?>/?product_cat="+dropdown.options[dropdown.selectedIndex].value;
}
}
dropdown.onchange = onCatChange;
/* ]]> */
</script>
<?php
} else {
global $wp_query, $post, $woocommerce;
$this->current_cat = false;
$this->cat_ancestors = array();

if ( is_tax('product_cat') ) :
$this->current_cat = $wp_query->queried_object;
$this->cat_ancestors = get_ancestors( $this->current_cat->term_id, 'product_cat' );
elseif ( is_singular('product') ) :
$product_category = wp_get_post_terms( $post->ID, 'product_cat' );
if ($product_category) :
$this->current_cat = end($product_category);
$this->cat_ancestors = get_ancestors( $this->current_cat->term_id, 'product_cat' );
endif;
endif;

include_once( $woocommerce->plugin_path() . '/classes/walkers/class-product-cat-list-walker.php' );
$cat_args['walker']
= new WC_Product_Cat_List_Walker;
$cat_args['title_li']
= '';
$cat_args['show_children_only'] = ( isset( $instance['show_children_only'] ) && $instance['show_children_only'] ) ? 1 : 0;
$cat_args['pad_counts']
= 1;
$cat_args['show_option_none']
= __('No product categories exist.', 'woocommerce');
$cat_args['current_category']
= ( $this->current_cat ) ? $this->current_cat->term_id : '';
$cat_args['current_category_ancestors'] = $this->cat_ancestors;

echo '<ul class="product-categories">';
wp_list_categories( apply_filters( 'woocommerce_product_categories_widget_args', $cat_args ) );
echo '</ul>';
}

echo $after_widget;
}

/**
* Hàm cập nhật
*
* @see WP_Widget->update
* @access public
* @param array $new_instance
* @param array $old_instance
* @return array
*/
function update( $new_instance, $old_instance ) {
$instance = $old_instance;
$instance['title'] = strip_tags($new_instance['title']);
$instance['orderby'] = strip_tags($new_instance['orderby']);
$instance['count'] = !empty($new_instance['count']) ? 1 : 0;
$instance['hierarchical'] = !empty($new_instance['hierarchical']) ? true : false;
$instance['dropdown'] = !empty($new_instance['dropdown']) ? 1 : 0;
$instance['show_children_only'] = !empty($new_instance['show_children_only']) ? 1 : 0;

return $instance;
}

/**
* Hàm hiển thị biểu mẫu
