<?php
class A extends Z {
    public function sampleFunction($post) {
        // mã ở đây
    }
}

class B extends A {
    public __construct() {
        $this->anotherClass();
    }

    // add_action() và update_meta_box() là các hàm từ WordPress

    public function anotherClass() {
        $post = $_POST['test'];
        add_action('save_post', function($id) {
            if (isset($post)) {
                // Ở đây tôi không biết cách gọi nó bên trong hàm ẩn danh
                $this->sampleFunction($post);
                update_meta_box(
                    $id,
                    'key',
                    strip_tags($post)
                );
            }
        });
    }
}
?>

