function filter_more_with_nextpage( $content ){
    $content = str_replace( '<!--more-->', '<!--nextpage-->', $content );
    $content = preg_replace( '/<!--nextpage-->/i', '<!--more-->', $content, 1 );
    return $content;
}
add_filter( 'content_save_pre', 'filter_more_with_nextpage' );

