function auto_login() {
    if (!is_user_logged_in()) {
        // Xóa bỏ một số mã vì lý do ngắn gọn.
        $user = get_userdatabylogin($domainName);

        if ($user != null) {
            // Thiết lập cookie xác thực.
            wp_set_auth_cookie($user->ID, false, null);

            // Thiết lập người dùng hiện tại (cũng sẽ thiết lập các đối tượng WP ở cấp độ toàn cầu)
