```php
function featured() {
    $featured = new WP_Query(array(
        'meta_query' => array(
            array(
                'key' => 'featured',
                'value' => '"top"',
                'compare' => 'LIKE'
            )
        ),
        'posts_per_page' => 1
    ));

    while ( $featured->have_posts() ) : $featured -> the_post();
        $do_not_duplicate = $post->ID; ?>

        <div id="featured">
            // bài viết nổi bật
        </div><!-- end #featured -->

    <?php
    endwhile;

    if(have_posts()) : while (have_posts()) : the_post();
        if ($post->ID == $do_not_duplicate) continue; ?>

        <div class="container">
            // bài viết bình thường
        </div><!-- .charities-container -->

    <?php
    endwhile;
    endif;
}
```

