Tôi đã tìm thấy một đoạn mã thiết lập thứ tự của điều hướng qua bài viết đơn như "menu_order", vì vậy có lẽ giải pháp bây giờ là khác.

Dưới đây là mã mà tôi đang nói về

function square_adjacent_post_where($sql) {
if ( !is_main_query() || !is_singular() )
return $sql;
$the_post = get_post( get_the_ID() );
$patterns = array();
$patterns[] = '/post_date/';
$patterns[] = '/\'[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\'/';
$replacements = array();
$replacements[] = 'menu_order';
$replacements[] = $the_post->menu_order;
return preg_replace( $patterns, $replacements, $sql );
}
add_filter( 'get_next_post_where', 'square_adjacent_post_where' );
add_filter( 'get_previous_post_where', 'square_adjacent_post_where' );

function square_adjacent_post_sort($sql) {
if ( !is_main_query() || !is_singular() )
return $sql;
$pattern = '/post_date/';
$replacement = 'menu_order';
return preg_replace( $pattern, $replacement, $sql );
}
add_filter( 'get_next_post_sort', 'square_adjacent_post_sort' );
add_filter( 'get_previous_post_sort', 'square_adjacent_post_sort' );

Cập nhật meta của bài viết tùy chỉnh Tôi đang viết một plugin cho công việc và có thêm một vấn đề. Tôi đã thêm các hộp meta như yêu cầu. Tuy nhiên, vấn đề tôi gặp phải xảy ra khi lưu bài viết. Các đoạn mã của tôi để lưu bài viết được lấy từ bài viết này. Tôi cũng đã nhận được câu trả lời tương tự ở đây, nhưng nó chỉ không hoạt động vì một lý do nào đó. :/

protected function __update_post_meta( $post_id, $field_name, $value = '' )
{
    if ( empty( $value ) OR ! $value )
    {
        delete_post_meta( $post_id, $field_name );
    }
    elseif ( ! get_post_meta( $post_id, $field_name ) )
    {
        add_post_meta( $post_id, $field_name, $value );
    }
    else
    {
        update_post_meta( $post_id, $field_name, $value );
    }
}

Mã trên được gọi bằng cách sau. Tuy nhiên, tôi nghĩ rằng vấn đề của tôi không nằm trong quá trình lưu bài viết mà có thể là do nonce gây ra.

public function _wp_save_post( $post_id, $post )
{
    if ( empty($_POST)
        OR !isset($_POST['argus_edit_visitor'])
        OR !wp_verify_nonce( $_POST['argus_edit_visitor'], 'argus_edit_visitor' ) )
    {
        return $post->ID;
    }

    if ( ! current_user_can( 'edit_post', $post->ID ) ) return $post->ID;

    // v_f_name | v_l_name | v_workstation | v_id
    // Argh!
    $this->__update_post_meta( $post->ID, 'v_f_name', $_POST['v_f_name'] );
    $this->__update_post_meta( $post->ID, 'v_l_name', $_POST['v_l_name'] );
    $this->__update_post_meta( $post->ID, 'v_workstation', $_POST['v_workstation'] );
    $this->__update_post_meta( $post->ID, 'v_id', $_POST['v_id'] );
}

Nonce được sử dụng như sau: <input type="hidden" name="argus_edit_visitor" id="argus_edit_visitor" value="{$nonce}" /> và được tạo bằng cách sử dụng $nonce = wp_create_nonce( plugin_basename( __FILE__ ) );. Trường đầu vào nằm trong khối HTML được lưu trữ trong biến $html. Stackexchange đã phân tích mã HTML của tôi nếu không tôi sẽ dán nó ở đây. - Zack

