Tạo một danh sách thả xuống hiển thị dữ liệu người dùng Tôi muốn hiển thị một danh sách thả xuống của người dùng thông tin từ bảng `wp_usermeta`. Tôi biết rằng có một phương thức `wp_dropdown_users` mà đầu ra là một danh sách chọn của người dùng nhưng tôi không thể tìm ra cách để sửa đổi mã để cho phép tôi hiển thị một cột từ bảng `meta` của tôi. Ai có thể giúp tôi? Hiện tại tôi đã sửa đổi `wp_dropdown_users` nhưng nó chỉ đầu ra một danh sách hiển thị `options` như thế này `()`.

```php
function wp_dropdown_users( $args = '' ) {
    $defaults = array(
        'show_option_all' => 'Chọn Grower để chia sẻ...', 'show_option_none' => '', 'hide_if_only_one_author' => '',
        'orderby' => 'display_name', 'order' => 'ASC',
        'include' => '', 'exclude' => '1', 'multi' => 0,
        'show' => 'display_name', 'echo' => 1,
        'selected' => 0, 'name' => 'user', 'class' => '', 'id' => '',
        'blog_id' => $GLOBALS['blog_id'], 'who' => '', 'include_selected' => false
    );
    $defaults['selected'] = is_author() ? get_query_var( 'author' ) : 0;
    $r = wp_parse_args( $args, $defaults );
    extract( $r, EXTR_SKIP );
    $query_args = wp_array_slice_assoc( $r, array( 'blog_id', 'include', 'exclude', 'orderby', 'order', 'who' ) );
    $query_args['fields'] = array( 'ID', 'user_login', $show );
    $users = get_users( $query_args );
    $output = '';
    if ( !empty($users) && ( empty($hide_if_only_one_author) || count($users) > 1 ) ) {
        $name = esc_attr( $name );
        if ( $multi && ! $id )
            $id = '';
        else
            $id = $id ? " id='" . esc_attr( $id ) . "'" : " id='$name'";
        $output = "<select name='{$name}'{$id} class='$class'>\n";
        if ( $show_option_all )
            $output .= "\t<option value='0'>$show_option_all</option>\n";
        if ( $show_option_none ) {
            $_selected = selected( -1, $selected, false );
            $output .= "\t<option value='-1'$_selected>$show_option_none</option>\n";
        }
        $found_selected = false;
        foreach ( (array) $users as $user ) {
            $user->ID = (int) $user->ID;
            $_selected = selected( $user->ID, $selected, false );
            if ( $_selected )
                $found_selected = true;
            $display = !empty($user->$show) ? $user->$show : '('. $user->user_login . ')';
            $output .= "\t<option value='$user->ID'$_selected>" . esc_html($display) . "</option>\n";
        }
        if ( $include_selected && ! $found_selected && ( $selected > 0 ) ) {
            $user = get_userdata( $selected );
            $_selected = selected( $user->ID, $selected, false );
            $display = !empty($user->$show) ? $user->$show : '('. $user->user_login . ')';
            $output .= "\t<option value='$user->ID'$_selected>" . esc_html($display) . "</option>\n";
        }
        $output .= "</select>";
    }

