Phân biệt hình ảnh nổi bật từ hình ảnh bài viết khi tải lên Tôi muốn phân biệt hình ảnh nổi bật với hình ảnh trong bài viết. Kế hoạch là cho hình ảnh nổi bật nhiều kích thước khác nhau, nhưng hình ảnh bên trong hoặc liên quan đến bài viết chỉ cần kích thước mặc định. Tôi biết tôi có thể sử dụng `intermediate_image_sizes` để lọc các loại bài viết tùy chỉnh được gán cho kích thước hình ảnh nào, như sau:

/** Đừng tạo kích thước bổ sung */

function post_type_sizes( $image_sizes ){
    $post_type_size_array = array('icon', 'med-thumb', 'large', 'full');
    $post_image_sizes = array('thumbnail', 'medium', 'large', 'full');

    if( isset($_REQUEST['post_id']) && 'cpt_test' === get_post_type($_REQUEST['post_id']) )
        return $post_type_size_array;
    else
        return $post_image_sizes;

    return $image_sizes;
}

add_filter('intermediate_image_sizes', 'post_type_sizes', 999 );

