Nếu bạn nhận thấy rằng `'sub_menu' => true` lập luận bạn có mắt tốt. Đây là mã cho điều đó.

// Submenus - cần thiết cho menu con (trên) hoạt động
// hàm filter_hook để phản ứng trên cờ sub_menu
function coepio_submenu( $sorted_menu_items, $args ) {
if ( isset( $args->sub_menu ) ) {
$root_id = 0;
// tìm mục menu hiện tại
foreach ( $sorted_menu_items as $menu_item ) {
if ( $menu_item->current ) {
// đặt ID gốc dựa trên việc mục menu hiện tại có một bậc cha hay không
$root_id = ( $menu_item->menu_item_parent ) ? $menu_item->menu_item_parent : $menu_item->ID;
break;
}
}
$menu_item_parents = array();
foreach ( $sorted_menu_items as $key => $item ) {
// khởi tạo menu_item_parents
if ( $item->ID == $root_id ) $menu_item_parents[] = $item->ID;
if ( in_array( $item->menu_item_parent, $menu_item_parents ) ) {
// là một phần của cây con: giữ lại!
$menu_item_parents[] = $item->ID;
} else {
// không phải là một phần của cây con: bỏ đi!
unset( $sorted_menu_items[$key] );
}
}
return $sorted_menu_items;
} else {
return $sorted_menu_items;
}
}
add_filter( 'wp_nav_menu_objects', 'coepio_submenu', 10, 2 );

