$email = is_email($_POST ["email"]);
nếu (!$email) {
$error = TRUE;
$errorMsg = "EMAIL KHÔNG HỢP LỆ";
}
nếu (email_exists($email)) {
$error = TRUE;
$errorMsg = "EMAIL ĐÃ TỒN TẠI";
