}
nếu (!$error) {
// Tạo mật khẩu ngẫu nhiên, đặt tên người dùng, wp_create_user, vv hoạt động tốt
$output = "TỐT";
}
// Một số thứ khác ở đây không thiết lập $error thành TRUE
nếu ($error) {
$output = $errorMsg;
}
trả về $output;
}

