Đặt độ phức tạp của mật khẩu Chúng tôi cần thực thi độ phức tạp mật khẩu trên một trang web wordpress, chúng tôi đã sử dụng bài viết này: http://www.webtipblog.com/force-password-complexity-requirements-wordpress/ Chúng tôi đã tạo ra những điều sau trong functions.php:

add_action('user_profile_update_errors', 'validateProfileUpdate', 10, 3 );

add_filter('registration_errors', 'validateRegistration', 10, 3 );

add_action('validate_password_reset', 'validatePasswordReset', 10, 2 );

function validateProfileUpdate( WP_Error &$errors, $update, &$user ) {

return validateComplexPassword( $errors );

}

function validateRegistration( WP_Error &$errors, $sanitized_user_login, $user_email ) {

return validateComplexPassword( $errors );

}

function validatePasswordReset( WP_Error &$errors, $userData ) {

return validateComplexPassword( $errors );

}

function validateComplexPassword( $errors ) {

$password = ( isset( $_POST[ 'pass1' ] ) && trim( $_POST[ 'pass1' ] ) ) ? $_POST[ 'pass1' ] : null;

if ( empty( $password ) || ( $errors->get_error_data( 'pass' ) ) )

return $errors;

$passwordValidation = validatePassword($password);

if ( $passwordValidation !== true ) {

$errors->add( "pass", "<strong>ERROR</strong>: " . $passwordValidation . "." );

}

return $errors;

}

function validatePassword($Password) {

//#### Kiểm tra nó lớn hơn 6 ký tự

if (strlen($Password) < 6) {

return "Mật khẩu quá ngắn (" . strlen($Password) . "), vui lòng sử dụng 6 ký tự hoặc nhiều hơn.";

}

//#### Kiểm tra mật khẩu có chữ hoa và chữ thường

if (preg_match("/^(?=.*[a-z])(?=.*[A-Z]).+$/", $Password) !== 1) {

return "Mật khẩu không chứa sự kết hợp giữa chữ hoa và chữ thường.";

}

//#### Kiểm tra mật khẩu có sự kết hợp giữa chữ cái và số

if (preg_match("/^((?=.*[a-z])|(?=.*[A-Z]))(?=.*\d).+$/", $Password) !== 1) {

return "Mật khẩu không chứa sự kết hợp giữa chữ cái và số.";

}

//#### Mật khẩu trông ổn

return true;

}

Như bạn thấy, chúng tôi đã sử dụng móc 'validate_password_reset' & sử dụng nó để gọi hàm tùy chỉnh của chúng tôi 'validatePassword()' kiểm tra mật khẩu với một vài biểu thức chính quy đơn giản. Tuy nhiên, mã này dường như không được gọi khi người dùng đặt lại mật khẩu qua 'wp-login.php' - chúng tôi biết điều này bởi vì nó vẫn cho phép chúng tôi nhập mật khẩu "woof" (mà rõ ràng là không hợp lệ) và để kiểm tra lại, chúng tôi đã thêm một số mã vào hàm 'validateComplexPassword()' để gửi email cho chúng tôi, một lần nữa, không có email nào được gửi đi. Có phải có gì đó sai với mã của chúng tôi? Có phải hành động 'validate_password_reset' không còn được gọi nữa không? Giúp :)

