Cách xử lý cookie từ một plugin WordPress trên trang lưu cache? Tôi đang cố gắng viết một plugin có thể hoạt động với cookie trên một trang web WordPress sử dụng bộ nhớ đệm trang (tại sao?). Tôi đã theo dõi hướng dẫn này trên Esanctuary.net. Tôi đang cố gắng ghi vào error_log để kiểm tra xem logic cookie có hoạt động hay không, nhưng vì một lý do nào đó, tôi không nhận được bất kỳ log nào từ hàm esanctuary_sidebar_cookie khi sử dụng các hook wp_ajax. Tôi cũng đang sử dụng cookie.js để xử lý việc đặt cookie. Đây là mã plugin của tôi:

<?php
/*
Plugin Name: Ví dụ
Plugin URI:
Mô tả:
Phiên bản: 0.0.1
Tác giả:
Author URI:
*/
class Ví dụ {
// Hàm khởi tạo
function __construct() {
add_action( 'wp_enqueue_scripts', array( &$this, 'add_js' ) );
add_action( 'wp_ajax_my_action', array( &$this, 'esanctuary_sidebar_cookie' ) );
add_action( 'wp_ajax_nopriv_my_action', array( &$this, 'esanctuary_sidebar_cookie' ) );
}
// Hàm PHP4 Constructor
function Ví dụ () {
$this->__construct();
}
function add_js() {
if( !wp_script_is( 'cookiejs', 'queue' ) ) {
wp_enqueue_script( 'cookiejs', plugins_url( basename( __DIR__ ) . '/js/cookie.min.js' ), array( 'jquery' ) );
}
wp_enqueue_script( 'cookieset', plugins_url( basename( __DIR__ ) . '/js/cookie-set.js' ), array( 'jquery' ) );
}
function esanctuary_sidebar_cookie() {
error_log( 'esanctuary' );
// Kiểm tra xem cookie đã được đặt chưa
if ( isset($_COOKIE["edition"]) ) {
// Lấy giá trị của cookie đó
$edition = $_COOKIE["edition"];
// Quyết định hiển thị sidebar nào dựa trên cookie đó
if ($edition == 'new-york') {
error_log( 'New York' );
}
else if ($edition == 'miami') {
error_log( 'Miami!' );
}
} else {
error_log( 'Không!' );
}
}
}
