Meta boxes tùy chỉnh có nên được cho phép hiển thị shortcode giống như trình soạn thảo bài viết mặc định của Wordpress? Câu hỏi đơn giản: Hộp meta tùy chỉnh có thể hiển thị mã ngắn giống như trình soạn thảo bài viết bản địa của Wordpress không? Lý do tôi hỏi là bởi vì tôi đã tạo hộp meta tùy chỉnh để nhập mã ngắn của plugin Cart66 nhằm hiển thị nút "Thêm vào giỏ hàng" nhưng khi thử thì nó chỉ in ra văn bản từ mã ngắn thay vì hiển thị nút thực tế. Hộp meta hiện tại của tôi:

<?php

// Đăng ký hộp meta tùy chỉnh cho loại bài viết -- Trường nút Thêm vào giỏ hàng [mã ngắn]
add_action( 'add_meta_boxes', 'store_button_meta_box_add' );
function store_button_meta_box_add() {
    add_meta_box( 'epr_store_button_meta_id', 'Thêm vào giỏ hàng Button [shortcode]', 'store_button_meta_box_cb', 'epr_store', 'side', 'high' );
}

function store_button_meta_box_cb( $post ) {
    $values = get_post_custom( $post->ID );
    $button = isset( $values['meta_box_button_shortcode'] ) ? esc_attr( $values['meta_box_button_shortcode'][0] ) : '';
    wp_nonce_field( 'my_meta_box_nonce', 'meta_box_nonce' );

    ?>
    <p>
        <textarea name="meta_box_button_shortcode" id="meta_box_button_shortcode" row="5" style="width:100%; height:100px;text-align:left;"><?php echo esc_textarea($button); ?></textarea>
    </p>
    <?php
}

add_action( 'save_post', 'epr_button_meta_box_save' );
function epr_button_meta_box_save( $post_id ) {
    // Ngừng nếu chúng ta đang tự lưu
    if( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) return;

    // Nếu nonce của chúng ta không tồn tại hoặc không xác minh được, dừng lại
    if( !isset( $_POST['meta_box_nonce'] ) || !wp_verify_nonce( $_POST['meta_box_nonce'], 'my_meta_box_nonce' ) ) return;

    // Nếu người dùng hiện tại không thể chỉnh sửa bài viết này, dừng lại
    if( !current_user_can( 'edit_post' ) ) return;

    // Bây giờ chúng ta có thể lưu dữ liệu

    $allowed = array(
        'a' => array( // chỉ cho phép thẻ a
            'href' => array() // và những neo này chỉ có thể có thuộc tính href
        )
    );

    // Có lẽ là một ý tưởng tốt để đảm bảo dữ liệu của bạn được thiết lập
    if( isset( $_POST['meta_box_button_shortcode'] ) )
        update_post_meta( $post_id, 'meta_box_button_shortcode', wp_kses( $_POST['meta_box_button_shortcode'], $allowed ) );
}
?>

