WordPress daily cron đang thực thi thường xuyên hơn một lần một ngày Tôi có một công việc cron của WP được lên lịch dựa trên những gì trong các tùy chọn. Trong trường hợp này, lịch trình của nó là hàng ngày.

add_action('init', function(){
    if( !wp_next_scheduled('product_posting_cron') ){
        wp_schedule_event(time() + 700, 'timely', 'product_posting_cron' );
    }
});

add_filter( 'cron_schedules', function( $schedules ) {
    global $frequency;
    $interval = $frequency['interval']; //daily
    $display = $frequency['display'];

    $schedules['timely'] = array(
        'interval' => $interval,
        'display' => $display
    );
});

Nhưng tôi không biết tại sao nó thực hiện nhiều hơn một lần một ngày tùy thuộc vào số lần truy cập trang trên trang web. Tôi đã bỏ lỡ điều gì ở đây?

