    return '<img src="/path/to/file/'.$name.'.png" alt="'.$name.'" title="'.$name.'" />';
}
add_shortcode("pkmn", "cwc_pkmn");

Tất cả tên file của tôi đều viết chữ thường với dấu "-" giữa các từ. Tôi có thể thay đổi chữ cái sau mỗi dấu "-" thành chữ hoa và thay thế dấu "-" bằng khoảng trắng không? Hiện tại khi tôi sử dụng đoạn mã trên như sau:

[pkmn name="mr.-deeds"]

