add_rewrite_rule('^players/type/([^/]*)/?$','index.php?pagename=player-types&type=$matches[1]','top');

//sẽ khớp với www.site.com/players/type/pro/page/2
add_rewrite_rule('^players/type/([^/]*)/page/([0-9]+)?$','index.php?pagename=player-types&type=$matches[1]&paged=$matches[2]','top');

}

3. Thêm biến "type" vào "query_vars" để tôi có thể sử dụng nó trên mẫu trang mới (đặt trong functions.php)

add_filter( 'query_vars', 'add_query_vars' );

function add_query_vars( $query_vars ) {
$query_vars[] = 'type'; //thêm type vào query vars
return $query_vars;
}

4. Và mẫu trang ở dạng đơn giản nhất trông giống như thế này

<?php /* Template Name: Player Types */ ?>

