Custom Shortcode bị hỏng trong Wordpress 3.1 Một bản nâng cấp gần đây lên wordpress 3.1 đã làm hỏng một plugin tùy chỉnh được viết để sử dụng mã ngắn trong việc tạo mã nhúng HTML dễ dàng cho các video brightcove. Có ai có thể thấy những gì đang xảy ra trong đoạn mã sau đây là không tương thích với 3.1, và những gì cần phải thực hiện để sửa chữa nó? Nó hoạt động tốt trong 3.0 trước khi nâng cấp.

<?php

/*
Plugin Name: Brightcove Video Player
Version: 1.0
Plugin URI: http://www.brightcove.com
Description: Simplifies the process of adding a Brightcove video to a WordPress blog.
Author: Bob de Wit
Author URI: http://brightcove.active6.com
*/

//Thiết lập ID của nhà xuất bản - BẠN PHẢI CÀI ĐẶT ID CỦA RIÊNG BẠN VÀO ĐÂY
$publisher = 1705665024;

//Thiết lập một trình phát mặc định để sử dụng - BẠN PHẢI CÀI ĐẶT ID CỦA RIÊNG BẠN VÀO ĐÂY
$player = 1911416499;

//Thiết lập độ rộng và chiều cao cho trình phát video mặc định
$width = 486;
$height = 412;

//Xác định biến video mặc định
$videoid = 0;

//Hàm phân tích nội dung thực tế được gọi bởi bộ lọc
//Hàm này sẽ sử dụng hàm callback BCVideo_Render để thực hiện việc
//thay thế văn bản thực tế cho widget
function Brightcove_Parse($content)
{
    $content = preg_replace_callback("/\[brightcove ([^]]*)\/\]/i", "Brightcove_Render", $content);
    return $content;
}

function Brightcove_Render($matches)
{
    global $video, $player, $publisher, $width, $height, $arguments;
    $output = '';

    $matches[1] = str_replace(array('&#8221;','&#8243;'), '', $matches[1]);
    preg_match_all('/(\w*)=(.*?) /i', $matches[1], $attributes);
    $arguments = array();
    foreach ( (array) $attributes[1] as $key => $value )
    {
        // Loại bỏ dấu ngoặc kép cũ
        $arguments[$value] = str_replace('"', '', $attributes[2][$key]);
    }

    if (( !array_key_exists('video', $arguments) ) && ( !array_key_exists('player', $arguments) ))
    {
        return '<div style="background-color:#f99; padding:10px;">Lỗi widget trình phát Brightcove: Thiếu tham số bắt buộc "video" hoặc "player"! </div>';
        exit;
    }
    else
    {
        $video = $arguments['video'];
    }

    if( array_key_exists('width', $arguments) )
    {
        $height = $arguments['width'];
    }

    if( array_key_exists('height', $arguments) )
    {
        $height = $arguments['height'];
    }

    if( array_key_exists('player', $arguments) )
    {
        $player = $arguments['player'];
    }

    //$flashVars = "isVid=1&playerID=$player&publisherID=$publisher&@videoPlayer=$video";
    $output .= "<embed src='http://c.brightcove.com/services/viewer/federated_f9/$player?isVid=1&publisherID=$publisher'
    bgcolor='#FFFFFF'
    flashVars='@videoPlayer=$video&playerID=$player&domain=embed&'
    base='http://admin.brightcove.com'
    name='flashObj'
    width='$width'
    height='$height'
    seamlesstabbing='false'
    type='application/x-shockwave-flash'
    allowFullScreen='true'
    swLiveConnect='true'
    pluginspage='http://www.macromedia.com/shockwave/download/index.cgi?P1_Prod_Version=ShockwaveFlash'>
    </embed>";

    return $output;
}

//Thêm một móc lọc - đăng ký hàm này cho tất cả nội dung
//văn bản (Trang và Bài viết) để tìm thẻ [CONTRIBUTOR_WIDGET].
add_filter('the_content', 'Brightcove_Parse');

